begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما أقصى عدد من الإلكترونات يستوعبه مستوى الطاقة الثانوي p؟', null, '["2","6","10","14"]'::jsonb, 'تذكر', 'تذكر سعة مستوى ثانوي', 'سهل', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('mcq', 2, 'مستوى طاقة ثانوي يتسع لعشرة إلكترونات كحد أقصى. ما هذا المستوى؟', null, '["d","p","f","s"]'::jsonb, 'تذكر', 'تذكر سعة مستوى ثانوي', 'سهل', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('mcq', 3, 'أيّ مستويات الطاقة الثانوية الآتية تكون سعته من الإلكترونات الأكبر؟', null, '["s","d","f","p"]'::jsonb, 'تذكر', 'تذكر سعة مستوى ثانوي', 'سهل', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('mcq', 4, 'أيّ التتابعات الآتية تمثّل أقصى عدد من الإلكترونات في المستويات الثانوية s وp وd وf على الترتيب؟', null, '["2 ، 8 ، 18 ، 32","1 ، 3 ، 5 ، 7","2 ، 4 ، 6 ، 8","2 ، 6 ، 10 ، 14"]'::jsonb, 'تذكر', 'تذكر سعات المستويات الثانوية', 'متوسط', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('mcq', 5, 'ما أقصى عدد من الإلكترونات تستوعبه المستويات الثانوية s وp وd مجتمعة؟', null, '["12","18","32","16"]'::jsonb, 'تطبيق', 'جمع سعات مستويات ثانوية', 'متوسط', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('mcq', 6, 'أيّ العمليات الحسابية الآتية تعطي أقصى عدد من الإلكترونات في مستوى الطاقة الرئيس الرابع بجمع سعات مستوياته الثانوية؟', null, '["2 + 6 + 10 = 18","2 + 6 = 8","6 + 10 + 14 = 30","2 + 6 + 10 + 14 = 32"]'::jsonb, 'تطبيق', 'تطبيق السعات على مستوى رئيس', 'صعب', 'الكتاب ص 113–114 — سعة مستويات الطاقة الثانوية'),
('mcq', 7, 'يحتوي المستوى الثانوي 4p في ذرة ما على 3 إلكترونات. كم إلكترونًا إضافيًّا يمكن أن يستوعبه هذا المستوى حتى يمتلئ؟', null, '["6","9","3","4"]'::jsonb, 'تطبيق', 'حساب المتبقي من السعة', 'متوسط', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('essay', 1, 'اذكر أقصى عدد من الإلكترونات يستوعبه كلٌّ من مستويات الطاقة الثانوية s وp وd وf.', null, null, 'تذكر', 'تذكر سعات', 'متوسط', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية'),
('essay', 2, 'احسب أقصى عدد من الإلكترونات في مستوى الطاقة الرئيس الثالث بجمع سعات مستوياته الثانوية، ثم تحقق من صحة الناتج بالقانون e = 2n². بيّن خطواتك.', null, null, 'تطبيق', 'حل مسألة والتحقق منها', 'صعب', 'الكتاب ص 113–114 — سعة مستويات الطاقة الثانوية'),
('essay', 3, 'رتّب المستويات الثانوية s وp وd وf من الأقل سعة إلى الأكثر سعة وحدّد أكثرها سعة. ثم احسب كم إلكترونًا إضافيًّا يمكن أن يستوعبه المستوى 3d إذا كان فيه 6 إلكترونات، وكم إلكترونًا إضافيًّا يمكن أن يستوعبه المستوى 4f إذا كان فيه 9 إلكترونات.', null, null, 'تطبيق', 'مقارنة وحساب', 'صعب', 'الكتاب ص 114 — سعة مستويات الطاقة الثانوية')
