('mcq', 1, 1, 'أقصى سعة للمستوى الثانوي p هي 6 إلكترونات (ستة).', '["العدد 2 سعة المستوى الثانوي s وليس p.","","العدد 10 سعة المستوى الثانوي d وليس p.","العدد 14 سعة المستوى الثانوي f وليس p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.768Z"}'::jsonb),
('mcq', 2, 0, 'المستوى الثانوي الذي يتسع لعشرة إلكترونات هو d؛ فسعة d عشرة إلكترونات.', '["","المستوى p يتسع لستة إلكترونات فقط.","المستوى f يتسع لأربعة عشر إلكترونًا.","المستوى s يتسع لإلكترونين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.768Z"}'::jsonb),
('mcq', 3, 2, 'سعات المستويات الثانوية s وp وd وf هي 2 و6 و10 و14؛ فالمستوى f هو الأكبر سعة، إذ يستوعب 14 إلكترونًا.', '["المستوى s أصغرها سعة، إذ يستوعب إلكترونين فقط.","المستوى d يستوعب 10 إلكترونات، وهي أقل من سعة f.","","المستوى p يستوعب 6 إلكترونات فقط، وهي أقل من سعة f."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.768Z"}'::jsonb),
('mcq', 4, 3, 'سعات المستويات الثانوية s وp وd وf هي 2 و6 و10 و14 إلكترونًا على الترتيب.', '["هذه سعات المستويات الرئيسة 1 و2 و3 و4 وليست سعات المستويات الثانوية.","هذه أعداد تتبع تسلسلًا فرديًّا، وسعات المستويات الثانوية تساوي ضعف هذه الأعداد.","هذا تتابع لا يمثل السعات؛ فسعة p هي 6 وليست 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.768Z"}'::jsonb),
('mcq', 5, 1, 'سعة s تساوي 2، وسعة p تساوي 6، وسعة d تساوي 10؛ فالمجموع 2 + 6 + 10 = 18 إلكترونًا.', '["العدد 12 مجموع سعتي s وd فقط (2 + 10) دون p.","","العدد 32 مجموع سعات المستويات الثانوية الأربعة s وp وd وf.","العدد 16 مجموع سعتي p وd فقط (6 + 10) دون s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.768Z"}'::jsonb),
('mcq', 6, 3, 'يتكوّن المستوى الرئيس الرابع من s وp وd وf، فسعته 2 + 6 + 10 + 14 = 32 إلكترونًا.', '["هذا مجموع سعات s وp وd فقط، أي سعة المستوى الرئيس الثالث، وقد أُهمل المستوى f.","هذا مجموع سعتي s وp فقط، أي سعة المستوى الرئيس الثاني.","هذا المجموع أهمل المستوى s الموجود في المستوى الرئيس الرابع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.769Z"}'::jsonb),
('mcq', 7, 2, 'سعة المستوى الثانوي p هي 6 إلكترونات، وفيه 3 إلكترونات؛ فيتسع لـ 6 − 3 = 3 إلكترونات إضافية.', '["العدد 6 هو السعة الكلية للمستوى p، وليس عدد الإلكترونات الإضافية.","العدد 9 ناتج جمع 6 + 3 بدل طرح 3 من السعة.","","العدد 4 لا ينتج من أي عملية صحيحة؛ فسعة p هي 6 والمطلوب 6 − 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.769Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المستوى الثانوي s يستوعب 2 إلكترونًا، والمستوى p يستوعب 6 إلكترونات، والمستوى d يستوعب 10 إلكترونات، والمستوى f يستوعب 14 إلكترونًا.', '["s: 2","p: 6","d: 10","f: 14"]'::jsonb, '[]'::jsonb, '[{"element":"سعة s","marks":1},{"element":"سعة p","marks":1},{"element":"سعة d","marks":1},{"element":"سعة f","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"السعات الأربع صحيحة"},{"level":"2–3 درجات","description":"سعتان أو ثلاث سعات صحيحة"},{"level":"1 درجة","description":"سعة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 1 و3 و5 و7 بدل السعات الصحيحة","الخلط بين سعة المستوى الثانوي وسعة المستوى الرئيس","تبديل سعتي p وd"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.769Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المستوى الرئيس الثالث يضم المستويات الثانوية s وp وd، وسعاتها 2 و6 و10 على الترتيب. المجموع = 2 + 6 + 10 = 18 إلكترونًا. وبالقانون: e = 2n² = 2 × 3² = 2 × 9 = 18. النتيجتان متطابقتان، فسعة المستوى الرئيس الثالث 18 إلكترونًا.', '["المستويات الثانوية في المستوى الثالث: s وp وd","السعات 2 و6 و10","المجموع 18","القانون يعطي 18 أيضًا"]'::jsonb, '["المستويات الثانوية في المستوى الرئيس الثالث: s وp وd","المجموع = 2 + 6 + 10 = 18","e = 2n² = 2 × 3² = 2 × 9 = 18","النتيجتان متطابقتان: 18 إلكترونًا"]'::jsonb, '[{"element":"تحديد المستويات الثانوية وسعاتها (2 و6 و10)","marks":1},{"element":"جمع السعات للحصول على 18","marks":1},{"element":"تطبيق القانون e = 2n² بالتعويض","marks":1},{"element":"المقارنة بين النتيجتين والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جمع السعات وتطبيق القانون والمقارنة بينهما"},{"level":"2–3 درجات","description":"إحدى الطريقتين صحيحة كاملة مع نقص في الأخرى"},{"level":"1 درجة","description":"ذكر سعات المستويات الثانوية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة سعة المستوى f إلى المستوى الرئيس الثالث","نسيان الضرب في 2 عند تطبيق القانون","جمع سعات المستويات الثانوية بصورة خاطئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:27:04.769Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الترتيب من الأقل سعة إلى الأكثر: s (2) ثم p (6) ثم d (10) ثم f (14)؛ وأكثرها سعة المستوى f. المستوى 3d سعته 10 وفيه 6، فيستوعب 10 − 6 = 4 إلكترونات إضافية. والمستوى 4f سعته 14 وفيه 9، فيستوعب 14 − 9 = 5 إلكترونات إضافية.', '["الترتيب s < p < d < f في السعة","المستوى f أكثرها سعة (14)","3d يستوعب 4 إلكترونات إضافية","4f يستوعب 5 إلكترونات إضافية"]'::jsonb, '["السعات: s = 2، p = 6، d = 10، f = 14","3d: 10 − 6 = 4","4f: 14 − 9 = 5"]'::jsonb, '[{"element":"ترتيب المستويات حسب السعة","marks":1},{"element":"تحديد f أكثرها سعة","marks":1},{"element":"حساب المتبقي في 3d (4)","marks":1},{"element":"حساب المتبقي في 4f (5)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح مع تحديد f وحساب المتبقي في المستويين"},{"level":"2–3 درجات","description":"ترتيب صحيح مع حساب صحيح لأحد المستويين أو أخطاء حسابية بسيطة"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال سعة d = 6 وسعة f = 10","جمع الإلكترونات الموجودة إلى السعة بدل طرحها","كتابة السعة الكلية على أنها عدد الإلكترونات الإضافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.769Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C4-L1-O05') and x.type = v.type and x.number = v.number
