('mcq', 1, 3, 'تُملأ المستويات بالترتيب 1s ثم 2s ثم 2p ثم 3s ثم 3p؛ فبعد 2 + 2 + 6 + 2 = 12 إلكترونًا يبقى إلكترون واحد يدخل المستوى 3p، فالتوزيع 1s² 2s² 2p⁶ 3s² 3p¹.', '["مجموع إلكترونات هذا التوزيع 14 وليس 13، فهو توزيع السيليكون ذي العدد الذري 14.","المستوى 3s لا يتسع لثلاثة إلكترونات؛ فسعته القصوى إلكترونان.","لا يجوز دخول إلكترونين في 3p قبل امتلاء 3s بإلكترونين؛ فالمستويات تُملأ بدءًا من الأقل طاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-10-18T03:27:04.770Z"}'::jsonb),
('mcq', 2, 2, 'للأكسجين 8 إلكترونات: إلكترونان في 1s، وإلكترونان في 2s، وتبقى أربعة إلكترونات في 2p؛ فالتوزيع 1s² 2s² 2p⁴.', '["مجموع إلكترونات هذا التوزيع 10 وهو توزيع النيون Ne، وليس الأكسجين.","المستوى 2s لا يتسع لأربعة إلكترونات؛ فسعته القصوى إلكترونان.","","مجموعه 8 لكن 3s امتلأ قبل امتلاء 2p، والصحيح أن يمتلئ 2p أولًا لأنه أقل طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.770Z"}'::jsonb),
('mcq', 3, 0, 'بعد امتلاء 3p بستة إلكترونات (18 إلكترونًا) يدخل الإلكترون التاسع عشر المستوى 4s لأن طاقته أقل من طاقة 3d، فالتوزيع 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹.', '["","المستوى 4s أقل طاقة من 3d، لذلك يُملأ قبله ولا يدخل الإلكترون الأخير 3d.","المستوى 3p لم يمتلئ في هذا التوزيع مع أن 4s امتلأ؛ والصحيح امتلاء 3p قبل 4s.","مجموع إلكترونات هذا التوزيع 20 وهو توزيع الكالسيوم، وليس البوتاسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-10-18T03:27:04.770Z"}'::jsonb),
