('mcq', 5, 3, 'مجموع الإلكترونات في التوزيع 2 + 2 + 6 + 2 + 6 + 2 + 2 = 22، وهو العدد الذري للتيتانيوم Ti.', '["السكانديوم Sc عدده الذري 21، وتوزيعه ينتهي بـ 4s² 3d¹.","الفاناديوم V عدده الذري 23، وتوزيعه ينتهي بـ 4s² 3d³.","الكالسيوم Ca عدده الذري 20، وتوزيعه ينتهي بـ 4s² دون إلكترونات في 3d.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.770Z"}'::jsonb),
