('mcq', 7, 1, 'توزيع الكلور 1s² 2s² 2p⁶ 3s² 3p⁵؛ فبعد 12 إلكترونًا في المستويات 1s و2s و2p و3s يبقى 17 − 12 = 5 إلكترونات في المستوى 3p.', '["العدد 6 هو سعة 3p القصوى، وهو توزيع الأرجون، أما الكلور فيحتوي 3p على 5 إلكترونات.","","العدد 7 هو عدد إلكترونات المستوى الرئيس الثالث كله (3s² 3p⁵) وليس المستوى 3p وحده.","العدد 3 لا يوافق التوزيع؛ فالمستوى 3s يمتلئ بإلكترونين ثم يدخل الباقي 3p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.771Z"}'::jsonb),
('essay', 1, null::int, null, null, 'Mg: 1s² 2s² 2p⁶ 3s² (مجموع الإلكترونات 12). Cl: 1s² 2s² 2p⁶ 3s² 3p⁵ (مجموع الإلكترونات 17). تُملأ المستويات بتسلسل الطاقة 1s ثم 2s ثم 2p ثم 3s ثم 3p.', '["Mg: 1s² 2s² 2p⁶ 3s²","Cl: 1s² 2s² 2p⁶ 3s² 3p⁵","الالتزام بتسلسل مستويات الطاقة","مجموع الإلكترونات يساوي العدد الذري"]'::jsonb, '["Mg: 2 + 2 + 6 + 2 = 12 إلكترونًا فالتوزيع 1s² 2s² 2p⁶ 3s²","Cl: 2 + 2 + 6 + 2 = 12 والباقي 17 − 12 = 5 إلكترونات في 3p"]'::jsonb, '[{"element":"توزيع المغنسيوم صحيح","marks":2},{"element":"توزيع الكلور صحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"توزيعان صحيحان بتسلسل الطاقة الصحيح"},{"level":"2–3 درجات","description":"توزيع واحد صحيح، أو توزيعان فيهما خطأ بسيط في عدد الإلكترونات"},{"level":"1 درجة","description":"تسلسل المستويات صحيح دون عدد صحيح من الإلكترونات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تجاوز سعة المستوى الثانوي (3s³ مثلًا)","ملء 3p قبل امتلاء 3s","عدم مطابقة مجموع الإلكترونات للعدد الذري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.771Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Fe: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶. Cu: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹ 3d¹⁰. باتباع تسلسل الملء كان المتوقع للنحاس 4s² 3d⁹، لكن التوزيع الصحيح 4s¹ 3d¹⁰؛ إذ ينتقل إلكترون من المستوى 4s إلى المستوى 3d فيمتلئ 3d بعشرة إلكترونات ويصبح التوزيع أكثر استقرارًا، وهو أحد استثناءات التوزيع الإلكتروني.', '["Fe: ...4s² 3d⁶","Cu: ...4s¹ 3d¹⁰","المتوقع للنحاس 4s² 3d⁹","انتقال إلكترون من 4s إلى 3d","التوزيع الناتج أكثر استقرارًا (استثناء)"]'::jsonb, '["Fe: 2 + 2 + 6 + 2 + 6 + 2 + 6 = 26","Cu: 2 + 2 + 6 + 2 + 6 + 1 + 10 = 29"]'::jsonb, '[{"element":"توزيع الحديد صحيح","marks":2},{"element":"توزيع النحاس الصحيح (4s¹ 3d¹⁰)","marks":2},{"element":"تفسير الاختلاف بانتقال إلكترون واستقرار التوزيع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توزيعان صحيحان مع تفسير صحيح للاستثناء"},{"level":"3–4 درجات","description":"توزيعان صحيحان مع تفسير ناقص، أو توزيع واحد صحيح مع تفسير"},{"level":"1–2 درجة","description":"توزيع واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة توزيع النحاس 4s² 3d⁹","ملء 3d قبل 4s في الحديد","تفسير الاختلاف بخطأ في الحساب بدل الاستقرار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.771Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) مجموع الإلكترونات 2 + 2 + 6 + 2 + 1 = 13، فالعدد الذري 13 والعنصر الألومنيوم Al، وتوزيعه يتبع تسلسل الملء. (ب) مجموع الإلكترونات 2 + 2 + 6 + 2 + 6 + 1 + 5 = 24، فالعدد الذري 24 والعنصر الكروم Cr. والتوزيع (ب) هو الحالة الاستثنائية؛ إذ يكون في 4s إلكترون واحد وفي 3d خمسة إلكترونات بدل 4s² 3d⁴.', '["(أ): العدد الذري 13 والعنصر Al","(ب): العدد الذري 24 والعنصر Cr","(ب) حالة استثنائية","التوزيع المتوقع للكروم 4s² 3d⁴"]'::jsonb, '["(أ) 2 + 2 + 6 + 2 + 1 = 13 فالعنصر Al","(ب) 2 + 2 + 6 + 2 + 6 + 1 + 5 = 24 فالعنصر Cr","الكروم استثناء: 4s¹ 3d⁵ بدل 4s² 3d⁴"]'::jsonb, '[{"element":"(أ) العدد الذري 13 والرمز Al","marks":1},{"element":"(ب) العدد الذري 24 والرمز Cr","marks":1},{"element":"تحديد (ب) حالة استثنائية","marks":1},{"element":"تعليل الاستثناء بمقارنته بالتوزيع المتوقع 4s² 3d⁴","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العنصران صحيحان مع العدد الذري، وتحديد الاستثناء وتعليله"},{"level":"2–3 درجات","description":"العنصران صحيحان دون تحديد الاستثناء، أو عنصر واحد مع الاستثناء"},{"level":"1 درجة","description":"عنصر واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع الأسس بصورة خاطئة","اعتبار توزيع الكروم غير صحيح لأنه يخالف تسلسل الملء","الخلط بين Cr وMn"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.771Z"}'::jsonb)
