('mcq', 2, 'تكتسب ذرات العناصر F وCl وBr وI إلكترونًا واحدًا عند تفاعلها. ما عدد تأكسد كل منها؟', null, '["+1","−1","−2","+7"]'::jsonb, 'فهم', 'ربط اكتساب الإلكترونات بعدد التأكسد', 'سهل', 'الكتاب ص 115 — أعداد تأكسد بعض مجموعات العناصر'),
('mcq', 3, 'ما عدد تأكسد الأكسجين O وهو من عناصر المجموعة 16؟', null, '["+2","+1","−3","−2"]'::jsonb, 'تذكر', 'تذكر عدد تأكسد', 'سهل', 'الكتاب ص 115 — أعداد تأكسد بعض مجموعات العناصر'),
('mcq', 4, 'أيّ المتتاليات الآتية تمثّل أعداد تأكسد عناصر المجموعات 1 و2 و15 على الترتيب؟', null, '["+1 ، +2 ، −3","+1 ، +2 ، +3","−1 ، −2 ، −3","+1 ، −2 ، −3"]'::jsonb, 'تذكر', 'تذكر أعداد تأكسد عدة مجموعات', 'متوسط', 'الكتاب ص 115 — أعداد تأكسد بعض مجموعات العناصر'),
('mcq', 5, 'كيف تُعرف أعداد تأكسد الفلزات الانتقالية التي لها أكثر من عدد تأكسد؟', null, '["بحسب رقم المجموعة فقط","عدد تأكسدها دائمًا +2","بالشحنة الظاهرة على الأيون","عدد تأكسدها دائمًا −1"]'::jsonb, 'فهم', 'فهم تحديد عدد التأكسد للفلزات الانتقالية', 'صعب', 'الكتاب ص 115 — أيونات بعض العناصر'),
('mcq', 6, 'أيّ الأزواج الآتية يمثّل عددي التأكسد المحتملين لأيونات الحديد Fe؟', null, '["+1 و +2","+2 و +3","+3 و +4","+1 و +3"]'::jsonb, 'تذكر', 'تذكر أعداد تأكسد فلز انتقالي', 'متوسط', 'الكتاب ص 115 — أيونات بعض العناصر'),
('mcq', 7, 'ما المقصود بعدد التأكسد لذرة عنصر في أثناء التفاعل؟', null, '["عدد البروتونات الموجودة في نواة ذرة العنصر","عدد الإلكترونات الموجودة في مستوى الطاقة الأخير فقط","عدد الذرات المرتبطة بذرة العنصر في الجزيء","عدد الإلكترونات التي تفقدها الذرة أو تكتسبها أو تشارك بها"]'::jsonb, 'تذكر', 'تذكر تعريف', 'متوسط', 'الكتاب ص 115 — كتابة الصيغ الكيميائية (عدد التأكسد)'),
('essay', 1, 'اذكر عدد التأكسد لكل من العناصر الآتية: Li وCa وP وS وBr.', null, null, 'تذكر', 'تذكر أعداد التأكسد', 'متوسط', 'الكتاب ص 115 — أعداد تأكسد بعض مجموعات العناصر'),
('essay', 2, 'لماذا يصعب تحديد عدد تأكسد الحديد والنحاس بحسب رقم المجموعة كما يُفعل مع الصوديوم؟ وكيف تُعرف أعداد تأكسدهما؟ اذكر عددي تأكسد محتملين لكل منهما.', null, null, 'فهم', 'تعليل وتوضيح', 'صعب', 'الكتاب ص 115 — أيونات بعض العناصر'),
('essay', 3, 'عرّف عدد التأكسد، ثم حدّد عدد تأكسد كل عنصر في المركبات الآتية اعتمادًا على مجموعة العنصر: Na₂S وCaCl₂ وMg₃N₂.', null, null, 'تطبيق', 'تعريف وتطبيق', 'صعب', 'الكتاب ص 115 — عدد التأكسد وأعداد تأكسد المجموعات')
