from (values
('mcq', 1, 2, 'عدد تأكسد عناصر المجموعة 2 (Be وMg وCa وSr وBa) يساوي +2، فعدد تأكسد المغنسيوم +2.', '["العدد +1 عدد تأكسد عناصر المجموعة 1 وليس المجموعة 2.","العدد −2 عدد تأكسد عناصر المجموعة 16 (O وS وSe وTe)، أما الفلزات فأعداد تأكسدها موجبة.","","العدد −1 عدد تأكسد عناصر المجموعة 17، والمغنسيوم فلز يفقد إلكترونين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-18T03:27:04.771Z"}'::jsonb),
('mcq', 2, 1, 'عناصر المجموعة 17 تكتسب إلكترونًا واحدًا، فعدد تأكسد كل منها −1.', '["الإشارة الموجبة تعني فقد الإلكترونات، وهذه العناصر تكتسب إلكترونًا فعدد تأكسدها سالب.","","العدد −2 يخص عناصر المجموعة 16 التي تكتسب إلكترونين.","العدد +7 يمثل عدد إلكترونات التكافؤ في ذرة العنصر، وليس عدد تأكسده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
