('mcq', 4, 0, 'أعداد التأكسد: المجموعة 1 تساوي +1، والمجموعة 2 تساوي +2، والمجموعة 15 تساوي −3.', '["","عناصر المجموعة 15 (N وP وAs) أعداد تأكسدها −3 وليست +3.","عناصر المجموعتين 1 و2 فلزات تفقد إلكترونات، فأعداد تأكسدها موجبة وليست سالبة.","عناصر المجموعة 2 أعداد تأكسدها +2 وليست −2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('mcq', 5, 2, 'لمعظم الفلزات الانتقالية أكثر من عدد تأكسد محتمل، لذلك تُعرف أعداد تأكسدها بالشحنة الظاهرة على الأيون، مثل Fe²⁺ وFe³⁺.', '["رقم المجموعة لا يحدد عدد التأكسد لهذه الفلزات؛ لأن لها أكثر من عدد تأكسد محتمل.","ليس لجميعها +2؛ فالحديد له +2 و+3 والنحاس له +1 و+2.","","الفلزات تفقد إلكترونات فأعداد تأكسدها موجبة وليست −1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('mcq', 6, 1, 'للحديد أيونان شائعان هما Fe²⁺ وFe³⁺، فعددا تأكسده المحتملان +2 و+3.', '["العددان +1 و+2 يخصان النحاس Cu (Cu⁺ وCu²⁺).","","العدد +4 ليس من أعداد تأكسد أيونات الحديد الشائعة؛ فهو من أعداد تأكسد القصدير Sn والرصاص Pb.","العدد +1 ليس من أعداد تأكسد أيونات الحديد؛ فأيوناته Fe²⁺ وFe³⁺ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('mcq', 7, 3, 'عدد التأكسد هو عدد الإلكترونات التي تفقدها ذرة العنصر أو تكتسبها أو تشارك بها في أثناء التفاعل.', '["عدد البروتونات في النواة هو العدد الذري، وليس عدد التأكسد.","عدد إلكترونات مستوى الطاقة الأخير يرتبط بالتوزيع الإلكتروني، أما عدد التأكسد فيتعلق بفقد الإلكترونات أو اكتسابها أو المشاركة بها.","عدد الذرات المرتبطة لا يعبّر عن الإلكترونات التي تفقدها الذرة أو تكتسبها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الليثيوم Li من المجموعة 1 وعدد تأكسده +1. الكالسيوم Ca من المجموعة 2 وعدد تأكسده +2. الفوسفور P من المجموعة 15 وعدد تأكسده −3. الكبريت S من المجموعة 16 وعدد تأكسده −2. البروم Br من المجموعة 17 وعدد تأكسده −1.', '["Li: +1","Ca: +2","P: −3","S: −2","Br: −1"]'::jsonb, '[]'::jsonb, '[{"element":"عدد تأكسد Li","marks":1},{"element":"عدد تأكسد Ca","marks":1},{"element":"عدد تأكسد P","marks":1},{"element":"عدد تأكسد S","marks":1},{"element":"عدد تأكسد Br","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"أعداد التأكسد الخمسة صحيحة بإشاراتها"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة أعداد صحيحة"},{"level":"1–2 درجة","description":"عدد أو عددان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة العدد دون الإشارة أو بإشارة خاطئة","الخلط بين المجموعتين 15 و16 (−3 و−2)","كتابة +2 للكبريت قياسًا على الكالسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الصوديوم من المجموعة 1 وله عدد تأكسد واحد هو +1. أما الحديد والنحاس فمن الفلزات الانتقالية التي لها أكثر من عدد تأكسد محتمل، فلا يكفي رقم المجموعة لتحديده. وتُعرف أعداد تأكسدها بالشحنة الظاهرة على الأيون. فللحديد الأيونان Fe²⁺ وFe³⁺، أي أن عددي تأكسده +2 و+3. وللنحاس الأيونان Cu⁺ وCu²⁺، أي أن عددي تأكسده +1 و+2.', '["الصوديوم له عدد تأكسد واحد (+1)","الفلزات الانتقالية لها أكثر من عدد تأكسد","تُعرف بالشحنة الظاهرة على الأيون","الحديد: +2 و+3","النحاس: +1 و+2"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل الصعوبة بتعدد أعداد التأكسد","marks":1},{"element":"ذكر أن العدد يُعرف بالشحنة الظاهرة على الأيون","marks":1},{"element":"عددا تأكسد الحديد (+2 و+3)","marks":1},{"element":"عددا تأكسد النحاس (+1 و+2)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح وطريقة التحديد وعددا الحديد وعددا النحاس"},{"level":"2–3 درجات","description":"تعليل أو طريقة التحديد مع عددي أحد الفلزين"},{"level":"1 درجة","description":"ذكر عدد تأكسد واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن للحديد عدد تأكسد واحدًا هو +2","الخلط بين أعداد تأكسد الحديد والنحاس","عدم ذكر الشحنة الظاهرة على الأيون طريقةً للتحديد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.772Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد التأكسد هو عدد الإلكترونات التي تفقدها ذرة العنصر أو تكتسبها أو تشارك بها في أثناء التفاعل. في Na₂S: الصوديوم من المجموعة 1 (+1) والكبريت من المجموعة 16 (−2). في CaCl₂: الكالسيوم من المجموعة 2 (+2) والكلور من المجموعة 17 (−1). في Mg₃N₂: المغنسيوم من المجموعة 2 (+2) والنيتروجين من المجموعة 15 (−3).', '["تعريف عدد التأكسد","Na: +1 وS: −2","Ca: +2 وCl: −1","Mg: +2 وN: −3"]'::jsonb, '["Na₂S: 2 × (+1) + (−2) = 0","CaCl₂: (+2) + 2 × (−1) = 0","Mg₃N₂: 3 × (+2) + 2 × (−3) = 0"]'::jsonb, '[{"element":"تعريف عدد التأكسد","marks":1},{"element":"أعداد تأكسد Na₂S","marks":1},{"element":"أعداد تأكسد CaCl₂","marks":1},{"element":"أعداد تأكسد Mg₃N₂","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وأعداد تأكسد صحيحة للمركبات الثلاثة"},{"level":"2–3 درجات","description":"تعريف صحيح مع مركب أو مركبين صحيحين، أو المركبات الثلاثة دون تعريف"},{"level":"1 درجة","description":"تعريف صحيح فقط أو مركب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس إشارات أعداد التأكسد","اعتبار عدد التأكسد مساويًا لعدد الذرات في الصيغة","الخلط بين عددي تأكسد الكبريت والنيتروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.773Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
