from (values
('mcq', 1, 3, 'السهم (→) يفصل المتفاعلات (على يساره) عن النواتج (على يمينه)، ويدل على أن التفاعل يسير في اتجاه واحد.', '["الإشارة (+) تفصل بين مادتين أو أكثر من المتفاعلات أو من النواتج، لا بين المتفاعلات والنواتج.","السهم المزدوج ⇌ يدل على تفاعل عكسي يسير في الاتجاهين، لا في اتجاه واحد.","(aq) رمز للمحلول المائي، وهو يبين حالة المادة ولا يفصل المتفاعلات عن النواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.774Z"}'::jsonb),
('mcq', 2, 0, 'الرمز (aq) يدل على أن المادة مذابة في الماء، أي أنها في محلول مائي.', '["","الحالة الصلبة يرمز لها بالرمز (s).","الحالة السائلة يرمز لها بالرمز (l).","الحالة الغازية يرمز لها بالرمز (g)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.774Z"}'::jsonb),
('mcq', 3, 2, 'السهم المزدوج ⇌ يفصل المتفاعلات عن النواتج، ويشير إلى وجود تفاعل في الاتجاه المعاكس، أي أن التفاعل عكسي.', '["التسخين يدل عليه الرمز Δ فوق السهم، لا السهم المزدوج.","عدم حدوث التفاعل يدل عليه الرمز NR، لا السهم المزدوج.","","الحالة الغازية يدل عليها الرمز (g) المكتوب أسفل الصيغة، لا السهم المزدوج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.774Z"}'::jsonb),
('mcq', 4, 1, 'توضع رموز الحالة الفيزيائية بين قوسين وتُكتب أسفل صيغة كل عنصر أو مركب في التفاعل، لأنها تعطي أدلة على كيفية حدوث التفاعل.', '["رموز الحالة لا تُكتب فوق الصيغة، بل أسفلها.","","الذي يُكتب فوق السهم هو الرمز Δ الدال على التسخين، أما رموز الحالة فمكانها أسفل الصيغة.","المعامل يُكتب قبل الصيغة، أما رمز الحالة فيُكتب بعد الصيغة وأسفلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('mcq', 5, 3, 'الرمز Δ فوق السهم يدل على أن التفاعل يحتاج إلى تسخين المتفاعلات، كما في تفكك نترات الأمونيوم عند تسخينها.', '["الرمز Δ يدل على التسخين لا على التبريد.","المحلول المائي يدل عليه الرمز (aq) المكتوب أسفل الصيغة.","التفاعل العكسي يدل عليه السهم المزدوج ⇌.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('mcq', 6, 0, 'يُستخدم الرمز NR عادة للدلالة على عدم حدوث تفاعل كيميائي؛ فالفضة تقع بعد النحاس في سلسلة النشاط الكيميائي ولا تحل محله.', '["","تكوّن الراسب يُمثَّل بالرمز (s) أسفل صيغة الناتج، وليس بالرمز NR.","التفاعل العكسي يدل عليه السهم المزدوج ⇌، وليس الرمز NR.","تكوّن الغاز يُمثَّل بالرمز (g) أسفل صيغة الناتج، وليس بالرمز NR."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('mcq', 7, 1, 'رمز الحالة السائلة هو (l)، لذلك تمثل H₂O(l) الماء السائل.', '["H₂O(s) تمثل الماء الصلب (الجليد) لأن الرمز (s) يدل على الحالة الصلبة.","","H₂O(g) تمثل بخار الماء لأن الرمز (g) يدل على الحالة الغازية.","H₂O(aq) تعني ماءً مذابًا فيه مادة، أي محلولًا مائيًّا، وليس ماءً سائلًا نقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('essay', 1, null::int, null, null, '(+): تفصل بين مادتين أو أكثر من المتفاعلات أو من النواتج. (→): تفصل المتفاعلات عن النواتج. (⇌): تفصل المتفاعلات عن النواتج وتدل على تفاعل عكسي يحدث في الاتجاهين. (s): المادة في الحالة الصلبة. (l): المادة في الحالة السائلة. (g): المادة في الحالة الغازية. (aq): المادة في محلول مائي.', '["(+) تفصل بين المتفاعلات أو بين النواتج","(→) تفصل المتفاعلات عن النواتج","(⇌) تفاعل عكسي","(s) الحالة الصلبة","(l) الحالة السائلة","(g) الحالة الغازية","(aq) المحلول المائي"]'::jsonb, '[]'::jsonb, '[{"element":"دلالة (+)","marks":1},{"element":"دلالة (→)","marks":1},{"element":"دلالة (⇌)","marks":1},{"element":"دلالة (s)","marks":1},{"element":"دلالة (l)","marks":1},{"element":"دلالة (g)","marks":1},{"element":"دلالة (aq)","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"ذكر دلالة الرموز السبعة كلها ذكرًا صحيحًا"},{"level":"5–6 درجات","description":"ذكر دلالة خمسة أو ستة رموز ذكرًا صحيحًا"},{"level":"1–4 درجات","description":"ذكر دلالة رمز إلى أربعة رموز ذكرًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن (aq) تعني حالة غازية أو سائلة","عدم التمييز بين السهم → والسهم المزدوج ⇌","عدّ إشارة (+) فاصلة بين المتفاعلات والنواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السهم → يفصل المتفاعل CaCO₃ (على يساره) عن الناتجين (على يمينه) ويدل على اتجاه التفاعل. إشارة (+) تفصل بين الناتجين CaO وCO₂. الرمز (s) يدل على أن CaCO₃ وCaO صلبتان. الرمز (g) يدل على أن CO₂ غاز. الرمز Δ يدل على أن التفاعل يحتاج إلى تسخين.', '["السهم يفصل المتفاعل عن الناتجين","إشارة (+) تفصل بين الناتجين","(s) الحالة الصلبة لـ CaCO₃ وCaO","(g) الحالة الغازية لـ CO₂","Δ تسخين"]'::jsonb, '[]'::jsonb, '[{"element":"دلالة السهم","marks":1},{"element":"دلالة إشارة (+)","marks":1},{"element":"دلالة (s) مع تحديد المادتين الصلبتين","marks":1},{"element":"دلالة (g) مع تحديد CO₂","marks":1},{"element":"دلالة Δ","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"بيان دلالة الرموز الخمسة بيانًا صحيحًا مع ربطها بمواد المعادلة"},{"level":"3–4 درجات","description":"بيان دلالة ثلاثة أو أربعة رموز بيانًا صحيحًا"},{"level":"1–2 درجة","description":"بيان دلالة رمز أو رمزين بيانًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Δ تدل على تبريد المتفاعلات","عدّ (g) دليلًا على أن CaO غاز","إغفال أن إشارة (+) هنا تفصل بين ناتجين لا بين متفاعلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.775Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: Zn(l) والصحيح Zn(s) لأن الخارصين صلب. الخطأ الثاني: HCl(g) والصحيح HCl(aq) لأن الحمض في محلول مائي. الخطأ الثالث: السهم المزدوج ⇌ والصحيح → لأن التفاعل يسير في اتجاه واحد. الخطأ الرابع: H₂(aq) والصحيح H₂(g) لأن الهيدروجين غاز. والمعادلة الصحيحة: Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g).', '["Zn(l) خطأ والصحيح Zn(s)","HCl(g) خطأ والصحيح HCl(aq)","⇌ خطأ والصحيح →","H₂(aq) خطأ والصحيح H₂(g)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ رمز حالة الخارصين وتصحيحه","marks":1},{"element":"تحديد خطأ رمز حالة الحمض وتصحيحه","marks":1},{"element":"تحديد خطأ السهم وتصحيحه","marks":1},{"element":"تحديد خطأ رمز حالة الهيدروجين وتصحيحه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الأخطاء الأربعة وتصحيحها كلها"},{"level":"2–3 درجات","description":"تحديد خطأين أو ثلاثة وتصحيحها"},{"level":"1 درجة","description":"تحديد خطأ واحد وتصحيحه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء السهم المزدوج رغم أن التفاعل في اتجاه واحد","كتابة (l) للفلز الصلب","عدّ HCl غازًا بدل محلول مائي رغم ذكر الحمض المائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.776Z"}'::jsonb)
