('mcq', 6, 'عند كتابة صيغة المركب الناتج عن اتحاد Mg²⁺ وO²⁻ تُبدَّل أعداد التأكسد ثم يُقسم على العامل المشترك. ما الصيغة النهائية للمركب؟', null, '["MgO","Mg₂O₂","Mg₂O","MgO₂"]'::jsonb, 'فهم', 'القسمة على العامل المشترك', 'سهل', 'الكتاب ص 116 — خطوات كتابة صيغة المركب الأيوني'),
('mcq', 7, 'أعداد التأكسد لعنصرين في أكسيد الرصاص IV مبينة أدناه. ما صيغة هذا المركب؟', '{"headers":["العنصر","عدد التأكسد"],"rows":[["Pb","4+"],["O","2−"]]}'::jsonb, '["PbO","Pb₂O","PbO₂","Pb₄O₂"]'::jsonb, 'تطبيق', 'كتابة صيغة من جدول أعداد التأكسد', 'متوسط', 'الكتاب ص 115، 116 — الجدول 4-4 وخطوات كتابة صيغة المركب الأيوني'),
('essay', 1, 'اكتب الصيغة الكيميائية لكل مركب أيوني مما يأتي مبيّنًا أعداد التأكسد وخطوات التبديل: (أ) بروميد الألومنيوم (Al³⁺ وBr⁻)، (ب) كبريتات الصوديوم (Na⁺ وSO₄²⁻)، (جـ) هيدروكسيد الحديد III (Fe³⁺ وOH⁻)، (د) فوسفات الكالسيوم (Ca²⁺ وPO₄³⁻).', null, null, 'تطبيق', 'كتابة صيغ مركبات أيونية', 'متوسط', 'الكتاب ص 116 — خطوات كتابة صيغة المركب الأيوني'),
('essay', 2, 'اشرح بخطوات الكتابة المتتابعة كيف تحصل على صيغة كل من المركبين الناتجين عن اتحاد Al³⁺ مع OH⁻ وعن اتحاد Mg²⁺ مع Cl⁻، ثم وضّح لماذا يوضع OH بين قوسين في صيغة المركب الأول ولا توضع الأقواس في المركب الثاني.', null, null, 'فهم', 'شرح خطوات كتابة صيغة', 'متوسط', 'الكتاب ص 116 — خطوات كتابة صيغة المركب الأيوني'),
('essay', 3, 'يكوّن النحاس أيونين شائعين هما Cu⁺ وCu²⁺. اكتب صيغة المركب الناتج عن اتحاد كل أيون منهما مع أيون الأكسيد O²⁻، وصيغة المركب الناتج عن اتحاد كل أيون منهما مع أيون النترات NO₃⁻، ثم فسّر لماذا تختلف الصيغتان في كل حالة.', null, null, 'تحليل', 'مقارنة صيغ لعنصر متعدد أعداد التأكسد', 'صعب', 'الكتاب ص 115، 116 — الجدول 4-4 وخطوات كتابة صيغة المركب الأيوني')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
