select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'بتبديل أعداد التأكسد: الماغنسيوم 2+ يعطي الرقم 2 لأيون النترات، والنترات 1− تعطي الرقم 1 للماغنسيوم، فتكون الصيغة Mg(NO₃)₂، ويوضع أيون النترات بين قوسين لأن عدده أكثر من واحد. تحقق: 2+ و2×(1−) = 0.', '["MgNO₃ شحنته الكلية 1+ (2+ و1−)، فالمركب غير متعادل؛ لم تُبدَّل أعداد التأكسد.","","Mg₂NO₃ يعطي شحنة كلية 3+ (4+ و1−)، وهو ناتج عن تبديل خاطئ للأرقام.","Mg₂(NO₃)₃ يعطي شحنة كلية 1+ (4+ و3−)، فهو غير متعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.776Z"}'::jsonb),
('mcq', 2, 3, 'يُبدَّل عدد تأكسد الحديد (3) إلى رقم سفلي للأكسجين، وعدد تأكسد الأكسجين (2) إلى رقم سفلي للحديد، فتكون الصيغة Fe₂O₃؛ وتحقق التعادل: 2×(3+) و3×(2−) = 0.', '["FeO يناسب الحديد II (Fe²⁺) مع O²⁻، أما Fe³⁺ فيلزم أيونان منه لكل ثلاثة أكسيدات.","Fe₃O₂ ناتج عن كتابة عدد التأكسد كرقم سفلي لنفس العنصر دون تبديل، وشحنته الكلية 5+.","FeO₃ يعطي شحنة كلية 3− (3+ و6−)، لأن الرقم 3 وُضع للأكسجين فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.776Z"}'::jsonb),
('mcq', 3, 0, 'يُبدَّل العددان فيصبح للألومنيوم الرقم 2 ولأيون الكبريتات الرقم 3، ويوضع الأيون بين قوسين: Al₂(SO₄)₃. تحقق: 2×(3+) = 6+ و3×(2−) = 6−.', '["","AlSO₄ شحنته الكلية 1+ (3+ و2−)، فهو غير متعادل.","Al₃(SO₄)₂ ناتجة عن كتابة كل عدد تأكسد رقمًا سفليًّا للعنصر نفسه دون تبديل؛ شحنتها الكلية 5+.","Al(SO₄)₃ يعطي شحنة كلية 3− (3+ و6−)، لأن الرقم 2 لم يُوضع للألومنيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.777Z"}'::jsonb),
('mcq', 4, 2, 'يُعطى عدد تأكسد الفوسفات (3) رقمًا سفليًّا للصوديوم، وعدد تأكسد الصوديوم (1) لا يُكتب للفوسفات، فتكون الصيغة Na₃PO₄ دون أقواس لأن أيون الفوسفات واحد.', '["NaPO₄ شحنته الكلية 2− (1+ و3−)، فهو غير متعادل.","Na(PO₄)₃ شحنته الكلية 8− (1+ و9−)، لأن الرقم 3 وُضع للفوسفات بدل الصوديوم.","","Na₃(PO₄)₃ شحنته الكلية 6− (3+ و9−)، ويحوي ثلاثة أيونات فوسفات بلا داعٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.777Z"}'::jsonb),
('mcq', 5, 1, 'شحنة الأمونيوم 1+ وشحنة الكبريتات 2−، فيلزم أيونا أمونيوم لكل أيون كبريتات: (NH₄)₂SO₄. ويوضع أيون الأمونيوم بين قوسين لأن عدده أكثر من واحد، ولا يُوضع أيون الكبريتات بين قوسين لأن عدده واحد.', '["NH₄SO₄ شحنته الكلية 1− (1+ و2−)، فهو غير متعادل.","","NH₄(SO₄)₂ شحنته الكلية 3− (1+ و4−)، لأن الرقم 2 وُضع للكبريتات بدل الأمونيوم.","(NH₄)₂(SO₄)₂ متعادل لكنه ليس بأبسط نسبة؛ إذ يُقسم على العامل المشترك 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.777Z"}'::jsonb),
('mcq', 6, 0, 'بتبديل العددين تنتج Mg₂O₂، ثم يُقسم على العامل المشترك 2 فتكون الصيغة MgO؛ فالنسبة 1:1 هي الأبسط، والشحنتان 2+ و2− متعادلتان.', '["","Mg₂O₂ هي ناتج التبديل قبل القسمة على العامل المشترك 2، وليست بأبسط نسبة.","Mg₂O شحنته الكلية 2+ (4+ و2−)، فهو غير متعادل.","MgO₂ شحنته الكلية 2− (2+ و4−)، فهو غير متعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.777Z"}'::jsonb),
('mcq', 7, 2, 'بتبديل العددين تنتج Pb₂O₄، ثم يُقسم على العامل المشترك 2 فتكون الصيغة PbO₂. تحقق: 4+ و2×(2−) = 0.', '["PbO يناسب الرصاص II (Pb²⁺)، أما الرصاص IV فيحتاج ذرتي أكسجين.","Pb₂O شحنته الكلية 6+ (8+ و2−)، فهو غير متعادل.","","Pb₄O₂ ناتج عن كتابة كل عدد تأكسد رقمًا سفليًّا للعنصر نفسه دون تبديل؛ شحنته الكلية 12+."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.777Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Al³⁺ وBr⁻: نبدّل 3 و1 فتكون AlBr₃. (ب) Na⁺ وSO₄²⁻: نبدّل 1 و2 فتكون Na₂SO₄ (أيون الكبريتات واحد فلا أقواس). (جـ) Fe³⁺ وOH⁻: نبدّل 3 و1 فتكون Fe(OH)₃ (ثلاثة أيونات هيدروكسيد فتوضع بين قوسين). (د) Ca²⁺ وPO₄³⁻: نبدّل 2 و3 فتكون Ca₃(PO₄)₂ (أيونا فوسفات فتوضعان بين قوسين).', '["AlBr₃","Na₂SO₄","Fe(OH)₃","Ca₃(PO₄)₂","تبديل أعداد التأكسد وكتابة الأيون العديد الذرات بين قوسين عند وجود أكثر من أيون واحد"]'::jsonb, '["كتابة الأيون الموجب يسارًا والسالب يمينًا مع عدد تأكسد كل منهما","تبديل أعداد التأكسد بين شقّي المركب","القسمة على العامل المشترك إن وُجد","وضع الأيون العديد الذرات بين قوسين إذا زاد عدده على واحد"]'::jsonb, '[{"element":"AlBr₃ بخطوات صحيحة","marks":2},{"element":"Na₂SO₄ بخطوات صحيحة","marks":2},{"element":"Fe(OH)₃ بخطوات صحيحة مع الأقواس","marks":2},{"element":"Ca₃(PO₄)₂ بخطوات صحيحة مع الأقواس","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"الصيغ الأربع صحيحة مع خطوات التبديل والأقواس"},{"level":"5–7 درجات","description":"ثلاث صيغ صحيحة أو أربع صيغ مع نقص في الخطوات"},{"level":"1–4 درجات","description":"صيغة أو صيغتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة FeOH₃ بدل Fe(OH)₃ بإغفال الأقواس","كتابة Ca₂(PO₄)₃ بتبديل الأرقام في الاتجاه الخطأ","كتابة NaSO₄ بإهمال تبديل عدد تأكسد الكبريتات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.778Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوة الأولى: نكتب الأيون الموجب يسارًا والسالب يمينًا: Al OH وMg Cl. الثانية: نكتب عدد التأكسد أسفل كل منهما: Al 3 وOH 1، وMg 2 وCl 1. الثالثة: نبدّل الأعداد بين شقّي المركب فيصبح عدد Al هو 1 وعدد OH هو 3، وعدد Mg هو 1 وعدد Cl هو 2، ولا يوجد عامل مشترك. فتكون الصيغتان Al(OH)₃ وMgCl₂. يوضع OH بين قوسين لأنه أيون عديد الذرات وعدده في المركب ثلاثة؛ أما Cl فأيون أحادي الذرة فلا يحتاج إلى أقواس.', '["كتابة الأيون الموجب يسارًا والسالب يمينًا","كتابة أعداد التأكسد (Al 3، OH 1، Mg 2، Cl 1)","تبديل الأعداد والقسمة على العامل المشترك إن وُجد","الصيغتان Al(OH)₃ وMgCl₂","الأقواس لأن OH أيون عديد الذرات عدده أكثر من واحد"]'::jsonb, '["Al³⁺ وOH⁻: أعداد التأكسد 3 و1","تبديل العددين: Al₁(OH)₃ فتكتب Al(OH)₃","Mg²⁺ وCl⁻: أعداد التأكسد 2 و1","تبديل العددين: Mg₁Cl₂ فتكتب MgCl₂"]'::jsonb, '[{"element":"ترتيب الأيونين وكتابة أعداد التأكسد","marks":1},{"element":"تبديل الأعداد بطريقة صحيحة","marks":1},{"element":"الصيغة Al(OH)₃","marks":1},{"element":"الصيغة MgCl₂","marks":1},{"element":"تعليل وضع OH بين قوسين دون Cl","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات صحيحة، والصيغتان صحيحتان، وتعليل الأقواس"},{"level":"3–4 درجات","description":"الصيغتان صحيحتان مع نقص في الخطوات أو التعليل"},{"level":"1–2 درجة","description":"صيغة واحدة صحيحة أو خطوات ناقصة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة AlOH₃ دون أقواس","كتابة Mg₂Cl بتبديل الأرقام في الاتجاه الخطأ","التعليل بأن الأقواس تُستخدم لأن العدد 3 كبير لا لأن الأيون عديد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.778Z"}'::jsonb),
('essay', 3, null::int, null, null, 'Cu⁺ مع O²⁻: نبدّل 1 و2 فتكون Cu₂O. Cu²⁺ مع O²⁻: نبدّل 2 و2 فتكون Cu₂O₂ ثم نقسم على 2 فتكون CuO. Cu⁺ مع NO₃⁻: نبدّل 1 و1 فتكون CuNO₃. Cu²⁺ مع NO₃⁻: نبدّل 2 و1 فتكون Cu(NO₃)₂. تختلف الصيغتان لأن عدد تأكسد النحاس مختلف (1+ و2+)، فتختلف أعداد الأيونات اللازمة لتعادل شحنة الأيون السالب، ولذلك يحتاج الأيون Cu⁺ إلى أيونين لتعادل شحنة O²⁻ بينما يحتاج Cu²⁺ إلى أيون واحد.', '["Cu₂O","CuO بعد القسمة على العامل المشترك","CuNO₃","Cu(NO₃)₂ مع الأقواس","التفسير: اختلاف عدد تأكسد النحاس يغير عدد الأيونات اللازمة للتعادل"]'::jsonb, '["Cu⁺ وO²⁻: التبديل يعطي Cu₂O₁ أي Cu₂O","Cu²⁺ وO²⁻: التبديل يعطي Cu₂O₂ والقسمة على 2 تعطي CuO","Cu⁺ وNO₃⁻: التبديل يعطي CuNO₃","Cu²⁺ وNO₃⁻: التبديل يعطي Cu(NO₃)₂"]'::jsonb, '[{"element":"Cu₂O","marks":1},{"element":"CuO بعد القسمة على العامل المشترك","marks":1},{"element":"CuNO₃","marks":1},{"element":"Cu(NO₃)₂ مع الأقواس","marks":1},{"element":"تفسير الاختلاف بسبب اختلاف عدد تأكسد النحاس","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الصيغ الأربع صحيحة مع تفسير صحيح لسبب الاختلاف"},{"level":"4–5 درجات","description":"ثلاث أو أربع صيغ صحيحة مع تفسير ناقص"},{"level":"1–3 درجات","description":"صيغة إلى ثلاث صيغ صحيحة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترك Cu₂O₂ دون القسمة على العامل المشترك","كتابة CuNO₃ للمركب الذي فيه Cu²⁺","تفسير الاختلاف باختلاف الأيون السالب بدل اختلاف عدد تأكسد النحاس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.778Z"}'::jsonb)
