from (values
('mcq', 1, 3, 'يُسمى الأيون السالب أولًا متبوعًا باسم الأيون الموجب، ويُشتق اسم الأيون السالب الأحادي الذرة من اسم العنصر مضافًا إليه المقطع (يد)؛ فيكون الاسم بروميد الصوديوم.', '["هذا الاسم يبدأ بالأيون الموجب، والصحيح أن يُسمى الأيون السالب أولًا.","البرومات هو الأيون BrO₃⁻ العديد الذرات، أما Br⁻ فاسمه بروميد.","هذا الاسم لا يضيف المقطع (يد) إلى اسم العنصر السالب، ويبدأ بالأيون الموجب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 2, 2, 'يُسمى الأيون السالب (الأكسيد) أولًا ثم الأيون الموجب (الألومنيوم)، فيكون الاسم أكسيد الألومنيوم. والألومنيوم له عدد تأكسد واحد هو 3+ لذلك لا يُكتب بعده رقم لاتيني.', '["هذا الاسم يبدأ بالأيون الموجب، والصحيح أن يُسمى الأيون السالب أولًا.","تسمية الأعداد (ثالث، ثنائي) لا تُستخدم في تسمية المركبات الأيونية؛ فالاسم يشتق من اسمي الأيونين.","","الرقم اللاتيني يُكتب فقط للفلز الذي له أكثر من عدد تأكسد، والألومنيوم له عدد تأكسد واحد (3+)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 3, 0, 'ثلاثة أيونات أكسيد تحمل شحنة 6−، فتكون شحنة أيوني الحديد معًا 6+؛ أي 3+ لكل أيون. فالاسم أكسيد الحديد III، ويُكتب الرقم اللاتيني بعد اسم الفلز لأن الحديد له أكثر من عدد تأكسد.', '["","أكسيد الحديد II هو المركب FeO، إذ يكون فيه عدد تأكسد الحديد 2+.","تسمية أكسيد ثنائي الحديد لا تُستعمل للمركبات الأيونية؛ فيُشار إلى عدد تأكسد الفلز برقم لاتيني.","هذا الاسم يضع الفلز قبل الأيون السالب، والصحيح أن يُسمى الأيون السالب أولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 4, 1, 'يحوي المركب أيوني نترات NO₃⁻ شحنتهما معًا 2−، فعدد تأكسد النحاس 2+، ويُسمى أيون النترات أولًا ثم النحاس مع الرقم اللاتيني II: نترات النحاس II.', '["نترات النحاس I هي صيغة CuNO₃ التي فيها عدد تأكسد النحاس 1+، وليس Cu(NO₃)₂.","","النتريت هو الأيون NO₂⁻، أما المركب فيحوي أيون النترات NO₃⁻.","هذا الاسم يبدأ بالأيون الموجب، والصحيح أن يُسمى الأيون السالب (النترات) أولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 5, 2, 'السالب عديد الذرات هو الكرومات CrO₄²⁻ ويُسمى أولًا ثم الفضة؛ فالاسم كرومات الفضة. ولا يُكتب رقم لاتيني لأن الفضة لها عدد تأكسد واحد شائع هو 1+.', '["ثنائي الكرومات هو الأيون Cr₂O₇²⁻ الذي يحوي ذرتي كروم، أما المركب فيحوي CrO₄²⁻.","المقطع (يد) خاص بالأيونات السالبة أحادية الذرة، أما CrO₄²⁻ فيُسمى باسمه الخاص: الكرومات.","","الفضة لها عدد تأكسد واحد شائع (1+)، لذلك لا يلزم رقم لاتيني بعد اسمها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 6, 3, 'يُكتب الرقم اللاتيني عندما يكون للأيون الموجب أكثر من عدد تأكسد. الكوبلت له Co²⁺ وCo³⁺، فيسمى CoCl₂ كلوريد الكوبلت II؛ أما الصوديوم والماغنسيوم والبوتاسيوم فلكل منها عدد تأكسد واحد.', '["الصوديوم عدد تأكسده 1+ فقط، فالاسم كلوريد الصوديوم بلا رقم لاتيني.","الماغنسيوم عدد تأكسده 2+ فقط، فالاسم أكسيد الماغنسيوم بلا رقم لاتيني.","البوتاسيوم عدد تأكسده 1+ فقط، فالاسم بروميد البوتاسيوم بلا رقم لاتيني.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('mcq', 7, 0, 'يُسمى الأيون السالب عديد الذرات SO₄²⁻ (الكبريتات) أولًا ثم الأيون الموجب NH₄⁺ (الأمونيوم): كبريتات الأمونيوم.', '["","الكبريتيت هو الأيون SO₃²⁻ بثلاث ذرات أكسجين، أما المركب فيحوي SO₄²⁻.","هذا الاسم يبدأ بالأيون الموجب، والصحيح أن يُسمى الأيون السالب أولًا.","الكبريتيد هو الأيون S²⁻ أحادي الذرة، أما المركب فيحوي الأيون العديد الذرات SO₄²⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CaBr₂: بروميد الكالسيوم. (ب) Na₃PO₄: فوسفات الصوديوم. (جـ) Fe(OH)₃: هيدروكسيد الحديد III، لأن ثلاثة أيونات هيدروكسيد (3−) تعادل Fe³⁺. (د) CuCl: كلوريد النحاس I، لأن أيون الكلوريد واحد (1−) فعدد تأكسد النحاس 1+. (هـ) Zn(NO₃)₂: نترات الخارصين، ولا يُكتب رقم لاتيني لأن للخارصين عدد تأكسد واحد هو 2+.', '["بروميد الكالسيوم","فوسفات الصوديوم","هيدروكسيد الحديد III","كلوريد النحاس I","نترات الخارصين"]'::jsonb, '["تسمية الأيون السالب أولًا ثم الموجب","تحديد عدد تأكسد الفلز من شحنة الأيون السالب عند تعدد أعداد التأكسد","كتابة الرقم اللاتيني بعد اسم الفلز عند الحاجة فقط"]'::jsonb, '[{"element":"بروميد الكالسيوم","marks":1},{"element":"فوسفات الصوديوم","marks":1},{"element":"هيدروكسيد الحديد III","marks":1},{"element":"كلوريد النحاس I","marks":1},{"element":"نترات الخارصين دون رقم لاتيني","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تسمية المركبات الخمسة تسمية صحيحة"},{"level":"3–4 درجات","description":"ثلاث أو أربع تسميات صحيحة"},{"level":"1–2 درجة","description":"تسمية واحدة أو اثنتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الاسم بترتيب معكوس (الفلز أولًا)","إغفال الرقم اللاتيني في Fe(OH)₃ وCuCl","كتابة رقم لاتيني بعد الخارصين أو الكالسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.779Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في FeO: مجموع الأعداد صفر، لذا عدد تأكسد الحديد x + (−2) = 0 فيكون 2+؛ والاسم أكسيد الحديد II. في Fe₂O₃: 2x + 3×(−2) = 0 فـ 2x = 6 فيكون x = 3+؛ والاسم أكسيد الحديد III. لا يكفي «أكسيد الحديد» لأن للحديد أكثر من عدد تأكسد (2+ و3+) فيكوّن مركبين مختلفين، ويُوضح الرقم اللاتيني بعد اسم الفلز أي المركبين المقصود.', '["عدد تأكسد الحديد في FeO هو 2+","عدد تأكسد الحديد في Fe₂O₃ هو 3+","أكسيد الحديد II وأكسيد الحديد III","للحديد أكثر من عدد تأكسد فيلزم الرقم اللاتيني لتمييز المركبين"]'::jsonb, '["FeO: x + (−2) = 0 فـ x = +2","Fe₂O₃: 2x + 3×(−2) = 0 فـ 2x = 6 فـ x = +3","تسمية المركبين بالرقم اللاتيني بعد اسم الحديد"]'::jsonb, '[{"element":"حساب عدد تأكسد الحديد في FeO","marks":1},{"element":"حساب عدد تأكسد الحديد في Fe₂O₃","marks":1},{"element":"تسمية المركبين تسمية صحيحة","marks":2},{"element":"تفسير الحاجة إلى الرقم اللاتيني","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب العددين صحيح، والتسمية صحيحة، والتفسير صحيح"},{"level":"3–4 درجات","description":"حساب أو تسمية صحيحة مع نقص في التفسير"},{"level":"1–2 درجة","description":"حساب عدد تأكسد واحد صحيح أو تسمية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ عدد تأكسد الحديد في Fe₂O₃ يساوي 2+ بإهمال الرقم السفلي","عكس الاسمين فيُسمى FeO أكسيد الحديد III","القول إن الرقم اللاتيني يدل على عدد ذرات الحديد في الصيغة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:27:04.780Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاسم الأول خطأ لأنه بدأ بالأيون الموجب؛ والصحيح كلوريد الصوديوم، إذ يُسمى الأيون السالب أولًا. الاسم الثاني ناقص لأن الحديد له أكثر من عدد تأكسد، وفي FeCl₃ ثلاثة أيونات كلوريد (3−) فعدد تأكسد الحديد 3+؛ والصحيح كلوريد الحديد III. الاسم الثالث خطأ لأن اسم الأيون السالب الأحادي الذرة يشتق من اسم العنصر بإضافة المقطع (يد)؛ والصحيح كلوريد الكالسيوم.', '["الأول: ترتيب الأيونين خاطئ والصحيح كلوريد الصوديوم","الثاني: غياب الرقم اللاتيني والصحيح كلوريد الحديد III","الثالث: غياب المقطع (يد) والصحيح كلوريد الكالسيوم"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ الاسم الأول وتصحيحه","marks":2},{"element":"تحديد خطأ الاسم الثاني وتصحيحه","marks":2},{"element":"تحديد خطأ الاسم الثالث وتصحيحه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الأخطاء الثلاثة وتصحيحها مع التعليل"},{"level":"4–5 درجات","description":"تصحيح الأسماء الثلاثة مع نقص في التعليل، أو خطآن مصححان بتعليل"},{"level":"1–3 درجات","description":"تصحيح اسم أو اسمين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الاسم الثاني بكتابة II بدل III","الاكتفاء بقلب ترتيب الاسم الثالث دون إضافة المقطع (يد)","إضافة رقم لاتيني بعد الصوديوم أو الكالسيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.780Z"}'::jsonb)
