('mcq', 1, 1, 'المتفاعلان النحاس والأكسجين يكتبان قبل السهم، والناتج CuO يُسمى أكسيد النحاس II لأن عدد تأكسد النحاس فيه 2+ (يعادل أيون الأكسيد 2−). فالمعادلة: النحاس + الأكسجين → أكسيد النحاس II.', '["هذه المعادلة تعكس التفاعل؛ فقد وضعت الناتج في موضع المتفاعلات.","","أكسيد النحاس I صيغته Cu₂O، أما CuO ففيه عدد تأكسد النحاس 2+، فهو أكسيد النحاس II.","تسمية المركبات الأيونية لا تستخدم (ثاني أكسيد) بل تُشار إلى عدد تأكسد الفلز بالرقم اللاتيني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.780Z"}'::jsonb),
('mcq', 2, 0, 'المتفاعلان هما البوتاسيوم الصلب والماء السائل، والناتجان KOH (هيدروكسيد البوتاسيوم) وH₂ (غاز الهيدروجين). فتكون المعادلة: البوتاسيوم + الماء → هيدروكسيد البوتاسيوم + الهيدروجين.', '["","الناتج KOH هو هيدروكسيد البوتاسيوم، وليس أكسيد البوتاسيوم الذي صيغته K₂O.","الغاز الناتج H₂ هو الهيدروجين وليس الأكسجين الذي صيغته O₂.","هذه المعادلة تعكس موضع المتفاعلات والنواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.780Z"}'::jsonb),
('mcq', 3, 3, 'المواد على يسار السهم متفاعلات (الألومنيوم والبروم) والمادة على يمينه ناتج (بروميد الألومنيوم)، فتُقرأ: الألومنيوم والبروم يتفاعلان لإنتاج بروميد الألومنيوم.', '["هذه القراءة تعكس التفاعل فتجعل بروميد الألومنيوم متفاعلًا.","هذه القراءة تجعل الألومنيوم والبروم ناتجين، وهما في المعادلة متفاعلان.","بروميد الألومنيوم ناتج في المعادلة وليس متفاعلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.781Z"}'::jsonb),
('mcq', 4, 2, 'المعادلة اللفظية تعبّر بالكلمات عن أسماء المتفاعلات والنواتج واتجاه التفاعل، لكنها لا تبيّن الكميات النسبية للمواد، وهي معلومات كمية مهمة.', '["أسماء المتفاعلات هي ما تعبّر عنه المعادلة اللفظية صراحة.","أسماء النواتج هي ما تعبّر عنه المعادلة اللفظية صراحة.","","اتجاه التفاعل يوضحه السهم في المعادلة اللفظية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.781Z"}'::jsonb),
('mcq', 5, 1, 'كلورات البوتاسيوم هي المتفاعل الوحيد (يتفكك بالتسخين)، والناتجان كلوريد البوتاسيوم والأكسجين. فالمعادلة: كلورات البوتاسيوم → كلوريد البوتاسيوم + الأكسجين.', '["هذه المعادلة تعكس المتفاعل والناتج فتجعل كلوريد البوتاسيوم هو الذي يتفكك.","","هذه المعادلة تجعل الأكسجين متفاعلًا، بينما هو ناتج غازي في التفاعل.","الغاز الناتج هو الأكسجين وليس الهيدروجين، فلا يوجد هيدروجين في المتفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.781Z"}'::jsonb),
('mcq', 6, 3, 'CaCl₂ كلوريد الكالسيوم، وNa₂SO₄ كبريتات الصوديوم، وCaSO₄ كبريتات الكالسيوم، وNaCl كلوريد الصوديوم. والمتفاعلان على يسار السهم، فالمعادلة الصحيحة: كلوريد الكالسيوم + كبريتات الصوديوم → كبريتات الكالسيوم + كلوريد الصوديوم.', '["هذه المعادلة تعكس المتفاعلات والنواتج.","الكبريتيت هو SO₃²⁻ أما Na₂SO₄ فهو كبريتات الصوديوم، فاسما المتفاعل والناتج خاطئان.","الكلورات هو ClO₃⁻، أما NaCl فهو كلوريد الصوديوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.781Z"}'::jsonb),
('mcq', 7, 2, 'المتفاعلات هي المواد الموجودة عند بداية التفاعل وتُكتب يسار السهم، وهي كبريتيد الهيدروجين والأكسجين.', '["هاتان المادتان ناتجتان في التفاعل، وتُكتبان يمين السهم.","الماء ناتج وليس متفاعلًا، فهو مكتوب يمين السهم.","","ثاني أكسيد الكبريت ناتج وليس متفاعلًا، فهو مكتوب يمين السهم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.781Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الليثيوم + الكلور → كلوريد الليثيوم. (ب) كربونات الكالسيوم → أكسيد الكالسيوم + ثاني أكسيد الكربون. (جـ) كبريتيد الصوديوم + نترات الفضة → كبريتيد الفضة + نترات الصوديوم.', '["الليثيوم + الكلور → كلوريد الليثيوم","كربونات الكالسيوم → أكسيد الكالسيوم + ثاني أكسيد الكربون","كبريتيد الصوديوم + نترات الفضة → كبريتيد الفضة + نترات الصوديوم"]'::jsonb, '["تسمية كل مادة بحسب صيغتها","كتابة المتفاعلات يسار السهم والنواتج يمينه"]'::jsonb, '[{"element":"المعادلة (أ): المتفاعلان والناتج","marks":2},{"element":"المعادلة (ب): المتفاعل والناتجان","marks":2},{"element":"المعادلة (جـ): المتفاعلان والناتجان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث صحيحة بأسماء المواد وترتيبها"},{"level":"4–5 درجات","description":"معادلتان صحيحتان أو ثلاث معادلات بأخطاء طفيفة في الأسماء"},{"level":"1–3 درجات","description":"معادلة واحدة صحيحة أو أسماء صحيحة مع خطأ في الترتيب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الكلور بدل كلوريد الليثيوم أو العكس","تسمية CO₂ أول أكسيد الكربون","عكس مواضع المتفاعلات والنواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:27:04.782Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة اللفظية: المغنيسيوم + النيتروجين → نيتريد المغنيسيوم. وتُقرأ: المغنيسيوم والنيتروجين يتفاعلان لإنتاج نيتريد المغنيسيوم. المتفاعلان هما المغنيسيوم والنيتروجين، والناتج نيتريد المغنيسيوم. وتفتقر المعادلة اللفظية إلى المعلومات الكمية، أي الكميات النسبية للمواد المتفاعلة والناتجة.', '["المغنيسيوم + النيتروجين → نيتريد المغنيسيوم","قراءة المعادلة: يتفاعلان لإنتاج نيتريد المغنيسيوم","المعادلة اللفظية تفتقر إلى المعلومات الكمية (الكميات النسبية)"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة المعادلة اللفظية بالمتفاعلين والناتج في مواضعها الصحيحة","marks":2},{"element":"قراءة المعادلة قراءة صحيحة","marks":1},{"element":"ذكر أن المعادلة اللفظية تفتقر إلى المعلومات الكمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة وقراءة صحيحة وبيان افتقارها للمعلومات الكمية"},{"level":"2–3 درجات","description":"معادلة صحيحة مع نقص في القراءة أو في بيان المحدودية"},{"level":"1 درجة","description":"ذكر بعض المواد دون ترتيب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة نيترات المغنيسيوم بدل نيتريد المغنيسيوم","قراءة المعادلة بصورة معكوسة","القول إن المعادلة اللفظية توضح أعداد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.782Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة غير صحيحة؛ فقد وضع الطالب الناتج (كلوريد الصوديوم) يسار السهم مع المتفاعلات، ووضع المتفاعلين (الصوديوم والكلور) يمين السهم، فعكس التفاعل. والمعادلة الصحيحة: الصوديوم + الكلور → كلوريد الصوديوم، وتُقرأ: الصوديوم والكلور يتفاعلان لإنتاج كلوريد الصوديوم.', '["المعادلة غير صحيحة","تحديد الخطأ: عكس مواضع المتفاعلات والنواتج","الصوديوم + الكلور → كلوريد الصوديوم","القراءة: الصوديوم والكلور يتفاعلان لإنتاج كلوريد الصوديوم"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم صحة المعادلة وتحديد الخطأ","marks":1},{"element":"كتابة المعادلة الصحيحة","marks":2},{"element":"قراءة المعادلة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتصحيح المعادلة وقراءتها قراءة صحيحة"},{"level":"2–3 درجات","description":"تحديد الخطأ وتصحيح المعادلة مع نقص في القراءة"},{"level":"1 درجة","description":"الحكم بعدم الصحة دون تصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المعادلة صحيحة لأن أسماء المواد صحيحة","تصحيح الأسماء دون تغيير مواضع المتفاعلات والنواتج","قراءة المعادلة الصحيحة بصورة معكوسة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.782Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
