('essay', 1, 'زن المعادلات الرمزية الآتية بأبسط نسبة من الأعداد الصحيحة: (أ) N₂ + H₂ → NH₃، (ب) Al + O₂ → Al₂O₃، (جـ) Fe₂O₃ + C → Fe + CO₂.', null, null, 'تطبيق', 'وزن معادلات', 'متوسط', 'الكتاب ص 120، 121 — خطوات وزن المعادلات'),
('essay', 2, 'وضّح بالخطوات كيف تزن المعادلة Al(s) + Br₂(l) → AlBr₃(s)، مبيّنًا عدد ذرات كل عنصر قبل الوزن وبعده والتحقق النهائي.', null, null, 'تطبيق', 'شرح خطوات الوزن', 'متوسط', 'الكتاب ص 119، 120 — وزن المعادلات وخطواتها'),
('essay', 3, 'زنّ طالب المعادلة H₂ + O₂ → H₂O بتغيير صيغة الناتج إلى H₂O₂ فأصبح عدد الذرات متساويًا في الطرفين. هل هذه الطريقة صحيحة؟ علّل إجابتك، ثم زن المعادلة وزنًا صحيحًا بأبسط نسبة.', null, null, 'تحليل', 'تقويم طريقة وزن', 'صعب', 'الكتاب ص 120، 122 — الجدول 4-7 الخطوة 4 والتقويم 4-1 السؤال 15')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
