select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في المتفاعلات ذرتا أكسجين (O₂) وفي النواتج ذرة واحدة، فيوضع المعامل 2 قبل MgO فيصبح عدد Mg في الناتج 2، ثم يوضع المعامل 2 قبل Mg. فتكون 2Mg + O₂ → 2MgO: لكل طرف ذرتا Mg وذرتا O، والنسبة 2 : 1 : 2 هي الأبسط.', '["1 : 1 : 1 لا يحقق الوزن؛ ففي المتفاعلات ذرتا أكسجين وفي الناتج ذرة واحدة.","4 : 2 : 4 معادلة موزونة لكنها ليست بأبسط نسبة؛ إذ يمكن قسمة المعاملات على 2.","","2 : 2 : 2 غير موزونة؛ ففي المتفاعلات 4 ذرات أكسجين وفي الناتج ذرتان فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.783Z"}'::jsonb),
('mcq', 2, 0, 'في 2H₂S + 3O₂ → 2SO₂ + 2H₂O: 4 ذرات H و2 ذرتا S و6 ذرات O في الطرفين معًا (في النواتج 2×2 + 2 = 6 ذرات أكسجين). والنسبة 2 : 3 : 2 : 2 أبسط نسبة صحيحة.', '["","1 : 1 : 1 : 1 تعطي ذرتي أكسجين في المتفاعلات وثلاث ذرات في النواتج، فالمعادلة غير موزونة.","2 : 2 : 2 : 2 تعطي 4 ذرات أكسجين في المتفاعلات و6 في النواتج، فالمعادلة غير موزونة.","1 : 3 : 1 : 2 تعطي ذرتي هيدروجين في المتفاعلات و4 في النواتج، فالمعادلة غير موزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.783Z"}'::jsonb),
('mcq', 3, 1, 'بقسمة المعاملات 4 و2 و4 على العامل المشترك 2 نحصل على 2H₂ + O₂ → 2H₂O، وهي موزونة (4 ذرات H وذرتا O في كل طرف) وبأبسط نسبة 2 : 1 : 2.', '["هذه المعادلة غيّرت صيغة الناتج من H₂O إلى H₂O₂، وتغيير الأرقام السفلية يغير نوع المادة ولا يجوز في الوزن.","","H₂ + O₂ → H₂O غير موزونة؛ ففي المتفاعلات ذرتا أكسجين وفي الناتج ذرة واحدة.","2H₂ + 2O₂ → 2H₂O غير موزونة؛ ففي المتفاعلات 4 ذرات أكسجين وفي الناتج ذرتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('mcq', 4, 3, 'يتم وزن المعادلة بتغيير المعاملات فقط، أي بكتابة أعداد قبل الصيغ؛ أما الأرقام السفلية داخل الصيغة فلا تُغيَّر لأنها تحدد نوع المادة.', '["تغيير الرقم السفلي يغير الصيغة ونوع المادة، فلا يجوز.","حذف مادة ناتجة يغير التفاعل نفسه، والوزن لا يغير المواد المشاركة.","الذرات لا تُضاف ولا تُستحدث في التفاعل الكيميائي بحسب قانون حفظ الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('mcq', 5, 0, 'المعامل 3 يضرب جميع ذرات الصيغة، والرقم 2 خارج القوسين يضرب O وH داخل القوسين: 3 × 2 = 6 ذرات أكسجين و3 × 2 = 6 ذرات هيدروجين.', '["","هذا العدد ينتج عن إهمال الرقم 2 خارج القوسين، فتُعدّ ذرة أكسجين وذرة هيدروجين لكل وحدة فقط.","هذا يضرب ذرات الأكسجين في الرقم 2 ولا يضرب ذرات الهيدروجين، والصحيح أن الرقم 2 يشملهما معًا.","هذا يضرب ذرات الهيدروجين في الرقم 2 ولا يضرب ذرات الأكسجين، والصحيح أن الرقم 2 يشملهما معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('mcq', 6, 1, 'في المتفاعلات ذرتا بوتاسيوم (K₂CrO₄) وذرتا نيتروجين (Pb(NO₃)₂)، وفي الناتج يحوي كل KNO₃ ذرة K وذرة N، فيلزم المعامل 2 قبل KNO₃ لتتساوى الذرات: K₂CrO₄ + Pb(NO₃)₂ → 2KNO₃ + PbCrO₄.', '["المعامل 1 يعطي ذرة بوتاسيوم وذرة نيتروجين في النواتج، بينما في المتفاعلات ذرتان من كل منهما.","","المعامل 3 يعطي 3 ذرات بوتاسيوم في النواتج بينما في المتفاعلات ذرتان.","المعامل 4 يعطي 4 ذرات بوتاسيوم في النواتج بينما في المتفاعلات ذرتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('mcq', 7, 3, 'يوضع المعامل 3 قبل Ca(OH)₂ لتتساوى ذرات Ca مع 3 في الناتج، والمعامل 2 قبل H₃PO₄ لتتساوى ذرات P مع 2، فيصبح في المتفاعلات 12 ذرة H و14 ذرة O؛ ولذلك يلزم 6 H₂O. المعادلة: 2H₃PO₄ + 3Ca(OH)₂ → Ca₃(PO₄)₂ + 6H₂O.', '["1 : 1 : 1 : 1 تعطي ذرة كالسيوم واحدة في المتفاعلات وثلاث ذرات في الناتج.","3 : 2 : 1 : 6 تعطي 3 ذرات فوسفور في المتفاعلات وذرتين في الناتج، وتعكس ترتيب المعاملين.","2 : 3 : 1 : 3 تعطي 12 ذرة هيدروجين في المتفاعلات و6 فقط في النواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) N₂ + 3H₂ → 2NH₃ (ذرتا N و6 ذرات H في كل طرف). (ب) 4Al + 3O₂ → 2Al₂O₃ (4 ذرات Al و6 ذرات O في كل طرف). (جـ) 2Fe₂O₃ + 3C → 4Fe + 3CO₂ (4 ذرات Fe و6 ذرات O و3 ذرات C في كل طرف).', '["N₂ + 3H₂ → 2NH₃","4Al + 3O₂ → 2Al₂O₃","2Fe₂O₃ + 3C → 4Fe + 3CO₂"]'::jsonb, '["عدّ ذرات كل عنصر في المتفاعلات وفي النواتج","تغيير المعاملات فقط حتى تتساوى الذرات في الطرفين","كتابة المعاملات بأبسط نسبة والتحقق من تساوي الذرات"]'::jsonb, '[{"element":"المعادلة (أ) موزونة بأبسط نسبة","marks":2},{"element":"المعادلة (ب) موزونة بأبسط نسبة","marks":2},{"element":"المعادلة (جـ) موزونة بأبسط نسبة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث موزونة بأبسط نسبة"},{"level":"4–5 درجات","description":"معادلتان موزونتان بأبسط نسبة وثالثة بخطأ طفيف"},{"level":"1–3 درجات","description":"معادلة واحدة موزونة أو معادلات موزونة دون اختصار"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير الرقم السفلي بدل المعامل مثل كتابة AlO₂","كتابة 2N₂ + 6H₂ → 4NH₃ دون اختصار","ترك عدد ذرات الأكسجين غير متساوٍ في المعادلتين (ب) و(جـ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.784Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوة 1: المعادلة غير الموزونة Al(s) + Br₂(l) → AlBr₃(s) بالصيغ والحالات الصحيحة. الخطوة 2: ذرات المتفاعلات: 1 Al و2 Br. الخطوة 3: ذرات النواتج: 1 Al و3 Br. الخطوة 4: نغيّر المعاملات فقط: نضع 3 قبل Br₂ و2 قبل AlBr₃ فيصبح في المتفاعلات 6 Br وفي النواتج 6 Br، ثم نضع 2 قبل Al ليصبح 2 Al في كل طرف. الخطوة 5: النسبة 2 : 3 : 2 هي أبسط نسبة صحيحة. الخطوة 6: التحقق: 2 Al و6 Br في كل طرف. المعادلة: 2Al(s) + 3Br₂(l) → 2AlBr₃(s).', '["عدّ ذرات المتفاعلات: 1 Al و2 Br","عدّ ذرات النواتج: 1 Al و3 Br","تغيير المعاملات فقط","المعادلة الموزونة 2Al + 3Br₂ → 2AlBr₃ بأبسط نسبة","التحقق: 2 Al و6 Br في كل طرف"]'::jsonb, '["المتفاعلات: Al = 1، Br = 2؛ النواتج: Al = 1، Br = 3","المضاعف المشترك الأصغر لـ 2 و3 هو 6: 3Br₂ و2AlBr₃ يعطيان 6 Br في كل طرف","2AlBr₃ يحتوي 2 Al فنضع المعامل 2 قبل Al","التحقق: Al = 2، Br = 6 في كل طرف"]'::jsonb, '[{"element":"عدّ ذرات المتفاعلات والنواتج قبل الوزن","marks":1},{"element":"تغيير المعاملات فقط دون تغيير الأرقام السفلية","marks":1},{"element":"المعاملات الصحيحة 2 : 3 : 2","marks":2},{"element":"التحقق من تساوي الذرات في الطرفين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة ومعاملات صحيحة وتحقق نهائي"},{"level":"3–4 درجات","description":"معاملات صحيحة مع نقص في خطوة أو في التحقق"},{"level":"1–2 درجة","description":"عدّ صحيح للذرات دون الوصول إلى المعاملات الصحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة AlBr₆ أو Al₂Br₃ بتغيير الأرقام السفلية","الاكتفاء بوزن البروم وترك الألومنيوم غير متساوٍ","ترك المعاملات دون أبسط نسبة أو دون تحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.785Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطريقة غير صحيحة؛ لأن تغيير الرقم السفلي داخل الصيغة يغيّر نوع المادة، فـ H₂O₂ مادة مختلفة عن الماء H₂O، والوزن يتم بتغيير المعاملات فقط ولا تُغيَّر الأرقام داخل الصيغ. الوزن الصحيح: في المتفاعلات ذرتا O وفي الناتج ذرة O واحدة، فنضع 2 قبل H₂O فيصبح 4 ذرات H، ثم نضع 2 قبل H₂ فتكون المعادلة 2H₂ + O₂ → 2H₂O بأبسط نسبة 2 : 1 : 2، وفي كل طرف 4 ذرات H وذرتا O.', '["الطريقة غير صحيحة","تغيير الرقم السفلي يغير نوع المادة (H₂O₂ غير H₂O)","الوزن بتغيير المعاملات فقط","المعادلة 2H₂ + O₂ → 2H₂O","التحقق: 4 H وذرتا O في كل طرف"]'::jsonb, '["المتفاعلات: H = 2، O = 2؛ الناتج: H = 2، O = 1","وضع المعامل 2 قبل H₂O فيصبح O = 2 وH = 4","وضع المعامل 2 قبل H₂ فيصبح H = 4","التحقق: H = 4، O = 2 في كل طرف"]'::jsonb, '[{"element":"الحكم بعدم صحة الطريقة","marks":1},{"element":"التعليل بأن تغيير الرقم السفلي يغير نوع المادة","marks":1},{"element":"المعادلة الموزونة 2H₂ + O₂ → 2H₂O","marks":2},{"element":"التحقق من تساوي الذرات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح وتعليل صحيح ومعادلة موزونة بأبسط نسبة وتحقق"},{"level":"3–4 درجات","description":"حكم وتعليل صحيحان مع معادلة ناقصة أو دون تحقق"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل أو معادلة موزونة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول H₂O₂ لأن عدد الذرات تساوى","كتابة 4H₂ + 2O₂ → 4H₂O دون أبسط نسبة","وضع المعامل 2 قبل H₂ فقط دون الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.785Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
