('mcq', 1, 'يتحلل بروميد الهيدروجين الغازي إلى غاز الهيدروجين وبروم سائل. ما المعادلة الرمزية (غير الموزونة) لهذا التفاعل؟', null, '["HBr(g) → H(g) + Br(l)","HBr(g) → H₂(g) + Br₂(g)","HBr(g) → H₂(g) + Br₂(l)","H₂(g) + Br₂(l) → HBr(g)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية لتفاعل تحلل', 'متوسط', 'الكتاب ص 146 — السؤال 72'),
('mcq', 2, 'ما المعادلة الرمزية للتفاعل بين الألومنيوم الصلب والكبريت الصلب لإنتاج كبريتيد الألومنيوم الصلب؟', null, '["Al(s) + S(s) → AlS(s)","Al(s) + S(s) → Al₃S₂(s)","Al(s) + S(s) → Al₂S₃(aq)","Al(s) + S(s) → Al₂S₃(s)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية لتفاعل تكوين', 'سهل', 'الكتاب ص 125 — مسائل تدريبية السؤال 18'),
('mcq', 3, 'يتفاعل الليثيوم الصلب مع غاز الكلور لإنتاج كلوريد الليثيوم الصلب. أيّ المعادلات الرمزية الآتية (غير الموزونة) تمثل هذا التفاعل؟', null, '["Li(s) + Cl(g) → LiCl(s)","Li(s) + Cl₂(g) → LiCl(s)","Li(s) + Cl₂(g) → LiCl₂(s)","Li(s) + Cl₂(g) → LiCl(aq)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية لتفاعل تكوين', 'سهل', 'الكتاب ص 146 — السؤال 74'),
('mcq', 4, 'عند خلط محلول كبريتيد الصوديوم مع محلول نترات الفضة يتكون راسب صلب من كبريتيد الفضة ويبقى محلول نترات الصوديوم. ما المعادلة الرمزية (غير الموزونة) لهذا التفاعل؟', null, '["Na₂S(aq) + AgNO₃(aq) → Ag₂S(s) + NaNO₃(aq)","NaS(aq) + AgNO₃(aq) → AgS(s) + NaNO₃(aq)","Na₂S(aq) + AgNO₃(aq) → Ag₂S(aq) + NaNO₃(aq)","Na₂S(s) + AgNO₃(s) → Ag₂S(s) + NaNO₃(s)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية لتفاعل في محلول مائي', 'صعب', 'الكتاب ص 146 — السؤال 73 (د)'),
('mcq', 5, 'ما المعادلة الرمزية الموزونة لاحتراق غاز الميثان CH₄ في غاز الأكسجين لإنتاج غاز ثاني أكسيد الكربون وبخار الماء؟', null, '["CH₄(g) + O₂(g) → CO₂(g) + H₂O(g)","CH₄(g) + 2O₂(g) → CO₂(g) + H₂O(g)","CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(g)","2CH₄(g) + 2O₂(g) → 2CO₂(g) + 2H₂O(g)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية موزونة', 'صعب', 'الكتاب ص 119، 125 — المعادلة الرمزية الموزونة وتفاعلات الاحتراق'),
('mcq', 6, 'ما الذي تعجز عنه المعادلة الرمزية Al(s) + Br₂(l) → AlBr₃(s) حتى تحتاج إلى وزن؟', null, '["إيضاح العدد الصحيح للذرات المتفاعلة والناتجة","كتابة الصيغ الكيميائية للمواد المشاركة","بيان الحالة الفيزيائية لكل مادة","الفصل بين المتفاعلات والنواتج"]'::jsonb, 'فهم', 'تحديد محدودية المعادلة الرمزية', 'سهل', 'الكتاب ص 118، 119 — المعادلات الرمزية والرمزية الموزونة'),
('mcq', 7, 'عند تسخين كربونات الصوديوم الصلبة ينتج غاز ثاني أكسيد الكربون وأكسيد الصوديوم الصلب. أيّ المعادلات الرمزية الآتية تمثل التفاعل؟ (الرمز Δ مكتوب فوق السهم ويدل على التسخين)', null, '["Na₂CO₃(s) –Δ→ CO₂(s) + Na₂O(g)","Na₂CO₃(s) –Δ→ CO₂(g) + Na₂O(s)","NaCO₃(s) –Δ→ CO₂(g) + NaO(s)","Na₂CO₃(s) –Δ→ CO(g) + Na₂O(s)"]'::jsonb, 'تطبيق', 'كتابة معادلة رمزية لتفاعل تفكك بالتسخين', 'متوسط', 'الكتاب ص 126، 146 — تفاعلات التفكك والسؤال 73 (أ)'),
('essay', 1, 'اكتب معادلة رمزية (غير موزونة) لكل تفاعل مما يأتي مع بيان الحالة الفيزيائية لكل مادة: (أ) يتفاعل المغنيسيوم الصلب مع غاز النيتروجين لإنتاج نيتريد المغنيسيوم الصلب. (ب) يتفاعل حمض الكبريتيك المائي مع محلول هيدروكسيد الصوديوم لإنتاج محلول كبريتات الصوديوم والماء السائل. (جـ) يتفكك أكسيد الألومنيوم الصلب بالكهرباء إلى ألومنيوم صلب وغاز الأكسجين.', null, null, 'تطبيق', 'كتابة معادلات رمزية', 'متوسط', 'الكتاب ص 118، 125، 146، 147 — المعادلات الرمزية'),
('essay', 2, 'اكتب المعادلة الرمزية الموزونة للتفاعل بين الألومنيوم الصلب والكبريت الصلب لإنتاج كبريتيد الألومنيوم الصلب، موضحًا كيف حصلت على صيغة الناتج وكيف وزنت المعادلة.', null, null, 'تطبيق', 'كتابة معادلة رمزية موزونة بخطوات', 'متوسط', 'الكتاب ص 119، 125 — المعادلة الرمزية الموزونة ومسائل تدريبية السؤال 18'),
('essay', 3, 'يتفاعل الكربون الصلب مع الكبريت الصلب لإنتاج ثاني كبريتيد الكربون السائل. اكتب المعادلة اللفظية والمعادلة الرمزية لهذا التفاعل، ثم اذكر فرقين بين النوعين من المعادلات، ووضّح لماذا لا تكفي المعادلة الرمزية لتمثيل التفاعل تمثيلًا كاملًا.', null, null, 'تحليل', 'مقارنة المعادلة اللفظية والرمزية', 'صعب', 'الكتاب ص 118، 119 — المعادلات اللفظية والرمزية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
