insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المتفاعل HBr غازي، والناتجان هما الهيدروجين وهو جزيء ثنائي الذرة H₂ غازي، والبروم جزيء ثنائي الذرة Br₂ سائل. فتكون المعادلة: HBr(g) → H₂(g) + Br₂(l).', '["كتب الناتجين على صورة ذرات منفردة H وBr، بينما يوجدان في صورة جزيئات ثنائية الذرة H₂ وBr₂.","كتب البروم غازًا (g) بينما المعطى أنه سائل (l).","","عكس المتفاعل والناتجين، فجعل HBr ناتجًا مع أن المعطى أنه المادة المتحللة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.785Z"}'::jsonb),
('mcq', 2, 3, 'عدد تأكسد الألومنيوم 3+ والكبريت 2−، وبتبديل العددين تكون صيغة كبريتيد الألومنيوم Al₂S₃، وحالته صلبة (s). فتكون المعادلة: Al(s) + S(s) → Al₂S₃(s).', '["AlS شحنته الكلية 1+ (3+ و2−)، فهو غير متعادل؛ لم تُبدَّل أعداد التأكسد.","Al₃S₂ ناتجة عن كتابة كل عدد تأكسد رقمًا سفليًّا للعنصر نفسه دون تبديل؛ شحنتها الكلية 5+.","الصيغة صحيحة لكن الحالة الفيزيائية خاطئة؛ فالناتج صلب (s) وليس محلولًا مائيًّا (aq).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.786Z"}'::jsonb),
('mcq', 3, 1, 'غاز الكلور جزيء ثنائي الذرة Cl₂(g)، وعدد تأكسد الليثيوم 1+ والكلور 1− فصيغة الناتج LiCl، وهو صلب (s). فالمعادلة: Li(s) + Cl₂(g) → LiCl(s).', '["كتب الكلور ذرة منفردة Cl، بينما يوجد غاز الكلور على صورة الجزيء Cl₂.","","LiCl₂ شحنته الكلية 1− (1+ و2−)، فهو غير متعادل؛ فصيغة كلوريد الليثيوم LiCl.","الناتج صلب (s) بحسب المعطى وليس محلولًا مائيًّا (aq)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.786Z"}'::jsonb),
('mcq', 4, 0, 'كبريتيد الصوديوم Na₂S ونترات الفضة AgNO₃ محلولان مائيان (aq)، وكبريتيد الفضة Ag₂S راسب صلب (s)، ونترات الصوديوم NaNO₃ تبقى في محلول مائي (aq). فتكون المعادلة: Na₂S(aq) + AgNO₃(aq) → Ag₂S(s) + NaNO₃(aq).', '["","الصيغتان NaS وAgS خاطئتان؛ فصيغة كبريتيد الصوديوم Na₂S وصيغة كبريتيد الفضة Ag₂S.","الصيغ صحيحة لكن حالة كبريتيد الفضة خاطئة؛ فهو راسب صلب (s) وليس محلولًا مائيًّا (aq).","الصيغ صحيحة لكن الحالات خاطئة؛ فالمتفاعلان محلولان مائيان ونترات الصوديوم تبقى في محلول مائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.786Z"}'::jsonb),
('mcq', 5, 2, 'ذرات الهيدروجين الأربع في CH₄ تعطي جزيئي ماء 2H₂O، فيصبح في النواتج 4 ذرات أكسجين (2 في CO₂ و2 في الماء) فيلزم 2O₂ في المتفاعلات: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(g).', '["غير موزونة؛ ففي المتفاعلات ذرتا أكسجين و4 ذرات هيدروجين، وفي النواتج 3 ذرات أكسجين وذرتا هيدروجين.","غير موزونة؛ ففي المتفاعلات 4 ذرات هيدروجين وفي النواتج ذرتان فقط.","","غير موزونة؛ ففي المتفاعلات 4 ذرات أكسجين وفي النواتج 6 ذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.786Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة الرمزية تستخدم الصيغ والحالات الفيزيائية والسهم، لكنها لا توضح العدد الصحيح للذرات المتفاعلة والناتجة: فالبروم 2 ذرة في المتفاعلات و3 في الناتج. لذلك تحتاج إلى المعادلة الرمزية الموزونة.', '["","المعادلة تحتوي الصيغ الكيميائية Al وBr₂ وAlBr₃، وهي ما يميز المعادلة الرمزية.","المعادلة تبين الحالات الفيزيائية (s) و(l) و(s) صراحة.","السهم في المعادلة يفصل المتفاعلات عن النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.787Z"}'::jsonb),
('mcq', 7, 1, 'كربونات الصوديوم Na₂CO₃ صلبة، والناتجان CO₂ غازي وNa₂O صلب، ويُكتب Δ فوق السهم للدلالة على التسخين. فالمعادلة: Na₂CO₃(s) –Δ→ CO₂(g) + Na₂O(s).', '["الصيغ صحيحة لكن حالتا الناتجين معكوستان؛ فثاني أكسيد الكربون غاز وأكسيد الصوديوم صلب.","","الصيغتان NaCO₃ وNaO خاطئتان؛ فصيغة كربونات الصوديوم Na₂CO₃ وصيغة أكسيد الصوديوم Na₂O.","CO هو أول أكسيد الكربون، أما الناتج المعطى فهو ثاني أكسيد الكربون CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.787Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Mg(s) + N₂(g) → Mg₃N₂(s). (ب) H₂SO₄(aq) + NaOH(aq) → Na₂SO₄(aq) + H₂O(l). (جـ) Al₂O₃(s) → Al(s) + O₂(g).', '["Mg(s) + N₂(g) → Mg₃N₂(s)","H₂SO₄(aq) + NaOH(aq) → Na₂SO₄(aq) + H₂O(l)","Al₂O₃(s) → Al(s) + O₂(g)"]'::jsonb, '["كتابة صيغة كل مادة مع مراعاة الجزيئات ثنائية الذرة (N₂ وO₂)","كتابة أعداد التأكسد وتبديلها لإيجاد صيغ المركبات الأيونية (Mg₃N₂ وNa₂SO₄ وAl₂O₃)","كتابة رمز الحالة الفيزيائية أسفل كل صيغة"]'::jsonb, '[{"element":"المعادلة (أ): الصيغ والحالات","marks":2},{"element":"المعادلة (ب): الصيغ والحالات","marks":2},{"element":"المعادلة (جـ): الصيغ والحالات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث بالصيغ والحالات الصحيحة"},{"level":"4–5 درجات","description":"معادلتان صحيحتان تمامًا وثالثة بخطأ طفيف في صيغة أو حالة"},{"level":"1–3 درجات","description":"معادلة واحدة صحيحة أو صيغ صحيحة دون حالات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة النيتروجين N والأكسجين O ذرتين منفردتين بدل N₂ وO₂","كتابة Mg₂N₃ بتبديل الأرقام تبديلًا خاطئًا","إغفال رموز الحالة الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.787Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عدد تأكسد الألومنيوم 3+ والكبريت 2−، وبتبديل العددين تكون صيغة الناتج Al₂S₃. المعادلة غير الموزونة: Al(s) + S(s) → Al₂S₃(s). في النواتج 2 Al و3 S، فنضع المعامل 2 قبل Al والمعامل 3 قبل S. المعادلة الموزونة: 2Al(s) + 3S(s) → Al₂S₃(s)، وفي كل طرف 2 ذرة Al و3 ذرات S، والمعاملات 2 : 3 : 1 بأبسط نسبة.', '["صيغة الناتج Al₂S₃ من تبديل أعداد التأكسد 3+ و2−","رموز الحالة: Al(s) وS(s) وAl₂S₃(s)","المعاملات 2 و3 و1","المعادلة 2Al(s) + 3S(s) → Al₂S₃(s)","التحقق: 2 Al و3 S في كل طرف"]'::jsonb, '["Al³⁺ وS²⁻: تبديل العددين يعطي Al₂S₃","كتابة المعادلة غير الموزونة مع الحالات: Al(s) + S(s) → Al₂S₃(s)","عدّ الذرات: المتفاعلات 1 Al و1 S؛ النواتج 2 Al و3 S","المعاملان 2 قبل Al و3 قبل S","التحقق: 2 Al و3 S في كل طرف"]'::jsonb, '[{"element":"صيغة الناتج Al₂S₃ مع تبديل أعداد التأكسد","marks":1},{"element":"رموز الحالة الفيزيائية الصحيحة","marks":1},{"element":"المعاملات الصحيحة 2 و3","marks":2},{"element":"التحقق من تساوي الذرات في الطرفين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"صيغة صحيحة وحالات صحيحة ومعادلة موزونة وتحقق"},{"level":"3–4 درجات","description":"معادلة صحيحة الصيغ والحالات مع وزن ناقص أو دون تحقق"},{"level":"1–2 درجة","description":"صيغة الناتج صحيحة دون حالات أو دون وزن"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة AlS أو Al₃S₂ لكبريتيد الألومنيوم","تغيير الرقم السفلي في Al₂S₃ عند الوزن","إغفال رموز الحالة الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.787Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة اللفظية: الكربون + الكبريت → ثاني كبريتيد الكربون. المعادلة الرمزية: C(s) + S(s) → CS₂(l). الفرق الأول: اللفظية تستعمل أسماء المواد بالكلمات، أما الرمزية فتستعمل رموز العناصر وصيغ المركبات. الفرق الثاني: الرمزية تبين الحالة الفيزيائية لكل مادة (s) و(l)، أما اللفظية فلا تبينها. ولا تكفي المعادلة الرمزية لأنها لا توضح العدد الصحيح للذرات المتفاعلة والناتجة (ففيها ذرة كبريت واحدة في المتفاعلات وذرتان في الناتج)، فتحتاج إلى وزن.', '["المعادلة اللفظية: الكربون + الكبريت → ثاني كبريتيد الكربون","المعادلة الرمزية: C(s) + S(s) → CS₂(l)","فرق أول: الكلمات مقابل الرموز والصيغ","فرق ثانٍ: الحالات الفيزيائية في الرمزية","الرمزية لا توضح عدد الذرات فتحتاج إلى وزن"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة اللفظية","marks":1},{"element":"المعادلة الرمزية بحالاتها","marks":1},{"element":"ذكر فرقين صحيحين بين النوعين","marks":2},{"element":"بيان أن المعادلة الرمزية لا توضح عدد الذرات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان صحيحتان وفرقان صحيحان وبيان محدودية المعادلة الرمزية"},{"level":"3–4 درجات","description":"معادلتان صحيحتان مع فرق واحد أو دون بيان المحدودية"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو أفكار عامة دون ربط بالتفاعل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغة الناتج CS أو C₂S","القول إن المعادلة اللفظية تبين الحالة الفيزيائية","القول إن المعادلة الرمزية موزونة تلقائيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.787Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
