insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L1-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يجب أن تكون المعادلة الكيميائية موزونة؟', null, '["لأن المادة لا تفنى ولا تُستحدث في التغير الكيميائي، فيجب أن يتساوى عدد ذرات كل عنصر على جانبي السهم","لأن عدد جزيئات المتفاعلات يجب أن يساوي دائمًا عدد جزيئات النواتج في كل تفاعل","لأن الحالات الفيزيائية للمتفاعلات يجب أن تطابق الحالات الفيزيائية للنواتج","لأن المعاملات يجب أن تساوي 1 في جميع المعادلات حتى يسهل قراءتها"]'::jsonb, 'فهم', 'تفسير أهمية الوزن', 'سهل', 'الكتاب ص 122 — تحقيق قانون حفظ الكتلة'),
('mcq', 2, 'المعادلة Al + Br₂ → AlBr₃ غير موزونة. ما سبب عدم اتفاقها مع قانون حفظ الكتلة؟', null, '["عدد ذرات الألومنيوم في المتفاعلات أكبر منه في النواتج","الصيغة AlBr₃ غير صحيحة وكان يجب كتابتها AlBr₂","عدد ذرات البروم 2 في المتفاعلات و3 في النواتج، فكأن ذرة بروم قد استُحدثت","الحالات الفيزيائية للمواد لم تُكتب بجانب الصيغ الكيميائية"]'::jsonb, 'فهم', 'تفسير عدم الاتزان بعد الذرات', 'متوسط', 'الكتاب ص 119 — المعادلات الكيميائية الرمزية الموزونة'),
('mcq', 3, 'احترق 48.6 g من المغنسيوم تمامًا مع 32.0 g من غاز الأكسجين في وعاء مغلق، فنتج أكسيد المغنسيوم فقط. ما كتلة أكسيد المغنسيوم الناتجة؟', null, '["16.6 g","80.6 g","48.6 g","40.3 g"]'::jsonb, 'تطبيق', 'حساب كتلة ناتج بقانون حفظ الكتلة', 'متوسط', 'الكتاب ص 149 — مسألة التحفيز (حفظ الكتلة)'),
('mcq', 4, 'أيّ المعادلات الآتية للتفاعل بين الألومنيوم والبروم تتفق مع قانون حفظ الكتلة؟', null, '["Al + Br₂ → AlBr₃","2Al + Br₂ → 2AlBr₃","Al + 3Br₂ → AlBr₃","2Al + 3Br₂ → 2AlBr₃"]'::jsonb, 'تطبيق', 'اختيار معادلة تحقق حفظ الكتلة', 'سهل', 'الكتاب ص 119 — الشكل: معادلة موزونة للألومنيوم والبروم'),
('mcq', 5, 'في التفاعل H₂ + Cl₂ → 2HCl تتساوى كتلة المتفاعلات مع كتلة النواتج. ما التفسير الصحيح لذلك؟', null, '["تتحول ذرات الكلور أثناء التفاعل إلى ذرات هيدروجين","تتكون ذرات جديدة أثناء التفاعل تعوّض كتلة الذرات المتفاعلة","ذرات المتفاعلات تُعاد ترتيبها دون أن تفنى ذرة أو تُستحدث، فيبقى عددها وكتلتها ثابتين","للمتفاعلات والنواتج الصيغ الكيميائية نفسها، فتتساوى كتلتاهما"]'::jsonb, 'فهم', 'تفسير حفظ الكتلة بالذرات', 'متوسط', 'الكتاب ص 119 — المعادلات الكيميائية الرمزية الموزونة'),
('mcq', 6, 'ما الذي توضحه المعادلة الكيميائية الموزونة؟', null, '["أنواع المواد المتضمنة في التفاعل وكمياتها النسبية","سرعة التفاعل والزمن اللازم لانتهائه","درجة الحرارة التي يجب أن يجري عندها التفاعل","لون المواد الناتجة ورائحتها"]'::jsonb, 'تذكر', 'تذكر دلالة المعادلة الموزونة', 'سهل', 'الكتاب ص 119 — المعادلات الكيميائية الرمزية الموزونة'),
('mcq', 7, 'كتب طالبان معادلتين للتفاعل بين الميثان CH₄ والأكسجين: الأولى CH₄ + 2O₂ → CO₂ + H₂O والثانية CH₄ + 2O₂ → CO₂ + 2H₂O. أيّ العبارات الآتية تفسّر الفرق بينهما في ضوء قانون حفظ الكتلة؟', null, '["الأولى موزونة لأن ذرات الكربون متساوية على الجانبين، والثانية غير موزونة لأن فيها ماءً أكثر","كلتاهما موزونة لأن المتفاعلات والنواتج تتكون من العناصر نفسها: الكربون والهيدروجين والأكسجين","الأولى موزونة لأن معاملات CO₂ وH₂O فيها تساوي معامل CH₄ وهو 1","الثانية فقط موزونة؛ ففيها 4 ذرات هيدروجين و4 ذرات أكسجين في كل جانب، أما الأولى فتُظهر فناء ذرتي هيدروجين وذرة أكسجين"]'::jsonb, 'تحليل', 'مقارنة معادلتين بعد الذرات', 'صعب', 'الكتاب ص 122 — تحقيق قانون حفظ الكتلة'),
('essay', 1, 'فسّر أهمية وزن المعادلة الكيميائية في ضوء قانون حفظ الكتلة، مستعينًا بالمعادلة غير الموزونة Al + Br₂ → AlBr₃، ثم اكتب المعادلة الموزونة لها.', null, null, 'فهم', 'تفسير وكتابة معادلة موزونة', 'متوسط', 'الكتاب ص 119، 122 — تحقيق قانون حفظ الكتلة'),
('essay', 2, 'تفاعل 63.5 g من النحاس مع 339.8 g من نترات الفضة، فنتج 215.8 g من الفضة ومادة أخرى هي نترات النحاس II. اكتب معادلة رمزية موزونة للتفاعل، ثم احسب كتلة نترات النحاس II الناتجة مستندًا إلى قانون حفظ الكتلة.', null, null, 'تطبيق', 'حساب كتلة ناتج وكتابة معادلة موزونة', 'صعب', 'الكتاب ص 149 — مسألة التحفيز (س100)'),
('essay', 3, 'كتب طالب التفاعل بين الهيدروجين والكلور هكذا: H₂ + Cl₂ → HCl. (أ) بيّن بعدّ الذرات لماذا لا تتفق هذه المعادلة مع قانون حفظ الكتلة. (ب) صحّح المعادلة. (ج) إذا تفاعل 2.0 g من H₂ تفاعلًا تامًّا مع 71.0 g من Cl₂، فما كتلة HCl الناتجة؟', null, null, 'تحليل', 'تقويم معادلة وتصحيحها وتطبيق حفظ الكتلة', 'صعب', 'الكتاب ص 120، 122 — خطوات وزن المعادلات وحفظ الكتلة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L1-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'ينص قانون حفظ الكتلة على أن المادة لا تفنى ولا تُستحدث خلال التغير الكيميائي، لذا يجب أن تُظهر المعادلة عددًا متساويًا من ذرات كل عنصر على جانبي السهم، وهذا ما تحققه المعادلة الموزونة.', '["","عدد الجزيئات قد يختلف بين الجانبين (مثل H₂ + Cl₂ → 2HCl)؛ المطلوب تساوي عدد ذرات كل عنصر لا عدد الجزيئات.","الحالات الفيزيائية قد تختلف بين المتفاعلات والنواتج، وهي لا علاقة لها بحفظ الكتلة.","المعاملات تُعدَّل لتتساوى أعداد الذرات، وقد تكون أكبر من 1؛ وإبقاؤها 1 قد يجعل المعادلة غير موزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.788Z"}'::jsonb),
('mcq', 2, 2, 'في المتفاعلات ذرة Al واحدة وذرتا Br، وفي النواتج ذرة Al واحدة وثلاث ذرات Br؛ أي إن ذرة بروم تظهر دون مصدر، والذرات لا تُستحدث في التفاعلات الكيميائية، لذلك المعادلة غير موزونة.', '["ذرة الألومنيوم واحدة في الجانبين، والخلل في عدد ذرات البروم.","الصيغة AlBr₃ صحيحة لأن عدد تأكسد Al هو +3 وعدد تأكسد Br هو −1؛ المشكلة في المعاملات لا في الصيغة.","","كتابة الحالات الفيزيائية لا تؤثر في عدد الذرات؛ فالمعادلة غير موزونة حتى مع كتابتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.788Z"}'::jsonb),
('mcq', 3, 1, 'وفق قانون حفظ الكتلة تساوي كتلة النواتج كتلة المتفاعلات: 48.6 g + 32.0 g = 80.6 g من أكسيد المغنسيوم.', '["هذا ناتج طرح كتلة الأكسجين من كتلة المغنسيوم (48.6 − 32.0)، والصحيح جمع كتلتي المتفاعلين.","","هذه كتلة المغنسيوم وحده؛ فقد أُهملت كتلة الأكسجين المتحد معه في الناتج.","هذه نصف المجموع (80.6 ÷ 2)، ولا يوجد سبب لقسمة كتلة الناتج على معامل في هذا الحساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.788Z"}'::jsonb),
('mcq', 4, 3, 'في المعادلة 2Al + 3Br₂ → 2AlBr₃ توجد ذرتا Al وست ذرات Br في كل من المتفاعلات والنواتج، فلا تفنى ذرة ولا تُستحدث، وهذا ما يتطلبه قانون حفظ الكتلة.', '["فيها ذرتا Br في المتفاعلات وثلاث ذرات في النواتج؛ فهي غير موزونة.","فيها ذرتا Br في المتفاعلات وست ذرات في النواتج؛ فهي غير موزونة.","فيها ست ذرات Br في المتفاعلات وثلاث ذرات في النواتج؛ فهي غير موزونة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.789Z"}'::jsonb),
('mcq', 5, 2, 'في التفاعل الكيميائي تُعاد ترتيب الذرات في روابط جديدة دون فناء أي ذرة أو استحداثها؛ فيبقى عدد الذرات وكتلتها ثابتين، ولهذا تتساوى كتلة المتفاعلات مع كتلة النواتج.', '["الذرات لا تتحول من عنصر إلى آخر في التفاعلات الكيميائية؛ تبقى ذرات الكلور كلورًا.","الذرات لا تُستحدث في التفاعلات الكيميائية، فلا حاجة إلى ذرات جديدة تعوّض شيئًا.","","صيغ النواتج تختلف عن صيغ المتفاعلات (HCl تختلف عن H₂ وCl₂)؛ وسبب تساوي الكتلة هو بقاء الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.789Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة الكيميائية الموزونة تعبير يستخدم الصيغ الكيميائية لتوضيح أنواع المواد المتضمنة في التفاعل وكمياتها النسبية، مع تساوي عدد ذرات كل عنصر في الجانبين.', '["","المعادلة الموزونة لا تبيّن سرعة التفاعل ولا زمنه.","المعادلة الموزونة لا تحدد درجة الحرارة المطلوبة.","الألوان والروائح مشاهدات تجريبية لا تُعبّر عنها المعادلة الموزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.789Z"}'::jsonb),
('mcq', 7, 3, 'في المتفاعلات 1 C و4 H و4 O. في الأولى تحتوي النواتج على 1 C و2 H و3 O، أي تفنى ذرتا هيدروجين وذرة أكسجين فتخالف حفظ الكتلة. وفي الثانية تحتوي النواتج على 1 C و4 H و4 O، فهي موزونة.', '["تساوي ذرات عنصر واحد لا يكفي؛ يجب أن يتساوى عدد ذرات كل عنصر، وفي الأولى لا يتساوى الهيدروجين والأكسجين.","تساوي أنواع العناصر لا يكفي لحفظ الكتلة؛ يجب أن يتساوى عدد ذرات كل عنصر، وهو غير متحقق في الأولى.","تساوي المعاملات لا يعني تساوي الذرات؛ فعدد ذرات الهيدروجين والأكسجين يختلف بين جانبي الأولى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.789Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص قانون حفظ الكتلة على أن المادة لا تفنى ولا تُستحدث خلال التغير الكيميائي، لذا يجب أن تُظهر المعادلة عددًا متساويًا من ذرات كل عنصر في جانبي السهم. في المعادلة Al + Br₂ → AlBr₃ توجد ذرة Al واحدة وذرتا Br في المتفاعلات، وذرة Al واحدة وثلاث ذرات Br في النواتج؛ فكأن ذرة بروم استُحدثت، وهذا يخالف القانون، فالمعادلة غير موزونة ولا تمثل التفاعل تمثيلًا صحيحًا. وزن المعادلة بتعديل المعاملات يجعل عدد الذرات متساويًا في الجانبين: 2Al + 3Br₂ → 2AlBr₃، ففيها ذرتا Al وست ذرات Br في كل جانب.', '["المادة لا تفنى ولا تُستحدث خلال التغير الكيميائي","يجب أن يتساوى عدد ذرات كل عنصر في جانبي المعادلة","في المعادلة غير الموزونة: 2 Br في المتفاعلات و3 Br في النواتج","هذا يعني استحداث ذرة وهو مخالف للقانون","المعادلة الموزونة: 2Al + 3Br₂ → 2AlBr₃"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر نص قانون حفظ الكتلة وضرورة تساوي عدد ذرات كل عنصر","marks":1},{"element":"عدّ ذرات Br في الجانبين (2 مقابل 3)","marks":1},{"element":"ربط الفرق باستحداث ذرة ومخالفة القانون","marks":1},{"element":"كتابة المعادلة الموزونة 2Al + 3Br₂ → 2AlBr₃","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص القانون، وعدّ الذرات، وربط الفرق بمخالفة القانون، والمعادلة الموزونة الصحيحة"},{"level":"2–3 درجات","description":"تفسير صحيح جزئيًا أو معادلة موزونة صحيحة دون تفسير كافٍ"},{"level":"1 درجة","description":"ذكر أن المادة لا تفنى فقط دون تطبيق على المعادلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن يهدف إلى تساوي عدد الجزيئات لا عدد الذرات","تعديل الصيغة إلى AlBr₂ لتتساوى ذرات البروم","ذكر القانون دون عدّ الذرات في الجانبين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.789Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة الموزونة: Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag. وفق قانون حفظ الكتلة تساوي كتلة المتفاعلات كتلة النواتج. كتلة المتفاعلات = 63.5 g + 339.8 g = 403.3 g. كتلة نترات النحاس II = 403.3 g − 215.8 g = 187.5 g.', '["المعادلة الموزونة: Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag","كتلة المتفاعلات = كتلة النواتج","مجموع كتل المتفاعلات = 403.3 g","كتلة نترات النحاس II = 187.5 g"]'::jsonb, '["كتابة المعادلة: Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag (1 Cu و2 Ag و2 N و6 O في كل جانب)","مجموع كتل المتفاعلات = 63.5 g + 339.8 g = 403.3 g","كتلة النواتج = كتلة المتفاعلات = 403.3 g","كتلة نترات النحاس II = 403.3 g − 215.8 g = 187.5 g"]'::jsonb, '[{"element":"صيغ المواد صحيحة في المعادلة","marks":1},{"element":"معاملات المعادلة الموزونة صحيحة","marks":1},{"element":"استخدام قانون حفظ الكتلة وجمع كتلتي المتفاعلين (403.3 g)","marks":1},{"element":"طرح كتلة الفضة للحصول على 187.5 g مع الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة موزونة صحيحة وحساب صحيح لكتلة نترات النحاس II (187.5 g) مع الوحدة"},{"level":"2–3 درجات","description":"معادلة صحيحة مع خطأ حسابي، أو حساب صحيح مع خطأ في المعاملات أو الصيغ"},{"level":"1 درجة","description":"ذكر أن كتلة المتفاعلات تساوي كتلة النواتج دون إتمام الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح كتلة النحاس فقط أو كتلة نترات الفضة فقط من كتلة الفضة","كتابة الصيغة Cu(NO₃) بدل Cu(NO₃)₂","نسيان المعامل 2 قبل AgNO₃ وقبل Ag"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.790Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في المتفاعلات ذرتا H وذرتا Cl، وفي النواتج ذرة H واحدة وذرة Cl واحدة؛ أي تفنى ذرة هيدروجين وذرة كلور، والمادة لا تفنى خلال التغير الكيميائي، فالمعادلة مخالفة لقانون حفظ الكتلة. (ب) تُصحَّح بوضع المعامل 2 قبل HCl: H₂ + Cl₂ → 2HCl، فتصبح ذرتا H وذرتا Cl في كل جانب. (ج) كتلة النواتج تساوي كتلة المتفاعلات: 2.0 g + 71.0 g = 73.0 g من HCl.', '["عدّ الذرات: 2H و2Cl في المتفاعلات مقابل 1H و1Cl في النواتج","فناء ذرات يخالف قانون حفظ الكتلة","المعادلة الصحيحة: H₂ + Cl₂ → 2HCl (بتغيير المعامل لا الصيغة)","كتلة HCl = 2.0 g + 71.0 g = 73.0 g"]'::jsonb, '["عدّ ذرات المتفاعلات: 2H و2Cl؛ وعدّ ذرات النواتج: 1H و1Cl","وضع المعامل 2 قبل HCl فتتساوى الذرات: 2H و2Cl في كل جانب","كتلة HCl = كتلة المتفاعلات = 2.0 g + 71.0 g = 73.0 g"]'::jsonb, '[{"element":"عدّ الذرات في الجانبين بشكل صحيح","marks":1},{"element":"تفسير المخالفة بفناء ذرات وربطها بقانون حفظ الكتلة","marks":1},{"element":"تصحيح المعادلة بتغيير المعامل فقط: H₂ + Cl₂ → 2HCl","marks":1},{"element":"حساب كتلة HCl الناتجة 73.0 g مع الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عدّ صحيح للذرات، وتفسير بحفظ الكتلة، وتصحيح بالمعامل، وكتلة 73.0 g"},{"level":"2–3 درجات","description":"إنجاز عنصرين أو ثلاثة من العناصر الأربعة بشكل صحيح"},{"level":"1 درجة","description":"إنجاز عنصر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح المعادلة بكتابة H₂Cl₂ أو HCl₂ بدل تغيير المعامل","طرح كتلتي المتفاعلين بدل جمعهما","الاكتفاء بتصحيح المعادلة دون تفسير المخالفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.790Z"}'::jsonb)
