('mcq', 2, 'ما الذي يُسمح بتغييره عند وزن المعادلة الكيميائية؟', null, '["الأرقام السفلية في صيغ المتفاعلات","رموز العناصر في صيغ النواتج","الحالة الفيزيائية لكل مادة","المعاملات المكتوبة قبل الصيغ الكيميائية"]'::jsonb, 'تذكر', 'تذكر ما يجوز تغييره عند الوزن', 'سهل', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوة 4)'),
('mcq', 3, 'لوزن المعادلة C + O₂ → CO غيّر طالب صيغة الناتج إلى CO₂ لتتساوى ذرات الأكسجين في الجانبين. لماذا يُعد ذلك خطأً؟', null, '["لأن تغيير الرقم السفلي يغيّر نوع المادة، فـ CO₂ مادة مختلفة عن CO","لأن الأرقام السفلية يجب أن تساوي 1 دائمًا في صيغ النواتج","لأن ذرات الأكسجين لا تتساوى في الجانبين حتى بعد هذا التغيير","لأن الصيغة CO₂ لا تحتوي على ذرات الكربون"]'::jsonb, 'فهم', 'تفسير خطأ تغيير الرقم السفلي', 'متوسط', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوة 4)'),
('mcq', 4, 'وُزنت معادلة تفاعل الهيدروجين مع الكلور بعدة صور. أيّها مكتوبة بأبسط نسبة عددية صحيحة للمعاملات؟', null, '["2H₂ + 2Cl₂ → 4HCl","H₂ + Cl₂ → HCl","H₂ + Cl₂ → 2HCl","4H₂ + 4Cl₂ → 8HCl"]'::jsonb, 'فهم', 'اختيار أبسط نسبة للمعاملات', 'متوسط', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوة 5)'),
('mcq', 5, 'كم ذرة هيدروجين يمثلها التعبير 2Al(OH)₃؟', null, '["3","5","2","6"]'::jsonb, 'تطبيق', 'حساب عدد الذرات من المعامل والرقم السفلي', 'سهل', 'الكتاب ص 119، 120 — المعامل والصيغة الكيميائية'),
('mcq', 6, 'أيّ التعديلات الآتية تَزِن المعادلة Mg + O₂ → MgO دون تغيير نوع أي مادة فيها؟', null, '["Mg + O₂ → MgO₂","2Mg + O₂ → 2MgO","Mg + O → MgO","Mg₂ + O₂ → 2MgO"]'::jsonb, 'تحليل', 'تمييز وزن صحيح من وزن بتغيير الصيغ', 'صعب', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوة 4)'),
('mcq', 7, 'لماذا تُكتب معاملات المعادلة الموزونة بأبسط نسبة عددية صحيحة؟', null, '["لأنها تعبّر عن الكميات النسبية للمواد بأصغر أعداد صحيحة لا يمكن اختصارها أكثر","لأن استخدام معاملات أكبر من الأصغر يغيّر نوع المواد المتفاعلة نفسها","لأن استخدام معاملات أكبر يخالف قانون حفظ الكتلة ولو تساوت الذرات","لأن المعاملات يجب أن تكون كسورًا حتى تتساوى الذرات على الجانبين"]'::jsonb, 'فهم', 'تفسير أبسط نسبة للمعاملات', 'متوسط', 'الكتاب ص 119، 120 — المعامل وأبسط نسبة عددية'),
('essay', 1, 'في التعبير 3Ca(OH)₂: (أ) وضّح دلالة كل من العدد 3 (المعامل) والعدد 2 (الرقم السفلي). (ب) احسب عدد ذرات كل عنصر يمثلها هذا التعبير. (ج) أيّ العددين يجوز تغييره عند وزن المعادلة؟ ولماذا؟', null, null, 'فهم', 'تمييز المعامل من الرقم السفلي وحساب الذرات', 'متوسط', 'الكتاب ص 119، 120 — المعامل وخطوات وزن المعادلات'),
('essay', 2, 'أراد طالب وزن المعادلة Li + Cl₂ → LiCl، فكتب Li + Cl₂ → LiCl₂ مدّعيًا أن ذرات الكلور تساوت. قوّم عمل الطالب: (أ) هل تساوت الذرات فعلًا في معادلته؟ (ب) لماذا لا يُقبل حله؟ (ج) اكتب المعادلة الموزونة الصحيحة.', null, null, 'تقويم', 'تقويم حل طالب لوزن معادلة', 'صعب', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوة 4)'),
('essay', 3, 'زن المعادلة K(s) + H₂O(l) → KOH(aq) + H₂(g) مبينًا خطواتك. ثم بيّن أن المعادلة 4K + 4H₂O → 4KOH + 2H₂ موزونة أيضًا، واذكر لماذا تُفضَّل صورتك الأولى عليها.', null, null, 'تطبيق', 'وزن معادلة وتفسير أبسط نسبة', 'صعب', 'الكتاب ص 120 — خطوات وزن المعادلات (الخطوتان 4 و5)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
