select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'العدد 3 المكتوب قبل الصيغة هو المعامل ويدل على عدد جزيئات الماء، أما العدد 2 المكتوب أسفل رمز الهيدروجين فهو رقم سفلي يدل على ذرتي هيدروجين في كل جزيء H₂O.', '["هنا عُكست الأدوار؛ فالعدد المكتوب قبل الصيغة معامل، والمكتوب أسفل الرمز رقم سفلي.","","العدد 2 مكتوب أسفل الرمز H، لذا فهو رقم سفلي يخص عدد ذرات الهيدروجين في الجزيء وليس معاملًا.","العدد 3 مكتوب قبل الصيغة، فهو معامل وليس رقمًا سفليًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.790Z"}'::jsonb),
('mcq', 2, 3, 'يتم وزن المعادلة بتغيير المعاملات قبل الصيغ لتتساوى أعداد الذرات في الجانبين، أما الصيغ نفسها وأرقامها السفلية فلا تُغيَّر لأن ذلك يغيّر نوع المادة.', '["تغيير الرقم السفلي يغيّر الصيغة ويحوّل المادة إلى مادة أخرى.","تغيير رموز العناصر يحوّل المادة إلى مادة مختلفة، ولا يُعد وزنًا للمعادلة.","الحالة الفيزيائية وصف لحالة المادة ولا تؤثر في عدد الذرات، فلا تُعدَّل لوزن المعادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.790Z"}'::jsonb),
('mcq', 3, 0, 'أول أكسيد الكربون CO وثاني أكسيد الكربون CO₂ مادتان مختلفتان؛ فتغيير الرقم السفلي يغيّر نوع المادة. والطريقة الصحيحة تغيير المعاملات: 2C + O₂ → 2CO.', '["","الأرقام السفلية ليست دائمًا 1، فكثير من الصيغ تحتوي أرقامًا سفلية مثل CO₂ وH₂O؛ لكن لا يجوز تغييرها لوزن المعادلة.","ذرات الأكسجين تتساوى فعلًا (2 في كل جانب) بعد التغيير؛ لكن الناتج صار مادة أخرى.","الصيغة CO₂ تحتوي ذرة كربون واحدة؛ والخطأ هو تغيير نوع المادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('mcq', 4, 2, 'المعاملات في H₂ + Cl₂ → 2HCl هي 1 : 1 : 2، وهي أصغر نسبة لا يمكن اختصارها أكثر مع بقاء الأعداد صحيحة، وفيها ذرتا H وذرتا Cl في كل جانب.', '["موزونة، لكن نسبتها 2 : 2 : 4 يمكن اختصارها إلى 1 : 1 : 2.","غير موزونة؛ فيها ذرتا H وذرتا Cl في المتفاعلات وذرة واحدة من كل منهما في النواتج.","","موزونة، لكن نسبتها 4 : 4 : 8 يمكن اختصارها إلى 1 : 1 : 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('mcq', 5, 3, 'الرقم السفلي 3 خارج القوسين يضاعف مجموعة OH فتحتوي كل وحدة Al(OH)₃ على 3 ذرات هيدروجين، والمعامل 2 يضاعف الصيغة كلها، فعدد ذرات الهيدروجين = 2 × 3 = 6.', '["هذا عدد ذرات الهيدروجين في وحدة واحدة فقط؛ أُهمل المعامل 2.","هذا ناتج جمع المعامل مع الرقم السفلي (2 + 3)، والصحيح ضربهما.","هذا هو المعامل نفسه، وأُهمل الرقم السفلي الذي يحدد عدد مجموعات OH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('mcq', 6, 1, 'المعادلة 2Mg + O₂ → 2MgO وُزنت بتغيير المعاملات فقط، فبقيت الصيغ Mg وO₂ وMgO كما هي وتساوت الذرات (2 Mg و2 O في كل جانب).', '["غيّرت الرقم السفلي في الناتج إلى MgO₂، وهذه مادة مختلفة عن MgO، فالموازنة العددية ناتجة عن تغيير الصيغة.","","غيّرت صيغة الأكسجين O₂ إلى O، فتغيّر نوع المادة؛ فالأكسجين يوجد على هيئة جزيئات O₂.","غيّرت صيغة المغنسيوم إلى Mg₂ وهي صيغة لا تمثل المغنسيوم الفلز؛ فتغيّر نوع المادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('mcq', 7, 0, 'تصف المعاملات الكميات النسبية للمتفاعلات والنواتج، وتُكتب بأبسط نسبة أي بأصغر أعداد صحيحة لا يمكن اختصارها أكثر؛ فالنسبة 1 : 1 : 2 مثلًا تغني عن 2 : 2 : 4.', '["","المعاملات لا تغيّر نوع المواد؛ الذي يغيّرها هو تغيير الأرقام السفلية في الصيغ.","المعادلة ذات المعاملات الأكبر قد تكون موزونة أيضًا، لكنها ليست بأبسط صورة؛ فلا تخالف حفظ الكتلة.","المعاملات تكون عادة أعدادًا صحيحة ولا تُكتب كسورًا في المعادلة الموزونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المعامل 3 مكتوب قبل الصيغة ويدل على وجود ثلاث وحدات من Ca(OH)₂، أما الرقم السفلي 2 فهو جزء من الصيغة ويدل على وجود مجموعتي OH في كل وحدة. (ب) Ca: 3 × 1 = 3 ذرات، O: 3 × 2 = 6 ذرات، H: 3 × 2 = 6 ذرات. (ج) يجوز تغيير المعامل فقط لتتساوى أعداد الذرات في جانبي المعادلة؛ أما الرقم السفلي فلا يُغيَّر لأن تغييره يغيّر الصيغة ويحوّلها إلى مادة أخرى.', '["المعامل 3 قبل الصيغة: عدد وحدات المركب","الرقم السفلي 2: عدد مجموعات OH في الوحدة","Ca = 3 وO = 6 وH = 6","يُغيَّر المعامل فقط","تغيير الرقم السفلي يغيّر نوع المادة"]'::jsonb, '["Ca: المعامل 3 × 1 = 3 ذرات","O: المعامل 3 × الرقم السفلي 2 = 6 ذرات","H: المعامل 3 × الرقم السفلي 2 = 6 ذرات"]'::jsonb, '[{"element":"دلالة المعامل والرقم السفلي بشكل صحيح","marks":1},{"element":"حساب عدد ذرات كل عنصر (Ca = 3، O = 6، H = 6)","marks":1},{"element":"تحديد أن المعامل هو ما يجوز تغييره","marks":1},{"element":"تعليل ذلك بأن تغيير الرقم السفلي يغيّر نوع المادة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تمييز صحيح بين المعامل والرقم السفلي، وحساب صحيح للذرات، وتحديد المعامل مع التعليل"},{"level":"2–3 درجات","description":"إنجاز عنصرين أو ثلاثة من العناصر الأربعة بشكل صحيح"},{"level":"1 درجة","description":"إنجاز عنصر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات O وH بـ 2 فقط دون ضرب المعامل","الخلط بين المعامل والرقم السفلي","القول إن الرقم السفلي يمكن تغييره عند الحاجة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.791Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نعم، تساوت الذرات عدديًّا في معادلته: ذرة Li وذرتا Cl في كل جانب. (ب) لكنه غيّر الرقم السفلي في صيغة الناتج، وتغيير الرقم السفلي يغيّر نوع المادة؛ فالصيغة LiCl₂ لا تمثل كلوريد الليثيوم، إذ عدد تأكسد Li هو +1 وعدد تأكسد Cl هو −1، فالصيغة الصحيحة LiCl. ولا يجوز تغيير الصيغ لوزن المعادلة. (ج) يُوزن التفاعل بتغيير المعاملات: 2Li + Cl₂ → 2LiCl، ففيها ذرتا Li وذرتا Cl في كل جانب.', '["الذرات تساوت عدديًّا في معادلة الطالب","تغيير الرقم السفلي غيّر نوع المادة","LiCl₂ ليست كلوريد الليثيوم (عدد التأكسد +1 و−1 يعطي LiCl)","الوزن يكون بتغيير المعاملات فقط","المعادلة الصحيحة: 2Li + Cl₂ → 2LiCl"]'::jsonb, '[]'::jsonb, '[{"element":"الإقرار بأن الذرات تساوت عدديًّا (1 Li و2 Cl في كل جانب)","marks":1},{"element":"بيان أن تغيير الرقم السفلي يغيّر نوع المادة","marks":1},{"element":"تعليل أن LiCl₂ ليست الصيغة الصحيحة لكلوريد الليثيوم","marks":1},{"element":"ذكر أن الوزن يتم بتغيير المعاملات فقط","marks":1},{"element":"كتابة المعادلة الموزونة 2Li + Cl₂ → 2LiCl","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل: إقرار بتساوي الذرات، وتعليل رفض تغيير الصيغة، وذكر تغيير المعاملات، ومعادلة صحيحة"},{"level":"3–4 درجات","description":"تقويم صحيح لمعظم العناصر مع نقص في التعليل أو في المعادلة"},{"level":"1–2 درجة","description":"ذكر المعادلة الصحيحة أو أن تغيير الصيغة خطأ دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرات لم تتساو في معادلة الطالب","اعتبار الحل مقبولًا لأن عدد الذرات صار متساويًا","كتابة المعادلة الموزونة 2Li + 2Cl → 2LiCl بتغيير صيغة الكلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.792Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعدّ ذرات المتفاعلات: 1 K و2 H و1 O؛ ونعدّ ذرات النواتج: 1 K و3 H و1 O؛ فالهيدروجين غير متساوٍ. نغيّر المعاملات فقط دون تغيير الصيغ: نضع 2 قبل H₂O و2 قبل KOH فيصبح الأكسجين 2 والهيدروجين 4 في الجهة اليسرى، ونضع 2 قبل K ليتساوى البوتاسيوم، ثم نتأكد أن الهيدروجين في النواتج (2 من KOH و2 من H₂) يساوي 4: 2K + 2H₂O → 2KOH + H₂. النسبة 2 : 2 : 2 : 1. المعادلة 4K + 4H₂O → 4KOH + 2H₂ موزونة أيضًا (4 K و8 H و4 O في كل جانب)، لكن نسبتها 4 : 4 : 4 : 2 يمكن اختصارها بالقسمة على 2 إلى 2 : 2 : 2 : 1؛ لذلك تُفضَّل الصورة الأولى لأن المعاملات تُكتب بأبسط نسبة عددية صحيحة.', '["عدّ الذرات في الجانبين وإيجاد عدم تساوي الهيدروجين","تغيير المعاملات فقط دون تغيير الصيغ","2K + 2H₂O → 2KOH + H₂","التحقق من تساوي الذرات في الجانبين","المعادلة ذات المعاملات 4 : 4 : 4 : 2 موزونة لكنها غير مختصرة"]'::jsonb, '["المتفاعلات: 1 K و2 H و1 O؛ النواتج: 1 K و3 H و1 O","وضع 2 قبل H₂O و2 قبل KOH ثم 2 قبل K: 2K + 2H₂O → 2KOH + H₂","التحقق: 2 K و4 H و2 O في كل جانب، والنسبة 2 : 2 : 2 : 1","المعادلة 4K + 4H₂O → 4KOH + 2H₂: 4 K و8 H و4 O في كل جانب، لكن يمكن اختصار نسبتها بالقسمة على 2"]'::jsonb, '[{"element":"عدّ الذرات في الجانبين وتحديد الخلل","marks":1},{"element":"معادلة موزونة صحيحة 2K + 2H₂O → 2KOH + H₂ بتغيير المعاملات فقط","marks":2},{"element":"التحقق من تساوي الذرات وكتابة النسبة 2 : 2 : 2 : 1","marks":1},{"element":"تفسير تفضيل أبسط نسبة وإمكان اختصار 4 : 4 : 4 : 2","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"عدّ صحيح، ومعادلة موزونة بتغيير المعاملات فقط، وتحقق من الذرات، وتفسير أبسط نسبة"},{"level":"3–4 درجات","description":"معادلة صحيحة مع نقص في الخطوات أو في التفسير"},{"level":"1–2 درجة","description":"عدّ الذرات أو محاولة وزن غير مكتملة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة KOH₂ أو H₃ لتساوي الهيدروجين بتغيير الصيغ","الاكتفاء بـ 2K + H₂O → 2KOH + H₂ دون التحقق من الأكسجين والهيدروجين","اعتبار المعادلة ذات المعاملات 4 : 4 : 4 : 2 غير موزونة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.792Z"}'::jsonb)
