from (values
('mcq', 1, 2, 'الأيون Na⁺ موجب الشحنة (+1)، فعدد إلكتروناته = 11 − 1 = 10، وتوزيعها: 1s² 2s² 2p⁶.', '["هذا توزيع ذرة الصوديوم المتعادلة (11 إلكترونًا) ولم تُطرح منه الشحنة.","هذا توزيع 12 إلكترونًا؛ فقد أُضيف إلكترون بدل طرحه، والأيون الموجب يفقد الإلكترونات.","","هذا توزيع 9 إلكترونات؛ فقد طُرح إلكترونان بدل إلكترون واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.792Z"}'::jsonb),
('mcq', 2, 0, 'الأيون Cl⁻ سالب الشحنة (−1)، فيكتسب إلكترونًا واحدًا: عدد إلكتروناته = 17 + 1 = 18، وتوزيعها: 1s² 2s² 2p⁶ 3s² 3p⁶.', '["","هذا توزيع ذرة الكلور المتعادلة (17 إلكترونًا) ولم يُضف إليها الإلكترون المكتسب.","هذا توزيع 16 إلكترونًا؛ فقد طُرح إلكترون بدل إضافته، والأيون السالب يكتسب الإلكترونات.","هذا توزيع 19 إلكترونًا؛ فقد أُضيف إلكترونان بدل إلكترون واحد، وشحنة الكلوريد −1 فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.792Z"}'::jsonb),
('mcq', 3, 3, 'الأيون S²⁻ سالب الشحنة (−2)، فيكتسب إلكترونين إلى عدد إلكترونات ذرته المتعادلة: 16 + 2 = 18 إلكترونًا.', '["هذا مقدار الشحنة وليس عدد الإلكترونات.","هذا ناتج طرح الشحنة (16 − 2)، وهو يصح للأيون الموجب لا السالب.","هذا عدد إلكترونات ذرة الكبريت المتعادلة، ولم تُضف إليه الإلكترونات المكتسبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.793Z"}'::jsonb),
('mcq', 4, 1, 'التوزيع 1s² 2s² 2p⁶ يمثل 10 إلكترونات، وأيون Mg²⁺ عدد إلكتروناته 12 − 2 = 10، فتوزيعه 1s² 2s² 2p⁶.', '["عدد إلكترونات Cl⁻ هو 17 + 1 = 18، وتوزيعه ينتهي بـ 3s² 3p⁶.","","عدد إلكترونات S²⁻ هو 16 + 2 = 18، وتوزيعه ينتهي بـ 3s² 3p⁶.","عدد إلكترونات Li⁺ هو 3 − 1 = 2، وتوزيعه 1s² فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-18T03:27:04.793Z"}'::jsonb),
('mcq', 5, 0, 'ذرة P تحتوي على 15 إلكترونًا: 1s² 2s² 2p⁶ 3s² 3p³. والأيون P³⁻ سالب الشحنة (−3) فعدد إلكتروناته 15 + 3 = 18، وتُضاف الإلكترونات الثلاثة إلى 3p فيصبح التوزيع 1s² 2s² 2p⁶ 3s² 3p⁶.', '["","هذا يصح لأيون موجب الشحنة (P³⁺)؛ أما P³⁻ فيكتسب إلكترونات.","المستوى 3p يتسع لـ 6 إلكترونات، فتُضاف الإلكترونات الثلاثة إليه أولًا قبل 4s.","تكوين الأيون يعني فقدان إلكترونات أو اكتسابها، فيتغير عدد الإلكترونات وبالتالي التوزيع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.793Z"}'::jsonb),
('mcq', 6, 2, 'الأيون Ca²⁺ موجب الشحنة (+2)، فعدد إلكتروناته = 20 − 2 = 18. وتوزيع ذرة Ca هو 1s² 2s² 2p⁶ 3s² 3p⁶ 4s²، فيفقد الإلكترونين من 4s ويصبح توزيعه 1s² 2s² 2p⁶ 3s² 3p⁶.', '["هذا توزيع ذرة الكالسيوم المتعادلة (20 إلكترونًا) ولم تُطرح منه الشحنة.","هذا توزيع 19 إلكترونًا؛ فقد طُرح إلكترون واحد فقط بدل إلكترونين.","","هذا توزيع 22 إلكترونًا؛ فقد أُضيف إلكترونان بدل طرحهما، والأيون الموجب يفقد الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.793Z"}'::jsonb),
('mcq', 7, 1, 'عدد إلكترونات Al³⁺ = 13 − 3 = 10، وعدد إلكترونات O²⁻ = 8 + 2 = 10؛ فلكل منهما التوزيع نفسه 1s² 2s² 2p⁶.', '["Mg²⁺ فيه 10 إلكترونات (1s² 2s² 2p⁶) وCl⁻ فيه 18 إلكترونًا، فتوزيعاهما مختلفان.","","K⁺ فيه 18 إلكترونًا وNa⁺ فيه 10 إلكترونات، فتوزيعاهما مختلفان.","S²⁻ فيه 18 إلكترونًا وMg²⁺ فيه 10 إلكترونات، فتوزيعاهما مختلفان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-18T03:27:04.793Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ذرة Mg: 12 إلكترونًا: 1s² 2s² 2p⁶ 3s². أيون Mg²⁺ موجب الشحنة (+2) فعدد إلكتروناته = 12 − 2 = 10: 1s² 2s² 2p⁶. ذرة O: 8 إلكترونات: 1s² 2s² 2p⁴. أيون O²⁻ سالب الشحنة (−2) فعدد إلكتروناته = 8 + 2 = 10: 1s² 2s² 2p⁶. نطرح مقدار الشحنة من العدد الذري للأيون الموجب، ونضيف مقدار الشحنة إلى العدد الذري للأيون السالب. للأيونين Mg²⁺ وO²⁻ التوزيع نفسه 1s² 2s² 2p⁶ لأن كلًّا منهما يحتوي على 10 إلكترونات.', '["Mg: 1s² 2s² 2p⁶ 3s²","Mg²⁺: 12 − 2 = 10 إلكترونات: 1s² 2s² 2p⁶","O: 1s² 2s² 2p⁴","O²⁻: 8 + 2 = 10 إلكترونات: 1s² 2s² 2p⁶","الأيونان لهما التوزيع نفسه لتساوي عدد الإلكترونات (10)"]'::jsonb, '["عدد إلكترونات Mg²⁺ = 12 − 2 = 10","عدد إلكترونات O²⁻ = 8 + 2 = 10","كتابة التوزيع لـ 10 إلكترونات: 1s² 2s² 2p⁶"]'::jsonb, '[{"element":"توزيع ذرتي Mg وO صحيح","marks":1},{"element":"حساب عدد إلكترونات Mg²⁺ (طرح الشحنة) وكتابة توزيعه","marks":1},{"element":"حساب عدد إلكترونات O²⁻ (إضافة الشحنة) وكتابة توزيعه","marks":1},{"element":"المقارنة وتعليل تطابق التوزيعين بتساوي عدد الإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توزيعات الذرتين والأيونين صحيحة مع حساب عدد الإلكترونات والمقارنة"},{"level":"2–3 درجات","description":"توزيعات صحيحة لبعض الأنواع مع خطأ في أحد الحسابين أو غياب المقارنة"},{"level":"1 درجة","description":"توزيع الذرتين المتعادلتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة الشحنة إلى الأيون الموجب بدل طرحها","طرح الشحنة من الأيون السالب بدل إضافتها","كتابة توزيع الذرة المتعادلة وتسميته توزيع الأيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.794Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عدد إلكترونات Br⁻ = 35 + 1 = 36. عدد إلكترونات Sr²⁺ = 38 − 2 = 36. نملأ 36 إلكترونًا بحسب تسلسل مستويات الطاقة: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p⁶. لكل من Br⁻ وSr²⁺ هذا التوزيع نفسه لأن عدد إلكترونات كل منهما 36.', '["عدد إلكترونات Br⁻ = 36","عدد إلكترونات Sr²⁺ = 36","التوزيع: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p⁶","كتابة 4s قبل 3d بحسب تسلسل الطاقة","الأيونان لهما التوزيع نفسه"]'::jsonb, '["Br⁻: 35 + 1 = 36 إلكترونًا","Sr²⁺: 38 − 2 = 36 إلكترونًا","ملء 36 إلكترونًا: 1s² 2s² 2p⁶ 3s² 3p⁶ (18) ثم 4s² (20) ثم 3d¹⁰ (30) ثم 4p⁶ (36)"]'::jsonb, '[{"element":"حساب عدد إلكترونات Br⁻ (36) بإضافة الشحنة","marks":1},{"element":"حساب عدد إلكترونات Sr²⁺ (36) بطرح الشحنة","marks":1},{"element":"كتابة التوزيع الصحيح بتسلسل الطاقة (4s قبل 3d)","marks":1},{"element":"الاستنتاج أن الأيونين لهما التوزيع نفسه مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عدد إلكترونات صحيح للأيونين، وتوزيع صحيح بتسلسل الطاقة، واستنتاج مع تعليل"},{"level":"2–3 درجات","description":"حساب صحيح للإلكترونات مع خطأ في ترتيب المستويات أو في الاستنتاج"},{"level":"1 درجة","description":"حساب صحيح لعدد إلكترونات أحد الأيونين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة الشحنة إلى Sr²⁺ بدل طرحها فيُحصل على 40 إلكترونًا","كتابة 3d قبل 4s","نسيان 4p⁶ أو الاكتفاء بـ 3d¹⁰"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.794Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الأيون N³⁻ سالب الشحنة، أي اكتسب ثلاثة إلكترونات، فيجب إضافة مقدار الشحنة إلى العدد الذري لا طرحه؛ أما الطرح فيكون للأيون الموجب. (ب) عدد إلكترونات N³⁻ = 7 + 3 = 10، فتوزيعه 1s² 2s² 2p⁶. (ج) توزيع ذرة N المتعادلة هو 1s² 2s² 2p³، فيزداد في الأيون عدد الإلكترونات في المستوى 2p من 3 إلى 6 (ثلاثة إلكترونات مكتسبة).', '["الأيون السالب يكتسب إلكترونات فتُضاف الشحنة","الطالب طرح الشحنة وهو خاص بالأيون الموجب","عدد الإلكترونات الصحيح 10","التوزيع: 1s² 2s² 2p⁶","ذرة N: 1s² 2s² 2p³ والفرق ثلاثة إلكترونات في 2p"]'::jsonb, '["عدد إلكترونات N³⁻ = 7 + 3 = 10","توزيع 10 إلكترونات: 1s² 2s² 2p⁶","توزيع ذرة N (7 إلكترونات): 1s² 2s² 2p³؛ الفرق 3 إلكترونات في 2p"]'::jsonb, '[{"element":"تحديد الخطأ: طرح الشحنة بدل إضافتها للأيون السالب","marks":1},{"element":"حساب عدد الإلكترونات الصحيح 10","marks":1},{"element":"كتابة التوزيع الصحيح 1s² 2s² 2p⁶","marks":1},{"element":"بيان الفرق عن ذرة N: 2p³ في الذرة و2p⁶ في الأيون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ، وحساب صحيح، وتوزيع صحيح، وبيان الفرق عن الذرة"},{"level":"2–3 درجات","description":"إنجاز عنصرين أو ثلاثة من العناصر الأربعة بشكل صحيح"},{"level":"1 درجة","description":"كتابة التوزيع الصحيح فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تطبيق قاعدة الأيون الموجب على الأيون السالب","الخلط بين عدد الإلكترونات ومقدار الشحنة","كتابة 2p³ في توزيع الأيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.794Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
