from (values
('mcq', 1, 3, 'تسلسل الطاقة المتصاعد هو: 1s 2s 2p 3s 3p 4s 3d 4p؛ فطاقة 4s أقل من طاقة 3d، وطاقة 3d أقل من طاقة 4p، وهذا يطابق الترتيب 3p ، 4s ، 3d ، 4p.', '["وضع 3d قبل 4s، وطاقة 3d أعلى من طاقة 4s.","وضع 4p قبل 4s و3d، وطاقة 4p أعلى منهما.","وضع 3d قبل 3p، وطاقة 3d أعلى من طاقة 3p، ثم 4s أقل من 3d.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.795Z"}'::jsonb),
('mcq', 2, 1, 'بعد امتلاء 3p بستة إلكترونات يُملأ المستوى 4s لأن طاقته أقل من طاقة 3d، فيكون توزيع ذرة العدد الذري 20: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s².', '["طاقة 3d أعلى من طاقة 4s، فلا يُملأ 3d قبل 4s.","","طاقة 4p أعلى من طاقة 4s و3d، فيأتي بعدهما.","طاقة 5s أعلى بكثير، ويُملأ بعد 4p."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.795Z"}'::jsonb),
('mcq', 3, 2, 'تُملأ المستويات بحسب تسلسل الطاقة: 1s 2s 2p 3s 3p 4s 3d؛ فبعد 3p⁶ (18 إلكترونًا) يُملأ 4s² ثم يدخل الإلكترونان المتبقيان في 3d²، فالتوزيع 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d².', '["كُتب 3d قبل 4s، بينما طاقة 4s أقل فيجب أن يسبقه في الكتابة.","أُهمل المستوى 4s ووُضعت أربعة إلكترونات في 3d، مع أن 4s أقل طاقة ويُملأ أولًا.","","وُضع الإلكترونان الأخيران في 4p قبل 3d، وطاقة 4p أعلى من طاقة 3d."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.795Z"}'::jsonb),
('mcq', 4, 0, 'ترتيب الملء: 1s 2s 2p 3s 3p 4s 3d 4p 5s 4d 5p 6s 4f؛ فالمستوى 5s أقل طاقة من 4d، ويُملأ مباشرة بعد 4p.', '["","المستوى 4d يُملأ بعد 5s لأن طاقة 5s أقل منها.","المستوى 5p يُملأ بعد 4d وليس مباشرة بعد 4p.","المستوى 4f أعلى طاقة بكثير ويُملأ بعد 6s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.795Z"}'::jsonb),
('mcq', 5, 1, 'يُملأ 1s² 2s² 2p⁶ 3s² 3p⁶ (18 إلكترونًا) ثم 4s² (20 إلكترونًا) قبل 3d، فيبقى 26 − 20 = 6 إلكترونات في 3d، وتوزيع الحديد 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶.', '["هذا عدد إلكترونات 4s وليس 3d.","","هذا يحدث إذا أُهمل 4s وملئ 3d مباشرة بعد 3p (26 − 18)، وطاقة 4s أقل فيُملأ أولًا.","هذا العدد الأقصى الذي يتسع له 3d، وليس عدد إلكترونات ذرة الحديد فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.795Z"}'::jsonb),
('mcq', 6, 3, 'قد تتداخل مستويات ثانوية تابعة لمستويات رئيسة مختلفة، وطاقة 4s أقل من طاقة 3d، لذلك تُملأ الإلكترونات في 4s أولًا ويُكتب قبل 3d.', '["طاقة المستوى الرئيس تزداد بزيادة n، فالمستوى الرابع أعلى طاقة من الثالث عمومًا؛ والتداخل هو سبب أفضلية 4s.","سعة 4s إلكترونان فقط بينما سعة 3d عشرة إلكترونات، والسعة ليست سبب ترتيب الملء.","الملء يتبع تسلسل الطاقة وليس ترتيب الحروف؛ ولو اتُّبع الحرف لكُتب 3d قبل 4s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.796Z"}'::jsonb),
('mcq', 7, 2, 'توزيع Zn: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰. المستويات الأقل طاقة من 3d هي 1s و2s و2p و3s و3p و4s، وفيها 2 + 2 + 6 + 2 + 6 + 2 = 20 إلكترونًا.', '["هذا عدد إلكترونات المستوى 3d نفسه، لا المستويات الأقل منه طاقة.","هذا العدد يُحسب إذا عُدَّ 4s أعلى من 3d (18 إلكترونًا حتى 3p)، وطاقة 4s أقل من 3d فتُحتسب إلكتروناته.","","هذا عدد إلكترونات الذرة كلها، ويتضمن إلكترونات 3d نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.796Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترتيب التصاعدي: 1s ، 2s ، 2p ، 3s ، 3p ، 4s ، 3d ، 4p. أعداد الإلكترونات التي يتسع لها كل مستوى: s إلكترونان، وp ستة، وd عشرة. نملأ 33 إلكترونًا بالترتيب: 1s² (2) 2s² (4) 2p⁶ (10) 3s² (12) 3p⁶ (18) 4s² (20) 3d¹⁰ (30) ثم تبقى 3 إلكترونات في 4p. فتوزيع As: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p³.', '["الترتيب: 1s ، 2s ، 2p ، 3s ، 3p ، 4s ، 3d ، 4p","4s قبل 3d","سعة s = 2 وp = 6 وd = 10","توزيع As: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p³"]'::jsonb, '["الملء بالترتيب: 2 + 2 + 6 + 2 + 6 = 18 إلكترونًا حتى 3p","4s² (20) ثم 3d¹⁰ (30)","المتبقي 33 − 30 = 3 إلكترونات في 4p: 4p³"]'::jsonb, '[{"element":"ترتيب المستويات الثمانية ترتيبًا صحيحًا","marks":2},{"element":"كتابة 4s قبل 3d في التوزيع","marks":1},{"element":"عدد الإلكترونات الصحيح في كل مستوى وانتهاء التوزيع بـ 4p³","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح للمستويات وتوزيع صحيح للزرنيخ بتسلسل الطاقة"},{"level":"2–3 درجات","description":"ترتيب صحيح مع خطأ في توزيع الإلكترونات، أو خطأ في موضع 4s مع بقية الحل صحيحًا"},{"level":"1 درجة","description":"ترتيب جزئي صحيح للمستويات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع 3d قبل 4s","وضع 4p قبل 3d","وضع 4 إلكترونات في 4s أو أكثر من سعة المستوى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.796Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Ca: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s². Ti: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d². (ب) قد تتداخل مستويات ثانوية تابعة لمستويات رئيسة مختلفة، وطاقة المستوى 4s أقل من طاقة المستوى 3d؛ لذلك تدخل الإلكترونات 4s أولًا ثم 3d، ولهذا يُكتب 4s قبل 3d. (ج) يُملأ 5s أولًا؛ لأن تسلسل الملء هو … 4s 3d 4p 5s 4d 5p …، فطاقة 5s أقل من طاقة 4d.', '["Ca: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s²","Ti: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d²","طاقة 4s أقل من طاقة 3d بسبب تداخل المستويات","الإلكترونات تُملأ بدءًا من الأقل طاقة","5s يُملأ قبل 4d"]'::jsonb, '[]'::jsonb, '[{"element":"توزيع Ca صحيح","marks":1},{"element":"توزيع Ti صحيح بكتابة 4s قبل 3d","marks":1},{"element":"تفسير تقدم 4s بأن طاقته أقل بسبب تداخل المستويات","marks":2},{"element":"تحديد أن 5s يُملأ قبل 4d","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توزيعان صحيحان، وتفسير كامل للتداخل، وتحديد صحيح لـ 5s قبل 4d"},{"level":"3–4 درجات","description":"توزيعان صحيحان مع تفسير ناقص، أو تفسير صحيح مع خطأ في أحد التوزيعين"},{"level":"1–2 درجة","description":"توزيع واحد صحيح أو ذكر أن 4s أقل طاقة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل ذلك بأن 4s يتسع لإلكترونات أكثر","كتابة 3d قبل 4s في توزيع Ti","الاعتقاد أن 4d يُملأ قبل 5s لأن عدد المستوى الرئيس أقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.796Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الخطأ في الترتيب: كُتب 3s قبل 2p، وطاقة 2p أقل من طاقة 3s، فيجب أن يأتي 2p بعد 2s مباشرة. (ب) الخطأ أن المستوى 4s أُهمل؛ فبعد 3p⁶ (18 إلكترونًا) يُملأ 4s² لأن طاقته أقل من 3d، ثم يدخل 6 إلكترونات في 3d (وليس 8). التوزيع الصحيح للحديد: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶، وفيه 26 إلكترونًا، وهو مكتوب بتسلسل الطاقة من الأقل إلى الأعلى.', '["في (أ) 3s كُتب قبل 2p وطاقته أعلى","في (ب) أُهمل 4s وهو أقل طاقة من 3d","في (ب) عدد إلكترونات 3d يجب أن يكون 6","التوزيع الصحيح: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶","التعليل بتسلسل الطاقة وملء الأقل طاقة أولًا"]'::jsonb, '["حتى 3p: 2 + 2 + 6 + 2 + 6 = 18 إلكترونًا","4s²: يصبح العدد 20","المتبقي 26 − 20 = 6 إلكترونات في 3d: 3d⁶"]'::jsonb, '[{"element":"تحديد الخطأ في التوزيع (أ): موضع 3s قبل 2p","marks":1},{"element":"تحديد الخطأ في التوزيع (ب): إهمال 4s وزيادة إلكترونات 3d","marks":1},{"element":"كتابة التوزيع الصحيح بتسلسل الطاقة","marks":1},{"element":"تعليل الترتيب بأن الإلكترونات تملأ الأقل طاقة أولًا وأن طاقة 4s أقل من 3d","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين، والتوزيع الصحيح، والتعليل بتسلسل الطاقة"},{"level":"2–3 درجات","description":"تحديد أحد الخطأين مع التوزيع الصحيح، أو التوزيع الصحيح دون تعليل كاف"},{"level":"1 درجة","description":"كتابة التوزيع الصحيح فقط دون تحديد الأخطاء"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار التوزيع (ب) صحيحًا لأن مجموع إلكتروناته 26","عدم ملاحظة أن 3s كُتب قبل 2p في التوزيع (أ)","كتابة 3d⁶ 4s² بدل 4s² 3d⁶ في الجواب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.797Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
