('mcq', 4, 'عند إضافة البوتاسيوم إلى محلول نترات الخارصين يتكون الخارصين ومحلول نترات البوتاسيوم. أيّ المواد الآتية هي النواتج؟', null, '["K و Zn(NO₃)₂","K و Zn","Zn(NO₃)₂ و KNO₃","Zn و KNO₃"]'::jsonb, 'فهم', 'تحديد النواتج من وصف', 'متوسط', 'الكتاب ص 146 — س68'),
('mcq', 5, 'ما وظيفة كل من الإشارة (+) والسهم (→) في المعادلة الكيميائية؟', null, '["الإشارة (+) تفصل المتفاعلات عن النواتج، والسهم يفصل بين مادتين في الجانب نفسه","الإشارة (+) تدل على عدد الذرات، والسهم يدل على الحالة الفيزيائية للمادة","الإشارة (+) تفصل بين متفاعلين أو بين ناتجين، والسهم يفصل المتفاعلات عن النواتج ويوضح اتجاه التفاعل","الإشارة (+) والسهم يفصلان المتفاعلات عن النواتج فقط"]'::jsonb, 'تذكر', 'تذكر وظائف رموز المعادلة', 'متوسط', 'الكتاب ص 117 — الجدول 4-6 (رموز المعادلات)'),
('mcq', 6, 'في المعادلة C(s) + S(s) → CS₂(l)، كم عدد المتفاعلات وكم عدد النواتج؟', null, '["متفاعلان وناتج واحد","متفاعل واحد وناتجان","متفاعلان وناتجان","متفاعل واحد وناتج واحد"]'::jsonb, 'فهم', 'عدّ المتفاعلات والنواتج', 'متوسط', 'الكتاب ص 118 — المعادلات الكيميائية الرمزية'),
('mcq', 7, 'عند تسخين كلورات البوتاسيوم KClO₃ الصلبة ينتج كلوريد البوتاسيوم KCl الصلب وغاز الأكسجين O₂. أيّ الصيغ الآتية تضع المتفاعلات والنواتج في موضعها الصحيح (بصرف النظر عن وزن المعادلة)؟', null, '["KCl(s) + O₂(g) → KClO₃(s)","KClO₃(s) → KCl(s) + O₂(g)","KClO₃(s) + O₂(g) → KCl(s)","KCl(s) → KClO₃(s) + O₂(g)"]'::jsonb, 'تطبيق', 'ترتيب المتفاعلات والنواتج من وصف تفاعل', 'صعب', 'الكتاب ص 118 — مسألة تدريبية (س5)'),
('essay', 1, 'عرّف المتفاعلات والنواتج، ثم حدّدهما في المعادلة C(s) + S(s) → CS₂(l)، مبينًا أين تُكتب كل منهما بالنسبة إلى السهم، ووظيفة الإشارة (+).', null, null, 'فهم', 'تعريف وتمييز المتفاعلات والنواتج', 'سهل', 'الكتاب ص 117، 118 — تمثيل التفاعلات الكيميائية'),
('essay', 2, 'لكل تفاعل من التفاعلين الآتيين: اكتب معادلة رمزية موزونة مع بيان الحالات الفيزيائية، ثم حدّد المتفاعلات والنواتج. (أ) يتفاعل الليثيوم الصلب مع غاز الكلور لإنتاج كلوريد الليثيوم الصلب. (ب) يتحلل يوديد الهيدروجين الغازي إلى غاز الهيدروجين وغاز اليود.', null, null, 'تطبيق', 'كتابة معادلة من وصف وتحديد المتفاعلات والنواتج', 'صعب', 'الكتاب ص 146 — س72 وس74'),
('essay', 3, 'عند تفاعل الألومنيوم الصلب مع البروم السائل ظهرت سحابة حمراء من بروم فائض، واستقرت في قعر الكأس جسيمات صلبة من بروميد الألومنيوم AlBr₃. (أ) حدّد المتفاعلات والنواتج. (ب) هل يُعد البروم الفائض ناتجًا؟ فسّر إجابتك. (ج) اكتب المعادلة الرمزية الموزونة للتفاعل مع الحالات الفيزيائية.', null, null, 'تحليل', 'تحليل مشاهدة وتمييز المتفاعل الفائض من الناتج', 'صعب', 'الكتاب ص 118 — المعادلات الكيميائية اللفظية والرمزية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
