from (values
('mcq', 1, 0, 'المتفاعلات هي المواد التي توجد عند بداية التفاعل، وتُكتب على يسار السهم في المعادلة الكيميائية.', '["","هذا تعريف النواتج، وهي المواد المتكونة خلال التفاعل.","المواد على يمين السهم هي النواتج، أما المتفاعلات فتُكتب على يساره.","المتفاعلات تتغير وتتحول إلى نواتج؛ والمادة التي يبقى جزء منها دون تفاعل هي المادة الفائضة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.797Z"}'::jsonb),
('mcq', 2, 2, 'المتفاعلات هي المواد المكتوبة يسار السهم: NaOH و CaBr₂؛ أما Ca(OH)₂ و NaBr فمكتوبتان يمين السهم، فهما النواتج.', '["هاتان المادتان تقعان يمين السهم، فهما نواتج وليستا متفاعلات.","NaOH متفاعل لكن NaBr ناتج لأنه يقع يمين السهم.","","CaBr₂ متفاعل لكن Ca(OH)₂ ناتج لأنه يقع يمين السهم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.797Z"}'::jsonb),
('mcq', 3, 1, 'الناتج هو المادة المتكونة خلال التفاعل وتُكتب يمين السهم، وهي بروميد الألومنيوم؛ أما الألومنيوم والبروم فمتفاعلان موجودان عند بداية التفاعل وتُكتبان يسار السهم.', '["الألومنيوم موجود عند بداية التفاعل ويُكتب يسار السهم، فهو متفاعل؛ ولا يتحدد النوع بالترتيب الأول في الكتابة.","","الحالة الفيزيائية لا تحدد كون المادة ناتجًا؛ والبروم موجود عند بداية التفاعل فهو متفاعل.","المواد المكتوبة يمين السهم هي النواتج، لا المتفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.797Z"}'::jsonb),
('mcq', 4, 3, 'النواتج هي المواد المتكونة خلال التفاعل، وهي الخارصين Zn ونترات البوتاسيوم KNO₃؛ أما البوتاسيوم K ونترات الخارصين Zn(NO₃)₂ فموجودان عند بداية التفاعل، فهما المتفاعلان.', '["K و Zn(NO₃)₂ هما المتفاعلان لأنهما موجودان قبل بدء التفاعل.","K متفاعل لأنه يُضاف في بداية التفاعل، وZn وحده ناتج.","Zn(NO₃)₂ متفاعل لأنه المحلول الموجود في البداية، وKNO₃ وحده ناتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.798Z"}'::jsonb),
('mcq', 5, 2, 'تُستخدم الإشارة (+) للفصل بين أكثر من متفاعل أو بين أكثر من ناتج، ويفصل السهم المتفاعلات عن النواتج ويوضح اتجاه التفاعل، فتُكتب المتفاعلات على يساره والنواتج على يمينه.', '["هذا عكس الوظيفتين؛ فالسهم هو الذي يفصل المتفاعلات عن النواتج، والإشارة (+) تفصل المواد داخل الجانب الواحد.","عدد الذرات تعبّر عنه المعاملات والأرقام السفلية، والحالة الفيزيائية تُكتب بالرموز (s) و(l) و(g) و(aq).","","الإشارة (+) لا تفصل المتفاعلات عن النواتج، بل تفصل بين مادتين في الجانب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.798Z"}'::jsonb),
('mcq', 6, 0, 'تقع المادتان C وS يسار السهم، وهما متفاعلان يفصل بينهما الإشارة (+)، ويقع CS₂ وحده يمين السهم، فهو الناتج الوحيد.', '["","عُكس الأمر؛ فالمادتان على اليسار والمادة الواحدة على اليمين.","ناتج واحد فقط (CS₂)؛ احتواء CS₂ على عنصرين لا يجعله ناتجين.","على يسار السهم مادتان هما C وS مفصولتان بالإشارة (+)، فالمتفاعلات اثنان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.798Z"}'::jsonb),
('mcq', 7, 1, 'المتفاعل هو KClO₃ الموجود عند بداية التفاعل فيُكتب يسار السهم، والناتجان هما KCl وO₂ المتكونان خلال التفاعل فيُكتبان يمين السهم ويُفصل بينهما بإشارة (+).', '["هنا عُكست المواد؛ فـ KCl وO₂ ناتجان ولا يُكتبان يسار السهم.","","وُضع O₂ بين المتفاعلات، وهو ناتج متكون خلال التفاعل.","وُضع KCl متفاعلًا وKClO₃ ناتجًا، وهذا عكس المعطى؛ فالمتفاعل هو KClO₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.798Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المتفاعلات هي المواد الموجودة عند بداية التفاعل، والنواتج هي المواد المتكونة خلال التفاعل. في المعادلة C(s) + S(s) → CS₂(l): المتفاعلان هما الكربون C والكبريت S، والناتج هو ثاني كبريتيد الكربون CS₂. تُكتب المتفاعلات على يسار السهم والنواتج على يمينه، ويفصل السهم بينهما ويوضح اتجاه التفاعل. وتُستخدم الإشارة (+) للفصل بين أكثر من متفاعل أو أكثر من ناتج، كما بين C وS.', '["المتفاعلات: المواد الموجودة عند بداية التفاعل","النواتج: المواد المتكونة خلال التفاعل","المتفاعلان C وS والناتج CS₂","المتفاعلات يسار السهم والنواتج يمينه","الإشارة (+) تفصل بين متفاعلين أو ناتجين"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المتفاعلات والنواتج بشكل صحيح","marks":1},{"element":"تحديد المتفاعلين C وS والناتج CS₂","marks":1},{"element":"موضع المتفاعلات يسار السهم والنواتج يمينه","marks":1},{"element":"وظيفة الإشارة (+)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وتحديد صحيح للمواد، وموضعها بالنسبة للسهم، ووظيفة الإشارة (+)"},{"level":"2–3 درجات","description":"إنجاز عنصرين أو ثلاثة من العناصر الأربعة بشكل صحيح"},{"level":"1 درجة","description":"تعريف واحد فقط أو تحديد جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CS₂ ناتجين لأنه يحتوي عنصرين","عكس موضع المتفاعلات والنواتج بالنسبة للسهم","القول إن الإشارة (+) تفصل المتفاعلات عن النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.799Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 2Li(s) + Cl₂(g) → 2LiCl(s). المتفاعلان: Li وCl₂ (يسار السهم)، والناتج: LiCl (يمين السهم). (ب) 2HI(g) → H₂(g) + I₂(g). المتفاعل: HI (يسار السهم)، والناتجان: H₂ وI₂ (يمين السهم).', '["2Li(s) + Cl₂(g) → 2LiCl(s)","متفاعلا (أ): Li وCl₂؛ وناتجه LiCl","2HI(g) → H₂(g) + I₂(g)","متفاعل (ب): HI؛ وناتجاه H₂ وI₂","كتابة الحالات الفيزيائية بين أقواس أسفل الصيغ"]'::jsonb, '["(أ) كتابة الصيغ: Li وCl₂ وLiCl، ثم وزن الذرات: 2 Li و2 Cl في كل جانب","(ب) كتابة الصيغ: HI وH₂ وI₂، ثم وزن الذرات: 2 H و2 I في كل جانب"]'::jsonb, '[{"element":"المعادلة الموزونة للتفاعل (أ) مع الحالات الفيزيائية","marks":1},{"element":"تحديد متفاعلات (أ) ونواتجه","marks":1},{"element":"المعادلة الموزونة للتفاعل (ب) مع الحالات الفيزيائية","marks":1},{"element":"تحديد متفاعل (ب) وناتجيه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان موزونتان مع الحالات الفيزيائية وتحديد صحيح للمتفاعلات والنواتج في كل منهما"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة كاملة، أو معادلتان مع أخطاء في الوزن أو في الحالات الفيزيائية"},{"level":"1 درجة","description":"تحديد المتفاعلات والنواتج دون معادلة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة اليود I بدل I₂ والهيدروجين H بدل H₂","وضع المتفاعل (HI) يمين السهم في التفاعل (ب)","كتابة LiCl₂ بدل LiCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.799Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المتفاعلان: الألومنيوم Al والبروم Br₂ لأنهما موجودان عند بداية التفاعل، والناتج: بروميد الألومنيوم AlBr₃ لأنه المادة المتكونة خلال التفاعل. (ب) لا؛ البروم الفائض جزء من البروم المتفاعل بقي دون تفاعل بعد انتهاء التفاعل، فهو مادة موجودة منذ البداية وليس مادة متكونة خلال التفاعل، لذلك يبقى متفاعلًا وليس ناتجًا. (ج) 2Al(s) + 3Br₂(l) → 2AlBr₃(s).', '["المتفاعلان Al وBr₂ والناتج AlBr₃","المتفاعلات موجودة عند بداية التفاعل والنواتج متكونة خلاله","البروم الفائض ليس ناتجًا لأنه كان موجودًا من البداية ولم يتفاعل","2Al(s) + 3Br₂(l) → 2AlBr₃(s)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المتفاعلين Al وBr₂ والناتج AlBr₃","marks":1},{"element":"الإجابة بأن البروم الفائض ليس ناتجًا","marks":1},{"element":"تعليل ذلك بأنه موجود عند بداية التفاعل وبقي دون تفاعل","marks":1},{"element":"كتابة المعادلة الموزونة 2Al + 3Br₂ → 2AlBr₃","marks":1},{"element":"كتابة الحالات الفيزيائية (s) و(l) و(s) بشكل صحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للمتفاعلات والناتج، وتفسير سليم لوضع البروم الفائض، ومعادلة موزونة بالحالات الفيزيائية"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص أو معادلة بخطأ في الوزن أو الحالات"},{"level":"1–2 درجة","description":"تحديد المتفاعلات والناتج فقط، أو معادلة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البروم الفائض ناتجًا لأنه ظهر بعد التفاعل","كتابة AlBr بدل AlBr₃","كتابة البروم Br بدل Br₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.800Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
