insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تُمثَّل المعادلة العامة A + BX → AX + B تفاعلًا من نوع:', null, '["تكوين","احتراق","تفكك","إحلال بسيط"]'::jsonb, 'تذكر', 'ربط المعادلة العامة بنوع التفاعل', 'سهل', 'الكتاب ص 127، 132 — تفاعلات الإحلال البسيط، النواتج المتوقعة لبعض التفاعلات'),
('mcq', 2, 'يتفكك أزيد الصوديوم وفق المعادلة: 2NaN₃ → 2Na + 3N₂ (وهو التفاعل المستعمل في نفخ أكياس الهواء في السيارات). يُصنَّف هذا التفاعل بأنه تفاعل:', null, '["تفكك","تكوين","احتراق","إحلال بسيط"]'::jsonb, 'فهم', 'تصنيف تفاعل من معادلته', 'سهل', 'الكتاب ص 126 — تفاعلات التفكك'),
('mcq', 3, 'عند إضافة الماء إلى أكسيد الكالسيوم الصلب يحدث التفاعل: CaO + H₂O → Ca(OH)₂. ما نوع هذا التفاعل؟', null, '["تفاعل تفكك","تفاعل إحلال مزدوج","تفاعل تكوين","تفاعل إحلال بسيط"]'::jsonb, 'فهم', 'تصنيف اتحاد مركبين', 'سهل', 'الكتاب ص 123 — تفاعلات التكوين'),
('mcq', 4, 'يحترق غاز الميثان وفق المعادلة: CH₄ + 2O₂ → CO₂ + 2H₂O. كيف يُصنَّف هذا التفاعل؟', null, '["تكوين فقط","احتراق فقط","احتراق وتكوين معًا","تفكك فقط"]'::jsonb, 'تطبيق', 'تصنيف تفاعل ينتمي إلى نوع واحد', 'متوسط', 'الكتاب ص 125 — تفاعلات الاحتراق'),
('mcq', 5, 'أيّ التفاعلات الآتية يُصنَّف احتراقًا وتكوينًا في الوقت نفسه؟', null, '["CH₄ + 2O₂ → CO₂ + 2H₂O","Fe + CuSO₄ → FeSO₄ + Cu","2NaN₃ → 2Na + 3N₂","2Mg + O₂ → 2MgO"]'::jsonb, 'فهم', 'تمييز تفاعل ينتمي إلى أكثر من نوع', 'متوسط', 'الكتاب ص 124، 125 — تفاعلات الاحتراق'),
('mcq', 6, 'يتفاعل محلول سيانيد البوتاسيوم مع محلول حمض الهيدروبروميك وفق المعادلة: KCN(aq) + HBr(aq) → KBr(aq) + HCN(g). ما نوع هذا التفاعل ولماذا؟', null, '["إحلال بسيط؛ لأن أحد النواتج غاز","إحلال مزدوج؛ لأن الأيونين السالبين تبادلا موقعيهما وينتج غاز","تكوين؛ لأن المتفاعلين اتحدا معًا","تفكك؛ لأن المتفاعلين انقسما إلى ناتجين"]'::jsonb, 'تطبيق', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 131، 132 — نواتج تفاعلات الإحلال المزدوج'),
('mcq', 7, 'صنِّف التفاعلات الأربعة المعروضة بالترتيب (I، II، III، IV):', '{"headers":["الرمز","المعادلة"],"rows":[["I","NH₄NO₃ → N₂O + 2H₂O (بالتسخين)"],["II","CaO + H₂O → Ca(OH)₂"],["III","Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag"],["IV","KCN + HBr → KBr + HCN"]]}'::jsonb, '["تفكك، تكوين، إحلال مزدوج، إحلال بسيط","تكوين، تفكك، إحلال بسيط، إحلال مزدوج","تفكك، تكوين، إحلال بسيط، إحلال مزدوج","إحلال بسيط، تكوين، تفكك، إحلال مزدوج"]'::jsonb, 'تطبيق', 'تصنيف عدة تفاعلات', 'صعب', 'الكتاب ص 132 — النواتج المتوقعة لبعض التفاعلات الكيميائية'),
('essay', 1, 'صنِّف كل تفاعل من التفاعلات الآتية إلى أحد الأنواع الأربعة (تكوين، احتراق، تفكك، إحلال)، مع ذكر سبب التصنيف في كل حالة:
(a) 2Na + Cl₂ → 2NaCl
(b) 2H₂O → 2H₂ + O₂ (بالكهرباء)
(c) Zn + CuSO₄ → ZnSO₄ + Cu
(d) BaCl₂ + K₂CO₃ → BaCO₃ + 2KCl
(e) C₃H₈ + 5O₂ → 3CO₂ + 4H₂O', null, null, 'تطبيق', 'تصنيف مع تبرير', 'متوسط', 'الكتاب ص 123–132 — أنواع التفاعلات الكيميائية'),
('essay', 2, 'فسِّر لماذا يُصنَّف تفاعل غاز الهيدروجين مع غاز الأكسجين (2H₂ + O₂ → 2H₂O) احتراقًا وتكوينًا معًا، في حين لا يُصنَّف احتراق غاز الميثان (CH₄ + 2O₂ → CO₂ + 2H₂O) تكوينًا.', null, null, 'فهم', 'تفسير انتماء تفاعل إلى أكثر من نوع', 'صعب', 'الكتاب ص 124، 125 — تفاعلات الاحتراق'),
('essay', 3, 'أكمل جدولًا يلخص أنواع التفاعلات الأربعة (تكوين، احتراق، تفكك، إحلال) على أن يشمل الإحلال نوعيه البسيط والمزدوج، بحيث تذكر لكل نوع المواد المتفاعلة والنواتج المتوقعة والمعادلة العامة.', null, null, 'فهم', 'تلخيص أنواع التفاعلات', 'صعب', 'الكتاب ص 132 — النواتج المتوقعة لبعض التفاعلات الكيميائية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
