insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'في المعادلة A + BX → AX + B يتفاعل عنصر (A) مع مركب (BX) فيحل محل العنصر B في المركب وينتج مركب جديد وعنصر حر؛ وهذا هو الإحلال البسيط.', '["التكوين معادلته العامة A + B → AB، إذ تتحد مادتان لتكوين مادة واحدة، ولا ينتج هنا عنصر حر.","الاحتراق يتضمن اتحاد الأكسجين بمادة (A + O₂ → AO)، وليس في المعادلة المعطاة أكسجين.","التفكك معادلته العامة AB → A + B، إذ يبدأ بمركب واحد، أما هنا فللتفاعل متفاعلان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.800Z"}'::jsonb),
('mcq', 2, 0, 'يبدأ التفاعل بمركب واحد (NaN₃) وينتج عنصرين (Na وN₂)؛ لذلك هو تفاعل تفكك (AB → A + B).', '["","التكوين يعني اتحاد مادتين أو أكثر لإنتاج مادة واحدة، والذي يحدث هنا هو العكس.","لا يتضمن التفاعل أكسجينًا ولا إطلاق حرارة وضوء، فليس احتراقًا.","الإحلال البسيط يحتاج إلى عنصر ومركب في المتفاعلات، أما هنا فمتفاعل واحد فقط هو مركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.800Z"}'::jsonb),
('mcq', 3, 2, 'يتحد مركبان (CaO وH₂O) لينتج مركب واحد هو Ca(OH)₂، وهذا هو تفاعل التكوين (A + B → AB).', '["التفكك ينتج من مركب واحد مادتين أو أكثر، والعكس هو ما حدث هنا.","في الإحلال المزدوج يتبادل مركبان أيونيهما وينتج مركبان، أما هنا فالناتج مركب واحد.","","الإحلال البسيط يتطلب عنصرًا حرًّا يحل محل عنصر في مركب، ولا يوجد عنصر حر هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.801Z"}'::jsonb),
('mcq', 4, 1, 'يتحد الأكسجين مع مادة (الميثان) مطلقًا طاقة، فهو احتراق. لكنه ليس تكوينًا لأن التكوين ينتج مركبًا واحدًا، أما هنا فينتج مركبان هما CO₂ وH₂O.', '["التكوين ينتج مركبًا واحدًا فقط، وهذا التفاعل ينتج مركبين، كما أنه يتضمن اتحاد الأكسجين بمادة.","","يُعدّ احتراق الهيدروجين تكوينًا واحتراقًا لأن ناتجه مركب واحد (H₂O)، أما احتراق الميثان فناتجه مركبان فلا يكون تكوينًا.","التفكك يبدأ بمركب واحد، بينما للتفاعل هنا متفاعلان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.801Z"}'::jsonb),
('mcq', 5, 3, 'في التفاعل 2Mg + O₂ → 2MgO يتحد الأكسجين مع الماغنسيوم (احتراق) وتتحد مادتان لتنتجا مركبًا واحدًا هو MgO (تكوين)؛ فهو ينتمي إلى النوعين معًا.', '["هذا احتراق فقط؛ فناتجاه مركبان (CO₂ وH₂O) فلا يكون تكوينًا.","هذا إحلال بسيط: عنصر الحديد يحل محل النحاس في مركبه، ولا أكسجين فيه.","هذا تفكك: متفاعل واحد ينتج عنصرين، وليس فيه اتحاد بالأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.801Z"}'::jsonb),
('mcq', 6, 1, 'يتفاعل مركبان فتتبادل الأيونات أماكنها (CN⁻ مع H⁺ وBr⁻ مع K⁺) ويتكون مركبان مختلفان أحدهما غاز (HCN)؛ وهذه سمات الإحلال المزدوج.', '["الإحلال البسيط يتضمن عنصرًا حرًّا يحل محل عنصر في مركب، وليس بين المتفاعلات أو النواتج هنا عنصر حر.","","التكوين ينتج مركبًا واحدًا، أما هنا فينتج مركبان (KBr وHCN).","التفكك يبدأ بمركب واحد، وهنا متفاعلان مركبان، ولم ينقسم أي منهما بمفرده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.801Z"}'::jsonb),
('mcq', 7, 2, 'I: مركب واحد يعطي ناتجين، فهو تفكك. II: مركبان يعطيان مركبًا واحدًا، فهو تكوين. III: عنصر (Cu) يحل محل عنصر (Ag) في مركبه، فهو إحلال بسيط. IV: مركبان يتبادلان أيونيهما، فهو إحلال مزدوج. فالترتيب: تفكك، تكوين، إحلال بسيط، إحلال مزدوج.', '["عكس فيه موضعي III وIV؛ فالتفاعل III فيه عنصر حر (Cu) فهو إحلال بسيط، والتفاعل IV بين مركبين فهو إحلال مزدوج.","عكس فيه موضعي I وII؛ فالتفاعل I يبدأ بمركب واحد (تفكك) بينما II ينتج مركبًا واحدًا من مركبين (تكوين).","","وضع I إحلالًا بسيطًا وIII تفككًا؛ لكن I مركب واحد يتفكك، وIII فيه عنصر ومركب متفاعلان فهو إحلال بسيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.801Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) تكوين؛ لأن عنصرين يتحدان لإنتاج مركب واحد (A + B → AB). (b) تفكك؛ لأن مركبًا واحدًا (الماء) ينتج عنصرين بتأثير الكهرباء (AB → A + B). (c) إحلال بسيط؛ لأن عنصر الخارصين يحل محل النحاس في مركبه (A + BX → AX + B). (d) إحلال مزدوج؛ لأن مركبين يتبادلان أيونيهما فينتج مركبان أحدهما راسب هو BaCO₃. (e) احتراق؛ لأن البروبان يتحد مع الأكسجين منتجًا CO₂ وماء ومطلقًا طاقة، وليس تكوينًا لأن الناتج مركبان.', '["(a) تكوين: اتحاد عنصرين لإنتاج مركب واحد","(b) تفكك: مركب واحد ينتج عنصرين","(c) إحلال بسيط: عنصر يحل محل عنصر في مركب","(d) إحلال مزدوج: تبادل الأيونات بين مركبين وينتج راسب","(e) احتراق: اتحاد مادة بالأكسجين وإطلاق طاقة"]'::jsonb, '[]'::jsonb, '[{"element":"(a) التصنيف مع السبب","marks":1},{"element":"(b) التصنيف مع السبب","marks":1},{"element":"(c) التصنيف مع السبب","marks":1},{"element":"(d) التصنيف مع السبب","marks":1},{"element":"(e) التصنيف مع السبب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف التفاعلات الخمسة تصنيفًا صحيحًا مع سبب مناسب لكل منها"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاثة أو أربعة تفاعلات مع أسبابها"},{"level":"1–2 درجة","description":"تصنيف صحيح لتفاعل أو اثنين، أو تصنيفات صحيحة دون أسباب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (c) تكوينًا لأن الناتجين يحتويان على مركب جديد","تصنيف (e) تكوينًا لمجرد وجود اتحاد بالأكسجين","الخلط بين الإحلال البسيط والمزدوج في (c) و(d)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.802Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تفاعل الهيدروجين مع الأكسجين احتراق لأن الأكسجين يتحد بمادة (الهيدروجين) مع إطلاق كمية كبيرة من الطاقة، وهو في الوقت نفسه تكوين لأن مادتين (H₂ وO₂) اتحدتا لتكوين مادة واحدة هي الماء (A + B → AB). أما احتراق الميثان فهو احتراق لأن الأكسجين يتحد بالميثان مطلقًا طاقة، لكنه ليس تكوينًا لأن التفاعل ينتج مركبين هما CO₂ وH₂O، بينما يشترط في التكوين أن تكون النتيجة مادة واحدة. إذن كل تفاعل احتراق ناتجه مركب واحد هو تكوين أيضًا، أما إذا نتج أكثر من مركب فلا يكون تكوينًا.', '["الأكسجين يتحد بمادة مع إطلاق طاقة فهو احتراق في المثالين","اتحاد H₂ وO₂ ينتج مادة واحدة (H₂O) فهو تكوين","احتراق الميثان ينتج مركبين (CO₂ وH₂O)","التكوين يشترط ناتجًا واحدًا فلا يكون احتراق الميثان تكوينًا"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن التفاعلين احتراق (اتحاد بالأكسجين مع إطلاق طاقة)","marks":1},{"element":"تبرير كون الهيدروجين مع الأكسجين تكوينًا (ناتج واحد)","marks":1},{"element":"تبرير عدم كون احتراق الميثان تكوينًا (ناتجان)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يوضح الاحتراق في المثالين وسبب كون الأول تكوينًا والثاني لا"},{"level":"2–3 درجات","description":"تفسير صحيح لأحد المثالين مع إشارة ناقصة للآخر"},{"level":"1 درجة","description":"ذكر أن التفاعلين احتراق دون تفسير التكوين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كل تفاعل احتراق هو تكوين","إغفال عدد النواتج عند تحديد التكوين","عدّ وجود الأكسجين وحده دليلًا على التكوين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.802Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التكوين: المتفاعلات مادتان أو أكثر، والناتج مركب واحد، المعادلة A + B → AB. الاحتراق: المتفاعلات فلز أو لافلز أو مركب مع الأكسجين، والنواتج أكسيد الفلز أو أكسيد اللافلز أو أكسيدان أو أكثر، المعادلة A + O₂ → AO. التفكك: المتفاعل مركب واحد، والنواتج عنصران أو أكثر و/أو مركبات أخرى، المعادلة AB → A + B. الإحلال البسيط: المتفاعلان فلز ومركب (أو لافلز ومركب)، والنواتج مركب جديد والفلز (أو اللافلز) المستعاض عنه، المعادلة A + BX → AX + B. الإحلال المزدوج: المتفاعلان مركبان، والناتجان مركبان مختلفان أحدهما صلب (راسب) أو ماء أو غاز، المعادلة AX + BY → AY + BX.', '["التكوين: مادتان أو أكثر ← مركب واحد؛ A + B → AB","الاحتراق: مادة وأكسجين ← أكسيد أو أكثر؛ A + O₂ → AO","التفكك: مركب واحد ← عنصران أو أكثر أو مركبات؛ AB → A + B","الإحلال البسيط: عنصر ومركب ← مركب جديد وعنصر؛ A + BX → AX + B","الإحلال المزدوج: مركبان ← مركبان أحدهما راسب أو ماء أو غاز؛ AX + BY → AY + BX"]'::jsonb, '[]'::jsonb, '[{"element":"التكوين (متفاعلات ونواتج ومعادلة)","marks":1},{"element":"الاحتراق (متفاعلات ونواتج ومعادلة)","marks":1},{"element":"التفكك (متفاعلات ونواتج ومعادلة)","marks":1},{"element":"الإحلال البسيط (متفاعلات ونواتج ومعادلة)","marks":1},{"element":"الإحلال المزدوج (متفاعلات ونواتج ومعادلة)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ملء الأنواع الخمسة كاملة بالمتفاعلات والنواتج والمعادلة العامة"},{"level":"3–4 درجات","description":"ملء ثلاثة أو أربعة أنواع بصورة صحيحة"},{"level":"1–2 درجة","description":"ملء نوع أو نوعين فقط، أو ذكر المعادلات العامة دون المتفاعلات والنواتج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس المعادلتين العامتين للتكوين والتفكك","إغفال أن ناتج الإحلال المزدوج يكون ماء أو راسبًا أو غازًا","كتابة معادلة الإحلال البسيط دون عنصر حر في النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.802Z"}'::jsonb)
