('mcq', 5, 'أيّ التفاعلات الآتية لا يُعدّ إحلالًا مزدوجًا؟', null, '["2NaOH + CuCl₂ → 2NaCl + Cu(OH)₂","KCN + HBr → KBr + HCN","Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag","Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O"]'::jsonb, 'تحليل', 'استبعاد تفاعل لا ينتمي إلى النوع', 'متوسط', 'الكتاب ص 127، 130، 131 — تفاعلات الإحلال'),
('mcq', 6, 'أيّ الخيارات الآتية يصف بدقة سمة كلٍّ من نوعي الإحلال؟', null, '["في البسيط يُستعان بسلسلة النشاط لتوقع حدوثه، وفي المزدوج ينتج ماء أو راسب أو غاز","في البسيط ينتج راسب دائمًا، وفي المزدوج يُستعان بسلسلة النشاط لتوقع حدوثه","في كليهما يُستعان بسلسلة النشاط لتوقع حدوث التفاعل","في كليهما ينتج عنصر حر ومركب جديد"]'::jsonb, 'تحليل', 'مقارنة السمات المميزة', 'متوسط', 'الكتاب ص 127، 128، 130 — تفاعلات الإحلال'),
('mcq', 7, 'قارن بين التفاعلين: Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag و 2NaOH + CuCl₂ → 2NaCl + Cu(OH)₂. أيّ العبارات الآتية صحيحة؟', null, '["في كليهما يتبادل أيونان سالبان موقعيهما ويرتبطان بأيونين موجبين","في كليهما ينتج ناتج صلب، عنصر في الأول ومركب في الثاني","في كليهما ينتج عنصر حر إلى جانب مركب جديد","في كليهما يتفاعل مركبان يتبادلان أيونيهما"]'::jsonb, 'تحليل', 'مقارنة تفاعلين', 'صعب', 'الكتاب ص 127، 130 — تفاعلات الإحلال البسيط والمزدوج'),
('essay', 1, 'قارن بين تفاعل الإحلال البسيط وتفاعل الإحلال المزدوج من حيث: المواد المتفاعلة، والمعادلة العامة، وما يحدث للجسيمات أثناء التفاعل، ونوع النواتج، ومثال على كل منهما.', null, null, 'تحليل', 'مقارنة متعددة المحاور', 'متوسط', 'الكتاب ص 127، 130، 132 — تفاعلات الإحلال، النواتج المتوقعة'),
('essay', 2, 'لديك التفاعلان الآتيان:
(1) Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag
(2) Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O
لكل تفاعل: حدّد نوع الإحلال، وبيّن أي الجسيمات حلّ محل أي جسيم، وحدّد نوع النواتج الناتجة.', null, null, 'تحليل', 'تحليل تفاعلين وتحديد ما يحل محل ماذا', 'صعب', 'الكتاب ص 127، 130 — تفاعلات الإحلال البسيط والمزدوج'),
('essay', 3, 'كتب طالب المعادلة KCN + HBr → KBr + HCN، وصنّفها إحلالًا بسيطًا قائلًا: «لأن الهيدروجين حلّ محل البوتاسيوم». ناقش صحة تصنيفه مستندًا إلى المتفاعلات والنواتج وما يحدث للأيونات، ثم اذكر التصنيف الصحيح.', null, null, 'تقويم', 'مناقشة تصنيف خاطئ', 'صعب', 'الكتاب ص 127، 130، 131 — تفاعلات الإحلال البسيط والمزدوج')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
