from (values
('mcq', 1, 0, 'في الإحلال البسيط (A + BX → AX + B) يتفاعل عنصر مع مركب، وفي الإحلال المزدوج (AX + BY → AY + BX) يتفاعل مركبان.', '["","هذا عكس الصحيح؛ فالإحلال البسيط يبدأ بعنصر ومركب، والمزدوج هو الذي يبدأ بمركبين.","تفاعل عنصرين هو تكوين، وليس إحلالًا، ولا يبدأ الإحلال المزدوج بمركب واحد.","المتفاعل الواحد (المركب) يميز التفكك، وليس الإحلال البسيط؛ كما أن الإحلال المزدوج لا يبدأ بعنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 2, 2, 'في الإحلال المزدوج يحل كل أيون سالب محل الآخر: يرتبط X بالأيون B ويرتبط Y بالأيون A، أي تتبادل الأيونات السالبة موقعيها وترتبط بأيونين موجبين مختلفين.', '["لو بقيا مرتبطين بالأيونين نفسيهما لما حدث تفاعل، وتسمية الإحلال المزدوج تعني أنهما تبادلا موقعيهما.","تحرر الأيونات عناصر حرة يميز الإحلال البسيط حيث ينتج عنصر حر، وليس الإحلال المزدوج.","","اتحاد الأيونين السالبين معًا غير ممكن لأنهما متشابهان في الشحنة؛ والذي يحدث هو ارتباط كل منهما بأيون موجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 3, 1, 'جميع تفاعلات الإحلال المزدوج تنتج مركبين مختلفين أحدهما ماء أو راسب أو غاز، بينما ينتج الإحلال البسيط مركبًا جديدًا وعنصرًا حرًّا (الفلز أو اللافلز المستعاض عنه).', '["العنصر الحر والمركب الجديد ناتجا الإحلال البسيط، أما الإحلال المزدوج فنواتجه مركبان.","","المركب الواحد ناتج التكوين؛ أما الإحلال المزدوج فينتج مركبين مختلفين.","الفلز الحر لا ينتج في الإحلال المزدوج لأن نواتجه مركبان؛ وهو ليس دائمًا في البسيط أيضًا إذ قد يكون الناتج لافلزًا مثل Br₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 4, 3, 'في التفاعل 1 يحل عنصر (النحاس) محل عنصر (الفضة) في مركبه فتظهر الفضة حرة، وهذا إحلال بسيط. في التفاعل 2 يتبادل مركبان (NaOH وCuCl₂) أيونيهما فينتج مركبان أحدهما راسب أزرق، وهذا إحلال مزدوج.', '["عكست التصنيف؛ التفاعل 1 فيه عنصر حر (Cu) يحل محل Ag فهو بسيط، والتفاعل 2 بين مركبين فهو مزدوج.","التفاعل 2 بين مركبين وليس فيه عنصر متفاعل أو ناتج، فلا يكون إحلالًا بسيطًا.","التفاعل 1 يبدأ بعنصر (Cu) وينتج عنصرًا حرًّا (Ag) فلا يكون إحلالًا مزدوجًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 5, 2, 'التفاعل Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag يبدأ بعنصر (Cu) وينتج عنصرًا حرًّا (Ag)، فهو إحلال بسيط. أما بقية التفاعلات فتبدأ بمركبين يتبادلان أيونيهما.', '["تفاعل بين مركبين تبادلا الأيونين السالبين OH⁻ وCl⁻، وينتج راسب Cu(OH)₂؛ فهو إحلال مزدوج.","تفاعل بين مركبين تبادلا فيه الأيونات وينتج غاز HCN؛ فهو إحلال مزدوج.","","تفاعل بين مركبين تبادلا فيه الأيونات وينتج ماء؛ فهو إحلال مزدوج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 6, 0, 'حدوث الإحلال البسيط يعتمد على نشاط العنصر؛ فيحل الفلز الأنشط محل الأقل نشاطًا ويُحدَّد ذلك بسلسلة النشاط. أما الإحلال المزدوج فيتميز بأن نواتجه تتضمن دائمًا ماء أو راسبًا أو غازًا.', '["","عكست السمتين؛ سلسلة النشاط تخص الإحلال البسيط، وليس الراسب شرطًا في البسيط (ينتج فيه فلز أو لافلز حر).","سلسلة النشاط تخص عناصر الإحلال البسيط (الفلزات والهالوجينات)، ولا تُستعمل مع تبادل الأيونات بين مركبين.","العنصر الحر ناتج الإحلال البسيط فقط، أما المزدوج فنواتجه مركبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.803Z"}'::jsonb),
('mcq', 7, 1, 'في التفاعل الأول ينتج الفضة الصلبة (عنصر)، وفي الثاني ينتج راسب هيدروكسيد النحاس II الصلب (مركب)؛ فينتج في كل منهما ناتج صلب، لكنه عنصر في الإحلال البسيط ومركب في الإحلال المزدوج.', '["تبادل الأيونات السالبة يحدث في التفاعل الثاني (المزدوج) فقط؛ ففي الأول يحل عنصر محل عنصر.","","العنصر الحر (Ag) ينتج في التفاعل الأول فقط، أما الثاني فنواتجه مركبان (NaCl وCu(OH)₂).","متفاعلا التفاعل الأول عنصر (Cu) ومركب (AgNO₃)، أما الثاني فمتفاعلاه مركبان؛ فهما ليسا من نوع واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.804Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإحلال البسيط: المتفاعلات عنصر ومركب، ومعادلته العامة A + BX → AX + B؛ يحل فيه عنصر (فلز أو لافلز) محل عنصر آخر في المركب؛ وينتج مركب جديد وعنصر حر هو العنصر المستعاض عنه؛ مثاله Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag. الإحلال المزدوج: المتفاعلات مركبان، ومعادلته العامة AX + BY → AY + BX؛ تتبادل فيه الأيونات بين المركبين فيرتبط كل أيون سالب بأيون موجب مختلف؛ وينتج مركبان مختلفان أحدهما ماء أو راسب أو غاز؛ مثاله Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O.', '["المتفاعلات: عنصر ومركب في البسيط، ومركبان في المزدوج","المعادلة العامة: A + BX → AX + B للبسيط، وAX + BY → AY + BX للمزدوج","ما يحدث: عنصر يحل محل عنصر في البسيط، وتبادل أيونات بين مركبين في المزدوج","النواتج: مركب وعنصر حر في البسيط، ومركبان أحدهما ماء أو راسب أو غاز في المزدوج","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"المتفاعلات في النوعين","marks":1},{"element":"المعادلة العامة لكل نوع","marks":1},{"element":"ما يحدث للجسيمات في كل نوع","marks":1},{"element":"نوع النواتج في كل نوع","marks":1},{"element":"مثال صحيح لكل نوع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في النقاط الخمس مع مثالين صحيحين"},{"level":"3–4 درجات","description":"مقارنة صحيحة في ثلاث أو أربع نقاط"},{"level":"1–2 درجة","description":"مقارنة صحيحة في نقطة أو نقطتين، أو وصف أحد النوعين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أن الإحلال المزدوج ينتج عنصرًا حرًّا","القول إن الإحلال البسيط يتضمن تبادل أيونات بين مركبين","الاكتفاء بوصف نوع واحد دون مقارنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.804Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التفاعل (1) إحلال بسيط: عنصر النحاس حلّ محل الفضة في مركبها نترات الفضة، فتكوّن مركب جديد هو نترات النحاس II وتحررت الفضة عنصرًا حرًّا صلبًا. التفاعل (2) إحلال مزدوج: تبادل المركبان Ca(OH)₂ وHCl الأيونات؛ فارتبط الأيون السالب OH⁻ بالأيون H⁺ وارتبط Cl⁻ بالأيون Ca²⁺، فتكوّن مركبان هما CaCl₂ (ذائب) والماء H₂O؛ فالناتج المميز هنا ماء.', '["(1) إحلال بسيط","Cu حل محل Ag في AgNO₃ وتحررت Ag عنصرًا حرًّا مع تكوّن Cu(NO₃)₂","(2) إحلال مزدوج","تبادل OH⁻ وCl⁻ موقعيهما فارتبط OH⁻ بـ H⁺ وCl⁻ بـ Ca²⁺","نواتج (2): CaCl₂ وماء (ناتج مميز لهذا النوع)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع التفاعل (1) وتعليله بوجود عنصر","marks":1},{"element":"وصف الإحلال في (1): Cu محل Ag ونواتج مركب وعنصر حر","marks":2},{"element":"تحديد نوع التفاعل (2)","marks":1},{"element":"وصف تبادل الأيونات في (2)","marks":1},{"element":"تحديد نواتج (2) وأن أحدها ماء","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحديد نوعي التفاعلين، ووصف دقيق لما حلّ محل ماذا، وتحديد نوع النواتج في كل منهما"},{"level":"4–5 درجات","description":"تحديد صحيح للنوعين مع وصف صحيح لأحد التفاعلين ونقص في الآخر"},{"level":"2–3 درجات","description":"تحديد صحيح للنوعين دون وصف كافٍ لما حلّ محل ماذا"},{"level":"1 درجة","description":"تحديد نوع تفاعل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التفاعل (2) إحلالًا بسيطًا لأن الهيدروجين «حل محل» الكالسيوم","عدم ذكر الأيونات التي تبادلت موقعيها في التفاعل (2)","إغفال أن الفضة في (1) تنتج عنصرًا حرًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.805Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تصنيف الطالب غير صحيح. في الإحلال البسيط يتفاعل عنصر مع مركب وينتج عنصر حر، أما هنا فالمتفاعلان مركبان (KCN وHBr) والناتجان مركبان (KBr وHCN) ولا يوجد عنصر حر. كما أن الحلول ليس في اتجاه واحد: فقد حلّ H⁺ محل K⁺ وفي الوقت نفسه حلّ K⁺ محل H⁺، أي تبادل الأيونان أماكنهما (CN⁻ ارتبط بـ H⁺ وBr⁻ ارتبط بـ K⁺)، وأحد الناتجين غاز HCN. التصنيف الصحيح إحلال مزدوج.', '["التصنيف غير صحيح","المتفاعلان مركبان وليس بينهما عنصر ولا يوجد عنصر حر في النواتج","حدث تبادل أيونات بين المركبين","أحد النواتج غاز (HCN)","التصنيف الصحيح: إحلال مزدوج"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم صحة التصنيف","marks":1},{"element":"الاستدلال بأن المتفاعلين مركبان ولا عنصر حر في النواتج","marks":1},{"element":"وصف تبادل الأيونات بين المركبين","marks":1},{"element":"ذكر التصنيف الصحيح (إحلال مزدوج) وأن أحد النواتج غاز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع الاستدلال بالمتفاعلات والنواتج وتبادل الأيونات وذكر التصنيف الصحيح"},{"level":"2–3 درجات","description":"حكم صحيح مع استدلال ناقص أو دون وصف تبادل الأيونات"},{"level":"1 درجة","description":"ذكر التصنيف الصحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول تصنيف الطالب لأن ذرة هيدروجين «ظهرت» في ناتج مختلف","الخلط بين حلول أيون محل أيون وحلول عنصر محل عنصر","عدم الانتباه إلى أن المتفاعلين مركبان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:27:04.805Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
