from (values
('mcq', 1, 'أيّ الفلزات الآتية يستطيع أن يحل محل النحاس في محلول نترات النحاس II؟', null, '["الفضة","الخارصين","الذهب","البلاتين"]'::jsonb, 'تطبيق', 'تحديد الفلز القادر على الإحلال', 'سهل', 'الكتاب ص 127، 128 — سلسلة النشاط الكيميائي'),
('mcq', 2, 'أيّ التفاعلات الآتية لا يحدث (NR)؟', null, '["Zn + NiCl₂ في محلول مائي","Fe + CuSO₄ في محلول مائي","Al + Pb(NO₃)₂ في محلول مائي","Ag + Pb(NO₃)₂ في محلول مائي"]'::jsonb, 'تطبيق', 'توقع عدم حدوث التفاعل', 'سهل', 'الكتاب ص 128 — توقع حدوث التفاعل باستعمال سلسلة النشاط'),
('mcq', 3, 'عند وضع الألومنيوم الصلب في محلول مائي لنترات الرصاص II Pb(NO₃)₂، أيّ المعادلات الآتية تمثل هذا التفاعل تمثيلًا صحيحًا وموزونًا؟', null, '["2Al + 3Pb(NO₃)₂ → 2Al(NO₃)₃ + 3Pb","Al + Pb(NO₃)₂ → NR","Al + Pb(NO₃)₂ → Al(NO₃)₂ + Pb","2Al + 3Pb(NO₃)₂ → Al₂(NO₃)₃ + 3Pb"]'::jsonb, 'تطبيق', 'توقع النواتج وكتابة المعادلة', 'متوسط', 'الكتاب ص 129 — المثال 4-2 والمسائل التدريبية'),
('mcq', 4, 'أيّ التفاعلات الآتية بين الهالوجين ومحلول ملح هاليد الصوديوم يحدث؟', null, '["Br₂ + 2NaCl → 2NaBr + Cl₂","I₂ + 2NaBr → 2NaI + Br₂","Cl₂ + 2NaI → 2NaCl + I₂","I₂ + 2NaF → 2NaI + F₂"]'::jsonb, 'تطبيق', 'توقع تفاعل الهالوجينات', 'متوسط', 'الكتاب ص 128، 129 — سلسلة نشاط الهالوجينات'),
('mcq', 5, 'وُضعت قطعة من الألومنيوم في أربعة أنابيب تحتوي على المحاليل المائية الآتية. في أيّ أنبوب لا يحدث تفاعل؟', null, '["ZnCl₂","NiCl₂","CuCl₂","MgCl₂"]'::jsonb, 'تطبيق', 'تحديد الحالة التي لا يحدث فيها تفاعل', 'متوسط', 'الكتاب ص 128 — سلسلة النشاط الكيميائي'),
('mcq', 6, 'تضم المجموعة الآتية خمسة أزواج من الفلز والمحلول المائي لملح فلز آخر. كم تفاعلًا منها يحدث فعلًا؟', '{"headers":["الرقم","الفلز","المحلول المائي"],"rows":[["1","Fe","CuSO₄"],["2","Cu","FeSO₄"],["3","Mg","AlCl₃"],["4","Ag","Pb(NO₃)₂"],["5","Zn","MnCl₂"]]}'::jsonb, '["تفاعل واحد","تفاعلان","ثلاثة تفاعلات","أربعة تفاعلات"]'::jsonb, 'تحليل', 'تقييم عدة تفاعلات بسلسلة النشاط', 'صعب', 'الكتاب ص 127، 128 — سلسلة النشاط الكيميائي'),
('mcq', 7, 'لا يحدث تفاعل عند وضع سلك من الفضة في محلول نترات النحاس II (Ag + Cu(NO₃)₂ → NR). ما التفسير الصحيح؟', null, '["الفضة تقع بعد النحاس في سلسلة النشاط، فهي أقل نشاطًا ولا تحل محله","الفضة تقع قبل النحاس في سلسلة النشاط لكنها فلز صلب","جميع الفلزات الصلبة لا تحل محل فلز آخر في المحاليل المائية","نترات النحاس II مركب لا يتفاعل مع أي فلز"]'::jsonb, 'تطبيق', 'تعليل عدم حدوث تفاعل', 'سهل', 'الكتاب ص 128 — توقع حدوث التفاعل (NR)'),
('essay', 1, 'استعن بسلسلة النشاط الكيميائي للفلزات والهالوجينات لتحدد هل يحدث كل تفاعل من التفاعلات الآتية في المحلول المائي أم لا، ثم اكتب معادلة رمزية موزونة للتفاعل الذي يحدث، واكتب NR للذي لا يحدث:
(a) Mg + ZnCl₂ →
(b) Cu + Pb(NO₃)₂ →
(c) Ni + AgNO₃ →
(d) Br₂ + KI →', null, null, 'تطبيق', 'توقع تفاعلات الإحلال البسيط وكتابة المعادلات', 'متوسط', 'الكتاب ص 128، 129 — المثال 4-2 والمسائل التدريبية 25–28'),
('essay', 2, 'تريد تخزين محلول نترات الفضة AgNO₃ في وعاء مصنوع من أحد الفلزات الآتية: الخارصين، النحاس، الذهب. استعن بسلسلة النشاط لتحدد هل يصلح كل فلز لصنع الوعاء، مع التعليل واكتب معادلة موزونة لكل تفاعل يحدث، ثم حدد الفلز الأنسب.', null, null, 'تطبيق', 'تطبيق سلسلة النشاط في موقف عملي', 'صعب', 'الكتاب ص 127، 128 — سلسلة النشاط الكيميائي'),
('essay', 3, 'حدّد لكل تفاعل مما يأتي هل يحدث في المحلول المائي، واكتب معادلة موزونة للتفاعل الذي يحدث أو NR:
(a) Cl₂ + NaBr
(b) Br₂ + NaCl
(c) Br₂ + KI
(d) I₂ + KBr
ثم اذكر القاعدة التي اعتمدت عليها.', null, null, 'تطبيق', 'توقع تفاعلات الهالوجينات', 'صعب', 'الكتاب ص 128، 129 — سلسلة نشاط الهالوجينات')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
