from (values
('mcq', 1, 1, 'يحل الفلز محل أي فلز يقع بعده في سلسلة النشاط. الخارصين يقع قبل النحاس فهو أنشط منه ويحل محله، أما الفضة والبلاتين والذهب فتقع بعد النحاس فهي أقل نشاطًا ولا تحل محله.', '["الفضة تقع بعد النحاس في السلسلة، فهي أقل نشاطًا منه ولا تحل محله.","","الذهب يقع في أسفل السلسلة بعد النحاس، فلا يحل محله.","البلاتين يقع بعد النحاس في السلسلة، فهو أقل نشاطًا ولا يحل محله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.805Z"}'::jsonb),
('mcq', 2, 3, 'الفضة تقع بعد الرصاص في سلسلة النشاط، فهي أقل نشاطًا منه ولا تحل محله؛ لذلك Ag + Pb(NO₃)₂ → NR. أما الخارصين والحديد والألومنيوم فتقع قبل النيكل والنحاس والرصاص على الترتيب، فتحل محلها.', '["الخارصين يقع قبل النيكل فهو أنشط منه، ولذلك يحل محله فيحدث التفاعل.","الحديد يقع قبل النحاس فهو أنشط منه، فيحل محله ويحدث التفاعل.","الألومنيوم يقع قبل الرصاص فهو أنشط منه، فيحل محله ويحدث التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.806Z"}'::jsonb),
('mcq', 3, 0, 'الألومنيوم يقع قبل الرصاص في سلسلة النشاط فيحل محله، ويتكوّن نترات الألومنيوم Al(NO₃)₃ (Al³⁺ مع ثلاثة NO₃⁻) ويتحرر الرصاص. وتكون المعادلة الموزونة 2Al + 3Pb(NO₃)₂ → 2Al(NO₃)₃ + 3Pb.', '["","الألومنيوم أنشط من الرصاص لوقوعه قبله في السلسلة، فالتفاعل يحدث ولا يكون NR.","صيغة Al(NO₃)₂ خاطئة لأن أيون الألومنيوم Al³⁺ (عدد تأكسده +3) يحتاج إلى ثلاثة أيونات NO₃⁻ لتتعادل الشحنات.","صيغة Al₂(NO₃)₃ غير صحيحة؛ فالصيغة المتعادلة لنترات الألومنيوم هي Al(NO₃)₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.806Z"}'::jsonb),
('mcq', 4, 2, 'يحل الهالوجين الأنشط محل الأقل نشاطًا في الهاليد. ترتيب النشاط: فلور > كلور > بروم > يود؛ فالكلور أنشط من اليود، ويحل محله في NaI: Cl₂ + 2NaI → 2NaCl + I₂.', '["البروم أقل نشاطًا من الكلور، فلا يحل محله في NaCl؛ والتفاعل NR.","اليود أقل الهالوجينات نشاطًا ولا يحل محل البروم؛ والتفاعل NR.","","اليود أقل نشاطًا من الفلور بكثير، فلا يحل محله في NaF؛ والتفاعل NR."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.806Z"}'::jsonb),
('mcq', 5, 3, 'يحل الألومنيوم محل الفلزات التي تقع بعده في سلسلة النشاط. الماغنسيوم يقع قبل الألومنيوم فهو أنشط منه، فلا يحل الألومنيوم محله؛ لذلك لا يحدث تفاعل في أنبوب MgCl₂.', '["الخارصين يقع بعد الألومنيوم، فيحل الألومنيوم محله ويحدث تفاعل.","النيكل يقع بعد الألومنيوم، فيحل الألومنيوم محله ويحدث تفاعل.","النحاس يقع بعد الألومنيوم بكثير، فيحل الألومنيوم محله ويحدث تفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.806Z"}'::jsonb),
('mcq', 6, 1, 'يحدث التفاعل عندما يقع الفلز قبل فلز المحلول في سلسلة النشاط. (1) الحديد قبل النحاس: يحدث. (2) النحاس بعد الحديد: لا يحدث. (3) الماغنسيوم قبل الألومنيوم: يحدث. (4) الفضة بعد الرصاص: لا يحدث. (5) الخارصين يقع بعد المنجنيز: لا يحدث. إذن يحدث تفاعلان فقط هما (1) و(3).', '["يحدث أكثر من تفاعل واحد؛ فكلٌّ من (1) و(3) يحدث، لأن الحديد قبل النحاس والماغنسيوم قبل الألومنيوم.","","الخطأ الشائع عدّ التفاعل (5) حادثًا؛ لكن المنجنيز يقع قبل الخارصين في السلسلة، فهو أنشط منه ولا يحل الخارصين محله.","للوصول إلى أربعة تفاعلات يلزم أن يحدث اثنان من التفاعلات (2) و(4) و(5)، وكلها لا تحدث لأن الفلز فيها يقع بعد فلز المحلول في السلسلة؛ فالعدد غير صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.806Z"}'::jsonb),
('mcq', 7, 0, 'لا يحل الفلز محل فلز يقع قبله في سلسلة النشاط. الفضة تقع بعد النحاس، أي هي أقل نشاطًا منه، فلا تستطيع أن تحل محله؛ ولذلك لا يحدث تفاعل (NR).', '["","الفضة تقع بعد النحاس لا قبله، وحالة الفلز الصلبة لا تمنع التفاعل: فالنحاس الصلب يحل محل الفضة.","الفلزات الصلبة تحل محل غيرها إذا كانت أنشط؛ فالنحاس الصلب يحل محل الفضة في AgNO₃.","نترات النحاس II تتفاعل مع الفلزات الأنشط من النحاس مثل الحديد والخارصين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.807Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) يقع الماغنسيوم قبل الخارصين، فيحدث التفاعل: Mg + ZnCl₂ → MgCl₂ + Zn. (b) يقع النحاس بعد الرصاص فهو أقل نشاطًا ولا يحل محله: Cu + Pb(NO₃)₂ → NR. (c) يقع النيكل قبل الفضة، فيحدث التفاعل: Ni + 2AgNO₃ → Ni(NO₃)₂ + 2Ag. (d) البروم أنشط من اليود، فيحل محله: Br₂ + 2KI → 2KBr + I₂.', '["(a) يحدث لأن Mg قبل Zn: Mg + ZnCl₂ → MgCl₂ + Zn","(b) لا يحدث لأن Cu بعد Pb: NR","(c) يحدث لأن Ni قبل Ag: Ni + 2AgNO₃ → Ni(NO₃)₂ + 2Ag","(d) يحدث لأن Br أنشط من I: Br₂ + 2KI → 2KBr + I₂"]'::jsonb, '["حدد موقع العنصر الحر والعنصر الموجود في المركب في سلسلة النشاط","إذا كان العنصر الحر قبل العنصر الذي في المركب فالتفاعل يحدث، وإلا فهو NR","اكتب صيغ النواتج: مركب جديد والعنصر المستعاض عنه","زن المعادلة بالتأكد من تساوي عدد ذرات كل عنصر في الطرفين"]'::jsonb, '[{"element":"(a) قرار صحيح مع المعادلة الموزونة","marks":2},{"element":"(b) قرار صحيح مع التعليل وكتابة NR","marks":2},{"element":"(c) قرار صحيح مع المعادلة الموزونة","marks":2},{"element":"(d) قرار صحيح مع المعادلة الموزونة","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"القرار صحيح في الحالات الأربع، والمعادلات الثلاث صيغها صحيحة وموزونة، مع NR في (b)"},{"level":"5–7 درجات","description":"القرار صحيح في الحالات الأربع مع خطأ في صيغة أو وزن في معادلة واحدة أو اثنتين"},{"level":"2–4 درجات","description":"قرار صحيح في حالتين أو ثلاث دون معادلات صحيحة"},{"level":"1 درجة","description":"قرار صحيح في حالة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ترتيب الفلزين وتوقع حدوث (b)","كتابة Ni(NO₃) أو إهمال المعامل 2 أمام AgNO₃ وAg","كتابة معادلة موزونة للتفاعل (b) بدل NR"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.807Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخارصين يقع قبل الفضة في سلسلة النشاط فهو أنشط منها ويحل محلها، فلا يصلح: Zn + 2AgNO₃ → Zn(NO₃)₂ + 2Ag. النحاس يقع قبل الفضة أيضًا فيحل محلها، فلا يصلح: Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag. الذهب يقع بعد الفضة، فهو أقل نشاطًا ولا يحل محلها (NR)، فلا يتفاعل مع المحلول ويصلح. الفلز الأنسب هو الذهب.', '["الخارصين يقع قبل الفضة فيحل محلها فلا يصلح","Zn + 2AgNO₃ → Zn(NO₃)₂ + 2Ag","النحاس يقع قبل الفضة فيحل محلها فلا يصلح","Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag","الذهب يقع بعد الفضة فلا يتفاعل (NR) فهو الأنسب"]'::jsonb, '["حدد موقع كل فلز بالنسبة إلى الفضة في سلسلة النشاط","الفلز الواقع قبل الفضة يحل محلها فيتفاعل مع المحلول","اكتب معادلة موزونة لكل تفاعل يحدث (Ag⁺ في AgNO₃ يحتاج إلى معامل 2 مع ذرتي Ag)","اختر الفلز الذي لا يتفاعل"]'::jsonb, '[{"element":"الخارصين: القرار والتعليل","marks":1},{"element":"معادلة الخارصين الموزونة","marks":1},{"element":"النحاس: القرار والتعليل","marks":1},{"element":"معادلة النحاس الموزونة","marks":1},{"element":"الذهب: القرار والتعليل","marks":1},{"element":"تحديد الفلز الأنسب (الذهب)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"قرارات صحيحة مع تعليل بسلسلة النشاط، ومعادلتان موزونتان صحيحتان، واختيار الذهب"},{"level":"4–5 درجات","description":"قرارات صحيحة مع خطأ في معادلة أو في التعليل"},{"level":"2–3 درجات","description":"قرار صحيح في فلزين دون معادلات صحيحة"},{"level":"1 درجة","description":"قرار صحيح لفلز واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النحاس يصلح لأن الفضة أنشط منه","كتابة Zn + AgNO₃ → ZnNO₃ + Ag بصيغة خاطئة أو غير موزونة","عدم استنتاج أن الفلز الأنسب هو الذي يقع بعد الفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.807Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الهالوجين الأنشط يحل محل الهالوجين الأقل نشاطًا في الهاليد، وترتيب النشاط: فلور > كلور > بروم > يود. (a) الكلور أنشط من البروم: Cl₂ + 2NaBr → 2NaCl + Br₂. (b) البروم أقل نشاطًا من الكلور: Br₂ + NaCl → NR. (c) البروم أنشط من اليود: Br₂ + 2KI → 2KBr + I₂. (d) اليود أقل نشاطًا من البروم: I₂ + KBr → NR.', '["القاعدة: الهالوجين الأنشط يحل محل الأقل نشاطًا (F > Cl > Br > I)","(a) Cl₂ + 2NaBr → 2NaCl + Br₂","(b) NR","(c) Br₂ + 2KI → 2KBr + I₂","(d) NR"]'::jsonb, '["رتب الهالوجين الحر والهالوجين في الملح بحسب سلسلة نشاط الهالوجينات","إذا كان الحر أنشط فالتفاعل يحدث ويحل محل الأقل نشاطًا","اكتب النواتج ثم زن المعادلة (معامل 2 لهاليد الفلز وللناتج المقابل)"]'::jsonb, '[{"element":"(a) القرار والمعادلة الموزونة","marks":1},{"element":"(b) القرار وكتابة NR","marks":1},{"element":"(c) القرار والمعادلة الموزونة","marks":1},{"element":"(d) القرار وكتابة NR","marks":1},{"element":"ذكر القاعدة وترتيب النشاط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"القرارات الأربعة صحيحة، والمعادلتان موزونتان، وNR في (b) و(d)، مع ذكر القاعدة"},{"level":"3–4 درجات","description":"قرارات صحيحة مع خطأ في وزن معادلة أو غياب القاعدة"},{"level":"1–2 درجة","description":"قرار صحيح في حالة أو حالتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع حدوث (b) أو (d) لأن «الهالوجينات كلها متشابهة»","عدم وزن المعادلة بوضع المعامل 2 للملح وللناتج","عكس ترتيب نشاط الكلور والبروم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.807Z"}'::jsonb)
