('mcq', 7, 'لوحظ أن البروم السائل Br₂ يحل محل اليود في محلول يوديد الصوديوم NaI، بينما لا يحدث تفاعل عند إضافته إلى محلول كلوريد الصوديوم NaCl. ما ترتيب الكلور والبروم واليود من الأنشط إلى الأقل نشاطًا؟', null, '["I > Br > Cl","Br > Cl > I","Cl > Br > I","Cl > I > Br"]'::jsonb, 'تحليل', 'استنتاج ترتيب الهالوجينات من نتائج', 'صعب', 'الكتاب ص 128 — سلسلة نشاط الهالوجينات'),
('essay', 1, 'عرّف النشاط الكيميائي للفلز، ثم رتّب الفلزات الآتية من الأنشط إلى الأقل نشاطًا اعتمادًا على سلسلة النشاط: الذهب، الفضة، الماغنسيوم، النحاس، الحديد. وحدّد أيًّا منها يحل محل النحاس في محلول نترات النحاس II، مع التعليل.', null, null, 'تطبيق', 'ترتيب فلزات واستعمال السلسلة', 'متوسط', 'الكتاب ص 127، 128 — سلسلة النشاط الكيميائي'),
('essay', 2, 'أُجريت تجارب لمقارنة نشاط الهالوجينات، وكانت نتائجها كما يأتي: الكلور يحل محل البروم في محلول بروميد الصوديوم، والكلور يحل محل اليود في محلول يوديد الصوديوم، والبروم يحل محل اليود في محلول يوديد الصوديوم، والبروم لا يحل محل الكلور في محلول كلوريد الصوديوم، واليود لا يحل محل البروم في محلول بروميد الصوديوم، والفلور يحل محل الكلور في محلول كلوريد الصوديوم. استنتج ترتيب الهالوجينات الأربعة من الأنشط إلى الأقل، ثم توقّع هل يحل البروم محل الفلور في فلوريد الصوديوم، وهل يحل الكلور محل اليود في يوديد البوتاسيوم، وأيّ الهالوجينات يتفاعل أسرع مع الصوديوم؟ علل.', null, null, 'تحليل', 'استنتاج ترتيب النشاط من نتائج', 'صعب', 'الكتاب ص 128 — تحليل التدرج في الخواص'),
('essay', 3, 'رتّب الفلزات الآتية بحسب نشاطها من الأنشط إلى الأقل نشاطًا اعتمادًا على سلسلة النشاط: الماغنسيوم، الكالسيوم، الألومنيوم، الليثيوم، البوتاسيوم. ثم حدّد أيّها يحل محل الماغنسيوم في محلول كلوريد الماغنسيوم، وهل يحل الألومنيوم محل الكالسيوم في محلول كلوريد الكالسيوم؟ علل إجابتك.', null, null, 'تطبيق', 'ترتيب فلزات والمقارنة بين نشاطها', 'صعب', 'الكتاب ص 127، 132 — سلسلة النشاط الكيميائي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
