insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يقع الفلز الأنشط في أعلى السلسلة. ترتيب هذه الفلزات من الأنشط إلى الأقل: الماغنسيوم، ثم الخارصين، ثم الحديد، ثم النحاس؛ فالماغنسيوم هو الأنشط.', '["النحاس أقل هذه الفلزات نشاطًا لأنه يقع في أسفل السلسلة بينها.","الحديد يقع بعد الماغنسيوم والخارصين فهو أقل نشاطًا منهما.","","الخارصين يقع بعد الماغنسيوم في السلسلة، فهو أقل نشاطًا منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.808Z"}'::jsonb),
('mcq', 2, 0, 'ترتّب الهالوجينات بحسب نشاطها: فلور > كلور > بروم > يود؛ فالفلور أنشطها ويقع في أعلى سلسلة نشاط الهالوجينات.', '["","الكلور أقل نشاطًا من الفلور لأنه يليه في السلسلة.","البروم يقع بعد الفلور والكلور، فهو أقل نشاطًا منهما.","اليود أقل الهالوجينات نشاطًا لأنه يقع في أسفل السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:27:04.808Z"}'::jsonb),
('mcq', 3, 3, 'الفلز الذي يحل محل فلز آخر أنشط منه. الحديد حل محل النحاس فهو أنشط من النحاس، والنحاس حل محل الفضة فهو أنشط من الفضة؛ إذن الترتيب: Fe > Cu > Ag.', '["هذا ترتيب معكوس؛ فالفضة هي التي حل النحاس محلها، فهي أقل نشاطًا وليست أنشط.","النحاس لا يمكن أن يكون أنشط من الحديد لأن الحديد هو الذي حل محله.","لا يتفق مع النتائج؛ فالفضة ليست أنشط من الحديد والنحاس لأن النحاس حل محلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.808Z"}'::jsonb),
('mcq', 4, 1, 'يحل الفلز محل الفلز الذي يقع بعده في سلسلة النشاط. الرصاص يقع قبل الفضة (فهو أنشط منها)، فيستطيع أن يحل محلها.', '["النيكل يقع قبل النحاس في السلسلة، فالنحاس أقل نشاطًا ولا يحل محل النيكل.","","القصدير يقع قبل الفضة، فالفضة أقل نشاطًا ولا تحل محله.","الحديد يقع قبل البلاتين، فالبلاتين أقل نشاطًا ولا يحل محل الحديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.809Z"}'::jsonb),
('mcq', 5, 0, 'يُقصد بنشاط الفلز مقدرته على التفاعل مع مادة أخرى؛ وكلما كان الفلز أنشط كان أعلى في السلسلة وأقدر على الحلول محل الفلزات التي تقع بعده.', '["","التوصيل خاصية فيزيائية للفلزات عامة، ولا يرتبط بترتيبها في سلسلة النشاط.","الكثافة خاصية فيزيائية، ولا تحدد نشاط الفلز الكيميائي.","قابلية الطرق خاصية فيزيائية للفلزات، وليست معيارًا للنشاط الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.809Z"}'::jsonb),
('mcq', 6, 3, 'ترتيب هذه الفلزات في السلسلة من الأعلى إلى الأسفل: الرصاص، ثم النحاس، ثم الفضة، ثم البلاتين. فالبلاتين يقع في أسفلها، وهو الأقل نشاطًا.', '["الفضة تقع قبل البلاتين في السلسلة، فهي أنشط منه.","النحاس يقع قبل الفضة والبلاتين، فهو أنشط منهما.","الرصاص أنشط هذه الفلزات لأنه يقع في أعلاها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.809Z"}'::jsonb),
('mcq', 7, 2, 'حلول البروم محل اليود يعني أن البروم أنشط من اليود (Br > I). وعدم حلوله محل الكلور يعني أن الكلور أنشط منه (Cl > Br). فالترتيب: Cl > Br > I.', '["هذا عكس الترتيب؛ فاليود أقل نشاطًا لأن البروم حل محله.","هذا يعني أن البروم أنشط من الكلور، لكنه لا يحل محل الكلور في NaCl، فالكلور هو الأنشط.","","لا يتفق مع أن البروم يحل محل اليود؛ فاليود لا يمكن أن يكون أنشط من البروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.809Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النشاط الكيميائي للفلز هو مقدرته على التفاعل مع مادة أخرى؛ ويكون الأنشط في أعلى السلسلة والأقل نشاطًا في أسفلها. ترتيب الفلزات من الأنشط إلى الأقل: الماغنسيوم > الحديد > النحاس > الفضة > الذهب. الفلزان اللذان يحلان محل النحاس في محلول نترات النحاس II هما الماغنسيوم والحديد؛ لأن كلًّا منهما يقع قبل النحاس في السلسلة فهو أنشط منه، أما الفضة والذهب فيقعان بعد النحاس فهما أقل نشاطًا ولا يحلان محله.', '["النشاط: مقدرة الفلز على التفاعل مع مادة أخرى","الترتيب: Mg > Fe > Cu > Ag > Au","الذي يحل محل النحاس: الماغنسيوم والحديد","التعليل: يقعان قبل النحاس في السلسلة فهما أنشط منه"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف النشاط الكيميائي","marks":1},{"element":"الترتيب الصحيح للفلزات الخمسة","marks":2},{"element":"تحديد الماغنسيوم والحديد","marks":1},{"element":"التعليل بموقعهما قبل النحاس","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح، وترتيب كامل صحيح، وتحديد الفلزين مع التعليل"},{"level":"3–4 درجات","description":"ترتيب صحيح أو بخطأ واحد مع تحديد الفلزين، أو نقص في التعريف أو التعليل"},{"level":"1–2 درجة","description":"تعريف صحيح فقط أو ترتيب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب بوضع الذهب أولًا","عدّ الفضة قادرة على إحلال النحاس لأنها «أغلى»","الخلط بين النشاط الكيميائي والقيمة المادية للفلز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.809Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الهالوجين الذي يحل محل غيره أنشط منه. من النتائج: Cl أنشط من Br ومن I، وBr أنشط من I، وF أنشط من Cl، فبالتتابع F أنشطها. الترتيب: F > Cl > Br > I. البروم لا يحل محل الفلور في NaF لأنه أقل نشاطًا منه (Br₂ + 2NaF → NR). الكلور يحل محل اليود في KI لأنه أنشط منه: Cl₂ + 2KI → 2KCl + I₂. والهالوجين الأنشط هو الفلور، فهو الأكثر قابلية للتفاعل مع الصوديوم.', '["الترتيب: F > Cl > Br > I","الاستدلال: الهالوجين الذي يحل محل آخر يكون أنشط منه","البروم لا يحل محل الفلور في NaF (NR)","الكلور يحل محل اليود في KI: Cl₂ + 2KI → 2KCl + I₂","الفلور هو الأنشط والأسرع تفاعلًا"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح للهالوجينات الأربعة","marks":2},{"element":"الاستدلال بحلول الهالوجين محل غيره","marks":1},{"element":"عدم حلول البروم محل الفلور مع التعليل","marks":1},{"element":"حلول الكلور محل اليود في KI مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ترتيب صحيح مع الاستدلال، وتوقع صحيح للتفاعلين مع التعليل، وتحديد الأنشط"},{"level":"3–4 درجات","description":"ترتيب صحيح مع توقع صحيح لتفاعل واحد أو تعليل ناقص"},{"level":"1–2 درجة","description":"ترتيب جزئي أو توقع صحيح دون استدلال"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب بجعل اليود أنشط الهالوجينات","توقع حلول البروم محل الفلور","عدم الاستفادة من نتيجة واحدة على الأقل في الاستدلال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.810Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الترتيب من الأنشط إلى الأقل نشاطًا: الليثيوم > البوتاسيوم > الكالسيوم > الماغنسيوم > الألومنيوم. الفلزات التي تحل محل الماغنسيوم هي الليثيوم والبوتاسيوم والكالسيوم؛ لأنها تقع قبل الماغنسيوم في السلسلة فهي أنشط منه. أما الألومنيوم فلا يحل محل الكالسيوم في CaCl₂ لأنه يقع بعد الكالسيوم، أي هو أقل نشاطًا منه (Al + CaCl₂ → NR).', '["الترتيب: Li > K > Ca > Mg > Al","الفلزات التي تحل محل Mg: Li وK وCa","التعليل: تقع قبل Mg في السلسلة","Al لا يحل محل Ca لأنه يقع بعده فهو أقل نشاطًا"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح للفلزات الخمسة","marks":2},{"element":"تحديد الفلزات الثلاثة التي تحل محل الماغنسيوم","marks":1},{"element":"عدم حلول الألومنيوم محل الكالسيوم","marks":1},{"element":"التعليل بموقع كل فلز في السلسلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ترتيب كامل صحيح مع تحديد الفلزات الثلاثة والتعليل لعدم حلول الألومنيوم"},{"level":"3–4 درجات","description":"ترتيب بخطأ واحد، أو ترتيب صحيح مع نقص في التحديد أو التعليل"},{"level":"1–2 درجة","description":"ترتيب جزئي أو تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الألومنيوم قبل الماغنسيوم","إهمال الكالسيوم أو البوتاسيوم عند تحديد ما يحل محل الماغنسيوم","القول إن الألومنيوم يحل محل الكالسيوم لأنه أخف وزنًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.810Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
