from (values
('mcq', 1, 'ما صيغتا الناتجين المتوقعين عند تفاعل محلول BaCl₂ مع محلول K₂CO₃؟', null, '["Ba₂CO₃ و KCl₂","BaK و Cl₂CO₃","BaCO₃ و KCl","BaCO₃ و K₂Cl"]'::jsonb, 'تطبيق', 'كتابة صيغ نواتج الإحلال المزدوج', 'سهل', 'الكتاب ص 131 — الجدول 4-8: الخطوات الأساسية لكتابة معادلات الإحلال المزدوج'),
('mcq', 2, 'ما المعادلة الرمزية الموزونة لتفاعل محلول Na₃PO₄ مع محلول CaCl₂ الذي ينتج Ca₃(PO₄)₂ وNaCl؟', null, '["2Na₃PO₄ + 3CaCl₂ → Ca₃(PO₄)₂ + 6NaCl","Na₃PO₄ + CaCl₂ → Ca₃(PO₄)₂ + NaCl","2Na₃PO₄ + 3CaCl₂ → Ca₂(PO₄)₃ + 6NaCl","2Na₃PO₄ + 3CaCl₂ → Ca₃(PO₄)₂ + 3NaCl"]'::jsonb, 'تطبيق', 'وزن معادلة إحلال مزدوج', 'متوسط', 'الكتاب ص 131 — الجدول 4-8: وزن المعادلة (الخطوة 6)'),
('mcq', 3, 'عند وزن المعادلة Al(NO₃)₃ + H₂SO₄ → Al₂(SO₄)₃ + HNO₃ بأصغر معاملات صحيحة، ما مجموع معاملات المواد في المعادلة الموزونة؟', null, '["4","9","11","12"]'::jsonb, 'تطبيق', 'حساب مجموع معاملات معادلة موزونة', 'متوسط', 'الكتاب ص 131 — الجدول 4-8: مثال Al(NO₃)₃ + H₂SO₄'),
('mcq', 4, 'عند كتابة معادلة تفاعل إحلال مزدوج، ما الخطوة التي تأتي مباشرة بعد تعيين الأيونات الموجبة والسالبة في كل متفاعل؟', null, '["ربط كل أيون موجب بالأيون السالب في المركب نفسه","ربط كل أيون موجب بالأيون السالب في المركب الآخر","وزن المعادلة بتعديل المعاملات","كتابة المعادلة الكاملة للتفاعل"]'::jsonb, 'تذكر', 'ترتيب خطوات كتابة المعادلة', 'سهل', 'الكتاب ص 131 — الجدول 4-8: الخطوات الأساسية لكتابة معادلات الإحلال المزدوج'),
('mcq', 5, 'عند مزج محلول MgCl₂ مع محلول Na₃PO₄ يتكون راسب فوسفات الماغنسيوم. ما صيغة هذا الراسب علمًا بأن أيون الماغنسيوم Mg²⁺ وأيون الفوسفات PO₄³⁻؟', null, '["Mg₂(PO₄)₃","MgPO₄","Mg₃(PO₄)₂","Mg₃PO₄"]'::jsonb, 'تطبيق', 'كتابة صيغة ناتج بدلالة الشحنات', 'متوسط', 'الكتاب ص 131 — الجدول 4-8: كتابة صيغ النواتج بدلالة أعداد التأكسد (الخطوة 4)'),
('mcq', 6, 'أيّ المعادلات الآتية تمثل تفاعل KOH مع H₂SO₄ في محلول مائي تمثيلًا صحيحًا وموزونًا؟', null, '["2KOH + H₂SO₄ → K₂SO₄ + 2H₂O","KOH + H₂SO₄ → K₂SO₄ + H₂O","2KOH + H₂SO₄ → K₂SO₄ + H₂O","2KOH + H₂SO₄ → 2KSO₄ + 2H₂O"]'::jsonb, 'تحليل', 'تمييز المعادلة الصحيحة الموزونة', 'صعب', 'الكتاب ص 130، 131 — تفاعلات الإحلال المزدوج ووزن المعادلات'),
('mcq', 7, 'كتب طالب لتفاعل محلول CaCl₂ مع محلول Na₂CO₃ المعادلة: CaCl₂ + Na₂CO₃ → CaCO₃ + NaCl. ما الخطأ الموجود في هذه المعادلة؟', null, '["صيغة كربونات الكالسيوم خاطئة والصحيحة Ca₂CO₃","لم تتبادل الأيونات الموجبة مواقعها","الناتج يجب أن يكون عنصرين لا مركبين","المعادلة غير موزونة، ويلزم المعامل 2 أمام NaCl"]'::jsonb, 'تحليل', 'تحليل خطأ في معادلة', 'صعب', 'الكتاب ص 131 — الجدول 4-8: وزن المعادلة (الخطوة 6)'),
('essay', 1, 'يتفاعل محلول مائي من FeCl₃ مع محلول مائي من NaOH فيتكون الراسب Fe(OH)₃ ويبقى NaCl ذائبًا في المحلول. اكتب معادلة رمزية موزونة لهذا التفاعل، موضحًا خطوات كتابتها.', null, null, 'تطبيق', 'كتابة معادلة إحلال مزدوج بخطوات', 'سهل', 'الكتاب ص 130، 131 — الجدول 4-8 وتفاعل NaOH مع CuCl₂'),
('essay', 2, 'اكتب معادلة رمزية موزونة لكل من تفاعلي الإحلال المزدوج الآتيين:
(a) محلول نترات الرصاص II Pb(NO₃)₂ مع محلول يوديد البوتاسيوم KI لإنتاج الراسب PbI₂ ومحلول KNO₃.
(b) محلول حمض النيتريك HNO₃ مع محلول هيدروكسيد الكالسيوم Ca(OH)₂ لإنتاج محلول Ca(NO₃)₂ والماء.', null, null, 'تطبيق', 'كتابة معادلات إحلال مزدوج موزونة', 'متوسط', 'الكتاب ص 131 — المسائل التدريبية 29–32'),
('essay', 3, 'كتب طالب لتفاعل محلول AlCl₃ مع محلول Na₂SO₄ المعادلة الآتية: AlCl₃ + Na₂SO₄ → AlSO₄ + NaCl₂
(a) بيّن الخطأين في صيغتي الناتجين مستعينًا بشحنات الأيونات (Al³⁺ وSO₄²⁻ وNa⁺ وCl⁻).
(b) اكتب الصيغتين الصحيحتين ثم المعادلة الموزونة.
(c) لماذا لا يجوز تغيير الأرقام الصغيرة (الأدلة) داخل الصيغ لتحقيق الاتزان؟', null, null, 'تقويم', 'تقويم معادلة خاطئة وتصحيحها', 'صعب', 'الكتاب ص 131 — الجدول 4-8: كتابة صيغ النواتج ووزن المعادلة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في الإحلال المزدوج يرتبط كل أيون موجب بالأيون السالب في المركب الآخر: يرتبط Ba²⁺ مع CO₃²⁻ فيتكون BaCO₃ (شحنتان متعادلتان)، ويرتبط K⁺ مع Cl⁻ فيتكون KCl. فالناتجان هما BaCO₃ وKCl.', '["الصيغتان خاطئتان: Ba²⁺ يتعادل مع CO₃²⁻ بنسبة 1:1 فصيغته BaCO₃ لا Ba₂CO₃، وK⁺ يتعادل مع Cl⁻ بنسبة 1:1 فصيغته KCl لا KCl₂.","ربط هذا الاختيار أيونًا موجبًا بأيون موجب وأيونًا سالبًا بأيون سالب؛ والصحيح ربط الأيون الموجب بالأيون السالب في المركب الآخر.","","صيغة BaCO₃ صحيحة، لكن K₂Cl خاطئة؛ فأيون K⁺ (شحنة +1) يتعادل مع Cl⁻ (شحنة −1) بنسبة 1:1 فصيغته KCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.811Z"}'::jsonb),
('mcq', 2, 0, 'لموازنة المعادلة نبدأ بمجموعة PO₄ وبالكالسيوم: يحتوي Ca₃(PO₄)₂ على 3 ذرات Ca ومجموعتين PO₄، لذا يلزم 3CaCl₂ و2Na₃PO₄، فينتج 6 أيونات Na⁺ و6 أيونات Cl⁻ أي 6NaCl. المعادلة 2Na₃PO₄ + 3CaCl₂ → Ca₃(PO₄)₂ + 6NaCl فيها 6Na و2P و8O و3Ca و6Cl على كل جانب.', '["","المعادلة غير موزونة؛ فعدد ذرات Ca وP وNa وCl مختلف في الطرفين.","الصيغة Ca₂(PO₄)₃ خاطئة (Ca²⁺ يتعادل مع PO₄³⁻ بنسبة 3:2 فتكون الصيغة Ca₃(PO₄)₂)، ولا تتزن ذرات Ca بها.","المعاملات أمام المتفاعلات وCa₃(PO₄)₂ صحيحة، لكن ذرات Na (6 في اليسار و3 في اليمين) وCl غير متزنة؛ والصحيح 6NaCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.811Z"}'::jsonb),
('mcq', 3, 3, 'المعادلة الموزونة هي 2Al(NO₃)₃ + 3H₂SO₄ → Al₂(SO₄)₃ + 6HNO₃، ومعاملاتها 2 و3 و1 و6، ومجموعها 2 + 3 + 1 + 6 = 12.', '["هذا مجموع معاملات المعادلة قبل وزنها (1 + 1 + 1 + 1)؛ والمعادلة غير الموزونة لا تحقق حفظ الذرات.","هذا ناتج وضع المعامل 3 أمام HNO₃ بدل 6، فلا تتساوى ذرات N وH في الطرفين.","هذا ناتج إهمال المعامل 2 أمام Al(NO₃)₃، فلا تتساوى ذرات Al وN في الطرفين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.811Z"}'::jsonb),
('mcq', 4, 1, 'بعد تعيين الأيونات يُربط كل أيون موجب بالأيون السالب في المركب الآخر، ثم تُكتب صيغ النواتج بحسب الشحنات، ثم تُكتب المعادلة الكاملة، وأخيرًا تُوزن.', '["هذا الربط موجود أصلًا في المتفاعلين، ولا يُنتج مركبين جديدين؛ فالإحلال المزدوج يعني تبادل الأيونات السالبة.","","الوزن هو الخطوة الأخيرة، ولا يمكن وزن المعادلة قبل معرفة صيغ النواتج.","كتابة المعادلة الكاملة تأتي بعد ربط الأيونات وكتابة صيغ النواتج، وليست الخطوة التالية مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.811Z"}'::jsonb),
('mcq', 5, 2, 'يجب أن يتعادل مجموع الشحنات في المركب: 3 أيونات Mg²⁺ تعطي +6، ومجموعتان PO₄³⁻ تعطيان −6، فتكون الصيغة Mg₃(PO₄)₂.', '["هذه الصيغة عكست الأعداد: 2 أيون Mg²⁺ (+4) و3 مجموعات PO₄³⁻ (−9) لا تتعادل؛ والصحيح 3 أيونات Mg²⁺ ومجموعتان PO₄³⁻.","نسبة 1:1 تعطي شحنة +2 و−3 فلا تتعادل الشحنات.","","أُهملت الأقواس حول PO₄؛ فتعني الصيغة وجود ذرة فوسفور واحدة وأربع ذرات أكسجين فقط، ولا تتعادل الشحنات (+6 و−3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.812Z"}'::jsonb),
('mcq', 6, 0, 'يتبادل الأيونان السالبان OH⁻ وSO₄²⁻ موقعيهما: K⁺ مع SO₄²⁻ يعطي K₂SO₄، وH⁺ مع OH⁻ يعطي H₂O. وللوزن يلزم 2KOH وتنتج 2H₂O، فتتساوى الذرات: 2K و6O و4H وS في كل جانب. المعادلة 2KOH + H₂SO₄ → K₂SO₄ + 2H₂O هي الصحيحة.', '["","المعادلة غير موزونة؛ فعدد ذرات K هو 1 في اليسار و2 في اليمين، وعدد ذرات H هو 3 مقابل 2.","ذرات K متزنة، لكن ذرات O (6 في اليسار و5 في اليمين) وH (4 مقابل 2) غير متزنة؛ إذ يلزم 2H₂O.","الصيغة KSO₄ خاطئة؛ فأيون K⁺ (+1) يتعادل مع SO₄²⁻ (−2) بنسبة 2:1 فتكون الصيغة K₂SO₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.812Z"}'::jsonb),
('mcq', 7, 3, 'صيغتا الناتجين CaCO₃ وNaCl صحيحتان، لكن ذرات Na وCl غير متزنة (2 في اليسار و1 في اليمين)، فيلزم المعامل 2 أمام NaCl لتصبح المعادلة: CaCl₂ + Na₂CO₃ → CaCO₃ + 2NaCl.', '["الصيغة CaCO₃ صحيحة؛ إذ يتعادل Ca²⁺ مع CO₃²⁻ بنسبة 1:1.","الأيونات تبادلت مواقعها فعلًا: ارتبط Ca²⁺ مع CO₃²⁻ وارتبط Na⁺ مع Cl⁻.","نواتج الإحلال المزدوج مركبان مختلفان، أحدهما راسب أو ماء أو غاز، وليست عناصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.812Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأيونات: في FeCl₃ يوجد Fe³⁺ وCl⁻، وفي NaOH يوجد Na⁺ وOH⁻. يرتبط Fe³⁺ مع OH⁻ فتكون صيغة الناتج Fe(OH)₃، ويرتبط Na⁺ مع Cl⁻ فتكون صيغته NaCl. المعادلة غير الموزونة: FeCl₃ + NaOH → Fe(OH)₃ + NaCl. للوزن نضع المعامل 3 أمام NaOH وأمام NaCl: FeCl₃ + 3NaOH → Fe(OH)₃ + 3NaCl، وفي كل جانب ذرة Fe و3 ذرات Cl و3 ذرات Na و3 ذرات O و3 ذرات H.', '["تعيين الأيونات: Fe³⁺ وCl⁻ وNa⁺ وOH⁻","ربط كل أيون موجب بالأيون السالب في المركب الآخر وكتابة الصيغتين Fe(OH)₃ وNaCl","كتابة المعادلة غير الموزونة FeCl₃ + NaOH → Fe(OH)₃ + NaCl","وزن المعادلة: FeCl₃ + 3NaOH → Fe(OH)₃ + 3NaCl"]'::jsonb, '["اكتب صيغتي المتفاعلين: FeCl₃ وNaOH","عيّن الأيونات: Fe³⁺ وCl⁻ في الأول، وNa⁺ وOH⁻ في الثاني","اربط Fe³⁺ مع OH⁻ وNa⁺ مع Cl⁻، واكتب الصيغتين بتعادل الشحنات: Fe(OH)₃ وNaCl","اكتب المعادلة الكاملة: FeCl₃ + NaOH → Fe(OH)₃ + NaCl","زن المعادلة: FeCl₃ + 3NaOH → Fe(OH)₃ + 3NaCl"]'::jsonb, '[{"element":"تعيين الأيونات الأربعة بشحناتها","marks":1},{"element":"كتابة صيغتي الناتجين Fe(OH)₃ وNaCl","marks":2},{"element":"المعادلة الموزونة FeCl₃ + 3NaOH → Fe(OH)₃ + 3NaCl","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعيين الأيونات صحيح، والصيغتان صحيحتان، والمعادلة موزونة بأصغر المعاملات"},{"level":"3–4 درجات","description":"الأيونات والصيغتان صحيحة مع خطأ في الوزن، أو معادلة موزونة بلا إظهار الخطوات"},{"level":"1–2 درجة","description":"تعيين الأيونات أو كتابة إحدى الصيغتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Fe(OH) بدل Fe(OH)₃ لإهمال شحنة الحديد +3","كتابة معادلة غير موزونة FeCl₃ + NaOH → Fe(OH)₃ + NaCl","ربط Fe³⁺ مع Cl⁻ مرة أخرى فلا يحدث تبادل للأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.812Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يرتبط Pb²⁺ مع I⁻ فينتج PbI₂، ويرتبط K⁺ مع NO₃⁻ فينتج KNO₃. المعادلة الموزونة: Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃. (b) يرتبط H⁺ مع OH⁻ فينتج H₂O، ويرتبط Ca²⁺ مع NO₃⁻ فينتج Ca(NO₃)₂. المعادلة الموزونة: 2HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2H₂O.', '["(a) الصيغتان PbI₂ وKNO₃","(a) المعادلة الموزونة: Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃","(b) الصيغتان Ca(NO₃)₂ وH₂O","(b) المعادلة الموزونة: 2HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2H₂O"]'::jsonb, '["(a) اربط Pb²⁺ مع I⁻ وK⁺ مع NO₃⁻، ثم اكتب Pb(NO₃)₂ + KI → PbI₂ + KNO₃","(a) زن النيترات والبوتاسيوم: Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃","(b) اربط H⁺ مع OH⁻ وCa²⁺ مع NO₃⁻، ثم اكتب HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + H₂O","(b) زن الهيدروجين والأكسجين والنيترات: 2HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2H₂O"]'::jsonb, '[{"element":"(a) صيغتا الناتجين صحيحتان","marks":1},{"element":"(a) المعادلة موزونة","marks":2},{"element":"(b) صيغتا الناتجين صحيحتان","marks":1},{"element":"(b) المعادلة موزونة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الصيغ الأربع صحيحة والمعادلتان موزونتان"},{"level":"4–5 درجات","description":"الصيغ صحيحة مع خطأ وزن في إحدى المعادلتين"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة وموزونة، أو الصيغ صحيحة دون وزن"},{"level":"1 درجة","description":"صيغة ناتج واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة PbI بدل PbI₂ لأن شحنة الرصاص +2 وشحنة اليود −1","نسيان المعامل 2 أمام H₂O في (b)","عدم موازنة مجموعة NO₃ بوصفها وحدة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.812Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) صيغة AlSO₄ خاطئة لأن Al³⁺ (+3) لا يتعادل مع SO₄²⁻ (−2) بنسبة 1:1؛ والصيغة NaCl₂ خاطئة لأن Na⁺ (+1) يتعادل مع Cl⁻ (−1) بنسبة 1:1. (b) تعادل الشحنات يتطلب 2 أيون Al³⁺ (+6) و3 مجموعات SO₄²⁻ (−6) فتكون الصيغة Al₂(SO₄)₃، وتكون صيغة الثاني NaCl. المعادلة غير الموزونة: AlCl₃ + Na₂SO₄ → Al₂(SO₄)₃ + NaCl، والموزونة: 2AlCl₃ + 3Na₂SO₄ → Al₂(SO₄)₃ + 6NaCl. (c) لأن تغيير الأدلة يغيّر المركب نفسه ويحوّله إلى مادة أخرى، أما تغيير المعاملات فيغيّر كميات المواد فقط دون تغيير هويتها.', '["(a) AlSO₄ خاطئة لعدم تعادل الشحنات (+3 و−2)","(a) NaCl₂ خاطئة؛ الصحيحة NaCl لأن شحنتي Na⁺ وCl⁻ متساويتان","(b) الصيغتان الصحيحتان Al₂(SO₄)₃ وNaCl","(b) المعادلة الموزونة: 2AlCl₃ + 3Na₂SO₄ → Al₂(SO₄)₃ + 6NaCl","(c) تغيير الأدلة يغيّر هوية المركب، والاتزان يتحقق بالمعاملات فقط"]'::jsonb, '["اكتب شحنات الأيونات واجعل مجموع الشحنات في كل مركب صفرًا: Al³⁺ مع SO₄²⁻ يعطي Al₂(SO₄)₃، وNa⁺ مع Cl⁻ يعطي NaCl","اكتب المعادلة: AlCl₃ + Na₂SO₄ → Al₂(SO₄)₃ + NaCl","زن الألومنيوم بوضع المعامل 2 أمام AlCl₃، وزن الكبريتات بوضع المعامل 3 أمام Na₂SO₄","زن الكلور والصوديوم بوضع المعامل 6 أمام NaCl، ثم تحقق من تساوي عدد الذرات في الطرفين"]'::jsonb, '[{"element":"تحديد خطأ AlSO₄ مع التعليل بالشحنات","marks":1},{"element":"تحديد خطأ NaCl₂ مع التعليل بالشحنات","marks":1},{"element":"كتابة الصيغتين الصحيحتين Al₂(SO₄)₃ وNaCl","marks":2},{"element":"المعادلة الموزونة","marks":2},{"element":"تفسير عدم جواز تغيير الأدلة","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"تحديد الخطأين بالتعليل الصحيح، والصيغتان صحيحتان، والمعادلة موزونة، وتفسير صحيح لعدم تغيير الأدلة"},{"level":"5–6 درجات","description":"الصيغتان والمعادلة صحيحة مع نقص في التعليل أو في التفسير"},{"level":"3–4 درجات","description":"الصيغتان صحيحتان مع خطأ في الوزن، أو وزن صحيح لصيغ غير صحيحة"},{"level":"1–2 درجة","description":"تحديد أحد الخطأين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Al₂SO₄ أو Al(SO₄) دون تعادل الشحنات","وزن المعادلة بتغيير الأدلة داخل الصيغ","وضع المعامل 2 أمام NaCl فقط دون موازنة Al وSO₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.813Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
