insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ المعادلات الآتية تمثل تفاعل تكوين موزونًا؟', null, '["Mg + O₂ → MgO","2Mg + O₂ → 2MgO","2Mg + O₂ → 2MgO₂","2MgO → 2Mg + O₂"]'::jsonb, 'فهم', 'تمييز معادلة تكوين موزونة', 'سهل', 'الكتاب ص 123 — تفاعلات التكوين (A + B → AB)'),
('mcq', 2, 'يتفاعل البورون B مع غاز الفلور F₂ لتكوين مركب واحد. ما صيغة هذا المركب علمًا بأن أيون البورون B³⁺ وأيون الفلور F⁻؟', null, '["BF","B₃F","B₂F₃","BF₃"]'::jsonb, 'تطبيق', 'كتابة صيغة ناتج التكوين', 'سهل', 'الكتاب ص 147 — السؤال 83: تفاعلات التكوين (بورون + فلور)'),
('mcq', 3, 'يتفاعل الألومنيوم الصلب مع الكبريت الصلب لتكوين كبريتيد الألومنيوم، علمًا بأن أيون الألومنيوم Al³⁺ وأيون الكبريتيد S²⁻. ما المعادلة الرمزية الموزونة لهذا التفاعل؟', null, '["2Al + 3S → Al₂S₃","Al + S → AlS","2Al + 3S → Al₃S₂","3Al + 2S → Al₂S₃"]'::jsonb, 'تطبيق', 'كتابة معادلة تكوين موزونة', 'متوسط', 'الكتاب ص 125 — المسألة التدريبية 18 (الألومنيوم والكبريت)'),
('mcq', 4, 'يتفاعل غاز ثاني أكسيد النيتروجين NO₂ مع غاز الأكسجين O₂ لتكوين غاز خامس أكسيد ثنائي النيتروجين N₂O₅. ما معامل NO₂ في المعادلة الموزونة بأصغر معاملات صحيحة؟', null, '["1","2","4","5"]'::jsonb, 'تطبيق', 'تحديد معامل في معادلة تكوين', 'صعب', 'الكتاب ص 125 — المسألة التدريبية 20'),
('mcq', 5, 'أيّ المتفاعلين الآتيين يكوّنان كلوريد الليثيوم LiCl بتفاعل تكوين من عنصريه؟', null, '["Li₂(s) و Cl₂(g)","Li(s) و Cl(g)","Li(s) و Cl⁻(aq)","Li(s) و Cl₂(g)"]'::jsonb, 'تطبيق', 'تحديد متفاعلات تفاعل تكوين', 'متوسط', 'الكتاب ص 123 — تفاعل عنصرين هو دائمًا تكوين (الصوديوم والكلور)'),
('mcq', 6, 'كتب طالب معادلة تكوين فلوريد الليثيوم من عنصريه على النحو: 2Li + F₂ → 2LiF₂. ما الخطأ في هذه المعادلة؟', null, '["يجب كتابة الفلور بالرمز F لا F₂ لأنه عنصر","صيغة الناتج خاطئة؛ فأيون Li⁺ يتعادل مع F⁻ بنسبة 1:1 وصيغته LiF","تفاعل عنصرين ينتج دائمًا عنصرين جديدين لا مركبًا","يجب وضع المعامل 3 أمام الليثيوم"]'::jsonb, 'تحليل', 'تحليل خطأ في معادلة تكوين', 'صعب', 'الكتاب ص 123، 125 — تفاعل عنصرين هو دائمًا تكوين'),
('mcq', 7, 'ما المعادلة الرمزية الموزونة لتفاعل المغنسيوم الصلب مع غاز النيتروجين لتكوين نيتريد المغنسيوم الصلب Mg₃N₂؟', null, '["Mg(s) + N₂(g) → Mg₃N₂(s)","3Mg(s) + 2N(g) → Mg₃N₂(s)","3Mg(s) + N₂(g) → Mg₃N₂(s)","3Mg(s) + N₂(g) → 3MgN₂(s)"]'::jsonb, 'تطبيق', 'كتابة معادلة تكوين موزونة بالحالات', 'متوسط', 'الكتاب ص 123، 147 — تفاعل عنصرين هو دائمًا تكوين (المسألتان 76 و83)'),
('essay', 1, 'اكتب معادلة رمزية موزونة لكل تفاعل من تفاعلات التكوين الآتية:
(a) الليثيوم الصلب مع غاز النيتروجين لإنتاج نيتريد الليثيوم الصلب (علمًا بأن أيون الليثيوم Li⁺ وأيون النيتريد N³⁻).
(b) أكسيد الكالسيوم الصلب CaO مع الماء السائل لإنتاج هيدروكسيد الكالسيوم الصلب Ca(OH)₂.
(c) غاز ثاني أكسيد الكبريت SO₂ مع غاز الأكسجين لإنتاج غاز ثالث أكسيد الكبريت SO₃.', null, null, 'تطبيق', 'كتابة معادلات تكوين موزونة', 'متوسط', 'الكتاب ص 123، 125 — أنواع تفاعلات التكوين'),
('essay', 2, 'اكتب معادلة رمزية موزونة لتفاعل المغنسيوم الصلب مع غاز الفلور لإنتاج فلوريد المغنسيوم الصلب (علمًا بأن Mg²⁺ وF⁻)، ثم وضّح لماذا يُصنّف هذا التفاعل تفاعل تكوين.', null, null, 'فهم', 'كتابة معادلة تكوين وتعليل التصنيف', 'سهل', 'الكتاب ص 123 — تفاعلات التكوين'),
('essay', 3, '(a) اكتب معادلة رمزية موزونة لتفاعل تكوين البوتاسيوم الصلب مع سائل البروم Br₂ لإنتاج بروميد البوتاسيوم الصلب.
(b) اكتب معادلة رمزية موزونة لتفاعل أكسيد الصوديوم الصلب Na₂O مع الماء لإنتاج هيدروكسيد الصوديوم NaOH.
(c) فسّر لماذا يُعدّ تفاعل 2H₂ + O₂ → 2H₂O تفاعل تكوين، في حين لا يُعدّ تفاعل CH₄ + 2O₂ → CO₂ + 2H₂O تفاعل تكوين.', null, null, 'تحليل', 'كتابة معادلات تكوين وتحليل التصنيف', 'صعب', 'الكتاب ص 123، 125 — تفاعلات التكوين وعلاقتها بالاحتراق')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
