from (values
('mcq', 1, 1, 'تفاعل التكوين تتحد فيه مادتان أو أكثر لتكوين مادة واحدة (A + B → AB). المعادلة 2Mg + O₂ → 2MgO تجمع الماغنسيوم والأكسجين في ناتج واحد هو MgO، وذرات كل عنصر متساوية في الطرفين (2Mg و2O).', '["هذه معادلة تكوين لكنها غير موزونة؛ فعدد ذرات Mg وO غير متساوٍ في الطرفين.","","صيغة MgO₂ خاطئة؛ فأيون Mg²⁺ يتعادل مع O²⁻ بنسبة 1:1 فصيغته MgO.","هذه معادلة تفكك وليست تكوينًا؛ فمركب واحد يتفكك إلى عنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.813Z"}'::jsonb),
('mcq', 2, 3, 'لتتعادل الشحنات يلزم أيون B³⁺ (+3) مع ثلاثة أيونات F⁻ (−3)، فتكون صيغة المركب BF₃.', '["نسبة 1:1 تعطي شحنة +3 و−1 فلا تتعادل الشحنات.","الصيغة غير متعادلة؛ فشحنتها الكلية +9 و−1، وأيون B³⁺ الواحد يحتاج إلى ثلاثة أيونات F⁻ لا العكس.","الصيغة غير متعادلة؛ فشحنتها الكلية +6 و−3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.814Z"}'::jsonb),
('mcq', 3, 0, 'لتتعادل الشحنات تتحد 2 من Al³⁺ (+6) مع 3 من S²⁻ (−6) فتكون الصيغة Al₂S₃. وتصبح المعادلة 2Al + 3S → Al₂S₃، وفي كل طرف ذرتا Al وثلاث ذرات S.', '["","الصيغة AlS خاطئة لأن الشحنتين +3 و−2 لا تتعادلان بنسبة 1:1.","الصيغة Al₃S₂ عكست الأعداد في الصيغة الصحيحة Al₂S₃.","الصيغة صحيحة لكن المعاملين تبادلا موقعيهما؛ فعدد ذرات Al (3 في اليسار و2 في اليمين) وS (2 مقابل 3) غير متساوٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.814Z"}'::jsonb),
('mcq', 4, 2, 'المعادلة غير الموزونة NO₂ + O₂ → N₂O₅. لتتزن ذرات N يلزم معاملان للنيتروجين؛ وبعد ضبط الأكسجين تصبح الموزونة 4NO₂ + O₂ → 2N₂O₅: في كل طرف 4 ذرات N و10 ذرات O. فمعامل NO₂ يساوي 4.', '["المعامل 1 يمثل المعادلة غير الموزونة؛ إذ توجد ذرة N في اليسار وذرتان في اليمين.","المعامل 2 يوازن ذرات النيتروجين فقط، لكنه لا يوازن الأكسجين (6 ذرات في اليسار و5 في اليمين).","","الرقم 5 هو الرقم السفلي لذرات الأكسجين في N₂O₅، وليس معاملًا يوازن المعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.814Z"}'::jsonb),
('mcq', 5, 3, 'يتكون LiCl من اتحاد عنصر الليثيوم (فلز صلب يُكتب Li) وعنصر الكلور الذي يوجد في صورة جزيئات ثنائية الذرة Cl₂. والمعادلة: 2Li + Cl₂ → 2LiCl.', '["الليثيوم فلز يُكتب بالرمز Li ولا يُكتب Li₂؛ فالفلزات لا توجد على هيئة جزيئات ثنائية.","الكلور عنصر ثنائي الذرة في حالته الحرة فيُكتب Cl₂ لا Cl.","Cl⁻ أيون وليس العنصر الحر؛ والعنصر هو Cl₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.814Z"}'::jsonb),
('mcq', 6, 1, 'الخطأ في صيغة الناتج: شحنة Li⁺ تساوي +1 وشحنة F⁻ تساوي −1، فيتعادلان بنسبة 1:1 وتكون الصيغة LiF. والمعادلة الصحيحة 2Li + F₂ → 2LiF، فيها ذرتا Li وذرتا F في كل طرف.', '["الفلور عنصر ثنائي الذرة في حالته الحرة، فكتابته F₂ صحيحة.","","تفاعل عنصرين هو دائمًا تفاعل تكوين، وينتج مركبًا واحدًا لا عنصرين.","المعامل 2 أمام Li صحيح؛ فالمعاملان 2Li وF₂ يوازنان المعادلة متى كانت صيغة الناتج LiF."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.814Z"}'::jsonb),
('mcq', 7, 2, 'يتحد 3 ذرات Mg مع جزيء N₂ (ذرتا نيتروجين) لتكوين وحدة Mg₃N₂، فتتساوى الذرات في الطرفين (3Mg و2N). المعادلة الموزونة هي 3Mg(s) + N₂(g) → Mg₃N₂(s).', '["المعادلة غير موزونة؛ فعدد ذرات Mg هو 1 في اليسار و3 في اليمين.","الذرات متساوية لكن النيتروجين الحر ثنائي الذرة ويُكتب N₂ لا N.","","الصيغة 3MgN₂ تغيّر صيغة المركب؛ فالناتج الصحيح Mg₃N₂، ولا تتساوى ذرات N (2 في اليسار و6 في اليمين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.815Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) تتعادل الشحنات بثلاثة أيونات Li⁺ لكل أيون N³⁻، فصيغة النيتريد Li₃N، والمعادلة الموزونة: 6Li(s) + N₂(g) → 2Li₃N(s). (b) CaO(s) + H₂O(l) → Ca(OH)₂(s)، وهي موزونة أصلًا (ذرة Ca وذرتا H وذرتا O في كل طرف). (c) 2SO₂(g) + O₂(g) → 2SO₃(g)؛ فيه 2S و6O في كل طرف.', '["(a) صيغة نيتريد الليثيوم Li₃N","(a) 6Li + N₂ → 2Li₃N","(b) CaO + H₂O → Ca(OH)₂","(c) 2SO₂ + O₂ → 2SO₃"]'::jsonb, '["(a) اكتب صيغة الناتج بتعادل الشحنات: Li₃N، ثم Li + N₂ → Li₃N","(a) زن النيتروجين بالمعامل 2 أمام Li₃N، ثم زن الليثيوم بالمعامل 6: 6Li + N₂ → 2Li₃N","(b) تحقق من تساوي الذرات: CaO + H₂O → Ca(OH)₂ موزونة","(c) زن الأكسجين: 2SO₂ + O₂ → 2SO₃"]'::jsonb, '[{"element":"(a) صيغة Li₃N صحيحة","marks":1},{"element":"(a) المعادلة موزونة","marks":1},{"element":"(b) المعادلة صحيحة وموزونة","marks":1},{"element":"(c) المعادلة صحيحة وموزونة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"المعادلات الثلاث صحيحة وموزونة وصيغة Li₃N صحيحة"},{"level":"3–4 درجات","description":"معادلتان صحيحتان، أو الصيغ الثلاث صحيحة مع خطأ في وزن إحداها"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو صيغة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Li₂N أو LiN لعدم تعادل الشحنات","كتابة النيتروجين N بدل N₂ أو الأكسجين O بدل O₂","كتابة SO₂ + O₂ → SO₃ دون وزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.815Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تتعادل الشحنات بأيون Mg²⁺ واحد وأيونين F⁻، فصيغة الناتج MgF₂، والمعادلة الموزونة: Mg(s) + F₂(g) → MgF₂(s). يُصنّف التفاعل تكوينًا لأن مادتين (عنصر الماغنسيوم وعنصر الفلور) تتحدان لتكوين مادة واحدة هي MgF₂، على نمط A + B → AB، وتفاعل عنصرين هو دائمًا تفاعل تكوين.', '["صيغة الناتج MgF₂","المعادلة الموزونة Mg + F₂ → MgF₂","التعليل: اتحاد مادتين لتكوين مادة واحدة (A + B → AB)"]'::jsonb, '["اكتب صيغة الناتج بتعادل الشحنات: Mg²⁺ مع 2F⁻ يعطي MgF₂","اكتب المعادلة: Mg + F₂ → MgF₂، وتحقق من تساوي الذرات (Mg وF₂ في كل طرف)","اربط المعادلة بالصيغة العامة A + B → AB"]'::jsonb, '[{"element":"صيغة الناتج MgF₂","marks":1},{"element":"المعادلة الموزونة","marks":1},{"element":"التعليل بأن مادتين تتحدان لتكوين مادة واحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"صيغة صحيحة ومعادلة موزونة وتعليل صحيح"},{"level":"2 درجتان","description":"عنصران من العناصر الثلاثة صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة MgF بدل MgF₂","كتابة الفلور F بدل F₂","تصنيف التفاعل تفككًا أو إحلالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.816Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) أيون K⁺ وأيون Br⁻ يتعادلان بنسبة 1:1 فالناتج KBr، والمعادلة: 2K(s) + Br₂(l) → 2KBr(s). (b) Na₂O + H₂O → 2NaOH؛ في كل طرف ذرتا Na وذرتا H وذرتا O. (c) يُعدّ تفاعل الهيدروجين مع الأكسجين تكوينًا لأن مادتين تتحدان لتنتجا مركبًا واحدًا هو H₂O، أما احتراق الميثان فينتج مركبين مختلفين (CO₂ وH₂O) وليس مادة واحدة، فلا يطابق الصيغة A + B → AB.', '["(a) 2K + Br₂ → 2KBr","(b) Na₂O + H₂O → 2NaOH","(c) تفاعل التكوين ينتج مادة واحدة (H₂O)","(c) احتراق الميثان ينتج مركبين فلا يُعدّ تكوينًا"]'::jsonb, '["(a) اكتب KBr بتعادل الشحنات، ثم زن البروم الثنائي بالمعامل 2 أمام KBr وأمام K","(b) اكتب NaOH ثم زن الصوديوم بالمعامل 2: Na₂O + H₂O → 2NaOH","(c) عدّ نواتج كل تفاعل وقارنها بالصيغة A + B → AB"]'::jsonb, '[{"element":"(a) معادلة صحيحة وموزونة","marks":2},{"element":"(b) معادلة صحيحة وموزونة","marks":2},{"element":"(c) تفسير سبب الاختلاف بعدد النواتج","marks":3}]'::jsonb, '[{"level":"7 درجات","description":"المعادلتان صحيحتان وموزونتان، والتفسير يقارن عدد النواتج ويربطه بالصيغة A + B → AB"},{"level":"5–6 درجات","description":"المعادلتان صحيحتان مع تفسير ناقص، أو تفسير كامل مع خطأ وزن واحد"},{"level":"3–4 درجات","description":"معادلة واحدة صحيحة مع تفسير جزئي، أو التفسير كامل فقط"},{"level":"1–2 درجة","description":"ذكر أحد العناصر المطلوبة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة KBr₂ أو K₂Br","نسيان المعامل 2 أمام NaOH","اعتبار كل تفاعل يشارك فيه الأكسجين تكوينًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.816Z"}'::jsonb)
