select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تحتوي الهيدروكربونات على الكربون والهيدروجين فقط، وعند احتراقها في الأكسجين يتحد الكربون معه فيتكون ثاني أكسيد الكربون CO₂، ويتحد الهيدروجين معه فيتكون الماء H₂O، مع انطلاق كمية كبيرة من الطاقة.', '["","الهيدروجين يتحد مع الأكسجين فيعطي الماء، ولا يبقى غازًا حرًا؛ كما أن أول أكسيد الكربون ليس ناتج الاحتراق الكامل.","الكربون يتحد مع الأكسجين فيعطي أكسيدًا هو CO₂، ولا يبقى عنصرًا حرًا في ناتج الاحتراق الكامل.","الهيدروجين يتحد مع الأكسجين وينتج الماء، ولا ينتج غاز الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 2, 3, 'في تفاعل الاحتراق يتحد الأكسجين مع مادة كيميائية مطلقًا طاقة على شكل حرارة وضوء. والزوج CH₄ وO₂ يحتوي على الأكسجين، فهو متفاعلات احتراق ينتج عنه CO₂ وH₂O.', '["NaOH وHCl متفاعلات إحلال مزدوج (تعادل)، ولا يوجد فيها غاز الأكسجين.","H₂ وCl₂ متفاعلان لتفاعل تكوين ينتج HCl، ولا يشارك فيه الأكسجين.","Zn وCuSO₄ متفاعلات إحلال بسيط، ولا يشارك فيها الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 3, 1, 'المعادلة الموزونة: C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. في الطرف الأيمن 3×2 + 4 = 10 ذرات أكسجين، أي 5 جزيئات O₂؛ فالمعامل 5.', '["المعامل 3 يوازن ذرات الكربون في CO₂ فقط، ولا يوازن الأكسجين في الطرفين.","","الرقم 7 هو مجموع معاملي CO₂ وH₂O (3 + 4) وليس عدد جزيئات الأكسجين اللازمة.","الرقم 10 هو عدد ذرات الأكسجين في النواتج؛ وجزيء O₂ يحتوي ذرتين، فيلزم 5 جزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 4, 2, 'لكل جزيء C₄H₁₀ يلزم 4×2 + 5 = 13 ذرة أكسجين، أي 6.5 جزيء O₂. وللحصول على معاملات صحيحة تُضرب المعادلة في 2: 2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O؛ فمعامل O₂ يساوي 13.', '["المعامل 6.5 يوازن معادلة 1C₄H₁₀ لكنه ليس عددًا صحيحًا؛ والمعاملات الصحيحة تتطلب مضاعفة المعادلة.","الرقم 9 ناتج جمع 4 جزيئات CO₂ و5 جزيئات H₂O من احتراق جزيء واحد، وهو لا يمثل عدد جزيئات الأكسجين اللازمة.","","26 هو عدد ذرات الأكسجين في النواتج (16 + 10)؛ وجزيء O₂ فيه ذرتان فيلزم نصف هذا العدد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 5, 0, 'يحتوي الجزيء CH₃OH على ذرة C و4 ذرات H وذرة O. لإنتاج CO₂ وH₂O تتساوى الذرات في المعادلة 2CH₃OH + 3O₂ → 2CO₂ + 4H₂O: في كل طرف 2C و8H و8O.', '["","المعادلة غير موزونة؛ فعدد ذرات H هو 4 في اليسار و2 في اليمين.","ذرات C وH متزنة (1C و4H) لكن الأكسجين غير متزن (5 ذرات في اليسار و4 في اليمين).","ذرات C متزنة لكن H (8 في اليسار و4 في اليمين) وO (8 مقابل 6) غير متزنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 6, 1, 'تفاعل التكوين ينتج مادة واحدة (A + B → AB). تفاعلات C وH₂ وMg مع الأكسجين تنتج مركبًا واحدًا فهي احتراق وتكوين معًا، أما احتراق الميثان فينتج مركبين هما CO₂ وH₂O، فهو احتراق فقط.', '["يتحد الكربون مع الأكسجين لتكوين مركب واحد هو CO₂، فهو احتراق وتكوين معًا.","","يتحد الهيدروجين مع الأكسجين لتكوين مركب واحد هو H₂O، فهو احتراق وتكوين معًا.","يتحد الماغنسيوم مع الأكسجين لتكوين مركب واحد هو MgO، فهو احتراق وتكوين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.817Z"}'::jsonb),
('mcq', 7, 3, 'يحتوي ناتج واحد B₂O₃ على ذرتي B و3 ذرات O. لتساوي الذرات مع O₂ نضاعف: 4B + 3O₂ → 2B₂O₃؛ في كل طرف 4 ذرات B و6 ذرات O.', '["الأكسجين الحر جزيء ثنائي الذرة يُكتب O₂، ولا يُكتب O.","المعادلة غير موزونة؛ فعدد ذرات B (1 في اليسار و2 في اليمين) وO (2 مقابل 3) غير متساوٍ.","الصيغة BO خاطئة؛ فالناتج المعطى في السؤال هو B₂O₃ (أيون B³⁺ مع O²⁻).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.818Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) 2Ba + O₂ → 2BaO. (b) 2C₈H₁₈ + 25O₂ → 16CO₂ + 18H₂O؛ فلكل جزيء أوكتان 8×2 + 9 = 25 ذرة أكسجين أي 12.5 جزيء O₂، ولذلك تُضاعف المعادلة. (c) C₃H₆O + 4O₂ → 3CO₂ + 3H₂O؛ في اليمين 6 + 3 = 9 ذرات أكسجين، وفي اليسار ذرة واحدة من الأسيتون و8 ذرات من 4O₂.', '["(a) 2Ba + O₂ → 2BaO","(b) 2C₈H₁₈ + 25O₂ → 16CO₂ + 18H₂O","(c) C₃H₆O + 4O₂ → 3CO₂ + 3H₂O"]'::jsonb, '["(a) اكتب Ba + O₂ → BaO ثم زن الأكسجين بالمعامل 2 أمام BaO ثم الباريوم بالمعامل 2","(b) زن الكربون: 8CO₂، وزن الهيدروجين: 9H₂O، ثم احسب ذرات الأكسجين (25) فيلزم 12.5O₂","(b) اضرب المعادلة في 2 للحصول على معاملات صحيحة","(c) زن الكربون: 3CO₂، والهيدروجين: 3H₂O، ثم الأكسجين: 4O₂"]'::jsonb, '[{"element":"(a) معادلة صحيحة وموزونة","marks":2},{"element":"(b) معادلة صحيحة وموزونة بمعاملات صحيحة","marks":3},{"element":"(c) معادلة صحيحة وموزونة","marks":2}]'::jsonb, '[{"level":"7 درجات","description":"المعادلات الثلاث صحيحة وموزونة بأصغر معاملات صحيحة"},{"level":"5–6 درجات","description":"معادلتان صحيحتان وموزونتان وخطأ في الثالثة"},{"level":"3–4 درجات","description":"معادلة واحدة صحيحة، أو نواتج صحيحة دون وزن"},{"level":"1–2 درجة","description":"كتابة نواتج إحدى المعادلات صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترك المعامل 12.5 أمام O₂ دون تحويل المعادلة إلى معاملات صحيحة","كتابة O بدل O₂ في المتفاعلات","كتابة CO بدل CO₂ في نواتج الاحتراق الكامل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.818Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة غير الموزونة: C₂H₆O + O₂ → CO₂ + H₂O. نوازن الكربون بوضع 2 أمام CO₂، ثم الهيدروجين بوضع 3 أمام H₂O، فيصبح في اليمين 4 + 3 = 7 ذرات أكسجين. يحتوي الإيثانول على ذرة أكسجين واحدة، فيلزم 6 ذرات من O₂ أي 3O₂. المعادلة الموزونة: C₂H₆O + 3O₂ → 2CO₂ + 3H₂O.', '["كتابة صيغ النواتج CO₂ وH₂O","موازنة الكربون والهيدروجين أولًا","موازنة الأكسجين أخيرًا بالمعامل 3","المعادلة: C₂H₆O + 3O₂ → 2CO₂ + 3H₂O"]'::jsonb, '["اكتب المعادلة: C₂H₆O + O₂ → CO₂ + H₂O","زن الكربون: 2CO₂","زن الهيدروجين: 3H₂O","عدّ ذرات الأكسجين في اليمين (7) واطرح ذرة الإيثانول (1) يبقى 6 ذرات فيلزم 3O₂"]'::jsonb, '[{"element":"صيغ المتفاعلات والنواتج صحيحة","marks":1},{"element":"موازنة الكربون والهيدروجين","marks":1},{"element":"موازنة الأكسجين","marks":1},{"element":"المعادلة النهائية صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات مرتبة والمعادلة النهائية موزونة"},{"level":"3 درجات","description":"المعادلة النهائية صحيحة مع نقص في توضيح الخطوات"},{"level":"1–2 درجة","description":"نواتج صحيحة مع خطأ في وزن الأكسجين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال ذرة الأكسجين الموجودة في الإيثانول عند حساب الأكسجين اللازم","كتابة 4O₂ بدل 3O₂","موازنة الأكسجين قبل الكربون والهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.818Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) C₂H₄ + 3O₂ → 2CO₂ + 2H₂O؛ في كل طرف 2C و4H و6O. (b) لأن الأكسجين يتحد مع مادة (الإيثين) مطلقًا طاقة على شكل حرارة وضوء. (c) تفاعل التكوين ينتج مادة واحدة (A + B → AB)، أما احتراق الإيثين فينتج مركبين هما CO₂ وH₂O فلا يُعدّ تكوينًا؛ بينما يتحد الماغنسيوم مع الأكسجين لإنتاج مركب واحد هو MgO فهو احتراق وتكوين معًا.', '["(a) C₂H₄ + 3O₂ → 2CO₂ + 2H₂O","(b) اتحاد الأكسجين مع مادة مع انطلاق طاقة (حرارة وضوء)","(c) احتراق الإيثين ينتج مركبين فلا يُعدّ تكوينًا","(c) احتراق Mg ينتج مركبًا واحدًا فهو تكوين أيضًا"]'::jsonb, '["(a) زن الكربون: 2CO₂، والهيدروجين: 2H₂O، ثم الأكسجين: عدد ذراته 6 فيلزم 3O₂","(b) اربط التفاعل بتعريف الاحتراق: اتحاد الأكسجين مع مادة وانطلاق طاقة","(c) عدّ نواتج كل تفاعل: ناتجان في احتراق الإيثين وناتج واحد في احتراق Mg"]'::jsonb, '[{"element":"(a) المعادلة صحيحة وموزونة","marks":2},{"element":"(b) التعليل بتعريف الاحتراق","marks":2},{"element":"(c) التمييز بين عدد النواتج في التفاعلين","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلة موزونة، وتعليل الاحتراق صحيح، والتمييز بعدد النواتج صحيح للتفاعلين"},{"level":"4–5 درجات","description":"المعادلة صحيحة مع نقص في أحد التعليلين"},{"level":"2–3 درجات","description":"المعادلة صحيحة دون تعليل، أو تعليل دون معادلة موزونة"},{"level":"1 درجة","description":"ذكر أن الأكسجين يشارك في التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار كل تفاعل يشارك فيه الأكسجين تفاعل تكوين","كتابة 2O₂ بدل 3O₂","إغفال شرط وجود ناتج واحد في تعريف التكوين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.818Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
