from (values
('mcq', 1, 'ما الذي تحتاج إليه تفاعلات التفكك غالبًا لكي تحدث؟', null, '["وجود غاز الأكسجين لإتمام التفاعل","إضافة الماء لإذابة المتفاعل","مصدر للطاقة كالحرارة أو الكهرباء","اتحاد مادتين على الأقل"]'::jsonb, 'تذكر', 'تذكر شروط التفكك', 'سهل', 'الكتاب ص 126 — تفاعلات التفكك'),
('mcq', 2, 'يتحلل يوديد الهيدروجين HI إلى غاز الهيدروجين وغاز اليود. ما المعادلة الرمزية الموزونة لهذا التفاعل؟', null, '["2HI → H₂ + I₂","HI → H + I","HI → H₂ + I₂","2HI → 2H + I₂"]'::jsonb, 'تطبيق', 'كتابة معادلة تفكك موزونة', 'سهل', 'الكتاب ص 147 — السؤال 72: تفكك يوديد الهيدروجين'),
('mcq', 3, 'يتفكك كربونات الصوديوم Na₂CO₃ بالتسخين إلى Na₂O وCO₂. بالمثل، ما نواتج تفكك كربونات الباريوم BaCO₃ بالتسخين؟', null, '["Ba وCO₂","BaO₂ وCO","Ba وC وO₂","BaO وCO₂"]'::jsonb, 'تطبيق', 'توقع نواتج تفكك مركب', 'متوسط', 'الكتاب ص 126، 147 — المسألة 73a والسؤال 85c'),
('mcq', 4, 'يتفكك أكسيد الألومنيوم الصلب Al₂O₃ عندما تسري فيه الكهرباء إلى ألومنيوم صلب وغاز الأكسجين. ما معامل O₂ في المعادلة الموزونة بأصغر معاملات صحيحة؟', null, '["2","3","4","6"]'::jsonb, 'تطبيق', 'تحديد معامل في معادلة تفكك', 'متوسط', 'الكتاب ص 126 — المسألة التدريبية 22'),
('mcq', 5, 'ما ناتجا تفكك بروميد المغنسيوم MgBr₂ إلى عنصريه؟', null, '["Mg(s) و Br₂(l)","Mg(s) و Br(l)","MgBr(s) و Br(l)","Mg₂(s) و Br₂(l)"]'::jsonb, 'تطبيق', 'كتابة ناتجي التفكك', 'متوسط', 'الكتاب ص 147 — السؤال 85a: تفكك بروميد المغنسيوم'),
('mcq', 6, 'عند تسخين كربونات الصوديوم الهيدروجينية الصلبة NaHCO₃ تتكون كربونات الصوديوم الصلبة Na₂CO₃ والماء وغاز ثاني أكسيد الكربون. ما المعادلة الرمزية الموزونة لهذا التفاعل؟', null, '["NaHCO₃ → Na₂CO₃ + H₂O + CO₂","2NaHCO₃ → Na₂CO₃ + 2H₂O + CO₂","2NaHCO₃ → Na₂CO₃ + H₂O + 2CO₂","2NaHCO₃ → Na₂CO₃ + H₂O + CO₂"]'::jsonb, 'تطبيق', 'وزن معادلة تفكك متعددة النواتج', 'صعب', 'الكتاب ص 126 — المسألة التدريبية 24'),
('mcq', 7, 'يتفكك أزيد الصوديوم NaN₃ في أكياس الهواء وفق المعادلة 2NaN₃ → 2Na + 3N₂. كم جزيء N₂ ينتج من تفكك 4 وحدات صيغة من NaN₃ تفككًا تامًا؟', null, '["3","4","6","12"]'::jsonb, 'فهم', 'قراءة معاملات معادلة التفكك', 'صعب', 'الكتاب ص 126 — تفكك أزيد الصوديوم وأكياس الهواء'),
('essay', 1, 'اكتب معادلة رمزية موزونة لكل تفاعل تفكك مما يأتي:
(a) يتفكك الماء السائل إلى غازي الهيدروجين والأكسجين عند مرور الكهرباء فيه.
(b) يتفكك أكسيد الكوبلت II الصلب CoO إلى كوبلت صلب وغاز الأكسجين.
(c) يتفكك كربونات الكالسيوم الصلب CaCO₃ بالتسخين إلى أكسيد الكالسيوم الصلب CaO وغاز ثاني أكسيد الكربون.', null, null, 'تطبيق', 'كتابة معادلات تفكك موزونة', 'متوسط', 'الكتاب ص 126، 147 — المسائل 22–24 والسؤال 85'),
('essay', 2, 'عرّف تفاعل التفكك، واكتب معادلته العامة، ثم اكتب المعادلة الموزونة لتفكك أزيد الصوديوم NaN₃ إلى فلز الصوديوم وغاز النيتروجين، وبيّن فائدة هذا التفاعل في السيارات.', null, null, 'فهم', 'تعريف التفكك وكتابة معادلة', 'سهل', 'الكتاب ص 126 — تفاعلات التفكك وأكياس الهواء'),
('essay', 3, '(a) اكتب معادلة رمزية موزونة لتكوين كلوريد الصوديوم من عنصريه الصوديوم والكلور.
(b) اكتب معادلة رمزية موزونة لتفكك كلوريد الصوديوم المنصهر بالكهرباء إلى عنصريه.
(c) قارن بين الصيغة العامة لكل من التفاعلين.
(d) فسّر لماذا يحتاج تفاعل التفكك عادة إلى مصدر للطاقة.', null, null, 'تحليل', 'مقارنة التكوين والتفكك', 'صعب', 'الكتاب ص 123، 126 — التفكك عكس التكوين')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
