select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تفاعل التفكك يتفكك فيه مركب واحد إلى عنصرين أو أكثر أو إلى مركبات جديدة، وغالبًا ما يحتاج إلى مصدر للطاقة كالحرارة أو الضوء أو الكهرباء لكسر الروابط في المركب.', '["الأكسجين لازم لتفاعل الاحتراق، وليس شرطًا لتفاعل التفكك.","التفكك لا يتطلب إضافة الماء؛ فكثير من تفاعلات التفكك تحدث للمواد الصلبة بالتسخين.","","اتحاد مادتين يميز تفاعل التكوين، أما التفكك فمتفاعله مركب واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-18T03:27:04.819Z"}'::jsonb),
('mcq', 2, 0, 'الهيدروجين واليود عنصران ثنائيا الذرة فيُكتبان H₂ وI₂. وللموازنة نضع المعامل 2 أمام HI فتتساوى الذرات: 2H و2I في كل طرف. المعادلة الصحيحة 2HI → H₂ + I₂.', '["","الهيدروجين واليود في حالتيهما الحرتين جزيئان ثنائيا الذرة، فلا يُكتبان H وI.","المعادلة غير موزونة؛ فعدد ذرات H وI هو 1 في اليسار و2 في اليمين.","الهيدروجين الحر يُكتب H₂ لا H؛ وذرات H (2 في اليسار و2 في اليمين) متساوية عدديًا، لكن الصيغة المكتوبة غير صحيحة للعنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.819Z"}'::jsonb),
('mcq', 3, 3, 'تتفكك الكربونات بالتسخين إلى أكسيد الفلز وغاز ثاني أكسيد الكربون. وبالمثل ينتج من BaCO₃ الناتجان BaO وCO₂، والمعادلة: BaCO₃ → BaO + CO₂.', '["Ba فلز حر لا يتكون بهذه الطريقة؛ فالفلز يبقى في الناتج على صورة أكسيد، ولا تتزن ذرات الأكسجين (3 في اليسار و2 في اليمين).","الصيغتان BaO₂ وCO لا تنتجان من تفكك الكربونات بالتسخين؛ فالأكسيد الناتج هو BaO والغاز هو CO₂.","هذا ينقل التفكك إلى العناصر الثلاثة جميعها، وهو لا يماثل تفكك Na₂CO₃ الذي ينتج أكسيدًا وCO₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.819Z"}'::jsonb),
('mcq', 4, 1, 'المعادلة الموزونة: 2Al₂O₃ → 4Al + 3O₂؛ ففي اليسار 4Al و6O، وفي اليمين 4Al و6O. فمعامل O₂ يساوي 3.', '["المعامل 2 هو معامل Al₂O₃، لا معامل O₂.","","المعامل 4 هو معامل Al، لا معامل O₂.","الرقم 6 هو عدد ذرات الأكسجين في 2Al₂O₃؛ وجزيء O₂ فيه ذرتان فيلزم 3 جزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.820Z"}'::jsonb),
('mcq', 5, 0, 'يتفكك المركب إلى عنصريه: الماغنسيوم فلز يُكتب Mg، والبروم لافلز ثنائي الذرة يُكتب Br₂. والمعادلة الموزونة: MgBr₂ → Mg + Br₂.', '["","البروم في حالته الحرة جزيء ثنائي الذرة، فيُكتب Br₂ لا Br.","MgBr لا ينتج لأن التفكك هنا إلى العنصرين الحرين، وفي MgBr₂ ترتبط ذرة Mg مع ذرتين من Br.","الماغنسيوم فلز يُكتب بذرة واحدة Mg، ولا يتكون منه جزيء Mg₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:27:04.820Z"}'::jsonb),
('mcq', 6, 3, 'يحتوي Na₂CO₃ على ذرتي Na، لذا يلزم 2NaHCO₃ (2Na و2H و2C و6O). في النواتج Na₂CO₃ (2Na و1C و3O) وH₂O (2H وO) وCO₂ (C و2O)، فتتساوى الذرات: 2Na و2H و2C و6O.', '["المعادلة غير موزونة؛ فذرات Na (1 في اليسار و2 في اليمين) وH وC غير متساوية.","ذرات Na متزنة لكن H (2 في اليسار و4 في اليمين) وO غير متزنة؛ إذ يكفي جزيء ماء واحد.","ذرات C (2 في اليسار و3 في اليمين) وO غير متزنة؛ إذ ينتج جزيء CO₂ واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.820Z"}'::jsonb),
('mcq', 7, 2, 'تبيّن المعاملات أن 2 وحدة من NaN₃ تعطي 3 جزيئات N₂. وعند تفكك 4 وحدات (ضعف الكمية) ينتج ضعف العدد، أي 3 × 2 = 6 جزيئات N₂.', '["الرقم 3 هو عدد جزيئات N₂ الناتجة من 2 وحدة فقط، لا من 4 وحدات.","الرقم 4 هو عدد وحدات NaN₃ المتفككة، وليس عدد جزيئات N₂ الناتجة.","","الرقم 12 هو عدد ذرات النيتروجين في 4 وحدات من NaN₃، وكل جزيء N₂ فيه ذرتان فينتج 6 جزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.820Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) 2H₂O(l) → 2H₂(g) + O₂(g). (b) 2CoO(s) → 2Co(s) + O₂(g). (c) CaCO₃(s) → CaO(s) + CO₂(g)، وهي موزونة أصلًا؛ ففي كل طرف ذرة Ca وذرة C و3 ذرات O.', '["(a) 2H₂O → 2H₂ + O₂","(b) 2CoO → 2Co + O₂","(c) CaCO₃ → CaO + CO₂"]'::jsonb, '["(a) اكتب H₂O → H₂ + O₂ ثم زن الأكسجين بالمعامل 2 أمام H₂O ثم الهيدروجين بالمعامل 2 أمام H₂","(b) اكتب CoO → Co + O₂ ثم زن الأكسجين بالمعامل 2 أمام CoO ثم الكوبلت بالمعامل 2 أمام Co","(c) تحقق من تساوي الذرات في CaCO₃ → CaO + CO₂"]'::jsonb, '[{"element":"(a) معادلة صحيحة وموزونة","marks":2},{"element":"(b) معادلة صحيحة وموزونة","marks":2},{"element":"(c) معادلة صحيحة وموزونة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المعادلات الثلاث صحيحة وموزونة"},{"level":"3–4 درجات","description":"معادلتان صحيحتان وموزونتان وخطأ في الثالثة"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو نواتج صحيحة دون وزن"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H وO بدل H₂ وO₂","كتابة H₂O → H₂ + O₂ دون وزن","كتابة نواتج (c) على شكل Ca وC وO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.820Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تفاعل التفكك هو تفاعل يتفكك فيه مركب واحد لإنتاج عنصرين أو أكثر أو مركبات جديدة، وهو عكس تفاعل التكوين، ومعادلته العامة AB → A + B. معادلة تفكك أزيد الصوديوم: 2NaN₃ → 2Na + 3N₂. يُستفاد منه في نفخ أكياس الهواء (الأكياس الواقية) في السيارات؛ إذ يعطي جهاز إشارة كهربائية عند الاصطدام فيتحلل الأزيد وينتج غاز النيتروجين الذي ينفخ الكيس بسرعة.', '["التعريف: مركب واحد ينتج عنصرين أو أكثر أو مركبات جديدة","المعادلة العامة AB → A + B","المعادلة الموزونة 2NaN₃ → 2Na + 3N₂","الاستفادة منه: غاز النيتروجين الناتج ينفخ أكياس الهواء"]'::jsonb, '["اكتب NaN₃ → Na + N₂","زن النيتروجين: 3N₂ و2NaN₃ لأن 6 ذرات N","زن الصوديوم: 2Na"]'::jsonb, '[{"element":"تعريف تفاعل التفكك","marks":1},{"element":"المعادلة العامة AB → A + B","marks":1},{"element":"المعادلة الموزونة للأزيد","marks":1},{"element":"فائدة التفاعل في أكياس الهواء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريف والمعادلة العامة والمعادلة الموزونة والفائدة صحيحة"},{"level":"3 درجات","description":"ثلاثة من العناصر الأربعة صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة NaN₃ → Na + N₃ أو NaN₃ → Na + N₂ دون وزن","الخلط بين التفكك والتكوين في الصيغة العامة","الظن أن التفكك يحتاج إلى مادتين متفاعلتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.821Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) 2Na + Cl₂ → 2NaCl. (b) 2NaCl → 2Na + Cl₂. (c) التكوين A + B → AB تتحد فيه مادتان لتكوين مادة واحدة، والتفكك AB → A + B يتفكك فيه مركب واحد إلى مادتين؛ فأحدهما عكس الآخر. (d) لأن المركب يكون ثابتًا نسبيًا فتلزم طاقة (حرارة أو ضوء أو كهرباء) لكسر الروابط التي تجمع مكوناته.', '["(a) 2Na + Cl₂ → 2NaCl","(b) 2NaCl → 2Na + Cl₂","(c) A + B → AB مقابل AB → A + B، وهما متعاكسان","(d) تلزم طاقة لكسر الروابط في المركب"]'::jsonb, '["(a) زن الكلور بالمعامل 2 أمام NaCl ثم الصوديوم بالمعامل 2 أمام Na","(b) اعكس معادلة التكوين: 2NaCl → 2Na + Cl₂","(c) قارن عدد المتفاعلات والنواتج في الصيغتين العامتين","(d) اربط التفكك بحاجة المركب إلى طاقة حرارية أو ضوئية أو كهربائية"]'::jsonb, '[{"element":"(a) معادلة التكوين الموزونة","marks":2},{"element":"(b) معادلة التفكك الموزونة","marks":2},{"element":"(c) المقارنة بين الصيغتين العامتين","marks":1},{"element":"(d) تفسير الحاجة إلى مصدر للطاقة","marks":2}]'::jsonb, '[{"level":"7 درجات","description":"المعادلتان صحيحتان وموزونتان، والمقارنة صحيحة، وتفسير الحاجة إلى الطاقة صحيح"},{"level":"5–6 درجات","description":"المعادلتان صحيحتان مع نقص في المقارنة أو في التفسير"},{"level":"3–4 درجات","description":"معادلة واحدة صحيحة مع إجابة جزئية لبقية الأجزاء"},{"level":"1–2 درجة","description":"ذكر أن التفكك عكس التكوين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Na + Cl → NaCl بدل 2Na + Cl₂ → 2NaCl","كتابة 2NaCl → 2Na + 2Cl","الظن أن التفكك لا يحتاج إلى طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.821Z"}'::jsonb)
