('mcq', 5, 'فيمَ يتشابه نوعا الإحلال البسيط «فلز يحل محل فلز» و«لافلز يحل محل لافلز»؟', null, '["كلاهما ينتج غاز الهيدروجين عند حدوثه","يحل العنصر الأنشط محل الأقل نشاطًا في مركب مذاب","كلاهما يحدث بتبادل الأيونات بين مركبين","كلاهما ينتج راسبًا في كل الحالات"]'::jsonb, 'تحليل', 'تحديد وجه الشبه بين نوعين', 'صعب', 'الكتاب ص 127، 128 — فلز يحل محل فلز ولافلز يحل محل لافلز'),
('mcq', 6, 'صنّف التفاعلات الثلاثة الواردة في الجدول إلى الأنواع الثلاثة للإحلال البسيط (فلز يحل محل الهيدروجين، فلز يحل محل فلز، لافلز يحل محل لافلز). أيّ الاختيارات الآتية صحيح؟', '{"headers":["الرقم","التفاعل"],"rows":[["I","Ca + 2H₂O → Ca(OH)₂ + H₂"],["II","Zn + 2AgNO₃ → Zn(NO₃)₂ + 2Ag"],["III","Br₂ + 2NaI → 2NaBr + I₂"]]}'::jsonb, '["I فلز محل فلز، II فلز محل الهيدروجين، III لافلز محل لافلز","I فلز محل الهيدروجين، II لافلز محل لافلز، III فلز محل فلز","I لافلز محل لافلز، II فلز محل فلز، III فلز محل الهيدروجين","I فلز محل الهيدروجين، II فلز محل فلز، III لافلز محل لافلز"]'::jsonb, 'تحليل', 'تصنيف ثلاثة تفاعلات إحلال', 'صعب', 'الكتاب ص 127، 128 — الأنواع الثلاثة لتفاعلات الإحلال البسيط'),
