insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'في هذا التفاعل تحل ذرة ليثيوم (فلز) محل ذرة هيدروجين من جزيء الماء، فينتج LiOH وغاز الهيدروجين H₂. فهو من نوع «فلز يحل محل الهيدروجين».', '["العنصر الحال هنا هو الليثيوم وهو فلز، وليس لافلزًا من الهالوجينات.","","العنصر المُستعاض عنه هو الهيدروجين وليس فلزًا؛ فالماء لا يحتوي على فلز.","تبادل الأيونين بين مركبين يميز الإحلال المزدوج، أما هنا فعنصر حر (Li) يحل محل عنصر في مركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.821Z"}'::jsonb),
('mcq', 2, 3, 'النحاس فلز حر حل محل فلز الفضة في مركب مذاب في الماء هو AgNO₃، فتكوّن Cu(NO₃)₂ وترسبت الفضة الحرة على الصفيحة. فهو إحلال بسيط من نوع «فلز يحل محل فلز».', '["الاتجاه معكوس؛ فالنحاس هو الذي حل محل الفضة، وليس العكس.","لا يحل النحاس محل الهيدروجين هنا؛ فالمركب المتفاعل هو نترات الفضة وليس الماء.","لم يحدث اتحاد بين الفلزين؛ بل حل أحدهما محل الآخر، وتكوّن مركب جديد وعنصر حر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.822Z"}'::jsonb),
('mcq', 3, 0, 'الكلور والبروم واليود من الهالوجينات (اللافلزات)، وفي هذا التفاعل يحل اللافلز الأنشط (Cl₂) محل اللافلز الأقل نشاطًا (I) في المركب المذاب. فهو إحلال من نوع «لافلز يحل محل لافلز».', '["","لا يوجد هيدروجين مُستعاض عنه في التفاعل؛ فالعنصر المُستعاض عنه هو اليود.","الكلور واليود لافلزان وليسا فلزين.","في التفاعل مادتان متفاعلتان (Cl₂ وKI)، أما التفكك فمتفاعله مركب واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.822Z"}'::jsonb),
('mcq', 4, 2, 'في التفاعل 2K + 2H₂O → 2KOH + H₂ يحل البوتاسيوم (فلز) محل الهيدروجين في الماء، وينتج غاز الهيدروجين. أما بقية التفاعلات فمن أنواع أخرى.', '["في هذا التفاعل يحل الخارصين (فلز) محل النحاس (فلز)، وليس محل الهيدروجين.","في هذا التفاعل يحل الكلور (لافلز) محل البروم (لافلز).","","هذا تفاعل إحلال مزدوج تبادلت فيه الأيونات مواقعها بين مركبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.822Z"}'::jsonb),
('mcq', 5, 1, 'في النوعين يحل عنصر حر محل عنصر آخر موجود في مركب مذاب في الماء، ولا يحدث ذلك إلا إذا كان العنصر الحر أنشط من العنصر المُستعاض عنه (الفلزات في سلسلة نشاطها، والهالوجينات في سلسلة نشاطها).', '["غاز الهيدروجين ينتج فقط عندما يحل فلز محل الهيدروجين، وليس في هذين النوعين.","","تبادل الأيونات بين مركبين يميز الإحلال المزدوج، أما في النوعين فيحل عنصر حر محل عنصر.","لا ينتج راسب في كل الحالات؛ فقد تبقى النواتج ذائبة كما في Cl₂ + 2KI → 2KCl + I₂ في المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.822Z"}'::jsonb),
('mcq', 6, 3, 'في التفاعل I يحل الكالسيوم (فلز) محل الهيدروجين في الماء. في التفاعل II يحل الخارصين (فلز) محل الفضة (فلز) في AgNO₃. في التفاعل III يحل البروم (لافلز) محل اليود (لافلز) في NaI. فالتصنيف الصحيح: I فلز محل الهيدروجين، II فلز محل فلز، III لافلز محل لافلز.', '["هذا الاختيار بدّل بين I وII؛ والتفاعل I يحل فيه الكالسيوم محل الهيدروجين في الماء، لا محل فلز.","هذا الاختيار بدّل بين II وIII؛ والتفاعل II يحل فيه فلز محل فلز، والتفاعل III يحل فيه الهالوجين Br₂ محل I.","هذا الاختيار جعل التصنيفات الثلاثة كلها خاطئة؛ فالتفاعل I يحل فيه فلز (Ca) لا لافلز، والتفاعل III يحل فيه لافلز لا فلز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.823Z"}'::jsonb),
('mcq', 7, 0, 'لا يحل الفلز دائمًا محل فلز آخر في مركب مذاب في الماء لأن الفلزات تختلف في نشاطها. يحل الفلز الحر محل الفلز الذي يقع بعده في سلسلة النشاط، أي عندما يكون أنشط منه، ولا يحل محل ما يقع قبله.', '["","الفلزات تختلف في نشاطها، ولا يحل الفلز دائمًا محل فلز آخر؛ فالفضة مثلًا لا تحل محل النحاس.","الفلز الأقل نشاطًا لا يحل محل الفلز الأنشط؛ فالفضة (أقل نشاطًا) لا تحل محل النحاس في محلول نتراته.","عندما يحل فلز محل الهيدروجين يكون النوع مختلفًا (فلز يحل محل الهيدروجين)، وليس فلزًا محل فلز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.823Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) فلز يحل محل الهيدروجين؛ الصوديوم هو العنصر الحال، والهيدروجين في الماء هو العنصر المُستعاض عنه. (b) فلز يحل محل فلز؛ الحديد هو العنصر الحال، والنحاس في CuSO₄ المذاب هو المُستعاض عنه. (c) لافلز يحل محل لافلز؛ الفلور هو العنصر الحال، والبروم في NaBr المذاب هو المُستعاض عنه.', '["(a) فلز محل الهيدروجين؛ الحال Na والمُستعاض عنه H","(b) فلز محل فلز؛ الحال Fe والمُستعاض عنه Cu","(c) لافلز محل لافلز؛ الحال F₂ والمُستعاض عنه Br"]'::jsonb, '[]'::jsonb, '[{"element":"(a) النوع مع تحديد الحال والمُستعاض عنه","marks":2},{"element":"(b) النوع مع تحديد الحال والمُستعاض عنه","marks":2},{"element":"(c) النوع مع تحديد الحال والمُستعاض عنه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"التصنيف صحيح في الحالات الثلاث مع تحديد صحيح للعنصرين في كل منها"},{"level":"4–5 درجات","description":"التصنيف صحيح في الحالات الثلاث مع خطأ في تحديد العنصرين في واحدة أو اثنتين"},{"level":"2–3 درجات","description":"تصنيف صحيح لحالتين"},{"level":"1 درجة","description":"تصنيف صحيح لحالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (a) على أنه فلز محل فلز","الخلط بين العنصر الحال والعنصر المُستعاض عنه","تصنيف (c) على أنه إحلال مزدوج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:27:04.823Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) Ca + 2H₂O → Ca(OH)₂ + H₂؛ فلز يحل محل الهيدروجين. (b) Al + 3AgNO₃ → Al(NO₃)₃ + 3Ag؛ فلز يحل محل فلز. (c) Cl₂ + 2NaBr → 2NaCl + Br₂؛ لافلز يحل محل لافلز.', '["(a) Ca + 2H₂O → Ca(OH)₂ + H₂ ونوعه فلز محل الهيدروجين","(b) Al + 3AgNO₃ → Al(NO₃)₃ + 3Ag ونوعه فلز محل فلز","(c) Cl₂ + 2NaBr → 2NaCl + Br₂ ونوعه لافلز محل لافلز"]'::jsonb, '["(a) زن الهيدروجين والأكسجين بوضع المعامل 2 أمام H₂O","(b) زن النترات بوضع المعامل 3 أمام AgNO₃ ثم الفضة بالمعامل 3 أمام Ag","(c) زن الصوديوم والكلور بوضع المعامل 2 أمام NaBr وأمام NaCl"]'::jsonb, '[{"element":"(a) المعادلة الموزونة","marks":1},{"element":"(a) النوع","marks":1},{"element":"(b) المعادلة الموزونة","marks":1},{"element":"(b) النوع","marks":1},{"element":"(c) المعادلة الموزونة","marks":1},{"element":"(c) النوع","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث موزونة والأنواع الثلاثة صحيحة"},{"level":"4–5 درجات","description":"الأنواع الثلاثة صحيحة مع خطأ وزن في معادلة أو اثنتين"},{"level":"2–3 درجات","description":"نوعان صحيحان أو معادلتان موزونتان فقط"},{"level":"1 درجة","description":"نوع واحد أو معادلة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان المعامل 2 أمام H₂O في (a)","كتابة Al + AgNO₃ → Al(NO₃)₃ + Ag دون وزن","تصنيف (b) فلزًا محل الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.823Z"}'::jsonb),
('essay', 3, null::int, null, null, 'فلز يحل محل الهيدروجين: العنصر الحر فلز نشط، يحل محل الهيدروجين في الماء، ويتميز بناتج هو غاز الهيدروجين، مثل 2Li + 2H₂O → 2LiOH + H₂. فلز يحل محل فلز: العنصر الحر فلز أنشط، يحل محل فلز في مركب مذاب في الماء، ويتميز بظهور الفلز الأقل نشاطًا حرًا، مثل Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag. لافلز يحل محل لافلز: العنصر الحر هالوجين أنشط، يحل محل هالوجين أقل نشاطًا في مركب مذاب، ويتميز بتحرر الهالوجين الأقل نشاطًا، مثل F₂ + 2NaBr → 2NaF + Br₂. وجه الشبه: في كل نوع يحل عنصر حر محل عنصر موجود في مركب، فينتج مركب جديد وعنصر حر.', '["فلز محل الهيدروجين: فلز نشط وماء، والناتج H₂، ومثال 2Li + 2H₂O → 2LiOH + H₂","فلز محل فلز: فلز أنشط ومركب مذاب، والناتج فلز حر، ومثال Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag","لافلز محل لافلز: هالوجين أنشط ومركب مذاب، والناتج هالوجين حر، ومثال F₂ + 2NaBr → 2NaF + Br₂","وجه الشبه: عنصر حر يحل محل عنصر في مركب فينتج مركب جديد وعنصر حر"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة النوع الأول مع مثاله","marks":2},{"element":"مقارنة النوع الثاني مع مثاله","marks":2},{"element":"مقارنة النوع الثالث مع مثاله","marks":2},{"element":"وجه الشبه","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"مقارنة كاملة للأنواع الثلاثة بأمثلة صحيحة، ووجه شبه صحيح"},{"level":"5–6 درجات","description":"مقارنة صحيحة للأنواع الثلاثة مع نقص في بعض الأمثلة أو غياب وجه الشبه"},{"level":"3–4 درجات","description":"مقارنة صحيحة لنوعين فقط"},{"level":"1–2 درجة","description":"ذكر مثال صحيح أو خاصية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الإحلال البسيط والمزدوج","ذكر أن الهالوجينات فلزات","عدم ذكر المعادلة أو كتابتها غير موزونة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.824Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
