from (values
('mcq', 1, 'وُضعت قطع من أربعة فلزات كل في محاليل نترات هذه الفلزات (1.0 M)، وسُجلت النتائج في الجدول. أيّ الفلزات تفاعل مع أكبر عدد من المحاليل فيكون الأكثر نشاطًا؟', '{"headers":["الفلز","Al(NO₃)₃","Mg(NO₃)₂","Zn(NO₃)₂","Cu(NO₃)₂"],"rows":[["Al","—","لا تفاعل","تفاعل","تفاعل"],["Mg","تفاعل","—","تفاعل","تفاعل"],["Zn","لا تفاعل","لا تفاعل","—","تفاعل"],["Cu","لا تفاعل","لا تفاعل","لا تفاعل","—"]]}'::jsonb, '["الماغنسيوم","الألومنيوم","الخارصين","النحاس"]'::jsonb, 'فهم', 'تحديد الفلز الأنشط من نتائج التجربة', 'سهل', 'الكتاب ص 144 — مختبر الكيمياء: تطوير سلسلة نشاط الفلزات'),
('mcq', 2, 'اعتمادًا على نتائج الجدول نفسه، ما ترتيب الفلزات الأربعة من الأكثر نشاطًا إلى الأقل نشاطًا؟', '{"headers":["الفلز","Al(NO₃)₃","Mg(NO₃)₂","Zn(NO₃)₂","Cu(NO₃)₂"],"rows":[["Al","—","لا تفاعل","تفاعل","تفاعل"],["Mg","تفاعل","—","تفاعل","تفاعل"],["Zn","لا تفاعل","لا تفاعل","—","تفاعل"],["Cu","لا تفاعل","لا تفاعل","لا تفاعل","—"]]}'::jsonb, '["الألومنيوم > الماغنسيوم > الخارصين > النحاس","الماغنسيوم > الخارصين > الألومنيوم > النحاس","الماغنسيوم > الألومنيوم > الخارصين > النحاس","النحاس > الخارصين > الألومنيوم > الماغنسيوم"]'::jsonb, 'تحليل', 'ترتيب الفلزات بحسب نشاطها', 'متوسط', 'الكتاب ص 144 — مختبر الكيمياء: ترتيب الفلزات من الأكثر نشاطًا إلى الأقل'),
('mcq', 3, 'في الجدول نفسه، لم يتفاعل الخارصين عند وضعه في محلول Mg(NO₃)₂. ما تفسير ذلك؟', '{"headers":["الفلز","Al(NO₃)₃","Mg(NO₃)₂","Zn(NO₃)₂","Cu(NO₃)₂"],"rows":[["Al","—","لا تفاعل","تفاعل","تفاعل"],["Mg","تفاعل","—","تفاعل","تفاعل"],["Zn","لا تفاعل","لا تفاعل","—","تفاعل"],["Cu","لا تفاعل","لا تفاعل","لا تفاعل","—"]]}'::jsonb, '["لأن الخارصين أنشط من الماغنسيوم","لأن الخارصين أقل نشاطًا من الماغنسيوم فلا يحل محله","لأن نترات الماغنسيوم لا تذوب في الماء","لأن الخارصين والماغنسيوم لهما النشاط نفسه"]'::jsonb, 'تحليل', 'تفسير غياب التفاعل', 'سهل', 'الكتاب ص 128، 144 — لا يحل الفلز محل فلز يقع قبله في السلسلة'),
('mcq', 4, 'وُضعت قطعة من الفلز X في محلول نترات الفلز Y فحدث تفاعل، ووُضعت قطعة من الفلز Y في محلول نترات الفلز Z فحدث تفاعل. أيّ التنبؤات الآتية صحيح؟', null, '["تتفاعل قطعة Z مع محلول نترات X","ترتيب النشاط من الأعلى إلى الأقل هو Z ثم Y ثم X","لا تتفاعل قطعة X مع محلول نترات Z","تتفاعل قطعة X مع محلول نترات Z"]'::jsonb, 'تحليل', 'استنتاج ترتيب النشاط من ملاحظات', 'متوسط', 'الكتاب ص 144 — ترتيب الفلزات بحسب نشاطها من نتائج التجربة'),
('mcq', 5, 'وُضعت قطع من أربعة فلزات في محاليل نتراتها كما في الجدول. أيّ المحاليل تفاعل مع أكبر عدد من الفلزات، وماذا يدل ذلك؟', '{"headers":["الفلز","Fe(NO₃)₂","Zn(NO₃)₂","Pb(NO₃)₂","AgNO₃"],"rows":[["Fe","—","لا تفاعل","تفاعل","تفاعل"],["Zn","تفاعل","—","تفاعل","تفاعل"],["Pb","لا تفاعل","لا تفاعل","—","تفاعل"],["Ag","لا تفاعل","لا تفاعل","لا تفاعل","—"]]}'::jsonb, '["Zn(NO₃)₂؛ لأن الخارصين أنشط الفلزات الأربعة","AgNO₃؛ لأن الفضة أقل الفلزات الأربعة نشاطًا فيحل محلها أي فلز آخر","Pb(NO₃)₂؛ لأن الرصاص يقع في وسط الفلزات الأربعة","Fe(NO₃)₂؛ لأن الحديد أقل الفلزات الأربعة نشاطًا"]'::jsonb, 'تحليل', 'استنتاج نشاط فلز من تفاعل محلول نتراته', 'صعب', 'الكتاب ص 127، 144 — ترتيب الفلزات بحسب نشاطها'),
('mcq', 6, 'في تجربة ترتيب الفلزات بحسب نشاطها استُخدمت محاليل بتركيز 1.0 M نفسه لجميع الأملاح، ونُظّفت أشرطة الفلزات بورق الصنفرة قبل وضعها في المحاليل. ما الغرض من ذلك؟', null, '["لتكون الفروق في التفاعل ناتجة عن اختلاف الفلزات فقط","لتتفاعل جميع الفلزات بالسرعة نفسها","لتنتج جميع الفلزات الكمية نفسها من الراسب","ليتفاعل الفلز الأقل نشاطًا أيضًا"]'::jsonb, 'تقويم', 'تقويم تصميم التجربة', 'متوسط', 'الكتاب ص 144 — مختبر الكيمياء: خطوات العمل'),
('mcq', 7, 'تبيّن نتائج الجدول أن الألومنيوم تفاعل مع محلول Cu(NO₃)₂. ما المعادلة الرمزية الموزونة لهذا التفاعل؟', '{"headers":["الفلز","Al(NO₃)₃","Mg(NO₃)₂","Zn(NO₃)₂","Cu(NO₃)₂"],"rows":[["Al","—","لا تفاعل","تفاعل","تفاعل"],["Mg","تفاعل","—","تفاعل","تفاعل"],["Zn","لا تفاعل","لا تفاعل","—","تفاعل"],["Cu","لا تفاعل","لا تفاعل","لا تفاعل","—"]]}'::jsonb, '["Al + Cu(NO₃)₂ → Al(NO₃)₂ + Cu","2Al + 3Cu(NO₃)₂ → 2Al(NO₃)₃ + 2Cu","3Cu + 2Al(NO₃)₃ → 3Cu(NO₃)₂ + 2Al","2Al + 3Cu(NO₃)₂ → 2Al(NO₃)₃ + 3Cu"]'::jsonb, 'تطبيق', 'كتابة معادلة تفاعل الإحلال المشاهَد', 'صعب', 'الكتاب ص 144 — مختبر الكيمياء: كتابة معادلة لكل تفاعل إحلال'),
('essay', 1, 'وُضعت قطع من أربعة فلزات (Zn وFe وPb وCu) كل في محاليل نترات الفلزات الأخرى، فلُوحظ ما يأتي:
- تفاعل الخارصين مع محاليل نترات الحديد II ونترات الرصاص II ونترات النحاس II.
- تفاعل الحديد مع محلولي نترات الرصاص II ونترات النحاس II، ولم يتفاعل مع محلول نترات الخارصين.
- تفاعل الرصاص مع محلول نترات النحاس II فقط.
- لم يتفاعل النحاس مع أي محلول.
(a) رتّب الفلزات الأربعة من الأكثر نشاطًا إلى الأقل نشاطًا.
(b) وضّح كيف استنتجت الترتيب.
(c) اكتب معادلة رمزية موزونة لتفاعل الخارصين مع محلول نترات الرصاص II.', null, null, 'تحليل', 'ترتيب الفلزات من نتائج تجربة', 'متوسط', 'الكتاب ص 132، 144 — السؤال 34 ومختبر الكيمياء'),
('essay', 2, 'لديك ثلاثة فلزات مجهولة X وY وZ، ومحلول مائي لنترات كل منها بتركيز 1.0 M، وأدوات المختبر المعتادة (طبق تفاعلات، ماصات، ورق صنفرة). صمّم تجربة لترتيب هذه الفلزات من الأنشط إلى الأقل نشاطًا، موضحًا: (a) الخطوات، (b) المتغيرات التي ينبغي تثبيتها، (c) المشاهدات التي تدل على حدوث تفاعل، (d) كيف تستنتج الترتيب من النتائج.', null, null, 'تقويم', 'تصميم تجربة لترتيب الفلزات', 'صعب', 'الكتاب ص 144 — مختبر الكيمياء: تطوير سلسلة نشاط الفلزات'),
('essay', 3, 'سجّل طالب في تجربة ترتيب الفلزات أن قطعة من النحاس تفاعلت مع محلول نترات الخارصين، وهي نتيجة تخالف سلسلة النشاط التي تضع الخارصين قبل النحاس.
(a) اذكر سببين محتملين لهذه النتيجة غير المتوقعة.
(b) ماذا ينبغي أن يفعل الطالب للتحقق من النتيجة؟', null, null, 'تقويم', 'تقويم نتيجة تجريبية غير متوقعة', 'سهل', 'الكتاب ص 128، 144 — سلسلة النشاط ومختبر الكيمياء')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L2-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تفاعل الماغنسيوم مع ثلاثة محاليل، وهو أكبر عدد، وهذا يعني أنه يحل محل الفلزات الثلاثة الأخرى؛ فهو الأكثر نشاطًا.', '["","تفاعل الألومنيوم مع محلولين فقط، فهو أقل نشاطًا من الماغنسيوم الذي تفاعل مع ثلاثة.","تفاعل الخارصين مع محلول واحد فقط، فهو أقل نشاطًا من الماغنسيوم والألومنيوم.","لم يتفاعل النحاس مع أي محلول، فهو أقل الفلزات الأربعة نشاطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:27:04.824Z"}'::jsonb),
('mcq', 2, 2, 'عدد المحاليل التي تفاعل معها كل فلز: الماغنسيوم 3، والألومنيوم 2، والخارصين 1، والنحاس صفر. كلما زاد العدد زاد النشاط، فالترتيب: الماغنسيوم > الألومنيوم > الخارصين > النحاس. ويؤكد ذلك أن الألومنيوم لم يحل محل الماغنسيوم بينما حل الماغنسيوم محله.', '["وضع هذا الترتيب الألومنيوم قبل الماغنسيوم؛ لكن الماغنسيوم حل محل الألومنيوم في نتراته بينما لم يحل الألومنيوم محل الماغنسيوم.","وضع هذا الترتيب الخارصين قبل الألومنيوم؛ لكن الألومنيوم حل محل الخارصين ولم يحدث العكس.","","هذا الترتيب معكوس؛ فالنحاس لم يتفاعل مع أي محلول فهو الأقل نشاطًا وليس الأكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.825Z"}'::jsonb),
('mcq', 3, 1, 'لا يحل الفلز محل فلز يقع قبله في سلسلة النشاط. ولم يتفاعل الخارصين مع Mg(NO₃)₂ لأنه أقل نشاطًا من الماغنسيوم، ولهذا يحل الماغنسيوم محل الخارصين لا العكس.', '["لو كان الخارصين أنشط من الماغنسيوم لحل محله وحدث تفاعل، لكن لم يحدث تفاعل.","","نترات الماغنسيوم تذوب في الماء، وقد استُخدمت محلولًا مائيًا في التجربة.","لو تساوى النشاط لما تفاعل أي منهما مع الآخر، لكن الماغنسيوم تفاعل مع محلول نترات الخارصين، فنشاطهما مختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.825Z"}'::jsonb),
('mcq', 4, 3, 'تفاعل X مع نترات Y يعني أن X أنشط من Y، وتفاعل Y مع نترات Z يعني أن Y أنشط من Z؛ فالترتيب X > Y > Z. وبما أن X أنشط من Z فإنه يحل محله، فتتفاعل قطعة X مع محلول نترات Z.', '["Z أقل الفلزات الثلاثة نشاطًا، فلا يحل محل X.","هذا الترتيب معكوس؛ فالفلز الذي يحل محل غيره هو الأنشط، والترتيب الصحيح X > Y > Z.","بما أن X أنشط من Y وY أنشط من Z فإن X أنشط من Z، فيتفاعل مع محلول نتراته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.825Z"}'::jsonb),
('mcq', 5, 1, 'تفاعل محلول AgNO₃ مع ثلاثة فلزات (Fe وZn وPb) وهو أكبر عدد. وهذا يعني أن الفضة أقل الفلزات نشاطًا، فأي فلز أنشط منها يحل محلها؛ فكلما تفاعل محلول ملح الفلز مع عدد أكبر من الفلزات دلّ ذلك على أن الفلز نفسه أقل نشاطًا.', '["محلول Zn(NO₃)₂ لم يتفاعل مع أي فلز لأن الخارصين أنشط الفلزات الأربعة فلا يحل محله فلز؛ فالمحلول الذي يدل على الأنشط هو الذي لا يتفاعل مع أحد.","","تفاعل محلول Pb(NO₃)₂ مع فلزين فقط (Fe وZn)، فليس هو الأكثر تفاعلًا.","الحديد ليس أقل الفلزات نشاطًا؛ وتفاعل محلول Fe(NO₃)₂ مع فلز واحد فقط (Zn)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:27:04.825Z"}'::jsonb),
('mcq', 6, 0, 'عند تثبيت التركيز وتنظيف سطح الفلزات (إزالة الطبقة الملوثة) تكون الظروف متماثلة، فيُنسب أي اختلاف في التفاعل إلى اختلاف نشاط الفلزات وحده، لا إلى اختلاف التركيز أو حالة السطح.', '["","تثبيت الظروف لا يجعل الفلزات تتفاعل بالسرعة نفسها؛ فالفلزات تختلف في نشاطها وسرعة تفاعلها.","لا يهدف ذلك إلى تساوي الكمية الناتجة؛ فبعض الفلزات لا تتفاعل أصلًا.","لا يغيّر تثبيت الظروف نتيجة التفاعل؛ فالفلز الأقل نشاطًا لا يحل محل الأنشط في أي ظرف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.825Z"}'::jsonb),
('mcq', 7, 3, 'يحل الألومنيوم (Al³⁺) محل النحاس في محلول Cu(NO₃)₂ فينتج Al(NO₃)₃ والنحاس الحر. وتتساوى الذرات في 2Al + 3Cu(NO₃)₂ → 2Al(NO₃)₃ + 3Cu: في كل طرف 2Al و3Cu و6N و18O.', '["صيغة Al(NO₃)₂ خاطئة؛ فأيون الألومنيوم Al³⁺ يرتبط بثلاث مجموعات نترات: Al(NO₃)₃.","المعادلة غير موزونة؛ فعدد ذرات Cu هو 3 في اليسار و2 في اليمين.","هذه المعادلة موزونة لكنها تمثل تفاعل النحاس مع نترات الألومنيوم، وهو لا يحدث لأن النحاس أقل نشاطًا من الألومنيوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.826Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الخارصين > الحديد > الرصاص > النحاس. (b) الخارصين تفاعل مع ثلاثة محاليل فهو أنشط الفلزات؛ والحديد تفاعل مع محلولين فهو يليه؛ والرصاص تفاعل مع محلول واحد؛ والنحاس لم يتفاعل مع أي محلول فهو الأقل نشاطًا. فكل فلز يحل محل الفلزات التي هي أقل منه نشاطًا فقط، وعدد المحاليل التي يتفاعل معها يدل على موقعه في الترتيب. (c) Zn + Pb(NO₃)₂ → Zn(NO₃)₂ + Pb.', '["(a) الخارصين > الحديد > الرصاص > النحاس","(b) كلما زاد عدد المحاليل التي تفاعل معها الفلز زاد نشاطه","(b) الفلز يحل محل الفلزات الأقل نشاطًا منه فقط","(c) Zn + Pb(NO₃)₂ → Zn(NO₃)₂ + Pb"]'::jsonb, '[]'::jsonb, '[{"element":"(a) الترتيب الصحيح","marks":2},{"element":"(b) التعليل بعدد المحاليل التي تفاعل معها كل فلز","marks":2},{"element":"(c) المعادلة صحيحة وموزونة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الترتيب صحيح، والتعليل يربط النشاط بعدد المحاليل ويذكر أن الفلز يحل محل الأقل نشاطًا، والمعادلة موزونة"},{"level":"4–5 درجات","description":"الترتيب صحيح مع نقص في التعليل أو خطأ في المعادلة"},{"level":"2–3 درجات","description":"ترتيب صحيح دون تعليل ولا معادلة، أو معادلة صحيحة مع ترتيب خاطئ"},{"level":"1 درجة","description":"تحديد الفلز الأنشط أو الأقل نشاطًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب (النحاس الأنشط)","الاعتماد على عدد المحاليل التي تحتوي فلزًا دون ربطها بحدوث التفاعل","كتابة Zn(NO₃)₃ أو معادلة غير موزونة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.826Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) تُنظَّف قطع متساوية من الفلزات الثلاثة بورق الصنفرة، ثم توضع قطعة من كل فلز في كل محلول من محاليل نترات الفلزين الآخرين (ست تجارب) في حفر طبق التفاعلات، ويُسجَّل ما يحدث بعد بضع دقائق. (b) يُثبَّت تركيز المحاليل (1.0 M) وحجمها (2 mL) وحجم قطع الفلزات ونظافتها وزمن الملاحظة، ويُغيَّر نوع الفلز ونوع المحلول فقط. (c) من الدلائل: ترسّب مادة على قطعة الفلز، أو تغيّر لون المحلول، أو تآكل القطعة. (d) الفلز الذي يتفاعل مع أكبر عدد من المحاليل هو الأنشط، والذي لا يتفاعل مع أي محلول هو الأقل نشاطًا؛ ويُرتَّب الفلز الأوسط بينهما. مثال: إذا تفاعل X مع نترات Y ونترات Z، وتفاعل Y مع نترات Z فقط، فالترتيب X > Y > Z.', '["(a) تنظيف قطع الفلزات ووضع كل فلز في محاليل نترات الفلزين الآخرين","(b) تثبيت التركيز والحجم وحجم القطع وزمن الملاحظة","(c) مشاهدات: راسب على القطعة أو تغيّر لون المحلول","(d) الأنشط هو الأكثر تفاعلًا مع المحاليل، والأقل نشاطًا لا يتفاعل مع أي محلول"]'::jsonb, '[]'::jsonb, '[{"element":"(a) خطوات صحيحة تغطي الاختبارات اللازمة","marks":2},{"element":"(b) تحديد المتغيرات المثبّتة","marks":2},{"element":"(c) ذكر مشاهدة تدل على حدوث التفاعل","marks":1},{"element":"(d) طريقة استنتاج الترتيب","marks":2}]'::jsonb, '[{"level":"7 درجات","description":"تصميم متكامل: خطوات صحيحة ومتغيرات مثبتة ومشاهدات ومنهج واضح لاستنتاج الترتيب"},{"level":"5–6 درجات","description":"تصميم صحيح مع نقص في تحديد المتغيرات أو في الاستنتاج"},{"level":"3–4 درجات","description":"خطوات ناقصة لا تغطي كل التجارب اللازمة أو استنتاج غير مبرر"},{"level":"1–2 درجة","description":"ذكر فكرة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تنظيف الفلزات قبل وضعها في المحاليل","وضع كل فلز في محلول نتراته نفسه","تغيير تركيز المحاليل من تجربة لأخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.826Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) من الأسباب المحتملة: تلوث سطح قطعة النحاس أو المحلول بفلز آخر أنشط، أو الخطأ في ملاحظة النتيجة وتسجيلها (كاعتبار تغير لون طفيف أو عكارة تفاعلًا). (b) يعيد الطالب التجربة بتنظيف قطعة النحاس بورق الصنفرة، واستخدام محلول طازج وأدوات نظيفة، ويقارنها بحفرة ضابطة لا يوضع فيها الفلز، ثم يسجل الملاحظة بدقة؛ فإذا لم يتكرر التفاعل فالنتيجة السابقة خطأ تجريبي، لأن النحاس أقل نشاطًا من الخارصين ولا يحل محله.', '["(a) سببان: تلوث الفلز أو المحلول، أو خطأ في الملاحظة أو التسجيل","(b) إعادة التجربة بفلز منظف ومحلول طازج وأدوات نظيفة","(b) الاستنتاج أن النحاس أقل نشاطًا من الخارصين فلا يحل محله"]'::jsonb, '[]'::jsonb, '[{"element":"(a) سبب محتمل أول","marks":1},{"element":"(a) سبب محتمل ثانٍ","marks":1},{"element":"(b) إجراء مناسب للتحقق","marks":1},{"element":"(b) الربط بسلسلة النشاط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"سببان مقبولان وإجراء تحقق مناسب وربط بسلسلة النشاط"},{"level":"3 درجات","description":"ثلاثة من العناصر الأربعة صحيحة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول النتيجة وتعديل سلسلة النشاط","ذكر أسباب لا علاقة لها بالتجربة","عدم اقتراح إعادة التجربة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.827Z"}'::jsonb)
