('mcq', 1, 'ما المقصود بالمحلول المائي؟', null, '["مخلوط غير متجانس تتوزع فيه مواد صلبة في الماء","محلول يحتوي على مادة أو أكثر مذابة في الماء","سائل نقي يتكوّن من جزيئات الماء فقط","محلول يكون فيه الماء هو المادة المذابة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 133 — المحاليل المائية'),
('mcq', 2, 'أُذيب 5 g من كلوريد الصوديوم في 100 g من الماء. أيّ العبارات الآتية تصف مكوّنات المحلول الناتج وصفًا صحيحًا؟', null, '["الماء مذاب وكلوريد الصوديوم مذيب","كلوريد الصوديوم مذيب لأنه مادة صلبة","كلٌّ من الماء وكلوريد الصوديوم مذيب لأن المحلول مائي","الماء مذيب وكلوريد الصوديوم مذاب"]'::jsonb, 'فهم', 'تحديد المذاب والمذيب', 'سهل', 'الكتاب ص 133 — المحاليل المائية'),
('mcq', 3, 'عند إضافة مسحوق نكهة الليمون إلى الماء تذوب بلوراته مكوّنةً محلولًا. ما المذاب وما المذيب في هذا المحلول؟', null, '["المذاب: مسحوق نكهة الليمون، والمذيب: الماء","المذاب: الماء، والمذيب: مسحوق نكهة الليمون","المذاب والمذيب كلاهما الماء لأن المحلول مائي","لا يوجد مذاب لأن المسحوق تحوّل إلى مادة جديدة"]'::jsonb, 'فهم', 'تحديد المذاب والمذيب في موقف حياتي', 'سهل', 'الكتاب ص 133 — الربط مع الحياة، المحاليل المائية'),
('mcq', 4, 'مُزج 10 mL من الإيثانول مع 90 mL من الماء فتكوّن محلول متجانس. ما المذيب في هذا المحلول ولماذا؟', null, '["الإيثانول؛ لأنه أسرع تبخرًا من الماء","الإيثانول؛ لأنه المادة التي تذوب في الماء","الماء؛ لأنه أكبر مكوّنات المحلول","لا مذيب في المحلول لأن المادتين سائلتان"]'::jsonb, 'فهم', 'تبرير تحديد المذيب', 'متوسط', 'الكتاب ص 133 — المحاليل المائية والمركبات الجزيئية في المحلول'),
('mcq', 5, 'أيّ المحاليل الآتية ليس محلولًا مائيًّا؟', null, '["محلول السكروز في الماء","محلول الإيثانول في الماء","محلول مسحوق نكهة الليمون في الماء","محلول اليود في كمية أكبر من الإيثانول"]'::jsonb, 'فهم', 'تمييز المحلول المائي', 'متوسط', 'الكتاب ص 133 — المحاليل المائية'),
('mcq', 6, 'أيّ العبارات الآتية تصف المحاليل المائية وصفًا صحيحًا؟', null, '["الماء هو المذيب دائمًا، والمواد التي قد تذوب فيه كثيرة","المذاب هو أكبر مكونات المحلول المائي","المذيب في المحلول المائي قد يكون أيّ سائل حسب المادة المذابة","المحلول المائي لا يحتوي إلا على مادة واحدة مذابة في الماء"]'::jsonb, 'فهم', 'تقويم عبارات عن المحاليل المائية', 'متوسط', 'الكتاب ص 133 — المحاليل المائية'),
('mcq', 7, 'أُعدّ محلول مائي بإذابة 8 g من كلوريد الصوديوم و3 g من السكروز في 100 g من الماء. كم مذابًا وكم مذيبًا في هذا المحلول؟', null, '["مذاب واحد ومذيبان","ثلاثة مذابات ومذيب واحد","مذابان ومذيب واحد","مذاب واحد ومذيب واحد"]'::jsonb, 'تطبيق', 'عدّ المذابات والمذيب في محلول', 'صعب', 'الكتاب ص 133 — المحاليل المائية'),
('essay', 1, 'عرّف المحلول المائي، ثم حدّد المذاب والمذيب في المحلول الناتج عن إذابة مسحوق نكهة الليمون في الماء، موضّحًا لماذا يُسمّى الماء مذيبًا.', null, null, 'فهم', 'تعريف وتحديد المذاب والمذيب مع تعليل', 'متوسط', 'الكتاب ص 133 — الربط مع الحياة، المحاليل المائية'),
('essay', 2, 'يحتوي كأس على محلول أُعدّ بإذابة 12 g من كلوريد البوتاسيوم و5 g من السكروز في 200 g من الماء. حدّد المذيب والمذابات في هذا المحلول، وعلّل لماذا يُعدّ محلولًا مائيًّا ولماذا لا يوجد فيه أكثر من مذيب واحد.', null, null, 'تطبيق', 'تطبيق على محلول بمذابين', 'صعب', 'الكتاب ص 133 — المحاليل المائية'),
('essay', 3, 'قال طالب: «كل محلول سائل يُعدّ محلولًا مائيًّا». قوّم هذه العبارة مستعينًا بمثالين: محلول الإيثانول في الماء (الماء هو الكمية الأكبر)، ومحلول اليود المذاب في كمية أكبر من الإيثانول.', null, null, 'تقويم', 'تقويم عبارة بأمثلة', 'صعب', 'الكتاب ص 133 — المحاليل المائية')
