from (values
('mcq', 1, 1, 'المحلول المائي محلول يحتوي على مادة أو أكثر مذابة في الماء؛ فالماء هو الوسط الذي تذوب فيه المواد، وهذا هو التعريف الصحيح المقابل للخيار «محلول يحتوي على مادة أو أكثر مذابة في الماء».', '["المحلول مخلوط متجانس تذوب فيه المادة تمامًا، وليس مخلوطًا غير متجانس تتوزع فيه مواد صلبة.","","السائل النقي الذي يحتوي جزيئات الماء فقط ليس محلولًا لأنه لا يحتوي مادة مذابة.","الماء في المحلول المائي هو المذيب دائمًا، وليس المادة المذابة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.827Z"}'::jsonb),
('mcq', 2, 3, 'الماء هو أكبر مكوّنات المحلول فهو المذيب، أما كلوريد الصوديوم الذي ذاب فيه فهو المذاب؛ فالعبارة الصحيحة هي «الماء مذيب وكلوريد الصوديوم مذاب».', '["هذا عكس الصحيح؛ فالماء أكبر المكونات وهو المذيب، وكلوريد الصوديوم هو المذاب.","حالة المادة (صلبة) لا تحدد المذيب؛ فالمذيب هو أكبر مكونات المحلول، وهو الماء.","في المحلول مذيب واحد فقط هو الماء، أما المادة التي تذوب فيه فهي المذاب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.827Z"}'::jsonb),
('mcq', 3, 0, 'بلورات مسحوق نكهة الليمون هي المادة التي تذوب فتكون المذاب، والماء أكبر مكونات المحلول فهو المذيب؛ أي أن الصحيح هو «المذاب: مسحوق نكهة الليمون، والمذيب: الماء».', '["","هذا عكس الصحيح؛ فالماء هو المذيب والمسحوق هو المذاب.","الماء هو المذيب فقط، أما المذاب فهو المسحوق الذي ذاب فيه.","ذوبان المسحوق لا يعني تحوله إلى مادة جديدة؛ فهو مذاب موزّع في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('mcq', 4, 2, 'المذيب هو أكبر مكوّنات المحلول، والماء (90 mL) أكبر من الإيثانول (10 mL)؛ لذلك المذيب هو الماء والإيثانول هو المذاب، أي «الماء؛ لأنه أكبر مكوّنات المحلول».', '["سرعة التبخر لا تحدد المذيب؛ فالمذيب هو أكبر مكونات المحلول وهو الماء.","المادة التي تذوب في الماء هي المذاب، وليست المذيب؛ والإيثانول هنا هو المذاب.","","يمكن أن تكون المادة المذابة سائلة؛ والمحلول يحتوي دائمًا على مذيب هو أكبر مكوناته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('mcq', 5, 3, 'المحلول المائي هو الذي يكون الماء مذيبه، أما في محلول اليود المذاب في كمية أكبر من الإيثانول فالمذيب هو الإيثانول وليس الماء؛ لذلك «محلول اليود في كمية أكبر من الإيثانول» ليس محلولًا مائيًّا.', '["السكروز مذاب في الماء، فالمحلول مائي.","الماء هنا هو المذيب والإيثانول هو المذاب، فالمحلول مائي.","مسحوق نكهة الليمون مذاب في الماء، فالمحلول مائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('mcq', 6, 0, 'الماء هو المذيب في المحاليل المائية دائمًا، أما المواد التي يمكن أن تذوب فيه فهي كثيرة؛ فالعبارة الصحيحة هي «الماء هو المذيب دائمًا، والمواد التي قد تذوب فيه كثيرة».', '["","أكبر مكونات المحلول هو المذيب (الماء)، وليس المذاب.","في المحلول المائي المذيب هو الماء دائمًا، ولا يتغير بتغير المادة المذابة.","قد يحتوي المحلول المائي على مادة مذابة واحدة أو أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('mcq', 7, 2, 'المادتان المذابتان هما كلوريد الصوديوم والسكروز، أي مذابان، أما المذيب فهو الماء وحده لأنه أكبر المكونات؛ فالمحلول يحتوي «مذابين ومذيبًا واحدًا».', '["الماء هو المذيب الوحيد، وكل من كلوريد الصوديوم والسكروز مذاب.","الماء مذيب وليس مذابًا؛ لذلك عدد المذابات اثنان فقط.","","المحلول يحتوي مادتين مذابتين وليس مادة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول المائي محلول يحتوي على مادة أو أكثر مذابة في الماء. في محلول مسحوق نكهة الليمون يكون المذاب هو مسحوق نكهة الليمون الذي تذوب بلوراته، ويكون المذيب هو الماء. ويُسمّى الماء مذيبًا لأنه أكبر مكوّنات المحلول، وهو المذيب دائمًا في المحاليل المائية.', '["المحلول المائي: محلول يحتوي مادة أو أكثر مذابة في الماء","المذاب هو مسحوق نكهة الليمون","المذيب هو الماء","الماء مذيب لأنه أكبر مكوّنات المحلول"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المحلول المائي","marks":1},{"element":"تحديد المذاب","marks":1},{"element":"تحديد المذيب","marks":1},{"element":"تعليل تسمية الماء مذيبًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وتحديد المذاب والمذيب، وتعليل كون الماء أكبر المكونات"},{"level":"2–3 درجات","description":"تعريف صحيح وتحديد صحيح للمذاب والمذيب مع نقص في التعليل، أو العكس"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس دور المذاب والمذيب","تعريف المحلول المائي بأنه ماء نقي","ذكر أن الماء مذيب دون تعليل (أكبر المكونات)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.828Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المذيب هو الماء، والمذابان هما كلوريد البوتاسيوم والسكروز. المحلول مائي لأن الماء هو المذيب الذي ذابت فيه المادتان. ولا يوجد فيه أكثر من مذيب لأن المذيب هو أكبر مكوّنات المحلول، والماء (200 g) أكبر بكثير من كل من كلوريد البوتاسيوم (12 g) والسكروز (5 g)، أما المادتان الأخريان فهما مذابان.', '["المذيب هو الماء","المذابان: كلوريد البوتاسيوم والسكروز","المحلول مائي لأن مذيبه الماء","المذيب هو أكبر المكونات، والماء أكبرها كتلة، فلا يوجد مذيب آخر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المذيب مع سبب كونه مذيبًا (أكبر المكونات)","marks":2},{"element":"تحديد المذابين","marks":2},{"element":"تعليل كون المحلول مائيًّا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد المذيب والمذابين بصورة صحيحة مع تعليل مبني على أكبر المكونات وكون المذيب ماء"},{"level":"3–4 درجات","description":"تحديد صحيح للمذيب والمذابين مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح لعنصر واحد فقط (المذيب أو أحد المذابين)"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ السكروز أو كلوريد البوتاسيوم مذيبًا لأنه صلب أو لأنه أول ما أُضيف","عدّ مذابًا واحدًا فقط","عدم الربط بين كون الماء أكبر المكونات وتسميته مذيبًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.829Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالمحلول المائي هو الذي يكون مذيبه الماء. في محلول الإيثانول في الماء يكون الماء أكبر المكونات فهو المذيب والإيثانول مذاب، فالمحلول مائي. أما في محلول اليود في كمية أكبر من الإيثانول فالمذيب هو الإيثانول لأنه أكبر المكونات، واليود مذاب، فالمحلول ليس مائيًّا. إذن لا يكفي أن يكون المحلول سائلًا ليُعدّ مائيًّا.', '["الحكم: العبارة غير صحيحة","المحلول المائي مذيبه الماء","الإيثانول في الماء: الماء مذيب فالمحلول مائي","اليود في الإيثانول: الإيثانول مذيب فالمحلول ليس مائيًّا"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة بأنها غير صحيحة مع ذكر شرط المحلول المائي (المذيب ماء)","marks":1},{"element":"تحليل مثال الإيثانول في الماء","marks":2},{"element":"تحليل مثال اليود في الإيثانول","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع شرط المحلول المائي، وتحليل المثالين بتحديد المذيب والمذاب في كل منهما"},{"level":"3–4 درجات","description":"حكم صحيح وتحليل صحيح لمثال واحد، أو تحليل المثالين دون ذكر شرط المحلول المائي"},{"level":"1–2 درجة","description":"حكم صحيح دون تحليل كافٍ للمثالين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن المحلول سائل","عدّ الإيثانول مذيبًا في المثال الأول لأنه سائل","عدم تحديد المذيب في المثال الثاني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.829Z"}'::jsonb)
