from (values
('mcq', 1, 2, 'السكروز مركب جزيئي (تساهمي) يذوب في الماء على شكل جزيئات تنتشر في المحلول دون أن تتكوّن أيونات؛ فالصحيح هو «يذوب على شكل جزيئات دون تكوين أيونات».', '["التفكك إلى أيونات يحدث للمركبات الأيونية، والسكروز مركب جزيئي.","السكروز ليس حمضًا ولا ينتج أيونات هيدروجين عند ذوبانه.","","لا تتحلل جزيئات السكروز إلى ذرات عند الذوبان؛ بل تبقى جزيئات كاملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.829Z"}'::jsonb),
('mcq', 2, 0, 'HCl مركب جزيئي يكوّن أيونات عند ذوبانه في الماء، وتُسمّى هذه العملية التأين: HCl(aq) → H⁺(aq) + Cl⁻(aq)؛ أي أنه «يتأين مكوّنًا أيونات H⁺ وCl⁻».', '["","هذا ما يحدث للسكروز والإيثانول، أما HCl فيتأين إلى أيونات.","الناتج أيونات مشحونة (H⁺ وCl⁻) وليس ذرات متعادلة.","لا يتكوّن راسب عند ذوبان HCl في الماء؛ بل يتكوّن محلول يحتوي أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:27:04.829Z"}'::jsonb),
('mcq', 3, 3, 'المركبات الأيونية مكوّنة أصلًا من أيونات موجبة وسالبة، وعند ذوبانها تنفصل أيوناتها عن بعض، وتُسمّى هذه العملية التفكك؛ فالإجابة هي «التفكك».', '["التأين اسم عملية تكوّن الأيونات من مركب جزيئي عند ذوبانه، مثل HCl.","الترسيب هو تكوّن مادة صلبة غير ذائبة في المحلول، وليس انفصال الأيونات.","التبخر تحوّل السائل إلى غاز، وليس انفصال الأيونات في المحلول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.830Z"}'::jsonb),
('mcq', 4, 1, 'الإيثانول (الكحول) مركب جزيئي يذوب في الماء على شكل جزيئات، أما HCl فيتأين، وNaCl وNaOH مركبان أيونيان تتفكك أيوناتهما؛ فالإجابة «الإيثانول C₂H₅OH».', '["HCl مركب جزيئي لكنه يتأين في الماء مكوّنًا H⁺ وCl⁻.","","NaCl مركب أيوني تنفصل أيوناته Na⁺ وCl⁻ عند الذوبان.","NaOH مركب أيوني تنفصل أيوناته Na⁺ وOH⁻ عند الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.830Z"}'::jsonb),
('mcq', 5, 0, 'HCl مركب جزيئي لا يحتوي أيونات قبل الذوبان، وتتكوّن الأيونات عند ذوبانه (تأين)، أما NaCl فمركب أيوني أيوناته موجودة في بلورته وتنفصل عن بعضها عند الذوبان (تفكك)؛ وهذا ما تنص عليه العبارة الصحيحة: HCl مركب جزيئي يكوّن أيونات عند ذوبانه، أما NaCl فأيوناته موجودة أصلًا وتنفصل عند ذوبانه.', '["","العبارة تعكس الأدوار؛ فـ HCl جزيئي وNaCl أيوني.","كلوريد الصوديوم مركب أيوني وليس جزيئيًّا، وسرعة الذوبان لا تميّز التأين من التفكك.","التأين للمركبات الجزيئية والتفكك للمركبات الأيونية، وليس العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.830Z"}'::jsonb),
('mcq', 6, 1, 'التأين تكوّن أيونات من مركب جزيئي عند ذوبانه، وهذا ما تمثله المعادلة HCl(aq) → H⁺(aq) + Cl⁻(aq) لأن HCl مركب جزيئي ينتج أيونات.', '["هذه معادلة تفكك مركب أيوني، وليست تأين مركب جزيئي.","","السكروز مركب جزيئي يذوب على شكل جزيئات ولا ينتج أيونات.","الإيثانول مركب جزيئي يذوب على شكل جزيئات ولا ينتج أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.830Z"}'::jsonb),
('mcq', 7, 3, 'بعض المركبات التساهمية مثل السكروز والإيثانول تذوب على شكل جزيئات، وبعضها مثل HCl يكوّن أيونات؛ فلا تتأين جميعها، والإجابة «لأن بعضها كالسكروز يذوب على شكل جزيئات وبعضها كـ HCl يكوّن أيونات».', '["كثير من المركبات التساهمية تذوب في الماء، مثل السكروز والإيثانول وHCl.","جزيئات المركبات التساهمية لا تتحول إلى ذرات عند الذوبان؛ بعضها يبقى جزيئات وبعضها يكوّن أيونات.","التأين يحدث في مركبات تساهمية مثل HCl؛ أما المركبات الأيونية فيحدث لها التفكك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.830Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السكروز مركب جزيئي يذوب على شكل جزيئات؛ فالجسيمات في المحلول جزيئات سكروز، ولا تتكوّن أيونات. كلوريد الهيدروجين مركب جزيئي يكوّن أيونات عند ذوبانه؛ فالجسيمات في المحلول أيونات H⁺ وCl⁻، والعملية تأين: HCl(aq) → H⁺(aq) + Cl⁻(aq). كلوريد الصوديوم مركب أيوني تنفصل أيوناته عن بعض عند ذوبانه؛ فالجسيمات في المحلول أيونات Na⁺ وCl⁻، والعملية تفكك.', '["السكروز: يذوب جزيئات","HCl: يتأين إلى H⁺ وCl⁻","NaCl: يتفكك إلى Na⁺ وCl⁻","تسمية العملية الصحيحة لكل مادة"]'::jsonb, '[]'::jsonb, '[{"element":"السكروز: الجسيمات الناتجة ونوع العملية","marks":2},{"element":"HCl: الجسيمات الناتجة والتأين","marks":2},{"element":"NaCl: الجسيمات الناتجة والتفكك","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد الجسيمات الناتجة ونوع العملية لكل من المواد الثلاث تحديدًا صحيحًا"},{"level":"4–5 درجات","description":"تحديد صحيح لمادتين كاملتين وجزء صحيح من الثالثة"},{"level":"2–3 درجات","description":"تحديد صحيح لمادة واحدة كاملة أو أجزاء صحيحة متفرقة"},{"level":"1 درجة","description":"ذكر جسيمات صحيحة لمادة واحدة دون تسمية العملية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن NaCl يتأين وإن HCl يتفكك (عكس المصطلحين)","القول إن السكروز يتحلل إلى أيونات","عدّ HCl يذوب على شكل جزيئات فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:27:04.831Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المركب الأيوني (مثل NaCl) يحتوي على أيونات موجبة وسالبة، وعند ذوبانه تنفصل أيوناته عن بعض (تفكك)، فيحتوي المحلول أيونات. أما المركب التساهمي فبعضه يذوب على شكل جزيئات (مثل السكروز والإيثانول) فيحتوي المحلول جزيئات، وبعضه يكوّن أيونات عند ذوبانه (مثل HCl الذي يتأين إلى H⁺ وCl⁻). لذلك لا تتأين المواد التساهمية جميعها؛ فالسكروز يذوب جزيئات والمثال المقابل HCl يتأين.', '["المركب الأيوني تنفصل أيوناته عند الذوبان (تفكك)","بعض المركبات التساهمية تذوب جزيئات","بعض المركبات التساهمية تكوّن أيونات (تأين)","لا تتأين المواد التساهمية جميعها","مثالان صحيحان (السكروز أو الإيثانول، وHCl)"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المركب الأيوني المذاب (أيونات منفصلة / تفكك)","marks":1},{"element":"وصف المركب التساهمي المذاب (جزيئات أو أيونات)","marks":1},{"element":"الجواب بأنها لا تتأين جميعها","marks":1},{"element":"مثالان صحيحان يدعمان الإجابة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تمييز صحيح بين النوعين، وإجابة بأن المواد التساهمية لا تتأين جميعها مع مثالين صحيحين"},{"level":"2–3 درجات","description":"تمييز صحيح مع إجابة صحيحة لكن بمثال واحد أو دون أمثلة كافية"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن جميع المركبات التساهمية تتأين","القول إن المركبات الأيونية تذوب جزيئات","ذكر مثالين من النوع نفسه دون إظهار الاختلاف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.831Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحلول (أ): المذاب هو HCl وهو مركب جزيئي، وقد تأين عند ذوبانه إلى H⁺ وCl⁻؛ ولأنه ينتج أيونات هيدروجين فهو حمض، ويُسمّى المحلول حمض الهيدروكلوريك. المحلول (ب): المذاب NaCl وهو مركب أيوني، وقد تفكك عند ذوبانه فانفصلت أيوناته Na⁺ وCl⁻. المحلول (ج): المذاب هو الإيثانول وهو مركب جزيئي ذاب على شكل جزيئات دون أن يتكوّن أيونات.', '["(أ) HCl مركب جزيئي يتأين","(أ) اسم المحلول حمض الهيدروكلوريك لأنه ينتج أيونات الهيدروجين","(ب) NaCl مركب أيوني يتفكك","(ج) الإيثانول مركب جزيئي يذوب جزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"المحلول (أ): المذاب ونوعه والتأين","marks":2},{"element":"تسمية المحلول (أ) حمض الهيدروكلوريك مع التعليل","marks":1},{"element":"المحلول (ب): المذاب ونوعه والتفكك","marks":2},{"element":"المحلول (ج): المذاب ونوعه والذوبان جزيئات","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحديد المذاب ونوعه والعملية في المحاليل الثلاثة وتسمية المحلول (أ) تسمية صحيحة مع التعليل"},{"level":"4–5 درجات","description":"تحديد صحيح لمحلولين كاملين مع جزء من الثالث أو من التسمية"},{"level":"2–3 درجات","description":"تحديد صحيح لمحلول واحد كامل أو أجزاء متفرقة صحيحة"},{"level":"1 درجة","description":"تحديد مذاب واحد فقط تحديدًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المحلول (أ) ناتج تفكك مركب أيوني","عدم تسمية HCl حمضًا مع أنه ينتج أيونات الهيدروجين","القول إن الإيثانول تأين لأنه ذاب في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.831Z"}'::jsonb)
