select (select id from public.objectives where code = 'K1-C4-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الفرق الأساسي بين المعادلة الأيونية الكاملة والمعادلة الأيونية النهائية؟', null, '["الكاملة تُكتب بالصيغ الجزيئية لجميع المواد، والنهائية تُكتب بالأيونات فقط","الكاملة غير موزونة، والنهائية موزونة من حيث عدد الذرات","الكاملة تُظهر الجسيمات المشاركة في التفاعل فقط، والنهائية تُظهر جميع الجسيمات في المحلول","الكاملة تُظهر جميع الجسيمات في المحلول، والنهائية تقتصر على الجسيمات المشاركة في التفاعل"]'::jsonb, 'فهم', 'تمييز بين معادلتين', 'سهل', 'الكتاب ص 135 — المعادلات الأيونية'),
('mcq', 2, 'في المعادلة الأيونية الكاملة الآتية: 2Na⁺(aq) + 2OH⁻(aq) + Cu²⁺(aq) + 2Cl⁻(aq) → 2Na⁺(aq) + 2Cl⁻(aq) + Cu(OH)₂(s)، أيّ الأيونات تظهر في المعادلة الكاملة ولا تظهر في المعادلة النهائية؟', null, '["OH⁻ وCu²⁺","Na⁺ وCl⁻","Na⁺ وOH⁻","Cu²⁺ وCl⁻"]'::jsonb, 'فهم', 'تحديد ما يُحذف عند الانتقال من الكاملة إلى النهائية', 'سهل', 'الكتاب ص 135 — المعادلات الأيونية'),
('mcq', 3, 'تفاعل Ba(NO₃)₂(aq) مع Na₂CO₃(aq) يكوّن راسب BaCO₃(s). كم نوعًا مختلفًا من الأيونات يظهر في معادلته الأيونية الكاملة، وكم نوعًا في معادلته الأيونية النهائية؟', null, '["4 أنواع في الكاملة و4 أنواع في النهائية","نوعان في الكاملة و4 أنواع في النهائية","4 أنواع في الكاملة ونوعان في النهائية","6 أنواع في الكاملة ونوعان في النهائية"]'::jsonb, 'تحليل', 'تحليل مكوّنات المعادلتين', 'متوسط', 'الكتاب ص 136 — مثال 4-3'),
('mcq', 4, 'أيّ العبارات الآتية صحيحة عند مقارنة المعادلتين الأيونيتين الكاملة والنهائية للتفاعل نفسه؟', null, '["كلتاهما موزونة، لكن النهائية تحتوي على عدد أقل من الجسيمات","النهائية تحتوي على الأيونات المتفرجة أيضًا، أما الكاملة فلا تحتويها","تختلف الكاملة عن النهائية في نوع الراسب أو الغاز الناتج","تُكتب الكاملة قبل موازنة المعادلة، وتُكتب النهائية بعد موازنتها"]'::jsonb, 'تحليل', 'تقويم عبارات المقارنة', 'متوسط', 'الكتاب ص 135–136 — المعادلات الأيونية، مثال 4-3'),
('mcq', 5, 'تفاعل التعادل بين HBr(aq) وNaOH(aq) تُكتب معادلته الأيونية الكاملة: H⁺ + Br⁻ + Na⁺ + OH⁻ → H₂O + Na⁺ + Br⁻. أراد طالب أن يُظهر الجسيمات التي شاركت فعلًا في التفاعل فقط دون الجسيمات التي لم تتغير. أيّ نوع من المعادلات يكتب؟', null, '["المعادلة الرمزية الموزونة","المعادلة الأيونية الكاملة","المعادلة الأيونية النهائية","المعادلة اللفظية"]'::jsonb, 'فهم', 'اختيار المعادلة المناسبة لغرض', 'سهل', 'الكتاب ص 137 — التفاعلات التي تكوّن ماء'),
('mcq', 6, 'أيّ الجسيمات الآتية تظهر في كلٍّ من المعادلة الأيونية الكاملة والمعادلة الأيونية النهائية للتفاعل نفسه؟', null, '["الأيونات المتفرجة التي لا تتغير أثناء التفاعل","الجسيمات المشاركة في التفاعل المتفاعلة والناتجة","الأيونات التي تبقى ذائبة في المحلول بعد التفاعل","جميع الأيونات الموجودة في المحلول قبل التفاعل"]'::jsonb, 'تحليل', 'تحديد المشترك بين المعادلتين', 'متوسط', 'الكتاب ص 135، 137 — المعادلات الأيونية'),
('mcq', 7, 'تفاعلان في محلول مائي: (1) HCl(aq) + NaOH(aq) → H₂O(l) + NaCl(aq)، و(2) HNO₃(aq) + NaOH(aq) → H₂O(l) + NaNO₃(aq). ما العبارة الصحيحة عند مقارنة معادلتيهما الأيونيتين؟', null, '["الكاملتان مختلفتان في أيوناتهما المتفرجة، أما النهائيتان فمتماثلتان: H⁺(aq) + OH⁻(aq) → H₂O(l)","الكاملتان متماثلتان تمامًا، أما النهائيتان فمختلفتان لاختلاف الحمضين","الكاملتان والنهائيتان جميعًا مختلفة لأن لكل تفاعل مواد متفاعلة مختلفة","الكاملتان والنهائيتان جميعًا متماثلة لأن القاعدة المتفاعلة في التفاعلين واحدة"]'::jsonb, 'تحليل', 'تحليل مقارن لتفاعلين', 'صعب', 'الكتاب ص 137–138 — التفاعلات التي تكوّن ماء، مثال 4-4'),
('essay', 1, 'للتفاعل 2NaOH(aq) + CuCl₂(aq) → Cu(OH)₂(s) + 2NaCl(aq): اكتب المعادلة الأيونية الكاملة والمعادلة الأيونية النهائية، ثم قارن بينهما من حيث الجسيمات التي تظهر في كل منهما.', null, null, 'تحليل', 'كتابة ومقارنة معادلتين', 'متوسط', 'الكتاب ص 134–135 — التفاعلات التي تكوّن راسبًا، المعادلات الأيونية'),
('essay', 2, 'يتفاعل HBr(aq) مع NaOH(aq) فينتج H₂O(l) وNaBr(aq)، ويتفاعل HCl(aq) مع LiOH(aq) فينتج H₂O(l) وLiCl(aq). اكتب المعادلة الأيونية النهائية لكل تفاعل، وحدّد الأيونات المتفرجة فيه، ثم فسّر لماذا تتشابه المعادلتان النهائيتان رغم اختلاف أيوناتهما المتفرجة.', null, null, 'تحليل', 'تحليل مقارن لتفاعلين', 'صعب', 'الكتاب ص 137–138 — التفاعلات التي تكوّن ماء، مثال 4-4'),
('essay', 3, 'قالت طالبة: «الأيونات المتفرجة غير موجودة في المحلول؛ ولهذا لا تظهر في المعادلة الأيونية النهائية». قوّم هذه العبارة، ووضّح الفرق بين ما تُظهره المعادلة الكاملة وما تُظهره المعادلة النهائية، مستعينًا بتفاعل HBr مع NaOH.', null, null, 'تقويم', 'تقويم عبارة مع تدعيم بمعادلات', 'صعب', 'الكتاب ص 135، 137 — الأيونات المتفرجة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المعادلة الأيونية الكاملة تبيّن جميع الجسيمات في المحلول بما فيها الأيونات المتفرجة، وبحذف المتفرجة نحصل على المعادلة النهائية التي تشتمل على الجسيمات المشاركة في التفاعل فقط؛ فالصحيح هو الخيار الأخير.', '["المعادلة الكاملة تكتب المواد الذائبة الأيونية على شكل أيونات، وليس بصيغ جزيئية.","كلتا المعادلتين موزونة؛ ولا يكمن الفرق في الموازنة.","هذا عكس الصحيح؛ فالنهائية هي التي تقتصر على الجسيمات المشاركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.833Z"}'::jsonb),
('mcq', 2, 1, 'أيونا Na⁺ وCl⁻ يظهران في طرفي المعادلة بالصورة نفسها فهما متفرجان، ويُحذفان عند كتابة المعادلة النهائية 2OH⁻ + Cu²⁺ → Cu(OH)₂(s)؛ فالإجابة «Na⁺ وCl⁻».', '["أيونا OH⁻ وCu²⁺ يشاركان في تكوين الراسب، فيبقيان في المعادلة النهائية.","","OH⁻ يشارك في التفاعل فيبقى في المعادلة النهائية، وليس متفرجًا.","Cu²⁺ يشارك في تكوين الراسب فيبقى في المعادلة النهائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:27:04.833Z"}'::jsonb),
('mcq', 3, 2, 'المعادلة الكاملة: Ba²⁺ + 2NO₃⁻ + 2Na⁺ + CO₃²⁻ → BaCO₃(s) + 2Na⁺ + 2NO₃⁻، وفيها أربعة أنواع من الأيونات (Ba²⁺ وNO₃⁻ وNa⁺ وCO₃²⁻). وبحذف المتفرجين Na⁺ وNO₃⁻ تبقى في النهائية Ba²⁺ وCO₃²⁻ فقط؛ أي نوعان.', '["النهائية لا تحتوي الأيونات المتفرجة، فعدد أنواع أيوناتها أقل من الكاملة.","هذا عكس الصحيح؛ فالكاملة أكثر أنواعًا من النهائية.","","الخطأ هنا عدّ الأيونات بحسب المعاملات (2NO₃⁻ تُحسب نوعًا واحدًا لا نوعين)؛ والكاملة فيها 4 أنواع فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.833Z"}'::jsonb),
('mcq', 4, 0, 'المعادلتان موزونتان لأن عدد الذرات متساوٍ في الطرفين، والنهائية تشمل جسيمات أقل لأن الأيونات المتفرجة حُذفت منها؛ فالعبارة الصحيحة هي أن كلتيهما موزونة وأن النهائية تحتوي عددًا أقل من الجسيمات.', '["","الأيونات المتفرجة تظهر في الكاملة فقط وتُحذف من النهائية، فالعبارة معكوسة.","الناتج الأساسي (الراسب أو الغاز أو الماء) يظهر في المعادلتين نفسه؛ والفرق في الأيونات المتفرجة.","الموازنة تتم قبل كتابة المعادلة الأيونية الكاملة، وتُشتق النهائية منها بحذف المتفرجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.833Z"}'::jsonb),
('mcq', 5, 2, 'المعادلة التي تشتمل على الجسيمات المشاركة في التفاعل فقط هي المعادلة الأيونية النهائية: H⁺(aq) + OH⁻(aq) → H₂O(l)؛ لأنها تُكتب بعد حذف الأيونات المتفرجة Na⁺ وBr⁻.', '["المعادلة الرمزية تكتب الصيغ الجزيئية للمواد ولا تُظهر الأيونات المشاركة.","الكاملة تُظهر جميع الأيونات بما فيها المتفرجة Na⁺ وBr⁻.","","المعادلة اللفظية تذكر أسماء المواد ولا تُظهر الجسيمات المشاركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.834Z"}'::jsonb),
('mcq', 6, 1, 'الجسيمات المشاركة في التفاعل (المتفاعلة والناتجة منها) تبقى في المعادلتين، أما الأيونات المتفرجة فتظهر في الكاملة فقط؛ فالإجابة «الجسيمات المشاركة في التفاعل».', '["الأيونات المتفرجة تُحذف من النهائية فلا تظهر فيها.","","الأيونات الذائبة بعد التفاعل قد تكون متفرجة، وهي تُحذف من النهائية.","جميع الأيونات قبل التفاعل تظهر في الكاملة فقط؛ أما النهائية فتقتصر على المشاركة منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.834Z"}'::jsonb),
('mcq', 7, 0, 'في (1) المتفرجان Na⁺ وCl⁻ وفي (2) المتفرجان Na⁺ وNO₃⁻، فالكاملتان مختلفتان؛ لكن بحذف المتفرجين تتماثل النهائيتان: H⁺ + OH⁻ → H₂O؛ فالعبارة الصحيحة هي الأولى.', '["","الكاملتان تختلفان في أيون Cl⁻ مقابل NO₃⁻، والنهائيتان متماثلتان وليستا مختلفتين.","النهائيتان متماثلتان لأن الجسيمات المشاركة في التفاعلين واحدة (H⁺ وOH⁻).","الكاملتان تختلفان لأن الأيون السالب للحمضين مختلف (Cl⁻ مقابل NO₃⁻)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.834Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعادلة الأيونية الكاملة: 2Na⁺(aq) + 2OH⁻(aq) + Cu²⁺(aq) + 2Cl⁻(aq) → 2Na⁺(aq) + 2Cl⁻(aq) + Cu(OH)₂(s). الأيونان المتفرجان هما Na⁺ وCl⁻ لأنهما يظهران في طرفي المعادلة ولم يشاركا في التفاعل. المعادلة الأيونية النهائية: 2OH⁻(aq) + Cu²⁺(aq) → Cu(OH)₂(s). المقارنة: تبيّن الكاملة جميع الجسيمات في المحلول، ومنها المتفرجة (Na⁺ وCl⁻)؛ أما النهائية فتقتصر على الجسيمات المشاركة في التفاعل فقط (OH⁻ وCu²⁺ والراسب Cu(OH)₂)، وعدد المواد فيها أقل. وكلتاهما موزونة.', '["المعادلة الكاملة صحيحة بالأيونات والحالات","تحديد الأيونين المتفرجين Na⁺ وCl⁻","المعادلة النهائية 2OH⁻ + Cu²⁺ → Cu(OH)₂(s)","الكاملة تُظهر جميع الجسيمات، والنهائية الجسيمات المشاركة فقط"]'::jsonb, '["اكتب المركبات الأيونية الذائبة على شكل أيونات وأبقِ الراسب Cu(OH)₂(s) بصيغته: 2Na⁺ + 2OH⁻ + Cu²⁺ + 2Cl⁻ → 2Na⁺ + 2Cl⁻ + Cu(OH)₂(s)","حدّد الأيونات التي تظهر في طرفي المعادلة بالصورة نفسها: Na⁺ وCl⁻ (متفرجة)","احذف الأيونات المتفرجة من الطرفين: 2OH⁻ + Cu²⁺ → Cu(OH)₂(s)","قارن: الكاملة تحتوي جميع الجسيمات والنهائية الجسيمات المشاركة فقط"]'::jsonb, '[{"element":"المعادلة الأيونية الكاملة الصحيحة","marks":2},{"element":"تحديد الأيونين المتفرجين","marks":1},{"element":"المعادلة الأيونية النهائية الصحيحة","marks":1},{"element":"المقارنة بين ما تُظهره كل معادلة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلتان صحيحتان مع الحالات، وتحديد المتفرجين، ومقارنة صحيحة"},{"level":"4–5 درجات","description":"معادلتان صحيحتان مع نقص في الحالات أو في المقارنة"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة مع تحديد المتفرجين، أو مقارنة دون معادلات دقيقة"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Cu(OH)₂ على شكل أيونات","حذف Cu²⁺ أو OH⁻ على أنهما متفرجان","إهمال المعاملات عند كتابة المعادلة الكاملة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:27:04.834Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التفاعل الأول: الأيونات المتفرجة Na⁺ وBr⁻، والمعادلة النهائية H⁺(aq) + OH⁻(aq) → H₂O(l). التفاعل الثاني: الأيونات المتفرجة Li⁺ وCl⁻، والمعادلة النهائية H⁺(aq) + OH⁻(aq) → H₂O(l). تتشابه المعادلتان النهائيتان لأن النهائية لا تتضمن الأيونات المتفرجة بل الجسيمات المشاركة في التفاعل فقط، وهي في التفاعلين أيون الهيدروجين H⁺ من الحمض وأيون الهيدروكسيد OH⁻ من القاعدة اللذان يتحدان لتكوين الماء؛ أما اختلاف المتفرجة فيظهر في الكاملتين فقط.', '["المتفرجة في الأول Na⁺ وBr⁻","المتفرجة في الثاني Li⁺ وCl⁻","النهائية في التفاعلين H⁺ + OH⁻ → H₂O(l)","الجسيمات المشاركة واحدة في التفاعلين (H⁺ وOH⁻)","المتفرجة لا تظهر في النهائية فلا تؤثر في تشابهها"]'::jsonb, '["التفاعل 1: H⁺ + Br⁻ + Na⁺ + OH⁻ → H₂O + Na⁺ + Br⁻ ؛ المتفرجة Na⁺ وBr⁻ ؛ النهائية H⁺ + OH⁻ → H₂O","التفاعل 2: H⁺ + Cl⁻ + Li⁺ + OH⁻ → H₂O + Li⁺ + Cl⁻ ؛ المتفرجة Li⁺ وCl⁻ ؛ النهائية H⁺ + OH⁻ → H₂O","قارن: الجسيمات المشاركة واحدة (H⁺ وOH⁻) فتتشابه النهائيتان، وتختلف الكاملتان في المتفرجة"]'::jsonb, '[{"element":"المعادلة النهائية الصحيحة للتفاعل الأول","marks":1},{"element":"المعادلة النهائية الصحيحة للتفاعل الثاني","marks":1},{"element":"تحديد المتفرجة في التفاعلين","marks":1},{"element":"تفسير التشابه بأن المشاركة واحدة وأن المتفرجة تُحذف","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان نهائيتان صحيحتان، وتحديد المتفرجة في كل تفاعل، وتفسير صحيح للتشابه"},{"level":"3–4 درجات","description":"معادلتان صحيحتان مع تحديد المتفرجة وتفسير ناقص"},{"level":"1–2 درجة","description":"معادلة نهائية واحدة صحيحة أو تحديد المتفرجة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء Na⁺ أو Li⁺ في المعادلة النهائية","القول إن الأيونات المتفرجة تشارك في تكوين الماء","كتابة H₂O على شكل أيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.835Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. الأيونات المتفرجة (Na⁺ وBr⁻ في تفاعل HBr مع NaOH) موجودة في المحلول قبل التفاعل وبعده، وهي تظهر في المعادلة الأيونية الكاملة على جانبي المعادلة بالصورة نفسها: H⁺ + Br⁻ + Na⁺ + OH⁻ → H₂O + Na⁺ + Br⁻. ولا تظهر في المعادلة النهائية لأنها لم تشارك في التفاعل، فتُحذف منها وتبقى الجسيمات المشاركة فقط: H⁺(aq) + OH⁻(aq) → H₂O(l). فالكاملة تبيّن جميع الجسيمات في المحلول، والنهائية تبيّن المشاركة فقط.', '["الحكم: العبارة غير صحيحة","المتفرجة موجودة في المحلول ولا تشارك في التفاعل","المتفرجة تظهر في الكاملة على الطرفين","النهائية H⁺ + OH⁻ → H₂O تقتصر على المشاركة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن العبارة غير صحيحة مع بيان وجود المتفرجة في المحلول","marks":1},{"element":"بيان سبب غيابها عن النهائية (لا تشارك في التفاعل)","marks":1},{"element":"كتابة المعادلة الكاملة والنهائية لتفاعل HBr مع NaOH","marks":1},{"element":"توضيح الفرق بين ما تُظهره كل معادلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل، ومعادلتان صحيحتان، وتوضيح الفرق"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو معادلات ناقصة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة وعدّ المتفرجة غير موجودة","الخلط بين حذف الأيون من المعادلة وانعدام وجوده في المحلول","عدم كتابة المعادلتين لإثبات الفرق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.835Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C4-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في التفاعل Ba(NO₃)₂(aq) + Na₂CO₃(aq) → BaCO₃(s) + 2NaNO₃(aq)، أيّ المواد الآتية تُكتب بصيغتها كاملة دون تفكك إلى أيونات عند كتابة المعادلة الأيونية الكاملة؟', null, '["Ba(NO₃)₂(aq)","NaNO₃(aq)","BaCO₃(s)","Na₂CO₃(aq)"]'::jsonb, 'تذكر', 'تحديد المواد التي لا تُفكَّك عند كتابة المعادلة الكاملة', 'سهل', 'الكتاب ص 136 — مثال 4-3'),
('mcq', 2, 'عند خلط محلول يوديد البوتاسيوم KI مع محلول نترات الفضة AgNO₃ يتكوّن راسب AgI ويبقى KNO₃ ذائبًا: KI(aq) + AgNO₃(aq) → AgI(s) + KNO₃(aq). ما المعادلة الأيونية النهائية لهذا التفاعل؟', null, '["Ag⁺(aq) + I⁻(aq) → AgI(s)","K⁺(aq) + NO₃⁻(aq) → KNO₃(s)","Ag⁺(aq) + 2I⁻(aq) → AgI₂(s)","AgNO₃(aq) + KI(aq) → AgI(s) + KNO₃(aq)"]'::jsonb, 'تطبيق', 'كتابة المعادلة الأيونية النهائية لتفاعل ترسيب', 'متوسط', 'الكتاب ص 136 — مسألة تدريبية 39'),
('mcq', 3, 'يتفاعل حمض الكبريتيك H₂SO₄(aq) مع محلول هيدروكسيد البوتاسيوم وفق المعادلة: H₂SO₄(aq) + 2KOH(aq) → K₂SO₄(aq) + 2H₂O(l). ما المعادلة الأيونية الكاملة الصحيحة لهذا التفاعل؟', null, '["H₂SO₄(aq) + 2K⁺(aq) + 2OH⁻(aq) → 2K⁺(aq) + SO₄²⁻(aq) + 2H₂O(l)","2H⁺(aq) + SO₄²⁻(aq) + 2K⁺(aq) + 2OH⁻(aq) → 2K⁺(aq) + SO₄²⁻(aq) + 2H⁺(aq) + 2OH⁻(aq)","H⁺(aq) + SO₄²⁻(aq) + K⁺(aq) + OH⁻(aq) → K⁺(aq) + SO₄²⁻(aq) + H₂O(l)","2H⁺(aq) + SO₄²⁻(aq) + 2K⁺(aq) + 2OH⁻(aq) → 2K⁺(aq) + SO₄²⁻(aq) + 2H₂O(l)"]'::jsonb, 'تطبيق', 'كتابة المعادلة الأيونية الكاملة لتفاعل تكوّن ماء', 'متوسط', 'الكتاب ص 138 — مسألة تدريبية 44'),
('mcq', 4, 'يتفاعل حمض النيتريك HNO₃(aq) مع محلول كبريتيد البوتاسيوم K₂S(aq) فيتصاعد غاز كبريتيد الهيدروجين: 2HNO₃(aq) + K₂S(aq) → H₂S(g) + 2KNO₃(aq). ما المعادلة الأيونية النهائية الموزونة؟', null, '["H⁺(aq) + S²⁻(aq) → H₂S(g)","2H⁺(aq) + S²⁻(aq) → H₂S(g)","2H⁺(aq) + 2NO₃⁻(aq) + S²⁻(aq) → H₂S(g) + 2NO₃⁻(aq)","2K⁺(aq) + S²⁻(aq) → K₂S(s)"]'::jsonb, 'تطبيق', 'كتابة المعادلة الأيونية النهائية لتفاعل تكوّن غاز', 'متوسط', 'الكتاب ص 139، 141 — مثال 4-5، مسألة تدريبية 52'),
('mcq', 5, 'يتفاعل حمض الهيدروكلوريك مع محلول كربونات الصوديوم الهيدروجينية وفق المعادلة: HCl(aq) + NaHCO₃(aq) → H₂O(l) + CO₂(g) + NaCl(aq). ما المعادلة الأيونية النهائية لهذا التفاعل؟', null, '["2H⁺(aq) + CO₃²⁻(aq) → H₂O(l) + CO₂(g)","H⁺(aq) + Na⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g) + Na⁺(aq)","H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)","H⁺(aq) + HCO₃⁻(aq) → H₂CO₃(aq)"]'::jsonb, 'تطبيق', 'كتابة المعادلة الأيونية النهائية لتفاعل حمض مع بيكربونات', 'صعب', 'الكتاب ص 140 — التفاعلات التي تكوّن غازات'),
('mcq', 6, 'عند خلط محلولي كلوريد الألومنيوم AlCl₃ وهيدروكسيد الصوديوم NaOH يتكوّن راسب من هيدروكسيد الألومنيوم Al(OH)₃ ويبقى كلوريد الصوديوم ذائبًا. ما المعادلة الأيونية النهائية الموزونة؟', null, '["Al³⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s)","Al³⁺(aq) + OH⁻(aq) → Al(OH)₃(s)","AlCl₃(aq) + 3OH⁻(aq) → Al(OH)₃(s) + 3Cl⁻(aq)","Al³⁺(aq) + 3OH⁻(aq) → Al(OH)₃(aq)"]'::jsonb, 'تطبيق', 'كتابة المعادلة الأيونية النهائية الموزونة بمعاملات', 'صعب', 'الكتاب ص 136 — مسألة تدريبية 41'),
('mcq', 7, 'يتفاعل Al₂(SO₄)₃(aq) مع BaCl₂(aq) وفق المعادلة: Al₂(SO₄)₃(aq) + 3BaCl₂(aq) → 3BaSO₄(s) + 2AlCl₃(aq). ما المعادلة الأيونية النهائية مكتوبة بأبسط نسبة عددية صحيحة؟', null, '["3Ba²⁺(aq) + 3SO₄²⁻(aq) → 3BaSO₄(s)","Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)","2Al³⁺(aq) + 3SO₄²⁻(aq) → Al₂(SO₄)₃(s)","3Ba²⁺(aq) + 6Cl⁻(aq) → 3BaCl₂(s)"]'::jsonb, 'تطبيق', 'كتابة المعادلة النهائية بأبسط نسبة', 'صعب', 'الكتاب ص 141 — مثال 4-5 (أصغر نسبة عددية صحيحة)'),
('essay', 1, 'يتفاعل محلول هيدروكسيد الباريوم Ba(OH)₂ مع محلول حمض الهيدروكلوريك HCl فينتج ماء ومحلول كلوريد الباريوم BaCl₂. اكتب المعادلة الرمزية الموزونة، ثم المعادلة الأيونية الكاملة مع الحالات، ثم المعادلة الأيونية النهائية بأبسط نسبة عددية صحيحة.', null, null, 'تطبيق', 'كتابة ثلاث معادلات لتفاعل تعادل', 'متوسط', 'الكتاب ص 137–138 — التفاعلات التي تكوّن ماء، مثال 4-4'),
('essay', 2, 'يتفاعل حمض النيتريك HNO₃ مع محلول كربونات البوتاسيوم K₂CO₃ فيتصاعد غاز ثاني أكسيد الكربون ويتكوّن ماء ومحلول نترات البوتاسيوم. اكتب المعادلة الرمزية الموزونة، والمعادلة الأيونية الكاملة، والمعادلة الأيونية النهائية، ثم اذكر الأيونين المتفرجين.', null, null, 'تطبيق', 'كتابة المعادلات لتفاعل تكوّن غاز', 'متوسط', 'الكتاب ص 139، 141 — التفاعلات التي تكوّن غازات، مسألة تدريبية 49'),
('essay', 3, 'كتبت طالبة المعادلة الأيونية الكاملة لتفاعل CuSO₄(aq) + Na₂S(aq) → CuS(s) + Na₂SO₄(aq) على النحو الآتي: Cu²⁺(aq) + SO₄²⁻(aq) + Na₂S(aq) → CuS(s) + Na₂SO₄(aq). حدّد الخطأ في ما كتبته، ثم اكتب المعادلة الأيونية الكاملة الصحيحة والمعادلة الأيونية النهائية.', null, null, 'تحليل', 'تصحيح معادلة أيونية خاطئة', 'صعب', 'الكتاب ص 135–136 — المعادلات الأيونية، مثال 4-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O04') and x.type = v.type and x.number = v.number);
