from (values
('mcq', 1, 2, 'المركبات الأيونية الذائبة (aq) تُكتب على شكل أيونات، أما الصلب فيبقى بصيغته؛ وBaCO₃(s) هو الراسب الصلب فيُكتب كاملًا في المعادلة الأيونية الكاملة: Ba²⁺ + 2NO₃⁻ + 2Na⁺ + CO₃²⁻ → BaCO₃(s) + 2Na⁺ + 2NO₃⁻؛ فالإجابة BaCO₃(s).', '["Ba(NO₃)₂ مركب أيوني ذائب في الماء، فيُكتب على شكل Ba²⁺ و2NO₃⁻.","NaNO₃ مركب أيوني ذائب، فيُكتب على شكل Na⁺ وNO₃⁻.","","Na₂CO₃ مركب أيوني ذائب، فيُكتب على شكل 2Na⁺ وCO₃²⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.836Z"}'::jsonb),
('mcq', 2, 0, 'الأيونان المتفرجان هما K⁺ وNO₃⁻ لأنهما يبقيان ذائبين على طرفي المعادلة. المعادلة الكاملة: K⁺ + I⁻ + Ag⁺ + NO₃⁻ → AgI(s) + K⁺ + NO₃⁻، وبحذف المتفرجين تبقى Ag⁺(aq) + I⁻(aq) → AgI(s)؛ فالإجابة هي الخيار الأول.', '["","هذان هما الأيونان المتفرجان، وهما يبقيان ذائبين ولا يكوّنان KNO₃ صلبًا.","صيغة الراسب AgI تتطلب أيونًا واحدًا من Ag⁺ وأيونًا واحدًا من I⁻؛ وكتابة 2I⁻ وAgI₂ خطأ في الصيغة.","هذه المعادلة الرمزية وليست أيونية؛ فهي لم تُكتب بالأيونات ولم تحذف المتفرجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.836Z"}'::jsonb),
('mcq', 3, 3, 'الحمض H₂SO₄ والقاعدة KOH والملح K₂SO₄ مواد أيونية ذائبة فتُكتب أيونات، أما الماء فجزيئي سائل يبقى بصيغته. والمعادلة موزونة بالمعاملات 2H⁺ و2OH⁻ و2K⁺ و2H₂O: 2H⁺ + SO₄²⁻ + 2K⁺ + 2OH⁻ → 2K⁺ + SO₄²⁻ + 2H₂O(l)؛ فالصحيح هو الخيار الأخير.', '["H₂SO₄ المذاب حمض يتأين إلى H⁺ وSO₄²⁻، فلا يُكتب بصيغته الجزيئية.","الماء H₂O(l) جزيئي ولا يُكتب على شكل أيونات؛ كتابته H⁺ وOH⁻ تعني أن التفاعل لم يحدث.","المعادلة غير موزونة: ينقصها المعاملان 2 للأيونات ولماء الناتج، فعدد ذرات H غير متساوٍ في الطرفين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.836Z"}'::jsonb),
('mcq', 4, 1, 'المعادلة الكاملة: 2H⁺ + 2NO₃⁻ + 2K⁺ + S²⁻ → H₂S(g) + 2K⁺ + 2NO₃⁻. الأيونان المتفرجان K⁺ وNO₃⁻ يُحذفان فتبقى 2H⁺(aq) + S²⁻(aq) → H₂S(g)، وهي موزونة ذريًّا وشحنيًّا؛ فالإجابة هي الخيار الثاني.', '["غير موزونة: ذرتا H في H₂S تتطلبان 2H⁺ وليس H⁺ واحدًا.","","حُذف K⁺ فقط وبقي NO₃⁻، وهو أيون متفرج يجب حذفه أيضًا لأنه يظهر على الطرفين.","K⁺ وS²⁻ لا يكوّنان K₂S صلبًا؛ فهذا الملح ذائب وK⁺ أيون متفرج، والتفاعل الفعلي بين H⁺ وS²⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.837Z"}'::jsonb),
('mcq', 5, 2, 'المعادلة الكاملة: H⁺ + Cl⁻ + Na⁺ + HCO₃⁻ → H₂O(l) + CO₂(g) + Na⁺ + Cl⁻. الأيونان المتفرجان Na⁺ وCl⁻ يُحذفان، فتبقى H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)؛ فالإجابة هي الخيار الثالث.', '["أيون الكربونات الهيدروجينية HCO₃⁻ لا يُفكَّك إلى CO₃²⁻ وH⁺ هنا؛ يبقى HCO₃⁻ بصيغته.","بقي Na⁺ على الطرفين وهو أيون متفرج لم يشارك في التفاعل، فيجب حذفه لتصبح المعادلة نهائية.","","هذه خطوة الإحلال المزدوج الأولى فقط؛ فH₂CO₃ يتفكك فورًا إلى H₂O وCO₂ فلا يظهر في المعادلة النهائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:27:04.837Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة الرمزية: AlCl₃ + 3NaOH → Al(OH)₃(s) + 3NaCl. الكاملة: Al³⁺ + 3Cl⁻ + 3Na⁺ + 3OH⁻ → Al(OH)₃(s) + 3Na⁺ + 3Cl⁻. بحذف Na⁺ وCl⁻ المتفرجين تبقى Al³⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s)؛ فالإجابة هي الخيار الأول.', '["","غير موزونة: Al(OH)₃ فيه ثلاث مجموعات OH، فتلزم 3OH⁻ لتتعادل الشحنة +3 لأيون الألومنيوم.","AlCl₃ مركب أيوني ذائب فيجب كتابته أيونات؛ وأيون Cl⁻ متفرج ولا يظهر في المعادلة النهائية.","الراسب مادة صلبة، فحالته (s) وليست (aq)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.837Z"}'::jsonb),
('mcq', 7, 1, 'الكاملة: 2Al³⁺ + 3SO₄²⁻ + 3Ba²⁺ + 6Cl⁻ → 3BaSO₄(s) + 2Al³⁺ + 6Cl⁻. بحذف Al³⁺ وCl⁻ تبقى 3Ba²⁺ + 3SO₄²⁻ → 3BaSO₄(s)، وبقسمة المعاملات على 3 نحصل على Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)؛ فالإجابة هي الخيار الثاني.', '["صحيحة كيميائيًّا لكنها ليست بأبسط نسبة؛ يجب قسمة جميع المعاملات على 3.","","Al₂(SO₄)₃ مركب ذائب وأيونا Al³⁺ وSO₄²⁻ لا يكوّنان راسبًا؛ فهذه ليست المعادلة الفعلية.","BaCl₂ مركب ذائب؛ فأيون Cl⁻ متفرج ولا يتكوّن BaCl₂ صلبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.837Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعادلة الرمزية الموزونة: Ba(OH)₂(aq) + 2HCl(aq) → 2H₂O(l) + BaCl₂(aq). المعادلة الأيونية الكاملة: Ba²⁺(aq) + 2OH⁻(aq) + 2H⁺(aq) + 2Cl⁻(aq) → 2H₂O(l) + Ba²⁺(aq) + 2Cl⁻(aq). الأيونان المتفرجان Ba²⁺ وCl⁻ يظهران على الطرفين فيُحذفان، فتبقى 2OH⁻(aq) + 2H⁺(aq) → 2H₂O(l). وبقسمة المعاملات على 2 تكون المعادلة النهائية بأبسط نسبة: H⁺(aq) + OH⁻(aq) → H₂O(l).', '["المعادلة الرمزية موزونة: Ba(OH)₂ + 2HCl → 2H₂O + BaCl₂","المعادلة الكاملة بأيونات الذائبات وH₂O(l) بصيغتها","تحديد المتفرجين Ba²⁺ وCl⁻ وحذفهما","المعادلة النهائية H⁺(aq) + OH⁻(aq) → H₂O(l) بأبسط نسبة"]'::jsonb, '["اكتب المعادلة الرمزية ووازنها: Ba(OH)₂(aq) + 2HCl(aq) → 2H₂O(l) + BaCl₂(aq)","اكتب المواد الأيونية الذائبة أيونات وأبقِ الماء السائل بصيغته: Ba²⁺ + 2OH⁻ + 2H⁺ + 2Cl⁻ → 2H₂O(l) + Ba²⁺ + 2Cl⁻","احذف الأيونين المتفرجين Ba²⁺ وCl⁻: 2H⁺ + 2OH⁻ → 2H₂O(l)","اقسم المعاملات على 2: H⁺(aq) + OH⁻(aq) → H₂O(l)"]'::jsonb, '[{"element":"المعادلة الرمزية الموزونة","marks":1},{"element":"المعادلة الأيونية الكاملة الصحيحة بالمعاملات والحالات","marks":2},{"element":"تحديد الأيونين المتفرجين Ba²⁺ وCl⁻","marks":1},{"element":"المعادلة الأيونية النهائية بأبسط نسبة عددية","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"ثلاث معادلات صحيحة وموزونة مع الحالات، وتحديد المتفرجين، والنهائية بأبسط نسبة"},{"level":"4–5 درجات","description":"المعادلات صحيحة مع خطأ في حالة أو نسيان تبسيط النسبة"},{"level":"2–3 درجات","description":"معادلة رمزية صحيحة ومعادلة أيونية واحدة صحيحة أو تحديد المتفرجين"},{"level":"1 درجة","description":"معادلة رمزية موزونة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان معامل 2 في 2HCl أو 2H₂O","كتابة H₂O على شكل أيونات","ترك المعادلة النهائية 2H⁺ + 2OH⁻ → 2H₂O دون تبسيط","عدّ Ba²⁺ أو Cl⁻ مشاركًا في التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:27:04.838Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المعادلة الرمزية الموزونة: 2HNO₃(aq) + K₂CO₃(aq) → CO₂(g) + H₂O(l) + 2KNO₃(aq). المعادلة الأيونية الكاملة: 2H⁺(aq) + 2NO₃⁻(aq) + 2K⁺(aq) + CO₃²⁻(aq) → CO₂(g) + H₂O(l) + 2K⁺(aq) + 2NO₃⁻(aq). الأيونان المتفرجان هما K⁺ وNO₃⁻. المعادلة الأيونية النهائية: 2H⁺(aq) + CO₃²⁻(aq) → CO₂(g) + H₂O(l).', '["المعادلة الرمزية الموزونة بالمعاملات 2HNO₃ و2KNO₃","المعادلة الكاملة بالأيونات والحالات (CO₂(g) وH₂O(l) غير مفككين)","تحديد المتفرجين K⁺ وNO₃⁻","المعادلة النهائية 2H⁺ + CO₃²⁻ → CO₂(g) + H₂O(l)"]'::jsonb, '["وازن المعادلة: 2HNO₃(aq) + K₂CO₃(aq) → CO₂(g) + H₂O(l) + 2KNO₃(aq)","اكتب الذائبات الأيونية أيونات وأبقِ الغاز والسائل بصيغتيهما: 2H⁺ + 2NO₃⁻ + 2K⁺ + CO₃²⁻ → CO₂(g) + H₂O(l) + 2K⁺ + 2NO₃⁻","حدّد المتفرجين على الطرفين: K⁺ وNO₃⁻، ثم احذفهما","اكتب النهائية: 2H⁺(aq) + CO₃²⁻(aq) → CO₂(g) + H₂O(l)"]'::jsonb, '[{"element":"المعادلة الرمزية الموزونة","marks":1},{"element":"المعادلة الأيونية الكاملة بالحالات الصحيحة","marks":2},{"element":"تحديد الأيونين المتفرجين K⁺ وNO₃⁻","marks":1},{"element":"المعادلة الأيونية النهائية الموزونة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلات صحيحة وموزونة بالحالات، وتحديد المتفرجين"},{"level":"4–5 درجات","description":"خطأ في حالة أو في معامل واحد في إحدى المعادلات"},{"level":"2–3 درجات","description":"المعادلة الرمزية صحيحة مع معادلة أيونية واحدة أو تحديد المتفرجين"},{"level":"1 درجة","description":"المعادلة الرمزية الموزونة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة CO₂(g) على شكل أيونات","نسيان المعامل 2 أمام H⁺ في النهائية","كتابة CO₃²⁻ بدلًا من HCO₃⁻ أو العكس","إبقاء K⁺ أو NO₃⁻ في المعادلة النهائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:27:04.838Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ أن الطالبة أبقت Na₂S وNa₂SO₄ بصيغتيهما الجزيئيتين مع أنهما مركبان أيونيان ذائبان (aq) يجب كتابتهما أيونات: 2Na⁺ وS²⁻ و2Na⁺ وSO₄²⁻. المعادلة الأيونية الكاملة الصحيحة: Cu²⁺(aq) + SO₄²⁻(aq) + 2Na⁺(aq) + S²⁻(aq) → CuS(s) + 2Na⁺(aq) + SO₄²⁻(aq). الأيونان المتفرجان Na⁺ وSO₄²⁻ يُحذفان، فتكون المعادلة النهائية: Cu²⁺(aq) + S²⁻(aq) → CuS(s).', '["تحديد الخطأ: Na₂S وNa₂SO₄ الذائبان لم يُكتبا أيونات","المعادلة الكاملة الصحيحة بالمعاملات 2Na⁺ وبالحالات","تحديد المتفرجين Na⁺ وSO₄²⁻","المعادلة النهائية Cu²⁺ + S²⁻ → CuS(s)"]'::jsonb, '["المركبات الأيونية الذائبة (aq) تُكتب أيونات: CuSO₄ → Cu²⁺ + SO₄²⁻، وNa₂S → 2Na⁺ + S²⁻، وNa₂SO₄ → 2Na⁺ + SO₄²⁻","أبقِ الراسب CuS(s) بصيغته: Cu²⁺ + SO₄²⁻ + 2Na⁺ + S²⁻ → CuS(s) + 2Na⁺ + SO₄²⁻","احذف المتفرجين Na⁺ وSO₄²⁻","اكتب النهائية: Cu²⁺(aq) + S²⁻(aq) → CuS(s)"]'::jsonb, '[{"element":"تحديد الخطأ وتعليله","marks":1},{"element":"المعادلة الأيونية الكاملة الصحيحة","marks":2},{"element":"تحديد المتفرجين","marks":1},{"element":"المعادلة الأيونية النهائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الخطأ بتعليل صحيح، والمعادلتان صحيحتان، وتحديد المتفرجين"},{"level":"3–4 درجات","description":"تحديد الخطأ مع معادلة كاملة صحيحة ونقص في النهائية أو المتفرجين"},{"level":"1–2 درجة","description":"تحديد الخطأ فقط أو معادلة نهائية دون الكاملة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة المعامل 2 أمام Na⁺ دون كتابة الأيونات كلها","كتابة CuS على شكل أيونات","حذف SO₄²⁻ وإبقاء Na⁺ في النهائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.838Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O04') and x.type = v.type and x.number = v.number
