select (select id from public.objectives where code = 'K1-C4-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عند خلط محلول كلوريد الصوديوم NaCl مع محلول نترات البوتاسيوم KNO₃، ما النتيجة المتوقعة؟', null, '["يتكوّن راسب من NaNO₃ لأن النترات تترسب مع الصوديوم","لا يحدث تفاعل (NR) لأن جميع الأيونات تبقى ذائبة","يتكوّن راسب من KCl لأن الكلوريدات غير ذائبة","يتصاعد غاز لأن الأيونات تتبادل شركاءها"]'::jsonb, 'تطبيق', 'توقع عدم حدوث تفاعل', 'سهل', 'المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية والتنبؤ بالراسب؛ الكتاب ص 148 — س94'),
('mcq', 2, 'أيّ المخاليط المائية الآتية يُتوقع أن يتكوّن فيه راسب؟', null, '["K₂SO₄(aq) + NaBr(aq)","Na₂CO₃(aq) + KNO₃(aq)","(NH₄)₂SO₄(aq) + LiCl(aq)","CuSO₄(aq) + Na₂S(aq)"]'::jsonb, 'تطبيق', 'اختيار الخليط الذي يكوّن راسبًا', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية والتنبؤ بالراسب'),
('mcq', 3, 'عند خلط محلول حمض النيتريك HNO₃ مع محلول هيدروكسيد البوتاسيوم KOH، أيّ الناتجين الآتيين يتكوّن فعلًا ويدل على حدوث التفاعل؟', null, '["ماء H₂O(l) مع بقاء KNO₃ ذائبًا","راسب من KNO₃(s) يظهر في قاع الكأس","غاز NO₂(g) يتصاعد على شكل فقاعات","غاز H₂(g) يتصاعد على شكل فقاعات"]'::jsonb, 'تطبيق', 'تحديد ناتج تفاعل التعادل', 'سهل', 'الكتاب ص 137 — التفاعلات التي تكوّن ماء'),
('mcq', 4, 'عند إضافة حمض الهيدروبروميك HBr إلى محلول كبريتيد البوتاسيوم K₂S يتصاعد غاز. ما الغاز المتوقع؟', null, '["غاز الهيدروجين H₂","غاز البروم Br₂","غاز كبريتيد الهيدروجين H₂S","غاز ثاني أكسيد الكبريت SO₂"]'::jsonb, 'تطبيق', 'توقع الغاز الناتج', 'سهل', 'الكتاب ص 139 — التفاعلات التي تكوّن غازات'),
('mcq', 5, 'يُخلط محلول نترات الفضة AgNO₃ مع محلول بروميد المغنيسيوم MgBr₂. أيّ العبارات الآتية تصف النتيجة المتوقعة صحيحًا؟', null, '["لا يحدث تفاعل لأن جميع الأيونات تبقى ذائبة","يتكوّن راسب من Mg(NO₃)₂ ويبقى AgBr ذائبًا","يتكوّن راسب من AgBr₂ ويبقى MgNO₃ ذائبًا","يتكوّن راسب من AgBr ويبقى Mg(NO₃)₂ ذائبًا"]'::jsonb, 'تطبيق', 'توقع الراسب وكتابة صيغته', 'صعب', 'الكتاب ص 148 — س94؛ المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية'),
('mcq', 6, 'عند خلط محلول فوسفات البوتاسيوم K₃PO₄ مع محلول كبريتات المغنيسيوم MgSO₄ يتكوّن راسب. ما صيغة الراسب؟', null, '["MgPO₄","Mg₃(PO₄)₂","Mg₂(PO₄)₃","K₂SO₄"]'::jsonb, 'تطبيق', 'اشتقاق صيغة الراسب', 'صعب', 'الكتاب ص 149 — س99 (فوسفات المغنيسيوم راسب)؛ المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية'),
('mcq', 7, 'محلول مائي يحتوي على أيونات Ba²⁺ وNO₃⁻. أيّ المحاليل الآتية إذا أُضيف إليه يتكوّن راسب؟', null, '["Na₂SO₄(aq)","KCl(aq)","NaNO₃(aq)","NH₄Br(aq)"]'::jsonb, 'تطبيق', 'اختيار الكاشف المرسِّب لأيون', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية والتنبؤ بالراسب'),
('essay', 1, 'توقّع نتيجة خلط كل زوج من المحاليل المائية الآتية، وحدّد نوع الناتج (راسب أو ماء أو غاز) واكتب صيغته، أو اكتب NR إذا لم يحدث تفاعل، ثم علّل كل إجابة: (أ) NaNO₃ مع KBr. (ب) K₂S مع HCl. (ج) AgNO₃ مع Na₂CO₃.', null, null, 'تطبيق', 'توقع ناتج ثلاثة تفاعلات وتعليله', 'متوسط', 'الكتاب ص 139، 148، 149 — أنواع النواتج؛ المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية'),
('essay', 2, 'عند خلط محلول كبريتات النحاس II CuSO₄ مع محلول نترات الباريوم Ba(NO₃)₂ يحدث تفاعل. اكتب المعادلة الرمزية الموزونة مع الحالات الفيزيائية، وحدّد نوع الناتج المتكوّن مع التعليل، ثم اكتب المعادلة الأيونية النهائية.', null, null, 'تطبيق', 'توقع تفاعل ترسيب وكتابة معادلته', 'متوسط', 'الكتاب ص 148 — س94 (ب)؛ المحتوى المكمّل (ليس في الكتاب) — قواعد الذائبية'),
('essay', 3, 'قال طالب: «عند خلط محلول HCl مع محلول NaOH لا يحدث تفاعل، لأنني لم أشاهد راسبًا ولا فقاعات غاز ولا تغيّرًا في اللون». قوّم هذا الاستنتاج، ووضّح نوع الناتج المتكوّن إن وُجد مع كتابة المعادلة الأيونية النهائية.', null, null, 'تقويم', 'تقويم استنتاج عن تفاعل تعادل', 'صعب', 'الكتاب ص 137 — التفاعلات التي تكوّن ماء')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'أملاح عناصر المجموعة الأولى (Na⁺ وK⁺) ذائبة دائمًا، وجميع النترات ذائبة؛ فالناتجان المحتملان NaNO₃ وKCl ذائبان. لا يتكوّن راسب ولا ماء ولا غاز، فلا يحدث تفاعل (NR)؛ والإجابة هي الخيار الثاني.', '["NaNO₃ ملح صوديوم ونترات معًا فهو ذائب، ولا يترسب.","","KCl ملح بوتاسيوم وهاليد معًا، وأملاح المجموعة الأولى ذائبة؛ فلا يترسب.","لا يتكوّن أي من الغازات H₂S أو HCN أو CO₂ من هذه الأيونات؛ والتبادل وحده لا ينتج غازًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.839Z"}'::jsonb),
('mcq', 2, 3, 'في الخلائط الثلاثة الأولى تنتج أملاح للمجموعة الأولى أو للأمونيوم أو نترات، وكلها ذائبة فلا يتكوّن راسب. أما CuSO₄ مع Na₂S فيتبادلان الشريكين فينتج CuS وNa₂SO₄؛ والكبريتيدات غير ذائبة إلا مع المجموعة الأولى والأمونيوم، فيترسب CuS؛ والإجابة هي الخيار الأخير.', '["الناتجان Na₂SO₄ وKBr ذائبان (أملاح المجموعة الأولى)، فلا راسب.","الناتجان K₂CO₃ وNaNO₃ ذائبان؛ فكربونات المجموعة الأولى ذائبة، والنترات ذائبة.","الناتجان Li₂SO₄ وNH₄Cl ذائبان؛ فلا راسب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.839Z"}'::jsonb),
('mcq', 3, 0, 'تتحد أيونات H⁺ من الحمض مع OH⁻ من القاعدة لتكوين الماء: H⁺ + OH⁻ → H₂O(l)، وKNO₃ ملح ذائب فيبقى أيونات في المحلول. والماء عديم اللون والرائحة فلا دليل مرئيًّا عليه؛ والإجابة هي الخيار الأول.', '["","KNO₃ من أملاح المجموعة الأولى والنترات، فهو ذائب ولا يترسب.","لا يتكوّن NO₂ في تفاعل التعادل؛ فأيون النترات يبقى ذائبًا متفرجًا.","لا ينتج H₂ من اتحاد H⁺ وOH⁻؛ فالناتج الفعلي هو الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.839Z"}'::jsonb),
('mcq', 4, 2, 'يحدث إحلال مزدوج بين HBr وK₂S: يتحد H⁺ مع S²⁻ لتكوين H₂S وهو غاز، ويبقى KBr ذائبًا: 2HBr + K₂S → H₂S(g) + 2KBr. والإجابة هي الخيار الثالث.', '["الإحلال المزدوج لا ينتج H₂ بل يتبادل الأيونان الشركاء.","Br₂ يتطلب أكسدة أيون البروميد وهي لا تحدث في الإحلال المزدوج؛ فBr⁻ متفرج.","","لا يوجد أكسجين في المتفاعلات، ولا يتكوّن SO₂ بالإحلال المزدوج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.839Z"}'::jsonb),
('mcq', 5, 3, 'يتبادل الشريكان: Ag⁺ مع Br⁻ وMg²⁺ مع NO₃⁻، والصيغتان الصحيحتان AgBr وMg(NO₃)₂. النترات ذائبة، أما هاليدات Ag⁺ فغير ذائبة، فيترسب AgBr: 2AgNO₃ + MgBr₂ → 2AgBr(s) + Mg(NO₃)₂(aq)؛ والإجابة هي الخيار الأخير.', '["هاليدات الفضة استثناء من قاعدة ذوبان الهاليدات، فيتكوّن راسب AgBr.","جميع النترات ذائبة فلا يترسب Mg(NO₃)₂، وهاليد الفضة هو الراسب.","صيغة بروميد الفضة AgBr لأن شحنة Ag⁺ واحدة؛ وMgNO₃ صيغة خاطئة لأن شحنة Mg²⁺ اثنتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:27:04.840Z"}'::jsonb),
('mcq', 6, 1, 'يتبادل الشريكان فينتج فوسفات المغنيسيوم وكبريتات البوتاسيوم. الفوسفات غير ذائب إلا مع المجموعة الأولى، فيترسب فوسفات المغنيسيوم، وتتعادل شحنته بثلاثة أيونات Mg²⁺ (+6) مع أيونين PO₄³⁻ (−6) فصيغته Mg₃(PO₄)₂: 2K₃PO₄ + 3MgSO₄ → Mg₃(PO₄)₂(s) + 3K₂SO₄؛ والإجابة هي الخيار الثاني.', '["صيغة غير متعادلة الشحنة: Mg²⁺ شحنته +2 وPO₄³⁻ شحنته −3.","","الأرقام السفلية معكوسة؛ فالشحنة هنا +4 مقابل −9 غير متعادلة.","K₂SO₄ ملح بوتاسيوم ذائب؛ فهو يبقى في المحلول ولا يترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.840Z"}'::jsonb),
('mcq', 7, 0, 'الراسب يتطلب ناتجًا غير ذائب: Ba²⁺ مع SO₄²⁻ يكوّنان BaSO₄ وهو من كبريتات Ba²⁺ غير الذائبة، أما مع Cl⁻ أو NO₃⁻ أو Br⁻ فتبقى الأملاح الناتجة ذائبة؛ والإجابة هي الخيار الأول.', '["","BaCl₂ كلوريد ذائب (ليس من هاليدات Ag⁺ وPb²⁺)، وKNO₃ ذائب؛ فلا راسب.","الناتجان Ba(NO₃)₂ وNaNO₃ نتراتان ذائبتان؛ فلا يحدث تفاعل.","BaBr₂ ذائب وNH₄NO₃ ذائب؛ فلا راسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.840Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) NR؛ فالناتجان المحتملان NaBr وKNO₃ ملحان ذائبان (المجموعة الأولى والنترات)، ولا يتكوّن راسب ولا ماء ولا غاز. (ب) يتكوّن غاز: 2HCl(aq) + K₂S(aq) → H₂S(g) + 2KCl(aq)؛ إذ يتحد H⁺ مع S²⁻ لتكوين غاز كبريتيد الهيدروجين، ويبقى KCl ذائبًا. (ج) يتكوّن راسب: 2AgNO₃(aq) + Na₂CO₃(aq) → Ag₂CO₃(s) + 2NaNO₃(aq)؛ فالكربونات غير ذائبة إلا مع المجموعة الأولى والأمونيوم، والفضة ليست منها، أما NaNO₃ فذائب.', '["(أ) NR مع تعليل ذوبان الناتجين","(ب) غاز H₂S مع المعادلة وتعليل اتحاد H⁺ وS²⁻","(ج) راسب Ag₂CO₃ بصيغة صحيحة","تعليل (ج) بأن الكربونات غير ذائبة مع الفضة وNaNO₃ ذائب"]'::jsonb, '["(أ) بدّل الشريكين: NaBr وKNO₃، وكلاهما ذائب ← NR","(ب) بدّل الشريكين: H₂S وKCl؛ H₂S غاز ← غاز: 2HCl + K₂S → H₂S(g) + 2KCl","(ج) بدّل الشريكين: Ag₂CO₃ وNaNO₃؛ الكربونات غير ذائبة والنترات ذائبة ← راسب Ag₂CO₃(s)"]'::jsonb, '[{"element":"(أ) NR مع التعليل","marks":2},{"element":"(ب) نوع الناتج (غاز) وصيغته H₂S مع التعليل","marks":2},{"element":"(ج) نوع الناتج (راسب) وصيغته Ag₂CO₃ مع التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الحالات الثلاث صحيحة بالصيغ والتعليل"},{"level":"4–5 درجات","description":"حالتان صحيحتان بتعليل، أو ثلاث حالات مع نقص في التعليل"},{"level":"2–3 درجات","description":"حالة واحدة صحيحة كاملة أو أنواع الناتج دون صيغ"},{"level":"1 درجة","description":"نوع ناتج واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة AgCO₃ بدل Ag₂CO₃","التنبؤ بتكوّن راسب في (أ) لمجرد تبادل الشريكين","عدّ KCl راسبًا في (ب)","كتابة H₂S دون الإشارة إلى أنه غاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.840Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نبدّل الشريكين فينتج كبريتات الباريوم ونترات النحاس II: CuSO₄(aq) + Ba(NO₃)₂(aq) → BaSO₄(s) + Cu(NO₃)₂(aq). يتكوّن راسب هو BaSO₄ لأن كبريتات Ba²⁺ غير ذائبة وهي استثناء من قاعدة ذوبان الكبريتات، أما Cu(NO₃)₂ فذائب لأن جميع النترات ذائبة. الأيونان المتفرجان Cu²⁺ وNO₃⁻، والمعادلة الأيونية النهائية: Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s).', '["المعادلة الرمزية الموزونة بالحالات BaSO₄(s) وCu(NO₃)₂(aq)","نوع الناتج: راسب BaSO₄","التعليل: كبريتات الباريوم غير ذائبة والنترات ذائبة","المعادلة النهائية Ba²⁺ + SO₄²⁻ → BaSO₄(s)"]'::jsonb, '["بدّل الشريكين: Cu²⁺ مع NO₃⁻ وBa²⁺ مع SO₄²⁻","اكتب الصيغتين: Cu(NO₃)₂ وBaSO₄؛ المعادلة موزونة كما هي بمعاملات 1","طبّق قواعد الذائبية: Cu(NO₃)₂ ذائب، BaSO₄ غير ذائب ← راسب","احذف المتفرجين Cu²⁺ وNO₃⁻: Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)"]'::jsonb, '[{"element":"المعادلة الرمزية الموزونة بصيغ صحيحة","marks":2},{"element":"الحالات الفيزيائية الصحيحة","marks":1},{"element":"تحديد الراسب BaSO₄ مع التعليل بقواعد الذائبية","marks":1},{"element":"المعادلة الأيونية النهائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة صحيحة بالحالات، وتحديد الراسب بتعليل، ومعادلة نهائية صحيحة"},{"level":"3–4 درجات","description":"المعادلة والراسب صحيحان مع نقص في التعليل أو النهائية"},{"level":"1–2 درجة","description":"صيغتا الناتجين صحيحتان دون حالات أو تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Cu(NO₃)₂ راسبًا","كتابة صيغة النحاس والنترات CuNO₃","إهمال المعامل 2 للنترات في Ba(NO₃)₂ و Cu(NO₃)₂ عند الأيونات","كتابة الحالة (aq) للراسب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.840Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاستنتاج غير صحيح؛ فالتفاعل يحدث وينتج ماء: HCl(aq) + NaOH(aq) → H₂O(l) + NaCl(aq). تتحد أيونات H⁺ من الحمض مع OH⁻ من القاعدة لتكوين الماء، وNaCl ملح ذائب تبقى أيوناته في المحلول. لا يلاحظ الطالب دليلًا مرئيًّا لأن الماء عديم اللون والرائحة ويشكّل معظم المحلول أصلًا. المعادلة الأيونية النهائية: H⁺(aq) + OH⁻(aq) → H₂O(l)، والأيونان المتفرجان Na⁺ وCl⁻.', '["الحكم: الاستنتاج غير صحيح والتفاعل يحدث","الناتج ماء من اتحاد H⁺ وOH⁻ مع بقاء NaCl ذائبًا","سبب عدم ظهور دليل مرئي: الماء عديم اللون والرائحة ويشكّل أغلب المحلول","المعادلة النهائية H⁺ + OH⁻ → H₂O(l)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن التفاعل يحدث (الاستنتاج خاطئ)","marks":1},{"element":"تحديد الناتج (ماء) وبقاء NaCl ذائبًا","marks":1},{"element":"تعليل غياب الدليل المرئي","marks":1},{"element":"المعادلة الأيونية النهائية الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تحديد الماء وتعليل غياب الدليل والمعادلة النهائية"},{"level":"2–3 درجات","description":"حكم صحيح مع تحديد الماء، ونقص في التعليل أو المعادلة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على الاستنتاج بحجة غياب الراسب والغاز","عدّ NaCl راسبًا","كتابة المعادلة النهائية بأيونات Na⁺ وCl⁻","الاعتقاد بأن التفاعل يتطلب دليلًا مرئيًّا دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.841Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
