from (values
('mcq', 1, 'المعادلة الأيونية الكاملة لتفاعل KI مع AgNO₃ هي: K⁺(aq) + I⁻(aq) + Ag⁺(aq) + NO₃⁻(aq) → AgI(s) + K⁺(aq) + NO₃⁻(aq). ما الأيونان المتفرجان في هذا التفاعل؟', null, '["Ag⁺ وI⁻","K⁺ وI⁻","Ag⁺ وNO₃⁻","K⁺ وNO₃⁻"]'::jsonb, 'تطبيق', 'تحديد المتفرجة من معادلة كاملة معطاة', 'سهل', 'الكتاب ص 135 — الأيونات المتفرجة'),
('mcq', 2, 'المعادلة الأيونية الكاملة لتفاعل HI مع Li₂S هي: 2H⁺(aq) + 2I⁻(aq) + 2Li⁺(aq) + S²⁻(aq) → H₂S(g) + 2Li⁺(aq) + 2I⁻(aq). ما الأيونان المتفرجان؟', null, '["H⁺ وS²⁻","Li⁺ وI⁻","H⁺ وI⁻","Li⁺ وS²⁻"]'::jsonb, 'تطبيق', 'تحديد المتفرجة في تفاعل يكوّن غازًا', 'سهل', 'الكتاب ص 139 — التفاعلات التي تكوّن غازات'),
('mcq', 3, 'المعادلة الأيونية الكاملة لتفاعل AlCl₃ مع NaOH هي: Al³⁺(aq) + 3Cl⁻(aq) + 3Na⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s) + 3Na⁺(aq) + 3Cl⁻(aq). ما مجموع معاملات الأيونات المتفرجة في الطرف الأيسر من المعادلة؟', null, '["2","3","6","10"]'::jsonb, 'تطبيق', 'حساب مجموع معاملات المتفرجة', 'متوسط', 'الكتاب ص 135، 137 — الأيونات المتفرجة والمعاملات'),
('mcq', 4, 'تفاعلان في المحلول المائي: (1) HCl(aq) + NaOH(aq) → H₂O(l) + NaCl(aq)، و(2) HNO₃(aq) + NaOH(aq) → H₂O(l) + NaNO₃(aq). أيّ الأيونات الآتية متفرج في التفاعلين معًا؟', null, '["Na⁺","Cl⁻","NO₃⁻","H⁺"]'::jsonb, 'فهم', 'تحديد المتفرج المشترك بين تفاعلين', 'متوسط', 'الكتاب ص 137–138 — مثال 4-4'),
('mcq', 5, 'عند خلط محلولي Na₂CO₃ وCaCl₂ يتكوّن راسب CaCO₃ ويبقى كلوريد الصوديوم NaCl ذائبًا. ما الأيونان المتفرجان في هذا التفاعل؟', null, '["Ca²⁺ وCO₃²⁻","Na⁺ وCl⁻","Na⁺ وCO₃²⁻","Ca²⁺ وCl⁻"]'::jsonb, 'تطبيق', 'استنتاج المتفرجة من وصف التفاعل', 'متوسط', 'الكتاب ص 134 — التفاعلات التي تكوّن راسبًا، ص 135'),
('mcq', 6, 'يتفاعل CuSO₄(aq) مع NaOH(aq) وفق المعادلة: CuSO₄(aq) + 2NaOH(aq) → Cu(OH)₂(s) + Na₂SO₄(aq). عند كتابة المعادلة الأيونية الكاملة، أيّ مما يأتي يُعدّ أيونًا متفرجًا؟', null, '["Cu²⁺","OH⁻","Cu(OH)₂","SO₄²⁻"]'::jsonb, 'تطبيق', 'تحديد متفرج متعدد الذرات', 'صعب', 'الكتاب ص 135 — الأيونات المتفرجة'),
('mcq', 7, 'أيّ التفاعلات المائية الآتية يكون فيه الأيونان Na⁺ وNO₃⁻ هما الأيونان المتفرجان؟', null, '["NaOH(aq) + HCl(aq)","K₂S(aq) + HNO₃(aq)","Ba(NO₃)₂(aq) + Na₂CO₃(aq)","KI(aq) + AgNO₃(aq)"]'::jsonb, 'تحليل', 'اختيار التفاعل الذي له متفرجان معطيان', 'صعب', 'الكتاب ص 135–138 — الأيونات المتفرجة، مثال 4-3'),
('essay', 1, 'يتفاعل محلول كبريتات الصوديوم Na₂SO₄ مع محلول كلوريد الباريوم BaCl₂ فيتكوّن راسب من كبريتات الباريوم BaSO₄ ويبقى كلوريد الصوديوم ذائبًا. اكتب المعادلة الأيونية الكاملة الموزونة مع الحالات، ثم حدّد الأيونات المتفرجة مبيّنًا سبب عدّها متفرجة.', null, null, 'تطبيق', 'كتابة معادلة كاملة وتحديد المتفرجة', 'متوسط', 'الكتاب ص 135–136 — المعادلات الأيونية، مثال 4-3'),
('essay', 2, 'المعادلة الأيونية الكاملة لتفاعل في محلول مائي هي: 2Na⁺(aq) + CO₃²⁻(aq) + 2H⁺(aq) + 2Br⁻(aq) → 2Na⁺(aq) + 2Br⁻(aq) + H₂O(l) + CO₂(g). حدّد الأيونات المتفرجة، واستنتج المادتين المتفاعلتين، ثم اكتب المعادلة الأيونية النهائية.', null, null, 'تحليل', 'استنتاج المتفرجة والمتفاعلات من معادلة كاملة', 'متوسط', 'الكتاب ص 139–141 — التفاعلات التي تكوّن غازات'),
('essay', 3, 'قارن بين دور أيون الكلوريد Cl⁻ في التفاعلين الآتيين: (1) HCl(aq) + NaOH(aq) → H₂O(l) + NaCl(aq)، و(2) NaCl(aq) + AgNO₃(aq) → AgCl(s) + NaNO₃(aq). حدّد الأيونات المتفرجة في كل تفاعل مع كتابة معادلته الأيونية الكاملة، ثم وضّح هل يمكن لأيون واحد أن يكون متفرجًا في تفاعل ومشاركًا في آخر.', null, null, 'تحليل', 'مقارنة دور أيون في تفاعلين', 'صعب', 'الكتاب ص 135، 137 — الأيونات المتفرجة؛ ص 148 — س91')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
