select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الأيون المتفرج يظهر في طرفي المعادلة بالصورة نفسها دون أن يتغير. K⁺ وNO₃⁻ يظهران في المتفاعلات وفي الناتج KNO₃ المذاب، أما Ag⁺ وI⁻ فيدخلان في الراسب AgI؛ فالإجابة هي الخيار الأخير.', '["Ag⁺ وI⁻ يتحدان معًا ويكوّنان الراسب AgI(s)، فهما مشاركان وليسا متفرجين.","I⁻ يشارك في تكوين الراسب فلا يُعدّ متفرجًا.","Ag⁺ يشارك في تكوين الراسب فلا يُعدّ متفرجًا، وإن كان NO₃⁻ متفرجًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.841Z"}'::jsonb),
('mcq', 2, 1, 'Li⁺ وI⁻ يظهران على طرفي المعادلة بلا تغير، فهما المتفرجان. أما H⁺ وS²⁻ فيتحدان لتكوين غاز H₂S ولا يظهران على الطرف الثاني كأيونات؛ فالإجابة هي الخيار الثاني.', '["H⁺ وS²⁻ يشاركان في التفاعل ويكوّنان الغاز H₂S(g).","","H⁺ يشارك في تكوين H₂S فلا يُعدّ متفرجًا، وإن كان I⁻ متفرجًا.","S²⁻ يشارك في تكوين H₂S فلا يُعدّ متفرجًا، وإن كان Li⁺ متفرجًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:27:04.842Z"}'::jsonb),
('mcq', 3, 2, 'الأيونان المتفرجان Na⁺ وCl⁻ يظهران على الطرفين، ومعامل كل منهما 3 في الطرف الأيسر؛ فالمجموع 3 + 3 = 6. أما Al³⁺ وOH⁻ فمشاركان في تكوين الراسب؛ والإجابة هي 6.', '["هذا عدد أنواع الأيونات المتفرجة (نوعان) وليس مجموع معاملاتها.","هذا معامل نوع واحد فقط من المتفرجين (Na⁺ أو Cl⁻) دون الآخر.","","هذا مجموع معاملات جميع أيونات الطرف الأيسر (1 + 3 + 3 + 3) بما فيها المشاركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.842Z"}'::jsonb),
('mcq', 4, 0, 'في (1) المتفرجان Na⁺ وCl⁻، وفي (2) المتفرجان Na⁺ وNO₃⁻؛ فالأيون المشترك المتفرج في التفاعلين هو Na⁺. أما H⁺ فيتحد مع OH⁻ لتكوين الماء في التفاعلين.', '["","Cl⁻ متفرج في التفاعل (1) فقط، ولا يوجد في التفاعل (2).","NO₃⁻ متفرج في التفاعل (2) فقط، ولا يوجد في التفاعل (1).","H⁺ يشارك في تكوين الماء في التفاعلين، فليس متفرجًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.842Z"}'::jsonb),
('mcq', 5, 1, 'الأيونات في المحلولين: Na⁺ وCO₃²⁻ وCa²⁺ وCl⁻، ويتحد منها Ca²⁺ مع CO₃²⁻ لتكوين الراسب CaCO₃. أما Na⁺ وCl⁻ فيبقيان ذائبين في المحلول (NaCl ذائب) على الطرفين فهما المتفرجان؛ والإجابة هي الخيار الثاني.', '["هذان الأيونان يكوّنان الراسب CaCO₃ فهما المشاركان وليسا متفرجين.","","CO₃²⁻ يشارك في تكوين الراسب، فلا يُعدّ متفرجًا مع Na⁺.","Ca²⁺ يشارك في تكوين الراسب، فلا يُعدّ متفرجًا مع Cl⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.842Z"}'::jsonb),
('mcq', 6, 3, 'المعادلة الكاملة: Cu²⁺ + SO₄²⁻ + 2Na⁺ + 2OH⁻ → Cu(OH)₂(s) + 2Na⁺ + SO₄²⁻. الأيون SO₄²⁻ (كاملًا بوصفه أيونًا متعدد الذرات) يظهر على الطرفين دون تغير فهو متفرج، إلى جانب Na⁺؛ والإجابة هي الخيار الأخير.', '["Cu²⁺ يتحد مع OH⁻ لتكوين الراسب Cu(OH)₂(s)، فهو مشارك.","OH⁻ يتحد مع Cu²⁺ لتكوين الراسب، فهو مشارك.","Cu(OH)₂ هو الراسب الناتج وليس أيونًا، ويظهر في طرف الناتج فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.843Z"}'::jsonb),
('mcq', 7, 2, 'في Ba(NO₃)₂ مع Na₂CO₃ يتحد Ba²⁺ مع CO₃²⁻ لتكوين BaCO₃(s)، ويبقى Na⁺ وNO₃⁻ ذائبين على الطرفين؛ فهما المتفرجان. وفي بقية التفاعلات تختلف المتفرجة؛ والإجابة هي الخيار الثالث.', '["المتفرجان هنا Na⁺ وCl⁻ لأن الناتج NaCl ذائب.","المتفرجان هنا K⁺ وNO₃⁻ وليس Na⁺ لأنه غير موجود في المتفاعلات.","","المتفرجان هنا K⁺ وNO₃⁻، وليس Na⁺ لأنه غير موجود في المتفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.843Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعادلة الرمزية: Na₂SO₄(aq) + BaCl₂(aq) → BaSO₄(s) + 2NaCl(aq). المعادلة الأيونية الكاملة: 2Na⁺(aq) + SO₄²⁻(aq) + Ba²⁺(aq) + 2Cl⁻(aq) → BaSO₄(s) + 2Na⁺(aq) + 2Cl⁻(aq). الأيونان المتفرجان هما Na⁺ وCl⁻؛ لأنهما يظهران على طرفي المعادلة بالصورة نفسها ويبقيان ذائبين في المحلول ولم يشاركا في التفاعل، أما Ba²⁺ وSO₄²⁻ فيتحدان لتكوين الراسب.', '["المعادلة الكاملة الصحيحة موزونة بالحالات","تحديد المتفرجين Na⁺ وCl⁻","سبب عدّهما متفرجين: يظهران على الطرفين دون تغير ولا يشاركان في تكوين الراسب"]'::jsonb, '["اكتب المعادلة الرمزية الموزونة: Na₂SO₄(aq) + BaCl₂(aq) → BaSO₄(s) + 2NaCl(aq)","اكتب الذائبات أيونات وأبقِ الراسب بصيغته: 2Na⁺ + SO₄²⁻ + Ba²⁺ + 2Cl⁻ → BaSO₄(s) + 2Na⁺ + 2Cl⁻","حدّد الأيونات التي تظهر على الطرفين بلا تغير: Na⁺ وCl⁻"]'::jsonb, '[{"element":"المعادلة الأيونية الكاملة الموزونة مع الحالات","marks":2},{"element":"تحديد الأيونين المتفرجين Na⁺ وCl⁻","marks":1},{"element":"تعليل عدّهما متفرجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة كاملة صحيحة مع تحديد المتفرجين وتعليل صحيح"},{"level":"2–3 درجات","description":"معادلة صحيحة مع تحديد المتفرجين دون تعليل، أو العكس"},{"level":"1 درجة","description":"تحديد المتفرجين دون المعادلة الصحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال المعامل 2 أمام Na⁺ وCl⁻","عدّ Ba²⁺ أو SO₄²⁻ متفرجًا","كتابة BaSO₄ على شكل أيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.843Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأيونات التي تظهر على الطرفين بالصورة نفسها هي Na⁺ وBr⁻، فهي المتفرجة. المادتان المتفاعلتان: Na⁺ مع CO₃²⁻ تعودان إلى كربونات الصوديوم Na₂CO₃، وH⁺ مع Br⁻ تعودان إلى حمض الهيدروبروميك HBr. المعادلة الأيونية النهائية بعد حذف المتفرجين: 2H⁺(aq) + CO₃²⁻(aq) → H₂O(l) + CO₂(g).', '["المتفرجان Na⁺ وBr⁻","المادتان المتفاعلتان Na₂CO₃ وHBr","المعادلة النهائية 2H⁺ + CO₃²⁻ → H₂O(l) + CO₂(g)"]'::jsonb, '["ابحث عن الأيونات المتطابقة على الطرفين: 2Na⁺ و2Br⁻ ← متفرجة","اجمع كل كاتيون مع أنيون من المتفاعلات: 2Na⁺ + CO₃²⁻ = Na₂CO₃، و2H⁺ + 2Br⁻ = 2HBr","احذف المتفرجين: 2H⁺(aq) + CO₃²⁻(aq) → H₂O(l) + CO₂(g)"]'::jsonb, '[{"element":"تحديد الأيونين المتفرجين Na⁺ وBr⁻","marks":2},{"element":"استنتاج المادتين المتفاعلتين Na₂CO₃ وHBr","marks":1},{"element":"المعادلة الأيونية النهائية الموزونة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد المتفرجين، واستنتاج المادتين، ومعادلة نهائية موزونة صحيحة"},{"level":"3–4 درجات","description":"تحديد المتفرجين مع استنتاج المادتين أو معادلة نهائية دون الآخر"},{"level":"1–2 درجة","description":"تحديد أحد المتفرجين أو المتفرجين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ H⁺ متفرجًا لأنه يظهر في المتفاعلات","كتابة Na₂CO₃ باسم خاطئ أو بصيغة NaCO₃","إغفال المعامل 2 أمام H⁺ في النهائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.843Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل (1): المعادلة الكاملة H⁺(aq) + Cl⁻(aq) + Na⁺(aq) + OH⁻(aq) → H₂O(l) + Na⁺(aq) + Cl⁻(aq)؛ المتفرجان Na⁺ وCl⁻، فالكلوريد متفرج. التفاعل (2): المعادلة الكاملة Na⁺(aq) + Cl⁻(aq) + Ag⁺(aq) + NO₃⁻(aq) → AgCl(s) + Na⁺(aq) + NO₃⁻(aq)؛ المتفرجان Na⁺ وNO₃⁻، أما Cl⁻ فيتحد مع Ag⁺ لتكوين الراسب AgCl فهو مشارك. إذن نعم: كون الأيون متفرجًا أو مشاركًا يتوقف على التفاعل نفسه؛ فيكون متفرجًا إذا بقي ذائبًا دون تغير على الطرفين، ومشاركًا إذا دخل في تكوين راسب أو ماء أو غاز.', '["المعادلة الكاملة للتفاعل (1) والمتفرجان Na⁺ وCl⁻","المعادلة الكاملة للتفاعل (2) والمتفرجان Na⁺ وNO₃⁻","Cl⁻ متفرج في (1) ومشارك في (2) بتكوين AgCl(s)","الاستنتاج: دور الأيون يعتمد على التفاعل"]'::jsonb, '["اكتب الكاملة (1) وحدّد ما يظهر على الطرفين: Na⁺ وCl⁻ ← متفرجان","اكتب الكاملة (2) وحدّد ما يظهر على الطرفين: Na⁺ وNO₃⁻ ← متفرجان؛ وCl⁻ يظهر في المتفاعلات فقط ويتحد مع Ag⁺","قارن: Cl⁻ متفرج في (1) ومشارك في (2) ← دور الأيون يعتمد على التفاعل"]'::jsonb, '[{"element":"المعادلة الأيونية الكاملة الصحيحة للتفاعل (1) مع المتفرجين","marks":1},{"element":"المعادلة الأيونية الكاملة الصحيحة للتفاعل (2) مع المتفرجين","marks":2},{"element":"بيان أن Cl⁻ متفرج في (1) ومشارك في (2)","marks":1},{"element":"الاستنتاج العام الصحيح مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان صحيحتان، وتحديد المتفرجين، ومقارنة دور Cl⁻، واستنتاج صحيح"},{"level":"3–4 درجات","description":"معادلتان مع تحديد المتفرجين ونقص في المقارنة أو الاستنتاج"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو تحديد جزئي للمتفرجين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Cl⁻ متفرج في التفاعلين دائمًا","عدّ Na⁺ مشاركًا في تكوين AgCl","كتابة AgCl على شكل أيونات","اعتبار المتفرجة صفة ثابتة للأيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.844Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
