('mcq', 3, 'عند جمع معادلتي التفاعلين المتزامنين: HCl(aq) + NaHCO₃(aq) → H₂CO₃(aq) + NaCl(aq)، وH₂CO₃(aq) → H₂O(l) + CO₂(g)، لا يظهر H₂CO₃ في المعادلة الكلية الناتجة. ما سبب ذلك؟', null, '["لأنه غاز يتصاعد من المحلول فلا يبقى فيه","لأنه ناتج في التفاعل الأول ومتفاعل في الثاني بالكمية نفسها فيُحذف من الطرفين","لأنه أيون متفرج يظهر على طرفي المعادلة الأولى","لأنه لا يتكوّن في المحلول من الأساس"]'::jsonb, 'فهم', 'تفسير حذف المادة الوسطية من المعادلة الكلية', 'متوسط', 'الكتاب ص 140 — المعادلة الكلية للتفاعل'),
('mcq', 4, 'يتفاعل حمض النيتريك HNO₃ مع محلول كربونات البوتاسيوم الهيدروجينية KHCO₃ فينتج محلول نترات البوتاسيوم KNO₃ وماء وغاز CO₂. ما المعادلة الأيونية النهائية لهذا التفاعل؟', null, '["H⁺(aq) + CO₃²⁻(aq) → H₂O(l) + CO₂(g)","2H⁺(aq) + CO₃²⁻(aq) → H₂CO₃(aq)","H⁺(aq) + HCO₃⁻(aq) → H₂CO₃(aq)","H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)"]'::jsonb, 'تطبيق', 'كتابة المعادلة النهائية لتفاعل حمض مع بيكربونات', 'متوسط', 'الكتاب ص 140، 142 — س60'),
('mcq', 5, 'أيّ المخاليط المائية الآتية يتصاعد منه غاز CO₂ بالآلية نفسها: إحلال مزدوج يتكوّن فيه H₂CO₃ ثم تفككه؟', null, '["HBr(aq) + KHCO₃(aq)","NaCl(aq) + KHCO₃(aq)","HBr(aq) + NaOH(aq)","KNO₃(aq) + NaHCO₃(aq)"]'::jsonb, 'فهم', 'تعرّف تفاعل ينتج CO₂ بالآلية نفسها', 'متوسط', 'الكتاب ص 139 — أي محلول حمضي مع كربونات الصوديوم الهيدروجينية'),
('mcq', 6, 'يتم تفاعل HNO₃ مع KHCO₃ على خطوتين متزامنتين: (1) HNO₃(aq) + KHCO₃(aq) → H₂CO₃(aq) + KNO₃(aq)، و(2) H₂CO₃(aq) → H₂O(l) + CO₂(g). ما المعادلة الكلية بعد جمع المعادلتين وحذف المادة المشتركة؟', null, '["HNO₃(aq) + KHCO₃(aq) → H₂CO₃(aq) + KNO₃(aq)","HNO₃(aq) + KHCO₃(aq) → H₂CO₃(aq) + H₂O(l) + CO₂(g) + KNO₃(aq)","HNO₃(aq) + KHCO₃(aq) → H₂O(l) + CO₂(g) + KNO₃(aq)","HNO₃(aq) + KHCO₃(aq) → H₂O(l) + 2CO₂(g) + KNO₃(aq)"]'::jsonb, 'تطبيق', 'اشتقاق المعادلة الكلية', 'صعب', 'الكتاب ص 140 — المعادلة الكلية للتفاعل'),
('mcq', 7, 'في تفاعل HCl مع NaHCO₃ يتكوّن في خطوة الإحلال المزدوج NaCl وH₂CO₃. لماذا يتصاعد CO₂ ولا يبقى H₂CO₃ في المحلول، بينما تبقى أيونات NaCl منفصلة فيه؟', null, '["لأن NaCl مركب جزيئي لا يتفكك، أما H₂CO₃ فمركب أيوني يتفكك","لأن H₂CO₃ يترسب أولًا ثم يتحول الراسب إلى غاز مع مرور الزمن","لأن HCl الزائد يتفاعل مع H₂CO₃ ويحوّله إلى CO₂ بعد تكوّن NaCl","لأن H₂CO₃ غير مستقر فيتفكك فور تكوّنه إلى H₂O وCO₂، أما NaCl الأيوني فتبقى أيوناته ذائبة"]'::jsonb, 'تحليل', 'تفسير تفكك H₂CO₃ مقابل بقاء أيونات NaCl', 'صعب', 'الكتاب ص 140 — التفاعلات التي تكوّن غازات'),
('essay', 1, 'يُنتج خلط محلول حمض الهيدروكلوريك HCl مع محلول NaHCO₃ غاز ثاني أكسيد الكربون. وضّح كيف يتكوّن الغاز بوصفه إحلالًا مزدوجًا يتبعه تفكك: اكتب معادلتي التفاعلين المتزامنين، ثم المعادلة الكلية، ثم المعادلة الأيونية النهائية.', null, null, 'فهم', 'شرح التفاعلين المتزامنين وكتابة المعادلات', 'متوسط', 'الكتاب ص 140 — المعادلة الكلية والنهائية'),
('essay', 2, 'قالت طالبة: «عند إضافة الحمض إلى بيكربونات الصوديوم يتكوّن CO₂ مباشرة من اتحاد الحمض مع البيكربونات دون أن تتكوّن أي مادة وسطية». قوّم هذه العبارة موضحًا ما يحدث فعلًا بالمعادلات، مستعينًا بتفاعل HBr مع NaHCO₃.', null, null, 'تقويم', 'تقويم عبارة عن آلية تكوّن CO₂', 'صعب', 'الكتاب ص 140 — تفاعلان متزامنان'),
('essay', 3, 'يتفاعل HBr(aq) مع NaHCO₃(aq)، ويتفاعل HNO₃(aq) مع KHCO₃(aq)، ويتصاعد CO₂ في الحالتين. اكتب المعادلة الأيونية الكاملة لكل تفاعل، وحدّد المتفرجة فيه، ثم فسّر تشابه المعادلتين الأيونيتين النهائيتين، واذكر تفاعلًا حيويًّا في الجسم يشبههما.', null, null, 'تحليل', 'مقارنة تفاعلين وربطهما بتفاعل حيوي', 'متوسط', 'الكتاب ص 140، 142 — الربط مع علم الأحياء، الشكل 4-22')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C4-L3-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'حمض الخل يتفاعل مع NaHCO₃ في إحلال مزدوج فيتبادل الهيدروجين والصوديوم موقعيهما وينتج H₂CO₃، وهو حمض غير مستقر يتفكك بمجرد تكوّنه إلى ماء وغاز CO₂. والإجابة هي الخيار الأول.', '["","ترتيب الخطوتين معكوس؛ فالإحلال المزدوج يحدث أولًا وينتج H₂CO₃، ثم يتفكك H₂CO₃ لا NaHCO₃.","التفاعل إحلال مزدوج وليس بسيطًا، ولا يتكوّن CO₂ مباشرة بل عبر H₂CO₃.","الغاز يتكوّن من تفاعل الحمض مع صودا الخبز؛ والحمض لا يكوّن CO₂ باتحاده مع الماء وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.844Z"}'::jsonb),
('mcq', 2, 2, 'في الإحلال المزدوج يتحد الهيدروجين من HCl مع HCO₃⁻ ويتحد الصوديوم مع الكلوريد: HCl + NaHCO₃ → H₂CO₃ + NaCl. يتكوّن حمض الكربونيك H₂CO₃، ثم يتفكك إلى H₂O وCO₂؛ والإجابة هي الخيار الثالث.', '["NaOH يحتاج إلى أيون OH⁻ وهو غير موجود في المتفاعلات.","CO₂ هو ناتج تفكك H₂CO₃ في الخطوة الثانية، وليس ناتج الإحلال المزدوج.","","Na₂CO₃ يتطلب أيون CO₃²⁻ غير الموجود هنا، ولا يتكوّن عند اتحاد H⁺ مع HCO₃⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.845Z"}'::jsonb),
('mcq', 3, 1, 'H₂CO₃ ناتج في المعادلة الأولى ومتفاعل في الثانية بالكمية نفسها، فعند جمع المعادلتين يظهر على طرفي المعادلة الكلية فيُحذف منهما، فنحصل على HCl + NaHCO₃ → H₂O + CO₂ + NaCl؛ والإجابة هي الخيار الثاني.', '["H₂CO₃ ليس غازًا؛ الغاز هو CO₂ الناتج عن تفككه.","","H₂CO₃ مركب جزيئي وليس أيونًا، وهو يظهر في الناتج فقط في المعادلة الأولى.","H₂CO₃ يتكوّن فعلًا في خطوة الإحلال المزدوج ثم يتفكك فورًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.845Z"}'::jsonb),
('mcq', 4, 3, 'المعادلة الكاملة: H⁺ + NO₃⁻ + K⁺ + HCO₃⁻ → H₂O(l) + CO₂(g) + K⁺ + NO₃⁻. المتفرجان K⁺ وNO₃⁻ يُحذفان، فتبقى H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)؛ والإجابة هي الخيار الأخير.', '["الأيون المتفاعل هو HCO₃⁻ وليس CO₃²⁻، والمعادلة غير موزونة شحنيًّا (−1 في طرف و0 في الآخر).","هذه المعادلة تمثّل أيون الكربونات CO₃²⁻ ولا تُظهر الناتجين النهائيين H₂O وCO₂.","هذه خطوة الإحلال المزدوج الأولى فقط؛ فH₂CO₃ يتفكك فورًا إلى H₂O وCO₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.845Z"}'::jsonb),
('mcq', 5, 0, 'تكوّن CO₂ بهذه الآلية يتطلب حمضًا مع ملح بيكربونات، فيتكوّن H₂CO₃ ثم يتفكك؛ وهذا متحقق في HBr مع KHCO₃: HBr + KHCO₃ → H₂CO₃ + KBr ثم H₂CO₃ → H₂O + CO₂. والإجابة هي الخيار الأول.', '["","لا يوجد حمض في المخلوط، فلا يتكوّن H₂CO₃ ولا يحدث تفاعل (الناتجان NaHCO₃ وKCl ذائبان).","الحمض هنا يتفاعل مع قاعدة فيتكوّن الماء وNaBr فقط، ولا يوجد أيون بيكربونات.","لا يوجد حمض في المخلوط، فلا يتكوّن H₂CO₃ ولا يتصاعد غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.845Z"}'::jsonb),
('mcq', 6, 2, 'جمع (1) و(2) يعطي HNO₃ + KHCO₃ + H₂CO₃ → H₂CO₃ + KNO₃ + H₂O + CO₂، وبحذف H₂CO₃ من الطرفين تصبح المعادلة HNO₃(aq) + KHCO₃(aq) → H₂O(l) + CO₂(g) + KNO₃(aq)، وهي موزونة (ذرة C واحدة في كل طرف)؛ والإجابة هي الخيار الثالث.', '["هذه المعادلة الأولى فقط ولا تتضمن التفكك الذي ينتج الماء وCO₂.","أبقت H₂CO₃ في الناتج وغير موزونة (ذرتا كربون في الناتج وذرة واحدة في المتفاعلات).","","غير موزونة: المتفاعلات فيها ذرة كربون واحدة بينما الناتج فيه ذرتا كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.846Z"}'::jsonb),
('mcq', 7, 3, 'حمض الكربونيك H₂CO₃ غير مستقر ويتفكك بمجرد تكوّنه إلى ماء وغاز CO₂، أما NaCl فمركب أيوني ذائب تبقى أيوناته Na⁺ وCl⁻ منفصلة في المحلول (عكس ما يحدث لـ H₂CO₃). والإجابة هي الخيار الأخير.', '["NaCl مركب أيوني وليس جزيئيًّا، وH₂CO₃ مركب جزيئي يتفكك إلى جزيئات ماء وغاز لا إلى أيونات.","H₂CO₃ لا يكوّن راسبًا؛ بل يتفكك فورًا لا مع مرور الزمن.","تفكك H₂CO₃ ذاتي ولا يحتاج إلى حمض زائد؛ فهو غير مستقر بطبيعته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:27:04.846Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل الأول إحلال مزدوج: HCl(aq) + NaHCO₃(aq) → H₂CO₃(aq) + NaCl(aq). التفاعل الثاني تفكك فوري لحمض الكربونيك غير المستقر: H₂CO₃(aq) → H₂O(l) + CO₂(g). بجمع المعادلتين وحذف H₂CO₃ من الطرفين (لأنه ناتج في الأولى ومتفاعل في الثانية) نحصل على المعادلة الكلية: HCl(aq) + NaHCO₃(aq) → H₂O(l) + CO₂(g) + NaCl(aq). وبكتابة الذائبات أيونات وحذف المتفرجين Na⁺ وCl⁻ تكون المعادلة الأيونية النهائية: H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g).', '["معادلة الإحلال المزدوج المنتجة لـ H₂CO₃","معادلة تفكك H₂CO₃ إلى H₂O وCO₂","المعادلة الكلية بعد حذف H₂CO₃","المعادلة الأيونية النهائية H⁺ + HCO₃⁻ → H₂O + CO₂"]'::jsonb, '["الإحلال المزدوج: HCl(aq) + NaHCO₃(aq) → H₂CO₃(aq) + NaCl(aq)","التفكك: H₂CO₃(aq) → H₂O(l) + CO₂(g)","اجمع المعادلتين واحذف H₂CO₃ من الطرفين: HCl(aq) + NaHCO₃(aq) → H₂O(l) + CO₂(g) + NaCl(aq)","اكتب الكاملة H⁺ + Cl⁻ + Na⁺ + HCO₃⁻ → H₂O(l) + CO₂(g) + Na⁺ + Cl⁻ ثم احذف Na⁺ وCl⁻: H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)"]'::jsonb, '[{"element":"معادلة الإحلال المزدوج الصحيحة مع تسميته","marks":1},{"element":"معادلة التفكك الصحيحة مع تسميته","marks":1},{"element":"المعادلة الكلية الصحيحة بعد حذف H₂CO₃ مع التعليل","marks":2},{"element":"المعادلة الأيونية النهائية الصحيحة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلتان صحيحتان مع تسمية النوعين، وكلية صحيحة بتعليل الحذف، ونهائية صحيحة"},{"level":"4–5 درجات","description":"المعادلتان والكلية صحيحة مع نقص في التعليل أو في النهائية"},{"level":"2–3 درجات","description":"معادلة الإحلال أو التفكك صحيحة مع المعادلة الكلية دون تعليل"},{"level":"1 درجة","description":"ذكر H₂CO₃ بوصفه مادة وسطية دون معادلات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء H₂CO₃ في المعادلة الكلية","كتابة CO₃²⁻ بدل HCO₃⁻ في المعادلة النهائية","عكس ترتيب التفاعلين","كتابة CO₂ على شكل أيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.846Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة غير صحيحة. يحدث تفاعلان متزامنان: الأول إحلال مزدوج ينتج مادة وسطية هي حمض الكربونيك: HBr(aq) + NaHCO₃(aq) → H₂CO₃(aq) + NaBr(aq)؛ والثاني تفكك فوري لهذا الحمض غير المستقر: H₂CO₃(aq) → H₂O(l) + CO₂(g). وH₂CO₃ لا يظهر في المعادلة الكلية HBr(aq) + NaHCO₃(aq) → H₂O(l) + CO₂(g) + NaBr(aq) لأنه يتكوّن ثم يتفكك في الحال، فيبدو كأن CO₂ تكوّن مباشرة، لكن الحقيقة أنه ناتج التفكك.', '["الحكم: العبارة غير صحيحة","الإحلال المزدوج ينتج H₂CO₃ مادة وسطية","H₂CO₃ يتفكك فورًا إلى H₂O وCO₂","سبب غياب H₂CO₃ عن المعادلة الكلية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"معادلة الإحلال المزدوج المنتجة لـ H₂CO₃","marks":1},{"element":"معادلة تفكك H₂CO₃","marks":1},{"element":"تفسير غياب H₂CO₃ عن المعادلة الكلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع معادلتين صحيحتين وتفسير غياب H₂CO₃ عن المعادلة الكلية"},{"level":"2–3 درجات","description":"حكم صحيح مع معادلة واحدة أو تفسير ناقص"},{"level":"1 درجة","description":"حكم صحيح دون معادلات أو تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن H₂CO₃ لا يظهر في المعادلة الكلية","القول إن H₂CO₃ أيون متفرج","كتابة تفكك NaHCO₃ بدل تفكك H₂CO₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.846Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل الأول: H⁺(aq) + Br⁻(aq) + Na⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g) + Na⁺(aq) + Br⁻(aq)؛ المتفرجان Na⁺ وBr⁻. التفاعل الثاني: H⁺(aq) + NO₃⁻(aq) + K⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g) + K⁺(aq) + NO₃⁻(aq)؛ المتفرجان K⁺ وNO₃⁻. بعد حذف المتفرجين تكون النهائية في الحالتين H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)؛ فهما متشابهتان لأن الجسيمين المتفاعلين فعلًا واحدان (H⁺ من الحمض وHCO₃⁻ من البيكربونات) وتختلف المتفرجة فقط. ويشبههما في الجسم تفاعل أيونات HCO₃⁻ مع H⁺ في الأوعية الدموية للرئتين لتكوين ماء وCO₂ يخرج مع هواء الزفير.', '["المعادلة الكاملة الصحيحة للتفاعل الأول وتحديد Na⁺ وBr⁻","المعادلة الكاملة الصحيحة للتفاعل الثاني وتحديد K⁺ وNO₃⁻","النهائية المشتركة H⁺ + HCO₃⁻ → H₂O + CO₂","تفسير التشابه بأن المشاركة واحدة والمتفرجة مختلفة","ذكر تفاعل الرئتين (HCO₃⁻ مع H⁺)"]'::jsonb, '["اكتب الكاملة (1): H⁺ + Br⁻ + Na⁺ + HCO₃⁻ → H₂O(l) + CO₂(g) + Na⁺ + Br⁻؛ المتفرجان Na⁺ وBr⁻","اكتب الكاملة (2): H⁺ + NO₃⁻ + K⁺ + HCO₃⁻ → H₂O(l) + CO₂(g) + K⁺ + NO₃⁻؛ المتفرجان K⁺ وNO₃⁻","احذف المتفرجين فتصبح النهائية في الحالتين: H⁺(aq) + HCO₃⁻(aq) → H₂O(l) + CO₂(g)","فسّر: المتفاعلان الفعليان H⁺ وHCO₃⁻ في الحالتين؛ واربط ذلك بتفاعل H⁺ مع HCO₃⁻ في الرئتين"]'::jsonb, '[{"element":"المعادلة الكاملة للتفاعل الأول مع المتفرجين","marks":1},{"element":"المعادلة الكاملة للتفاعل الثاني مع المتفرجين","marks":1},{"element":"المعادلة النهائية الصحيحة المشتركة","marks":1},{"element":"تفسير التشابه","marks":1},{"element":"ذكر التفاعل الحيوي المشابه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان كاملتان صحيحتان، ونهائية مشتركة، وتفسير صحيح، وربط بتفاعل الرئتين"},{"level":"3–4 درجات","description":"المعادلتان صحيحتان مع نقص في التفسير أو في الربط الحيوي"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو النهائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة CO₃²⁻ بدل HCO₃⁻","إبقاء Na⁺ أو K⁺ في النهائية","القول إن المعادلتين النهائيتين مختلفتان لاختلاف الحمضين","كتابة CO₂ على شكل أيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.847Z"}'::jsonb)
