('mcq', 1, 1, 'وحدة النظام الدولي الأساسية لقياس كمية المادة هي المول (mol)، أما الجرام فللكتلة واللتر للحجم، والدرزن وحدة عدّ يومية.', '["الجرام وحدة لقياس الكتلة وليس كمية المادة.","","اللتر وحدة لقياس الحجم وليس كمية المادة.","الدرزن وحدة عدّ يومية تمثل 12 شيئًا، وليست من وحدات النظام الدولي الأساسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.847Z"}'::jsonb),
('mcq', 2, 2, 'المول هو عدد ذرات الكربون-12 في عينة كتلتها 12 g من الكربون-12، وهذه الكتلة هي التي تحدد عدد الذرات في المول الواحد.', '["الكتلة 1 g ليست الكتلة المرجعية في التعريف؛ فالعينة المرجعية كتلتها 12 g.","6.02 g خلط بين العدد 6.02 الوارد في عدد أفوجادرو وكتلة العينة المرجعية.","","24 g ضعف الكتلة المرجعية، وتمثل مولين من الكربون-12 لا مولًا واحدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:27:04.847Z"}'::jsonb),
('mcq', 3, 0, 'اتُّفق من التجارب على أن المول الواحد من أي مادة يحتوي على 6.02 × 10²³ من الجسيمات الممثلة لها.', '["","6.02 × 10²⁴ يساوي عشرة أمثال العدد في المول الواحد، أي ما يقابل 10 mol.","6.02 × 10²² يساوي عُشر العدد في المول الواحد، أي ما يقابل 0.1 mol.","الأس السالب يعطي عددًا متناهيًا في الصغر، بينما المول يحتوي على عدد هائل من الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.848Z"}'::jsonb),
('mcq', 4, 3, 'المول الواحد من أي مادة يحتوي على 6.02 × 10²³ من الجسيمات الممثلة، فعينة الماء تحتوي على هذا العدد من الجزيئات وعينة النحاس تحتوي عليه من الذرات.', '["الجسيم الممثل للماء هو الجزيء، ويُعدّ الجزيء الواحد جسيمًا واحدًا مهما بلغ عدد ذراته؛ فعدد الجزيئات في المول 6.02 × 10²³ فقط.","عدد الجسيمات في المول لا يعتمد على الكتلة؛ فالمول من أي مادة يحتوي على العدد نفسه حتى لو اختلفت الكتلتان.","نوع الجسيم الممثل (جزيء أو ذرة) لا يغير العدد؛ فهو 6.02 × 10²³ في كل حالة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.848Z"}'::jsonb),
('mcq', 5, 2, 'يُعرَّف المول بدلالة عدد ذرات الكربون-12 في عينة كتلتها 12 g، فالكربون-12 هو النظير المرجعي.', '["الهيدروجين-1 ليس النظير المرجعي في تعريف المول.","الكربون-14 نظير آخر للكربون، والتعريف يعتمد الكربون-12 وليس هذا النظير.","","الأكسجين-16 ليس النظير الذي يستند إليه تعريف المول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.848Z"}'::jsonb),
('mcq', 6, 0, 'العينة التي كتلتها 12 g من الكربون-12 تمثل 1 mol أي 6.02 × 10²³ ذرة. و2 mol من الفضة تحتوي على 2 × 6.02 × 10²³ = 1.20 × 10²⁴ ذرة، وهو أكبر من هذا العدد.', '["","0.5 mol تحتوي على نصف العدد، أي 3.01 × 10²³ ذرة، وهو أقل من 6.02 × 10²³.","1 mol من الحديد يحتوي على 6.02 × 10²³ ذرة، وهو العدد نفسه وليس أكبر منه.","1 mol من الماء يحتوي على 6.02 × 10²³ جزيء، وهو العدد نفسه من الجسيمات الممثلة وليس أكبر منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.849Z"}'::jsonb),
('mcq', 7, 1, 'المول هو وحدة النظام الدولي الأساسية لقياس كمية المادة، ويحتوي على 6.02 × 10²³ جسيمًا ممثلًا؛ أما 12 g فهي كتلة عينة الكربون-12 التي يُعرَّف بها المول وليست كتلة المول من أي مادة.', '["المول ليس وحدة كتلة، بل وحدة لكمية المادة، وعدد الجسيمات فيه ثابت.","","المول ليس وحدة حجم؛ فهو وحدة لكمية المادة تعبّر عن عدد الجسيمات.","المول يمثل 6.02 × 10²³ جسيمًا لا 12 جسيمًا؛ فالرقم 12 يخص الدرزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.849Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المول وحدة النظام الدولي الأساسية لقياس كمية المادة، ويُعرَّف بأنه عدد ذرات الكربون-12 في عينة كتلتها 12 g من الكربون-12. والمول الواحد من أي مادة يحتوي على 6.02 × 10²³ من الجسيمات الممثلة لها.', '["المول وحدة النظام الدولي الأساسية لقياس كمية المادة","هو عدد ذرات الكربون-12 في عينة كتلتها 12 g من الكربون-12","المول الواحد يحتوي على 6.02 × 10²³ من الجسيمات الممثلة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن المول وحدة أساسية لقياس كمية المادة","marks":1},{"element":"التعريف بدلالة ذرات الكربون-12 في 12 g","marks":1},{"element":"ذكر العدد 6.02 × 10²³ للجسيمات الممثلة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل للمول مع ذكر العدد 6.02 × 10²³"},{"level":"2 درجة","description":"ذكر عنصرين صحيحين من العناصر الثلاثة"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المول وحدة كتلة أو حجم","نسيان ذكر الكربون-12 والكتلة 12 g في التعريف","كتابة العدد 6.02 × 10²³ بأس خاطئ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-18T03:27:04.849Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لأن المول الواحد من أي مادة يحتوي على 6.02 × 10²³ من الجسيمات الممثلة لها، بغض النظر عن نوع المادة. والجسيم الممثل للماء هو الجزيء، فمول من الماء يحتوي على 6.02 × 10²³ جزيء من H₂O. والجسيم الممثل للنحاس هو الذرة، فمول من النحاس يحتوي على 6.02 × 10²³ ذرة من Cu. فالعدد واحد في الحالتين، ويختلف نوع الجسيم فقط.', '["المول من أي مادة يحتوي على 6.02 × 10²³ من الجسيمات الممثلة","الجسيم الممثل للماء هو الجزيء","الجسيم الممثل للنحاس هو الذرة","العدد في العينتين 6.02 × 10²³ ويختلف نوع الجسيم فقط"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل بأن المول يحتوي على 6.02 × 10²³ جسيمًا لأي مادة","marks":1},{"element":"تحديد الجزيء جسيمًا ممثلًا للماء","marks":1},{"element":"تحديد الذرة جسيمًا ممثلًا للنحاس","marks":1},{"element":"ذكر العدد 6.02 × 10²³ في العينتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح مع تحديد نوع الجسيم الممثل في كل مادة وذكر العدد"},{"level":"2–3 درجات","description":"تعليل صحيح مع نقص في تحديد الجسيم أو العدد"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد الجسيمات يعتمد على كتلة المادة","عدّ ذرات جزيء الماء جسيمات ممثلة بدل الجزيء","الخلط بين نوع الجسيم الممثل وعدده"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:27:04.849Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير دقيقة؛ فالمول الواحد يحتوي على 6.02 × 10²³ من الجسيمات الممثلة للمادة، وهذه الجسيمات قد تكون ذرات أو جزيئات أو أيونات أو وحدات صيغة، وليست ذرات دائمًا. فمول من الماء يحتوي على 6.02 × 10²³ جزيء، وكل جزيء فيه 3 ذرات، فعدد الذرات الكلي = 3 × 6.02 × 10²³ = 1.81 × 10²⁴ ذرة. أما مول من كلوريد الصوديوم فيحتوي على 6.02 × 10²³ وحدة صيغة من NaCl.', '["العدد 6.02 × 10²³ يخص الجسيمات الممثلة وليس الذرات دائمًا","الجسيمات الممثلة قد تكون ذرات أو جزيئات أو أيونات أو وحدات صيغة","مول الماء يحتوي على 6.02 × 10²³ جزيء","مول NaCl يحتوي على 6.02 × 10²³ وحدة صيغة","عدد الذرات في مول الماء = 3 × 6.02 × 10²³ = 1.81 × 10²⁴ ذرة"]'::jsonb, '["عدد جزيئات الماء في 1 mol = 6.02 × 10²³ جزيء","كل جزيء H₂O يحتوي على 3 ذرات (ذرتا هيدروجين وذرة أكسجين)","عدد الذرات = 3 × 6.02 × 10²³ = 1.81 × 10²⁴ ذرة"]'::jsonb, '[{"element":"تحديد الخطأ: العدد يخص الجسيمات الممثلة وليس الذرات فقط","marks":1},{"element":"ذكر أنواع الجسيمات الممثلة المختلفة","marks":1},{"element":"تحديد جسيم الماء (جزيء) وجسيم NaCl (وحدة صيغة) وعددهما","marks":1},{"element":"حساب عدد الذرات في مول الماء بخطوات صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ، وذكر أنواع الجسيمات، وتحديد جسيمي الماء وNaCl، والحساب الصحيح 1.81 × 10²⁴ ذرة"},{"level":"2–3 درجات","description":"تحديد الخطأ مع نقص في التفصيل أو في الحساب"},{"level":"1 درجة","description":"ملاحظة أن العبارة خاطئة دون تعليل صحيح أو حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي واعتبار كل جسيم ممثل ذرة","الإجابة بأن عدد الذرات في مول الماء 6.02 × 10²³ دون ضرب في 3","تسمية NaCl جزيئًا بدل وحدة صيغة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:27:04.849Z"}'::jsonb)
