('mcq', 3, 3, 'الرزمة الواحدة تحتوي على 500 ورقة، فعدد الرزم = 1000 ÷ 500 = 2 رزمة.', '["10 رزم تعني اعتبار الرزمة 100 ورقة، والرزمة تحتوي على 500 ورقة.","83 ناتج قسمة 1000 على 12 أي استعمال قيمة الدرزن بدل الرزمة.","500 ناتج قسمة 1000 على 2 أي استعمال قيمة الزوج؛ والرزمة تمثل 500 ورقة لا شيئين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:27:04.850Z"}'::jsonb),
('mcq', 4, 1, 'الدرزن وحدة عدّ تمثل 12 شيئًا، وهو يشبه المول الذي يمثل 6.02 × 10²³ جسيمًا؛ أما اللتر والمتر والجرام فوحدات قياس للحجم والطول والكتلة.', '["اللتر وحدة قياس للحجم وليست وحدة عدّ.","","المتر وحدة قياس للطول وليست وحدة عدّ.","الجرام وحدة قياس للكتلة وليست وحدة عدّ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.850Z"}'::jsonb),
('mcq', 5, 3, 'العدد الذي تمثله الوحدة ثابت دائمًا أيًّا كان نوع الشيء، فكل درزن يمثل 12 شيئًا، أما الكتلة فتختلف لاختلاف حجم الأشياء وتركيبها.', '["كتلة الدرزن لا تغيّر عدد الأشياء فيه؛ فالدرزن يمثل 12 شيئًا دائمًا.","حجم الشيء لا يؤثر في العدد الذي تمثله الوحدة؛ فكل درزن 12 شيئًا.","اختلاف التركيب يغيّر الكتلة فقط، أما العدد الذي يمثله الدرزن فثابت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.850Z"}'::jsonb),
('mcq', 6, 1, 'الرزمة وحدة عدّ تمثل عددًا محددًا (500 ورقة)، وتجعل شراء الورق وبيعه أسهل من التعامل مع كل ورقة على حدة.', '["الرزمة وحدة عدّ لا وحدة كتلة.","","عدد الأوراق في الرزمة ثابت (500) ولا يتغير بحجم الورق.","الورقة الواحدة يمكن عدّها، لكن عدّ الأوراق الكثيرة واحدةً واحدة أصعب من استعمال الرزمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:27:04.850Z"}'::jsonb),
('mcq', 7, 0, 'كل من المول والدرزن وحدة عدّ تمثل عددًا ثابتًا: الدرزن 12 شيئًا والمول 6.02 × 10²³ جسيمًا، أيًّا كان نوع الشيء المعدود.', '["","الدرزن وحده يمثل 12 شيئًا، أما المول فيمثل 6.02 × 10²³ جسيمًا.","كلاهما وحدة عدّ لا وحدة كتلة.","عدد كل منهما ثابت ولا يتغير باختلاف نوع الشيء المعدود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-18T03:27:04.851Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من وحدات العدّ اليومية: الزوج ويمثل شيئين (مثل زوج القفازات)، والدرزن ويمثل 12 شيئًا (مثل درزن أقلام الرصاص)، والرزمة وتمثل 500 ورقة (مثل رزمة ورق الطباعة).', '["الزوج = 2","الدرزن = 12","الرزمة = 500 ورقة"]'::jsonb, '[]'::jsonb, '[{"element":"الزوج وعدده 2","marks":1},{"element":"الدرزن وعدده 12","marks":1},{"element":"الرزمة وعددها 500 ورقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر ثلاث وحدات مع العدد الصحيح لكل منها"},{"level":"2 درجة","description":"ذكر وحدتين صحيحتين مع عدديهما"},{"level":"1 درجة","description":"ذكر وحدة واحدة صحيحة مع عددها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة عدد الدرزن 10 بدل 12","ذكر وحدات قياس كالمتر واللتر على أنها وحدات عدّ","ذكر الوحدة دون العدد الذي تمثله"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.851Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وجه الشبه: كل من المول والدرزن وحدة عدّ تمثل عددًا ثابتًا من الأشياء مهما كان نوعها؛ فالدرزن 12 شيئًا سواء كانت بيضًا أو أقلامًا، والمول 6.02 × 10²³ جسيمًا سواء كانت ذرات أو جزيئات أو أيونات. وكلاهما يسهّل العدّ. أما الاختلاف فهو في العدد الذي تمثله كل وحدة: الدرزن 12 فقط ويُستعمل لعدّ الأشياء اليومية، أما المول فعدد هائل (6.02 × 10²³) يناسب الجسيمات المتناهية في الصغر كالذرات.', '["كلاهما وحدة عدّ تمثل عددًا ثابتًا من الأشياء","العدد ثابت مهما كان نوع الشيء المعدود","كلاهما يسهّل عملية العدّ","يختلفان في العدد: الدرزن 12 والمول 6.02 × 10²³","الدرزن للأشياء اليومية والمول للجسيمات المتناهية في الصغر"]'::jsonb, '[]'::jsonb, '[{"element":"كلاهما وحدة عدّ تمثل عددًا ثابتًا مهما كان نوع الشيء","marks":1},{"element":"كلاهما يسهّل عملية العدّ","marks":1},{"element":"الاختلاف في العدد (12 مقابل 6.02 × 10²³)","marks":1},{"element":"ربط المول بعدّ الجسيمات الدقيقة والدرزن بالأشياء اليومية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر وجه الشبه كاملًا مع الاختلاف في العدد وفي مجال الاستعمال"},{"level":"2–3 درجات","description":"ذكر وجه الشبه مع نقص في الاختلاف أو التعليل"},{"level":"1 درجة","description":"ذكر أن كليهما وحدة عدّ دون تفصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المول يمثل 12 جسيمًا","القول إن عدد الدرزن يتغير بتغير الشيء المعدود","اعتبار المول وحدة كتلة كالجرام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-18T03:27:04.851Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد البيض = 2.5 درزن × (12 بيضة / 1 درزن) = 30 بيضة. عدد القفازات = 3 أزواج × (2 قفاز / 1 زوج) = 6 قفازات. عدد الأوراق = 1.5 رزمة × (500 ورقة / 1 رزمة) = 750 ورقة.', '["اختيار عامل التحويل الذي تُلغى معه وحدة العدّ المعطاة","30 بيضة","6 قفازات","750 ورقة"]'::jsonb, '["البيض: 2.5 درزن × (12 بيضة / 1 درزن) = 30 بيضة","القفازات: 3 أزواج × (2 قفاز / 1 زوج) = 6 قفازات","الورق: 1.5 رزمة × (500 ورقة / 1 رزمة) = 750 ورقة"]'::jsonb, '[{"element":"كتابة عامل التحويل الصحيح مع إلغاء الوحدات","marks":1},{"element":"عدد البيض 30","marks":1},{"element":"عدد القفازات 6","marks":1},{"element":"عدد الأوراق 750","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"استعمال عوامل التحويل الصحيحة والحصول على القيم الثلاث الصحيحة"},{"level":"2–3 درجات","description":"قيمتان صحيحتان أو ثلاث قيم مع خطأ في عرض عامل التحويل"},{"level":"1 درجة","description":"قيمة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة عدد الدزينات على 12 بدل ضربه فيه","استعمال العدد 12 مع الأزواج أو الرزم","الإجابة بالأرقام دون الوحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.851Z"}'::jsonb)
