('mcq', 1, 3, 'عدد أفوجادرو هو عدد الجسيمات الممثلة (ذرات أو جزيئات أو أيونات أو وحدات صيغة) في مول واحد من أي مادة.', '["عدد الذرات في 1 g يختلف من عنصر إلى آخر، بينما عدد أفوجادرو ثابت لكل مول من أي مادة.","عينة الكربون-12 التي كتلتها 12 g تمثل مولًا واحدًا، وعدد أفوجادرو هو عدد الجسيمات فيه لا عدد المولات.","عدد أفوجادرو مرتبط بالمول لا بحجم لتر من الغاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.851Z"}'::jsonb),
('mcq', 2, 0, 'القيمة الدقيقة لعدد أفوجادرو 6.0221367 × 10²³، وتُقرَّب في المسائل إلى 6.02 × 10²³.', '["","6.20 × 10²³ تبديل لموضع رقمين من 6.02.","6.02 × 10³² تبديل لرقمي الأس 23 فصار 32.","الأس السالب يعطي عددًا متناهيًا في الصغر، وعدد أفوجادرو عدد هائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('mcq', 3, 2, 'سُمّي العدد 6.0221367 × 10²³ تكريمًا للفيزيائي الإيطالي أميديو أفوجادرو.', '["دالتون عالم بريطاني اشتهر بنظريته الذرية، ولم يُسمَّ هذا العدد باسمه.","مندليف اشتهر بالجدول الدوري، ولم يُسمَّ هذا العدد باسمه.","","لافوازييه عالم فرنسي اشتهر بقانون حفظ الكتلة، ولم يُسمَّ هذا العدد باسمه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('mcq', 4, 1, 'تمكّن أفوجادرو عام 1811م من تحديد حجم مول من الغاز، وسُمّي عدد الجسيمات في المول تكريمًا له.', '["الكتاب لا ينسب إليه تحديد كتلة ذرة الكربون-12.","","شحنة الإلكترون لم يحددها أفوجادرو، والمنسوب إليه تحديد حجم مول من الغاز.","عدد الإلكترونات في الذرة ليس ما حدده أفوجادرو عام 1811م."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('mcq', 5, 0, 'عدد أفوجادرو ثابت ويساوي 6.02 × 10²³ للجسيمات الممثلة في مول واحد من أي مادة، أيًّا كان نوع هذه الجسيمات.', '["","العدد لا يتأثر بنوع المادة ولا بثقلها؛ فهو واحد لجميع المواد.","العدد يرتبط بالمول لا بكتلة العينة؛ وهو ثابت في المول الواحد.","العدد نفسه للذرات والجزيئات والأيونات ووحدات الصيغة في المول الواحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('mcq', 6, 1, 'العلاقة 1 mol = 6.02 × 10²³ جسيم ممثل تعطي عاملي التحويل: (6.02 × 10²³ جسيم / 1 mol) ومقلوبه (1 mol / 6.02 × 10²³ جسيم).', '["العدد 12 يخص الدرزن وليس المول.","","عدد أفوجادرو يربط الجسيمات بالمولات لا بالجرامات.","هذا العامل يجعل جسيمًا واحدًا يعادل 6.02 × 10²³ mol، وهي علاقة معكوسة خاطئة؛ فالمول الواحد هو الذي يقابل 6.02 × 10²³ جسيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('mcq', 7, 3, 'عدد أفوجادرو يساوي عدد الجسيمات الممثلة في مول واحد، فالعينة التي تحتوي على 6.02 × 10²³ ذرة تساوي 1 mol.', '["العدد 12 مأخوذ من كتلة عينة الكربون-12 (12 g) ولا علاقة له بعدد المولات هنا.","هذا الجواب يعدّ العدد 6.02 × 10²³ عدد المولات، وهو في الحقيقة عدد الجسيمات في مول واحد.","الأس السالب يعطي كمية متناهية في الصغر، بينما العينة تحتوي على عدد أفوجادرو كاملًا من الذرات أي مولًا واحدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عدد أفوجادرو هو عدد الجسيمات الممثلة في مول واحد من أي مادة. قيمته الدقيقة 6.0221367 × 10²³ ويُقرَّب في المسائل إلى 6.02 × 10²³. وسُمّي تكريمًا للفيزيائي الإيطالي أميديو أفوجادرو.', '["عدد الجسيمات الممثلة في مول واحد من أي مادة","القيمة الدقيقة 6.0221367 × 10²³","القيمة التقريبية 6.02 × 10²³","سُمّي تكريمًا للفيزيائي الإيطالي أميديو أفوجادرو"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف عدد أفوجادرو","marks":1},{"element":"القيمة الدقيقة 6.0221367 × 10²³","marks":1},{"element":"القيمة التقريبية 6.02 × 10²³","marks":1},{"element":"ذكر أميديو أفوجادرو","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع القيمتين واسم العالم"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في القيمتين أو اسم العالم"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بأنه عدد الذرات فقط","كتابة الأس خطأ (10²² أو 10²⁴)","نسبته إلى عالم آخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العلاقة: 1 mol = 6.02 × 10²³ جسيم ممثل. ومنها عاملا التحويل: (6.02 × 10²³ جسيم / 1 mol) و(1 mol / 6.02 × 10²³ جسيم). يُستعمل العامل الأول عند التحويل من المولات إلى جسيمات (عدد الجسيمات = عدد المولات × العامل)، لأن المول يُلغى ويبقى عدد الجسيمات. ويُستعمل العامل الثاني (المقلوب) عند التحويل من الجسيمات إلى مولات، لأن وحدة الجسيمات تُلغى وتبقى المولات.', '["العلاقة 1 mol = 6.02 × 10²³ جسيم","العامل الأول: 6.02 × 10²³ جسيم / 1 mol","العامل الثاني: 1 mol / 6.02 × 10²³ جسيم","العامل الأول للتحويل من مولات إلى جسيمات","العامل الثاني للتحويل من جسيمات إلى مولات"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة العلاقة 1 mol = 6.02 × 10²³ جسيم","marks":1},{"element":"كتابة عاملي التحويل بصورتيهما الصحيحتين","marks":1},{"element":"تحديد استعمال العامل الأول للتحويل من المولات إلى جسيمات","marks":1},{"element":"تحديد استعمال المقلوب للتحويل من الجسيمات إلى مولات مع تعليل إلغاء الوحدات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العلاقة وعاملان صحيحان مع تحديد استعمال كل منهما"},{"level":"2–3 درجات","description":"كتابة العاملين دون تحديد كامل لاستعمالهما، أو العكس"},{"level":"1 درجة","description":"ذكر العلاقة أو عامل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس موضع البسط والمقام في عامل التحويل","استعمال العامل نفسه في الاتجاهين","كتابة العامل دون وحدات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.852Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطريقة الأولى: 2.00 mol × 6.0221367 × 10²³ جسيم/mol = 1.20442734 × 10²⁴ جسيم. الطريقة الثانية: 2.00 mol × 6.02 × 10²³ جسيم/mol = 1.204 × 10²⁴ جسيم. الكمية 2.00 mol تحتوي على ثلاثة أرقام معنوية، لذا يُكتب الناتج في الحالتين 1.20 × 10²⁴ جسيم، فلا يختلف الناتجان. وتكفي القيمة 6.02 × 10²³ لأنها تحتوي على ثلاثة أرقام معنوية تناسب بيانات المسائل، ولا تغيّر الأرقام الإضافية الناتج.', '["الناتج بالقيمة الدقيقة 1.2044 × 10²⁴ جسيم","الناتج بالقيمة التقريبية 1.204 × 10²⁴ جسيم","كلاهما 1.20 × 10²⁴ بثلاثة أرقام معنوية","القيمة 6.02 × 10²³ تكفي لأن البيانات بثلاثة أرقام معنوية"]'::jsonb, '["بالقيمة الدقيقة: 2.00 × 6.0221367 × 10²³ = 1.20442734 × 10²⁴","بالقيمة التقريبية: 2.00 × 6.02 × 10²³ = 1.204 × 10²⁴","التقريب إلى ثلاثة أرقام معنوية (لأن 2.00 تحتوي على ثلاثة): 1.20 × 10²⁴ في الحالتين"]'::jsonb, '[{"element":"حساب الناتج بالقيمة الدقيقة","marks":1},{"element":"حساب الناتج بالقيمة التقريبية","marks":1},{"element":"كتابة الناتج بثلاثة أرقام معنوية والاستنتاج أنهما متطابقان","marks":1},{"element":"تعليل كفاية القيمة 6.02 × 10²³","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح بالطريقتين مع الأرقام المعنوية والاستنتاج والتعليل"},{"level":"2–3 درجات","description":"حساب صحيح مع نقص في الأرقام المعنوية أو التعليل"},{"level":"1 درجة","description":"حساب إحدى الطريقتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترك الناتج بأرقام معنوية أكثر مما تسمح به البيانات","القول إن الناتجين مختلفان دون مراعاة الأرقام المعنوية","قسمة المولات على عدد أفوجادرو بدل ضربها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:27:04.853Z"}'::jsonb)
