('mcq', 3, 'غاز الأكسجين O₂ تتكوّن كل جزيئة منه من ذرتين. ما عدد ذرات الأكسجين في 3.00 mol من جزيئات O₂؟', null, '["3.61 × 10²⁴ ذرة","1.81 × 10²⁴ ذرة","1.20 × 10²⁴ ذرة","3.61 × 10²⁵ ذرة"]'::jsonb, 'تطبيق', 'تحويل مولات إلى ذرات مع مراعاة الصيغة', 'متوسط', 'الكتاب ص 157 — المسألة التدريبية 4 (تحفيز)'),
('mcq', 4, 'أراد طالب تحويل 4.50 × 10²² ذرة من الفضة Ag إلى مولات. أيّ الخيارات الآتية يذكر عامل التحويل الصحيح والناتج الصحيح؟', null, '["العامل (6.02 × 10²³ ذرة / 1 mol)، والناتج 2.71 × 10⁴⁶","العامل (6.02 × 10²³ ذرة / 1 mol)، والناتج 13.4 mol","العامل (1 mol / 6.02 × 10²³ ذرة)، والناتج 0.0748 mol","العامل (1 mol / 6.02 × 10²³ ذرة)، والناتج 0.748 mol"]'::jsonb, 'فهم', 'اختيار عامل التحويل والتحقق من الناتج', 'سهل', 'الكتاب ص 157، 158 — تحويل الجسيمات إلى مولات (مثال 5-1)'),
('mcq', 5, 'أيّ العيّنات الآتية تحتوي على أكبر عدد من الجسيمات الممثلة؟', null, '["2.00 mol من الحديد Fe","1.50 × 10²⁴ ذرة من الخارصين Zn","0.50 mol من الماء H₂O","4.00 × 10²³ جزيء من ثاني أكسيد الكربون CO₂"]'::jsonb, 'تحليل', 'مقارنة عدد الجسيمات بعد توحيد الوحدات', 'متوسط', 'الكتاب ص 159 — التقويم 5-1 (س13)'),
('mcq', 6, 'حلّ طالب مسألة كما يأتي: «عدد مولات النحاس في 3.01 × 10²³ ذرة Cu = 3.01 × 10²³ ذرة × (6.02 × 10²³ ذرة / 1 mol) = 1.81 × 10⁴⁷». ما سبب خطأ هذا الحل؟', null, '["القيمة الصحيحة لعدد أفوجادرو هي 6.02 × 10²² وليست 6.02 × 10²³","كان يجب ضرب عدد الذرات في الكتلة المولية للنحاس لا في عدد أفوجادرو","كان يجب جمع عدد أفوجادرو إلى عدد الذرات ثم القسمة على 2","استعمل عامل التحويل مقلوبًا فلم تُلغَ وحدة «ذرة»؛ والصواب القسمة على 6.02 × 10²³ لينتج 0.500 mol"]'::jsonb, 'تحليل', 'تشخيص خطأ في حل مسألة', 'صعب', 'الكتاب ص 157، 158 — تحويل الجسيمات إلى مولات'),
('mcq', 7, 'ما عدد جزيئات الميثان CH₄ في 1.35 × 10⁻² mol منه؟', null, '["2.24 × 10⁻²⁶ جزيء","8.13 × 10²¹ جزيء","8.13 × 10²⁵ جزيء","4.46 × 10²⁵ جزيء"]'::jsonb, 'تطبيق', 'تحويل مولات إلى جزيئات بأس سالب', 'صعب', 'الكتاب ص 159، 180 — التقويم 5-1 (س12 د)'),
('essay', 1, 'احسب عدد الذرات في 4.80 mol من الخارصين Zn، وعدد وحدات الصيغة في 3.20 × 10⁻³ mol من كلوريد الصوديوم NaCl. اكتب في كل حالة عامل التحويل المستعمل، وبيّن إلغاء الوحدات، وأعطِ الناتج بثلاثة أرقام معنوية.', null, null, 'تطبيق', 'حل مسألة تحويل مولات إلى جسيمات', 'متوسط', 'الكتاب ص 156، 157 — تحويل المولات إلى جسيمات'),
('essay', 2, 'احسب عدد المولات في كلٍّ مما يأتي: (أ) 5.75 × 10²⁴ ذرة من الألومنيوم Al. (ب) 2.50 × 10²⁰ ذرة من الحديد Fe. ثم وضّح، قبل الحساب، لماذا يجب أن يكون ناتج (أ) أكبر من 1 mol وناتج (ب) أقل من 1 mol.', null, null, 'تطبيق', 'تحويل جسيمات إلى مولات مع تقدير الناتج', 'متوسط', 'الكتاب ص 158 — مثال 5-1 والمسألة التدريبية 5'),
('essay', 3, 'تحتوي عيّنة من ثاني أكسيد الكربون CO₂ على 9.03 × 10²³ جزيء. احسب: (أ) عدد مولات CO₂ في العيّنة. (ب) عدد ذرات الأكسجين فيها. (ج) العدد الكلي للذرات فيها. بيّن خطوات الحل.', null, null, 'تحليل', 'حل مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 157، 158 — تحويل الجسيمات إلى مولات؛ المسألة التدريبية 4')
