from (values
('mcq', 1, 2, 'عدد الذرات = عدد المولات × (6.02 × 10²³ ذرة / 1 mol) = 2.40 mol × (6.02 × 10²³ ذرة / 1 mol) = 1.44 × 10²⁴ ذرة. وهي أكبر من 6.02 × 10²³ كما يُتوقع لأن العينة أكثر من مول واحد.', '["هذا ناتج قسمة 2.40 على 6.02 × 10²³ بدلًا من الضرب؛ فعند التحويل من مولات إلى جسيمات يوضع عدد أفوجادرو في البسط.","هذا ناتج خطأ في موضع الفاصلة العشرية عند الضرب (14.4 × 10²² كُتبت 1.44 × 10²³)؛ والصواب 14.4 × 10²³ = 1.44 × 10²⁴.","","هذا ناتج قسمة 6.02 × 10²³ على 2.40، أي قلب النسبة؛ والمطلوب ضرب 2.40 في 6.02 × 10²³."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.853Z"}'::jsonb),
('mcq', 2, 3, 'عدد المولات = عدد الجزيئات × (1 mol / 6.02 × 10²³ جزيء) = 7.22 × 10²³ ÷ 6.02 × 10²³ = 1.20 mol. والناتج أكبر من 1 mol لأن عدد الجزيئات أكبر من عدد أفوجادرو.', '["هذا ناتج ضرب العدد في 6.02 × 10²³ بدلًا من القسمة؛ والوحدات لا تُلغى بهذه الطريقة.","هذا ناتج قسمة 6.02 × 10²³ على 7.22 × 10²³، أي قلب النسبة؛ والناتج غير معقول لأن العينة تحتوي جزيئات أكثر من عدد أفوجادرو فيجب أن يزيد عدد مولاتها على 1.","هذا ناتج خطأ في الأس عند القسمة؛ فالأسّان متساويان (10²³) ويُلغي أحدهما الآخر، والصواب 7.22 ÷ 6.02 = 1.20 وليس 12.0.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.853Z"}'::jsonb),
('mcq', 3, 0, 'عدد الجزيئات = 3.00 mol × 6.02 × 10²³ جزيء/mol = 1.81 × 10²⁴ جزيء. وكل جزيء يحتوي ذرتين، فعدد الذرات = 1.81 × 10²⁴ × 2 = 3.61 × 10²⁴ ذرة.', '["","هذا عدد جزيئات O₂ فقط؛ نسي الطالب أن كل جزيء يحتوي ذرتين فلم يضرب في 2.","هذا عدد الذرات في 1.00 mol من O₂ (6.02 × 10²³ × 2)؛ نسي الطالب ضرب الناتج في 3.00 mol.","هذا ناتج خطأ في الأس عند الضرب؛ فالناتج 36.1 × 10²³ يُكتب 3.61 × 10²⁴ وليس 3.61 × 10²⁵."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.853Z"}'::jsonb),
('mcq', 4, 2, 'لتحويل الذرات إلى مولات يوضع عدد المولات في البسط وعدد الجسيمات في المقام لتُلغى وحدة «ذرة»: 4.50 × 10²² ذرة × (1 mol / 6.02 × 10²³ ذرة) = 0.0748 mol، وهو أقل من 1 mol كما يُتوقع.', '["العامل مقلوب؛ ضرب العدد في (6.02 × 10²³ ذرة / 1 mol) لا يُلغي وحدة «ذرة»، والناتج 2.71 × 10⁴⁶ لا معنى له.","العامل مقلوب؛ والناتج 13.4 هو 6.02 × 10²³ ÷ 4.50 × 10²² أي قلب النسبة، وهو غير معقول لأن عدد الذرات أقل من عدد أفوجادرو.","","العامل صحيح لكن الناتج خاطئ بمنزلة عشرية؛ 4.50 × 10²² ÷ 6.02 × 10²³ = 0.0748 وليس 0.748."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.854Z"}'::jsonb),
('mcq', 5, 1, 'تُحوَّل جميع العيّنات إلى الوحدة نفسها: 2.00 mol Fe = 1.20 × 10²⁴ ذرة، و0.50 mol H₂O = 3.01 × 10²³ جزيء، و4.00 × 10²³ جزيء CO₂، بينما عيّنة Zn تحتوي 1.50 × 10²⁴ ذرة؛ فهي الأكبر عددًا.', '["الطالب قارن الرقم 2.00 بالرقم 1.50 دون مراعاة اختلاف الوحدتين؛ فـ 2.00 mol من Fe تساوي 1.20 × 10²⁴ ذرة، وهي أقل من 1.50 × 10²⁴.","","0.50 mol من H₂O تساوي 3.01 × 10²³ جزيء، وهو أقل بكثير من 1.50 × 10²⁴.","4.00 × 10²³ أقل من 1.50 × 10²⁴ لأن الأس 23 أصغر من الأس 24."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.854Z"}'::jsonb),
('mcq', 6, 3, 'لتحويل الذرات إلى مولات يجب أن يكون عامل التحويل (1 mol / 6.02 × 10²³ ذرة) كي تُلغى وحدة «ذرة». وبذلك يكون الناتج 3.01 × 10²³ ÷ 6.02 × 10²³ = 0.500 mol، وهو أقل من 1 mol لأن العدد أقل من عدد أفوجادرو.', '["القيمة المستعملة صحيحة؛ فعدد أفوجادرو 6.02 × 10²³ وليس 6.02 × 10²².","الكتلة المولية تُستعمل للتحويل بين الكتلة والمولات، أما التحويل بين الجسيمات والمولات فيستعمل عدد أفوجادرو فقط.","لا تُجمع الأعداد في هذا التحويل؛ يُستعمل عامل تحويل تُلغى به الوحدات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.854Z"}'::jsonb),
('mcq', 7, 1, 'عدد الجزيئات = 1.35 × 10⁻² mol × (6.02 × 10²³ جزيء / 1 mol) = 8.13 × 10²¹ جزيء؛ فالأسّان يُجمعان (−2 + 23 = 21) والعددان 1.35 و6.02 يُضربان.', '["هذا ناتج قسمة 1.35 × 10⁻² على 6.02 × 10²³ بدلًا من الضرب.","","الطالب جمع القيمة المطلقة للأس (2 + 23 = 25) بدلًا من جمع −2 مع 23 جبريًّا.","هذا ناتج قسمة 6.02 × 10²³ على 1.35 × 10⁻²، أي قلب النسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:27:04.854Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحالة الأولى: عدد الذرات = 4.80 mol Zn × (6.02 × 10²³ ذرة / 1 mol Zn) = 2.89 × 10²⁴ ذرة من Zn، وتُلغى وحدة mol فتبقى «ذرة». الحالة الثانية: عدد وحدات الصيغة = 3.20 × 10⁻³ mol NaCl × (6.02 × 10²³ وحدة صيغة / 1 mol NaCl) = 1.93 × 10²¹ وحدة صيغة من NaCl، وتُلغى وحدة mol فتبقى «وحدة صيغة».', '["عامل التحويل (6.02 × 10²³ ذرة / 1 mol) للخارصين مع إلغاء mol","2.89 × 10²⁴ ذرة من Zn","عامل التحويل (6.02 × 10²³ وحدة صيغة / 1 mol) لكلوريد الصوديوم مع إلغاء mol","1.93 × 10²¹ وحدة صيغة من NaCl"]'::jsonb, '["Zn: 4.80 mol × 6.02 × 10²³ ذرة/mol = 2.89 × 10²⁴ ذرة","NaCl: 3.20 × 10⁻³ mol × 6.02 × 10²³ وحدة صيغة/mol = 1.93 × 10²¹ وحدة صيغة"]'::jsonb, '[{"element":"عامل التحويل الصحيح مع إلغاء الوحدات للخارصين","marks":1},{"element":"الناتج 2.89 × 10²⁴ ذرة بوحدته الصحيحة","marks":1},{"element":"عامل التحويل الصحيح مع إلغاء الوحدات لكلوريد الصوديوم","marks":1},{"element":"الناتج 1.93 × 10²¹ وحدة صيغة بوحدته الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عاملا التحويل صحيحان مع إلغاء الوحدات، والناتجان صحيحان بثلاثة أرقام معنوية ووحداتهما"},{"level":"3 درجات","description":"حلّ إحدى الحالتين كاملة والأخرى بخطأ واحد (عامل التحويل أو الناتج)"},{"level":"1–2 درجة","description":"عامل تحويل صحيح لحالة واحدة أو لحالتين دون ناتج صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة عدد المولات على 6.02 × 10²³ بدلًا من الضرب","خطأ في جمع الأسس عند التعامل مع 10⁻³","إهمال وحدة الجسيم (ذرة أو وحدة صيغة) في الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:27:04.855Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التوقع: 1 mol يحتوي 6.02 × 10²³ ذرة؛ فالعدد 5.75 × 10²⁴ أكبر من عدد أفوجادرو، فيكون ناتج (أ) أكبر من 1 mol، بينما العدد 2.50 × 10²⁰ أقل منه، فيكون ناتج (ب) أقل من 1 mol. الحساب: (أ) 5.75 × 10²⁴ ذرة × (1 mol / 6.02 × 10²³ ذرة) = 9.55 mol من Al. (ب) 2.50 × 10²⁰ ذرة × (1 mol / 6.02 × 10²³ ذرة) = 4.15 × 10⁻⁴ mol من Fe. والنتيجتان توافقان التوقع.', '["مقارنة عدد الذرات بعدد أفوجادرو لتوقع الناتج (أكبر من 1 mol أو أقل منه)","استعمال عامل التحويل (1 mol / 6.02 × 10²³ ذرة)","9.55 mol من Al","4.15 × 10⁻⁴ mol من Fe"]'::jsonb, '["التوقع: 5.75 × 10²⁴ > 6.02 × 10²³ فالناتج > 1 mol؛ و2.50 × 10²⁰ < 6.02 × 10²³ فالناتج < 1 mol","(أ) 5.75 × 10²⁴ ÷ 6.02 × 10²³ = 9.55 mol","(ب) 2.50 × 10²⁰ ÷ 6.02 × 10²³ = 4.15 × 10⁻⁴ mol"]'::jsonb, '[{"element":"توقع الناتجين بمقارنة العدد بـ 6.02 × 10²³","marks":1},{"element":"عامل التحويل الصحيح (مقلوب عدد أفوجادرو) مع إلغاء الوحدات","marks":1},{"element":"الناتج 9.55 mol","marks":1},{"element":"الناتج 4.15 × 10⁻⁴ mol","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح مبرَّر بمقارنة العدد بعدد أفوجادرو، وعامل تحويل صحيح، وناتجان صحيحان بثلاثة أرقام معنوية"},{"level":"2–3 درجات","description":"حساب أحد الناتجين صحيحًا مع توقع صحيح، أو حساب الناتجين دون توقع"},{"level":"1 درجة","description":"عامل تحويل صحيح فقط، أو توقع صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب عدد الذرات في عدد أفوجادرو بدلًا من القسمة عليه","كتابة 4.15 × 10⁻⁴ على أنها 4.15 × 10⁴ (نسيان الإشارة السالبة للأس)","الاكتفاء بالحساب دون التحقق من معقولية الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:27:04.855Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عدد المولات = 9.03 × 10²³ جزيء × (1 mol / 6.02 × 10²³ جزيء) = 1.50 mol. (ب) كل جزيء CO₂ يحتوي ذرتي أكسجين، فعدد ذرات الأكسجين = 9.03 × 10²³ × 2 = 1.81 × 10²⁴ ذرة. (ج) كل جزيء يحتوي ثلاث ذرات (ذرة كربون وذرتا أكسجين)، فالعدد الكلي للذرات = 9.03 × 10²³ × 3 = 2.71 × 10²⁴ ذرة.', '["1.50 mol من CO₂ باستعمال مقلوب عدد أفوجادرو","كل جزيء يحتوي ذرتي أكسجين","1.81 × 10²⁴ ذرة أكسجين","كل جزيء يحتوي ثلاث ذرات في المجموع","2.71 × 10²⁴ ذرة"]'::jsonb, '["(أ) 9.03 × 10²³ ÷ 6.02 × 10²³ = 1.50 mol","(ب) ذرات O = 9.03 × 10²³ جزيء × 2 ذرة/جزيء = 1.81 × 10²⁴ ذرة","(ج) كل الذرات = 9.03 × 10²³ جزيء × 3 ذرات/جزيء = 2.71 × 10²⁴ ذرة"]'::jsonb, '[{"element":"(أ) عدد المولات 1.50 mol بعامل تحويل صحيح","marks":1},{"element":"(ب) ربط عدد الذرات بصيغة CO₂ (ذرتا أكسجين في الجزيء) والناتج 1.81 × 10²⁴","marks":2},{"element":"(ج) العدد الكلي للذرات 2.71 × 10²⁴ بعد اعتبار ثلاث ذرات في الجزيء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الفقرات الثلاث صحيحة مع خطوات الحل ووحدات صحيحة"},{"level":"3 درجات","description":"فقرتان صحيحتان أو الثلاث بخطأ حسابي واحد"},{"level":"1–2 درجة","description":"فقرة واحدة صحيحة (غالبًا أ) أو فهم لنسبة الذرات في الجزيء دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الأكسجين بعدد الجزيئات نفسه دون الضرب في 2","القول إن العدد الكلي للذرات يساوي عدد الجزيئات","ضرب عدد الجزيئات في عدد أفوجادرو بدلًا من القسمة عليه في الفقرة (أ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.856Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
