from (values
('mcq', 1, 'ما الجسيم الممثل في الماء H₂O؟', null, '["ذرة واحدة","أيون واحد","وحدة صيغة","جزيء واحد"]'::jsonb, 'تذكر', 'تحديد الجسيم الممثل لمادة جزيئية', 'سهل', 'الكتاب ص 155 — الجسيمات الممثلة (الشكل 2-5)'),
('mcq', 2, 'أيّ الخيارات الآتية يحدد الجسيم الممثل لكل من الماء H₂O والحديد Fe وكلوريد البوتاسيوم KCl تحديدًا صحيحًا؟', null, '["H₂O: جزيء، Fe: ذرة، KCl: وحدة صيغة","H₂O: وحدة صيغة، Fe: ذرة، KCl: جزيء","H₂O: جزيء، Fe: جزيء، KCl: أيون","H₂O: ذرة، Fe: ذرة، KCl: وحدة صيغة"]'::jsonb, 'تطبيق', 'تحديد الجسيم الممثل لعدة مواد', 'متوسط', 'الكتاب ص 155، 159 — الجسيمات الممثلة (الشكل 2-5، الخلاصة)'),
('mcq', 3, 'لماذا يُسمّى الجسيم الممثل في كلوريد الصوديوم NaCl وحدة صيغة وليس جزيئًا؟', null, '["لأن NaCl عنصر تتكون بلورته من ذرات متماثلة","لأن كل جسيم منه يتكون من ذرة صوديوم وذرة كلور مرتبطتين معًا منفصلتين عن غيرهما","لأن البلورة كلها تحتوي أيونًا واحدًا من Na⁺ وأيونًا واحدًا من Cl⁻ فقط","لأن NaCl مركب أيوني تتكون بلورته من أيونات Na⁺ وCl⁻ بنسبة 1 : 1 دون وجود جزيئات منفصلة"]'::jsonb, 'فهم', 'تفسير تسمية الجسيم الممثل', 'متوسط', 'الكتاب ص 155 — وحدة الصيغة الكيميائية (الشكل 2-5)'),
('mcq', 4, 'أيّ المواد الآتية يكون جسيمها الممثل ذرة؟', null, '["غاز النيتروجين N₂","النحاس Cu","ثاني أكسيد الكربون CO₂","كلوريد الصوديوم NaCl"]'::jsonb, 'فهم', 'اختيار مادة بجسيم ممثل معيّن', 'سهل', 'الكتاب ص 155 — الجسيمات الممثلة (النحاس)'),
('mcq', 5, 'ما الجسيم الممثل للسكروز C₁₂H₂₂O₁₁، وكم ذرة يحتوي هذا الجسيم الواحد؟', null, '["وحدة صيغة، وتحتوي 45 ذرة","جزيء، ويحتوي 3 ذرات لأن المركب يتكون من 3 عناصر","ذرة، وتحتوي ذرة واحدة","جزيء، ويحتوي 45 ذرة"]'::jsonb, 'تطبيق', 'تحديد الجسيم الممثل وتحليل صيغته', 'متوسط', 'الكتاب ص 156، 157 — الشكل 4-5 (جزيء السكروز)'),
('mcq', 6, 'ما عدد الجسيمات الممثلة في 2.00 mol من غاز النيتروجين N₂؟', null, '["6.02 × 10²³ جزيء","2.41 × 10²⁴ جزيء","1.20 × 10²⁴ جزيء","3.01 × 10²³ جزيء"]'::jsonb, 'تطبيق', 'عدّ الجسيمات الممثلة لعنصر ثنائي الذرة', 'صعب', 'الكتاب ص 155، 159 — الجسيمات الممثلة والتقويم 5-1 (س12)'),
('mcq', 7, 'ما عدد الجسيمات الممثلة ونوعها في 0.500 mol من نترات الكالسيوم Ca(NO₃)₂؟', null, '["3.01 × 10²³ وحدة صيغة","3.01 × 10²³ جزيء","2.71 × 10²⁴ ذرة","6.02 × 10²³ وحدة صيغة"]'::jsonb, 'تطبيق', 'عدّ الجسيمات الممثلة لمركب أيوني', 'صعب', 'الكتاب ص 155، 157 — وحدة الصيغة الكيميائية (المسألة التدريبية 3)'),
('essay', 1, 'حدّد الجسيم الممثل (ذرة، جزيء، أيون، وحدة صيغة) لكل مما يأتي مع تعليل مختصر: (1) الفضة Ag. (2) الميثان CH₄. (3) كلوريد المغنيسيوم MgCl₂. (4) غاز الهيليوم He. (5) عيّنة من أيونات الكلوريد Cl⁻. (6) الأكسجين O₂.', null, null, 'تطبيق', 'تحديد الجسيم الممثل مع تعليل', 'سهل', 'الكتاب ص 155، 159 — الجسيمات الممثلة (الشكل 2-5، الخلاصة)'),
('essay', 2, 'عيّنة مقدارها 0.200 mol من كبريتات الصوديوم Na₂SO₄. حدّد الجسيم الممثل فيها، ثم احسب عدد هذه الجسيمات، وعدد أيونات Na⁺ وعدد أيونات SO₄²⁻ في العيّنة. بيّن خطوات الحل.', null, null, 'تطبيق', 'تحديد الجسيم الممثل وعدّه في مركب أيوني', 'متوسط', 'الكتاب ص 155، 157 — وحدة الصيغة الكيميائية (المسألة التدريبية 3)'),
('essay', 3, 'قال طالب: «1.50 mol من الأكسجين تحتوي على 9.03 × 10²³ ذرة». قيّم هذه العبارة؛ بيّن متى تكون صحيحة ومتى تكون خاطئة، وأعطِ عدد الجسيمات الممثلة وعدد الذرات في 1.50 mol من غاز الأكسجين O₂.', null, null, 'تقويم', 'تقييم عبارة وتصحيحها بالحساب', 'صعب', 'الكتاب ص 155، 159 — الجسيمات الممثلة؛ التقويم 5-1 (س12)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
