insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الماء مادة جزيئية تتكون من جزيئات H₂O، وكل جزيء وحدة بناء مستقلة تتكون من ذرتي هيدروجين وذرة أكسجين؛ لذا فالجسيم الممثل للماء هو الجزيء.', '["الذرة هي الجسيم الممثل للعناصر الفلزية مثل النحاس، وليس للماء الذي تترابط ذراته في جزيئات.","الماء مادة جزيئية لا تتكون من أيونات، فالأيون ليس جسيمه الممثل.","وحدة الصيغة هي الجسيم الممثل للمركبات الأيونية مثل NaCl، والماء ليس مركبًا أيونيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.857Z"}'::jsonb),
('mcq', 2, 0, 'الماء مادة جزيئية فجسيمه الممثل جزيء، والحديد فلز فجسيمه الممثل ذرة، وكلوريد البوتاسيوم مركب أيوني فجسيمه الممثل وحدة صيغة KCl.', '["","عُكس تصنيف الماء وKCl؛ فالماء جزيئي وجسيمه جزيء، وKCl أيوني وجسيمه وحدة صيغة.","الحديد فلز تتكون عيّنته من ذرات لا جزيئات، وKCl جسيمه الممثل وحدة صيغة وليس أيونًا منفردًا.","الماء تترابط فيه الذرات في جزيئات، فالذرة ليست جسيمه الممثل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.857Z"}'::jsonb),
('mcq', 3, 3, 'كلوريد الصوديوم مركب أيوني تتكون بلورته من عدد هائل من أيونات Na⁺ وCl⁻ مرتبة معًا بنسبة 1 : 1، ولا توجد فيه جزيئات منفصلة؛ لذا تُعبّر صيغة NaCl عن أبسط نسبة للأيونات وتُسمّى وحدة صيغة.', '["NaCl مركب يتكون من عنصرين وليس عنصرًا، ولا يتكون من ذرات متماثلة.","هذا وصف الجزيء المستقل، أما NaCl فلا تتكون بلورته من أزواج منفصلة من الذرات بل من أيونات مرتبة في شبكة.","البلورة تحتوي أعدادًا هائلة من الأيونات لا أيونًا واحدًا من كل نوع؛ والصيغة تدل على النسبة فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.858Z"}'::jsonb),
('mcq', 4, 1, 'النحاس فلز تتكون عيّنته من ذرات Cu، فالذرة جسيمه الممثل. أما N₂ وCO₂ فجسيمهما الممثل جزيء، وNaCl جسيمه الممثل وحدة صيغة.', '["النيتروجين عنصر لكنه يوجد على شكل جزيئات ثنائية الذرة N₂، فجسيمه الممثل جزيء وليس ذرة.","","ثاني أكسيد الكربون مركب جزيئي جسيمه الممثل جزيء CO₂.","كلوريد الصوديوم مركب أيوني جسيمه الممثل وحدة صيغة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:27:04.858Z"}'::jsonb),
('mcq', 5, 3, 'السكروز مركب جزيئي جسيمه الممثل الجزيء. وعدد الذرات في الجزيء الواحد = 12 + 22 + 11 = 45 ذرة.', '["عدد الذرات صحيح لكن نوع الجسيم خاطئ؛ فوحدة الصيغة للمركبات الأيونية، أما السكروز فمركب جزيئي جسيمه جزيء.","الطالب عدّ أنواع العناصر (3) بدلًا من عدد الذرات؛ والأرقام السفلية في الصيغة تُجمع: 12 + 22 + 11 = 45.","السكروز مركب وليس فلزًا؛ وتترابط ذراته في جزيء واحد فلا تكون الذرة جسيمه الممثل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.858Z"}'::jsonb),
('mcq', 6, 2, 'الجسيم الممثل للنيتروجين الغازي هو الجزيء N₂، لذا عدد الجزيئات = 2.00 mol × 6.02 × 10²³ جزيء/mol = 1.20 × 10²⁴ جزيء.', '["هذا عدد الجزيئات في 1.00 mol؛ نسي الطالب الضرب في 2.00 mol.","هذا عدد الذرات (1.20 × 10²⁴ × 2) وليس عدد الجسيمات الممثلة؛ فالجسيم الممثل هو الجزيء N₂ لا الذرة.","","هذا ناتج قسمة 6.02 × 10²³ على 2.00 بدلًا من ضربه في 2.00."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.858Z"}'::jsonb),
('mcq', 7, 0, 'نترات الكالسيوم مركب أيوني، فجسيمه الممثل وحدة صيغة Ca(NO₃)₂. عددها = 0.500 mol × 6.02 × 10²³ وحدة صيغة/mol = 3.01 × 10²³ وحدة صيغة.', '["","العدد صحيح لكن النوع خاطئ؛ فالمركب الأيوني لا تتكون منه جزيئات بل وحدات صيغة.","هذا العدد الكلي للذرات (9 ذرات في كل وحدة صيغة × 3.01 × 10²³)، وليس عدد الجسيمات الممثلة.","هذا عدد وحدات الصيغة في 1.00 mol؛ نسي الطالب الضرب في 0.500 mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.858Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) Ag: ذرة؛ لأنه فلز تتكون عيّنته من ذرات Ag. (2) CH₄: جزيء؛ لأنه مركب جزيئي ترتبط فيه ذرة كربون بأربع ذرات هيدروجين في وحدة مستقلة. (3) MgCl₂: وحدة صيغة؛ لأنه مركب أيوني من أيونات Mg²⁺ وCl⁻ بنسبة 1 : 2 دون جزيئات منفصلة. (4) He: ذرة؛ لأنه غاز أحادي الذرة. (5) أيونات Cl⁻: أيون؛ لأن العيّنة مكونة من أيونات منفردة. (6) O₂: جزيء؛ لأن ذرتي أكسجين ترتبطان في جزيء واحد، فالجسيم الممثل جزيء O₂ لا ذرة O.', '["Ag: ذرة","CH₄: جزيء","MgCl₂: وحدة صيغة","He: ذرة","Cl⁻: أيون","O₂: جزيء","تعليل مناسب لكل مادة (فلز، مركب جزيئي، مركب أيوني، غاز أحادي الذرة، أيون منفرد، عنصر ثنائي الذرة)"]'::jsonb, '[]'::jsonb, '[{"element":"Ag مع التعليل","marks":1},{"element":"CH₄ مع التعليل","marks":1},{"element":"MgCl₂ مع التعليل","marks":1},{"element":"He مع التعليل","marks":1},{"element":"Cl⁻ مع التعليل","marks":1},{"element":"O₂ مع التعليل","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحديد صحيح للجسيم الممثل في المواد الست مع تعليل لكل منها"},{"level":"4–5 درجات","description":"تحديد صحيح لأربع أو خمس مواد مع تعليلها"},{"level":"2–3 درجات","description":"تحديد صحيح لمادتين أو ثلاث، أو تحديد صحيح دون تعليل"},{"level":"1 درجة","description":"تحديد صحيح لمادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ O₂ ذرة لأنه عنصر","عدّ MgCl₂ جزيئًا لأنه مركب","عدّ He جزيئًا ثنائي الذرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.859Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كبريتات الصوديوم مركب أيوني، فالجسيم الممثل وحدة صيغة Na₂SO₄. عدد وحدات الصيغة = 0.200 mol × 6.02 × 10²³ وحدة صيغة/mol = 1.20 × 10²³ وحدة صيغة. كل وحدة صيغة تحتوي أيونين Na⁺ وأيونًا واحدًا SO₄²⁻، فعدد أيونات Na⁺ = 1.20 × 10²³ × 2 = 2.41 × 10²³ أيون، وعدد أيونات SO₄²⁻ = 1.20 × 10²³ أيون.', '["الجسيم الممثل وحدة صيغة لأن المركب أيوني","1.20 × 10²³ وحدة صيغة","كل وحدة صيغة تحتوي 2 Na⁺ و1 SO₄²⁻","2.41 × 10²³ أيون Na⁺","1.20 × 10²³ أيون SO₄²⁻"]'::jsonb, '["وحدات الصيغة = 0.200 mol × 6.02 × 10²³ = 1.20 × 10²³","أيونات Na⁺ = 1.20 × 10²³ × 2 = 2.41 × 10²³","أيونات SO₄²⁻ = 1.20 × 10²³ × 1 = 1.20 × 10²³"]'::jsonb, '[{"element":"تحديد الجسيم الممثل (وحدة صيغة) مع التعليل","marks":1},{"element":"عدد وحدات الصيغة 1.20 × 10²³","marks":1},{"element":"عدد أيونات Na⁺ = 2.41 × 10²³ مع ذكر نسبة 2 : 1","marks":2},{"element":"عدد أيونات SO₄²⁻ = 1.20 × 10²³","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للجسيم الممثل مع تعليل، وحسابات صحيحة للأعداد الثلاثة مع الخطوات"},{"level":"3–4 درجات","description":"تحديد صحيح مع عدد وحدات الصيغة وأحد عددي الأيونات، أو خطأ حسابي واحد"},{"level":"1–2 درجة","description":"تحديد صحيح للجسيم الممثل أو حساب وحدات الصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المركب الأيوني جزيئات","نسيان ضرب عدد وحدات الصيغة في 2 عند حساب أيونات Na⁺","اعتبار عدد الأيونات الكلي هو عدد الجسيمات الممثلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.859Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير دقيقة لأنها لا تحدد صيغة المادة. إذا كان المقصود ذرات الأكسجين O (الجسيم الممثل ذرة) فإن 1.50 mol × 6.02 × 10²³ = 9.03 × 10²³ ذرة، فتكون العبارة صحيحة. أما غاز الأكسجين O₂ فجسيمه الممثل الجزيء O₂، فتحتوي 1.50 mol منه على 9.03 × 10²³ جزيء، وكل جزيء يحتوي ذرتين، فعدد الذرات = 9.03 × 10²³ × 2 = 1.81 × 10²⁴ ذرة؛ فتكون العبارة خاطئة إذا كان المقصود غاز O₂ لأنها تخلط بين عدد الجزيئات وعدد الذرات.', '["العبارة تحتاج تحديد الصيغة (O أو O₂)","تصح إذا كان المقصود ذرات O: 9.03 × 10²³ ذرة","الجسيم الممثل لغاز O₂ هو الجزيء","9.03 × 10²³ جزيء في 1.50 mol من O₂","عدد الذرات = 1.81 × 10²⁴ ذرة لأن كل جزيء يحتوي ذرتين"]'::jsonb, '["جزيئات O₂ = 1.50 mol × 6.02 × 10²³ = 9.03 × 10²³ جزيء","ذرات O = 9.03 × 10²³ جزيء × 2 ذرة/جزيء = 1.81 × 10²⁴ ذرة"]'::jsonb, '[{"element":"بيان أن العبارة تتوقف على تحديد الجسيم الممثل (O أو O₂)","marks":1},{"element":"توضيح أن العبارة صحيحة لذرات O (9.03 × 10²³ ذرة)","marks":1},{"element":"تحديد أن الجسيم الممثل في O₂ هو الجزيء وحساب 9.03 × 10²³ جزيء","marks":1},{"element":"حساب عدد الذرات 1.81 × 10²⁴ بالضرب في 2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقييم صحيح يفرق بين حالتي ذرات O وجزيئات O₂ مع حسابات صحيحة"},{"level":"2–3 درجات","description":"تحديد صحيح للجسيم الممثل مع حساب أحد العددين، أو تقييم دون حسابات كاملة"},{"level":"1 درجة","description":"ذكر أن الجسيم الممثل في O₂ هو الجزيء فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار عدد الذرات يساوي عدد الجزيئات في O₂","الحكم على العبارة دون تحديد الصيغة","الضرب في 2 مرتين عند حساب الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.859Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
