from (values
('mcq', 1, 'لماذا يصعب على الكيميائيين عدّ الذرات في عيّنة من مادة عدًّا مباشرًا؟', null, '["لأن عدد الذرات في العيّنة يتغير باستمرار أثناء العدّ","لأن الذرات تتحد معًا فتختفي أثناء العدّ","لأن الذرات متناهية الصغر وأعدادها هائلة حتى في العيّنات الصغيرة","لأن الذرات لا توجد إلا ضمن المركبات فلا يمكن فصلها"]'::jsonb, 'تذكر', 'تفسير سبب صعوبة العدّ المباشر', 'سهل', 'الكتاب ص 154 — عدّ الجسيمات'),
('mcq', 2, 'لماذا لا يكفي الدرزن (12) وحدةً لعدّ الذرات في عيّنات المواد الكيميائية؟', null, '["لأنه يمثل عددًا صغيرًا جدًّا بالنسبة إلى أعداد الذرات الهائلة في أي عيّنة","لأنه لا يُستعمل إلا في عدّ الأجسام التي يمكن لمسها","لأن العدد الذي يمثله الدرزن يختلف باختلاف نوع الأشياء المعدودة","لأنه ليس من وحدات النظام الدولي فلا يمكن استعماله في الكيمياء"]'::jsonb, 'فهم', 'تفسير الحاجة إلى وحدة أكبر', 'سهل', 'الكتاب ص 154، 155 — عدّ الجسيمات، المول'),
('mcq', 3, 'لماذا لا يكون عدد أفوجادرو مناسبًا لقياس كمية من كرات اللعب الزجاجية؟', null, '["لأن عدد أفوجادرو صغير جدًّا ولا يكفي لعدّ الأجسام الكبيرة","لأن عدد أفوجادرو يختلف باختلاف نوع الجسيم المعدود","لأن الكرات الزجاجية لا يمكن عدّها بأي وحدة عدّ","لأن عدد أفوجادرو من هذه الكرات سيغطي سطح الأرض بعمق يتجاوز ستة كيلومترات"]'::jsonb, 'فهم', 'تفسير عدم ملاءمة المول للأجسام الكبيرة', 'متوسط', 'الكتاب ص 155 — عدد أفوجادرو'),
('mcq', 4, 'لو استطاع شخص عدّ ذرتين في كل ثانية دون توقف، فما الزمن التقريبي اللازم لعدّ 1 mol من الذرات؟ (السنة الواحدة = 3.15 × 10⁷ ثانية)', null, '["3.01 × 10²³ سنة","3.44 × 10¹⁹ سنة","9.56 × 10¹⁵ سنة","3.82 × 10¹⁶ سنة"]'::jsonb, 'تطبيق', 'حساب زمن العدّ المباشر', 'صعب', 'الكتاب ص 180 — التقويم 5-1 (س91)'),
('mcq', 5, 'ما المقصود بأن المول يتيح عدّ جسيمات المادة بطريقة غير مباشرة؟', null, '["عدّ الذرات واحدة واحدة تحت مجهر قوي ثم تجميعها في مولات","التعبير عن كمية المادة بالمول، وحساب عدد جسيماتها بضرب عدد المولات في 6.02 × 10²³ جسيم/mol","أخذ عيّنة صغيرة وعدّ ذراتها ثم ضرب العدد في حجم العيّنة الكلية","تقسيم الذرة إلى جسيمات أصغر منها يسهل عدّها"]'::jsonb, 'فهم', 'تفسير معنى العدّ غير المباشر', 'متوسط', 'الكتاب ص 154، 159 — عدّ الجسيمات، الخلاصة'),
('mcq', 6, 'أيّ الحالات الآتية يُناسب استخدام وحدة المول لقياس عدد الأشياء فيها؟', null, '["عدّ جزيئات الماء في كأس من الماء","عدّ الطلاب في مدرسة","عدّ أقلام الرصاص في علبة","عدّ الكرات الزجاجية في ملعب"]'::jsonb, 'تطبيق', 'تطبيق: اختيار الموقف المناسب لاستعمال المول', 'سهل', 'الكتاب ص 154، 155 — عدّ الجسيمات، عدد أفوجادرو'),
('mcq', 7, 'يكتب كيميائي «0.500 mol من المغنيسيوم Mg» بدلًا من «3.01 × 10²³ ذرة من Mg». ما أهم سبب لتفضيله استعمال المول؟', null, '["لأن عدد الذرات في العيّنة يتغير مع الزمن بينما يبقى عدد المولات ثابتًا","لأن المول الواحد يحتوي ذرات أقل من العدد المكتوب بالأرقام","لأن المول يعبّر عن العدد الهائل بقيمة صغيرة سهلة التداول، وتُحوَّل عند الحاجة إلى عدد ذرات","لأن المول يقيس كتلة الذرات مباشرة ولا يعبّر عن عددها"]'::jsonb, 'فهم', 'تفسير فائدة استعمال المول', 'متوسط', 'الكتاب ص 155، 159 — المول، الخلاصة'),
('essay', 1, 'فسّر لماذا يستخدم الكيميائيون وحدة المول في عدّ جسيمات المادة.', null, null, 'فهم', 'تفسير سبب استخدام المول', 'متوسط', 'الكتاب ص 154، 159 — عدّ الجسيمات؛ التقويم 5-1 (س7)'),
('essay', 2, 'تستطيع آلة افتراضية عدّ 1.00 × 10⁹ ذرة في كل ثانية دون توقف. احسب الزمن اللازم بالسنوات لتعدّ 1 mol من الذرات، علمًا بأن السنة الواحدة = 3.15 × 10⁷ ثانية، ثم استنتج ما يدل عليه ذلك بشأن العدّ المباشر وسبب استخدام المول.', null, null, 'تطبيق', 'حساب مع استنتاج', 'صعب', 'الكتاب ص 154، 180 — عدّ الجسيمات؛ التقويم 5-1 (س91)'),
('essay', 3, 'قارن بين الدرزن والمول من حيث: (1) العدد الذي تمثله كل وحدة، (2) هل يتغير هذا العدد بتغير نوع الشيء المعدود؟ (3) نوع الأشياء التي يناسب كلٌّ منهما عدّها. ثم فسّر لماذا لا يُستعمل المول لعدّ كرات اللعب الزجاجية.', null, null, 'تحليل', 'مقارنة مع تفسير', 'صعب', 'الكتاب ص 154، 155، 159 — وحدات العدّ، عدد أفوجادرو؛ التقويم 5-1 (س10)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
