from (values
('mcq', 1, 2, 'الذرات متناهية الصغر، ويوجد منها عدد هائل حتى في العيّنات الصغيرة جدًّا، مما يجعل عدّها مباشرة مستحيلًا؛ ولذلك ابتُكرت وحدة المول لعدّها بطريقة غير مباشرة.', '["عدد الذرات في عيّنة معينة ثابت ولا يتغير أثناء العدّ؛ وليس هذا سبب الصعوبة.","الذرات لا تختفي بالاتحاد؛ فالاتحاد الكيميائي يغيّر طريقة ارتباطها فقط، وليس هذا سبب لجوء الكيميائيين إلى المول.","","كثير من العناصر توجد ذراتها منفردة أو في عناصر نقية، وليس عدم إمكان الفصل هو سبب الصعوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.863Z"}'::jsonb),
('mcq', 2, 0, 'الدرزن يمثل 12 فقط، وهو عدد ضئيل جدًّا مقارنة بأعداد الذرات في أي عيّنة كيميائية؛ لذا يحتاج الكيميائيون إلى وحدة تمثل عددًا هائلًا هو المول الذي يمثل 6.02 × 10²³ جسيم.', '["","العدّ بالدرزن لا يتعلق بقابلية اللمس، وإنما بمقدار العدد (12) الصغير جدًّا للذرات.","العدد الذي تمثله الوحدة ثابت دائمًا أيًّا كان نوع الشيء المعدود؛ فالدرزن 12 دائمًا.","عدم وجود الدرزن ضمن النظام الدولي ليس هو سبب عدم كفايته، بل صغر العدد الذي يمثله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.864Z"}'::jsonb),
('mcq', 3, 3, 'عدد أفوجادرو (6.02 × 10²³) هائل جدًّا؛ فلو كان عدد الكرات الزجاجية بهذا العدد لغطّت سطح الأرض بعمق يتجاوز ستة كيلومترات. لذلك يناسب هذا العدد الجسيمات المتناهية الصغر كالذرات، ولا يناسب الأجسام الكبيرة.', '["العكس صحيح؛ فعدد أفوجادرو هائل الكبر، ولهذا لا يناسب الأجسام الكبيرة.","عدد أفوجادرو ثابت لا يتغير بنوع الجسيم؛ فالمول من أي مادة يحتوي 6.02 × 10²³ جسيم.","يمكن عدّ الكرات بوحدات عدّ مناسبة كالدرزن؛ لكن المشكلة في أن عدد أفوجادرو كبير جدًّا عليها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.868Z"}'::jsonb),
('mcq', 4, 2, 'الزمن بالثواني = 6.02 × 10²³ ذرة ÷ 2 ذرة/ثانية = 3.01 × 10²³ ثانية. وبالسنوات = 3.01 × 10²³ ÷ 3.15 × 10⁷ = 9.56 × 10¹⁵ سنة؛ وهو زمن هائل يبيّن استحالة العدّ المباشر.', '["هذا الزمن بالثواني (3.01 × 10²³ ثانية) لم يُحوَّل إلى سنوات.","الطالب حوّل الثواني إلى سنوات بقسمة على 365 × 24 (عدد ساعات السنة) بدلًا من عدد ثوانيها.","","الطالب ضرب 6.02 × 10²³ في 2 بدلًا من قسمته على 2؛ فعدّ ذرتين في الثانية يقلّل الزمن إلى النصف ولا يضاعفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.868Z"}'::jsonb),
('mcq', 5, 1, 'يُعبَّر عن كمية المادة بالمول، وكل مول يحتوي 6.02 × 10²³ جسيم، فيُحسب عدد الجسيمات بالضرب في عامل التحويل دون عدّها فرادى؛ وهذا هو العدّ غير المباشر.', '["هذا عدّ مباشر ومستحيل عمليًّا بسبب صغر الذرات وكثرتها.","","المول لا يعتمد على عدّ عيّنة صغيرة وضربها في الحجم؛ بل على عدد أفوجادرو الثابت لكل مول.","تقسيم الذرة إلى جسيمات أصغر لا علاقة له بالمول، ولا يساعد في عدّ الجسيمات الممثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.868Z"}'::jsonb),
('mcq', 6, 0, 'المول مناسب لعدّ الجسيمات المتناهية الصغر وأعدادها هائلة، كجزيئات الماء في كأس. أما الطلاب والأقلام والكرات الزجاجية فأعدادها صغيرة بالنسبة إلى 6.02 × 10²³ ويمكن عدّها بوحدات عدّ عادية.', '["","عدد الطلاب صغير جدًّا ويمكن عدّه فرادى، ولا يناسبه عدد هائل كعدد أفوجادرو.","أقلام العلبة عددها محدود ويناسبها الدرزن أو العدّ المباشر.","حتى عدد كبير من الكرات في ملعب أقل بكثير من 6.02 × 10²³؛ فعدد أفوجادرو منها يغطي الأرض بعمق كبير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:27:04.869Z"}'::jsonb),
('mcq', 7, 2, 'يختصر المول العدد الهائل من الجسيمات (3.01 × 10²³ ذرة) في قيمة صغيرة سهلة الكتابة والتداول (0.500 mol)، مع إمكان تحويلها إلى عدد الذرات بالضرب في 6.02 × 10²³ ذرة/mol.', '["عدد الذرات في العيّنة لا يتغير مع الزمن؛ فكلا التعبيرين يصف الكمية نفسها.","المول يحتوي بالضبط 6.02 × 10²³ ذرة، وهما تعبيران عن الكمية نفسها: 0.500 mol = 3.01 × 10²³ ذرة.","","المول وحدة لكمية المادة تعبّر عن عدد الجسيمات، وليس وحدة كتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:27:04.869Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الذرات والجزيئات متناهية الصغر، ويوجد منها عدد هائل حتى في العيّنات الصغيرة جدًّا، فيستحيل عدّها مباشرة واحدة واحدة. لذلك ابتكر الكيميائيون وحدة عدّ هي المول، وهو يمثل 6.02 × 10²³ جسيم (عدد أفوجادرو)، فيمكن عدّ الجسيمات بطريقة غير مباشرة بالتعبير عن الكمية بالمولات ثم تحويلها إلى عدد الجسيمات بضرب عدد المولات في 6.02 × 10²³ جسيم/mol. وهذا العدد الهائل يناسب الجسيمات المتناهية الصغر، كما يناسب الدرزن عدّ الأقلام والبيض.', '["الذرات متناهية الصغر","أعدادها هائلة حتى في العيّنات الصغيرة فيستحيل عدّها مباشرة","المول وحدة عدّ تمثل 6.02 × 10²³ جسيم","يتيح المول العدّ غير المباشر بالتحويل بين المولات وعدد الجسيمات"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الذرات متناهية الصغر","marks":1},{"element":"ذكر أن أعدادها هائلة حتى في العيّنات الصغيرة وأن العدّ المباشر مستحيل","marks":1},{"element":"ذكر أن المول وحدة عدّ تمثل 6.02 × 10²³ جسيم","marks":1},{"element":"توضيح أن المول يتيح العدّ غير المباشر بالتحويل بين المولات والجسيمات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط صغر الذرات وكثرتها باستحالة العدّ المباشر ودور المول في العدّ غير المباشر"},{"level":"2–3 درجات","description":"ذكر السبب (الصغر والكثرة) أو دور المول دون ربط كامل بينهما"},{"level":"1 درجة","description":"ذكر أن المول وحدة عدّ دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المول يقيس الكتلة فقط","ذكر الصغر دون ذكر كثرة الأعداد","عدم ذكر أن العدّ غير مباشر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:27:04.869Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الزمن بالثواني = 6.02 × 10²³ ذرة ÷ 1.00 × 10⁹ ذرة/ثانية = 6.02 × 10¹⁴ ثانية. الزمن بالسنوات = 6.02 × 10¹⁴ ثانية ÷ 3.15 × 10⁷ ثانية/سنة = 1.91 × 10⁷ سنة، أي نحو 19 مليون سنة. وهذا يدل على أن العدّ المباشر للذرات غير عملي حتى مع آلة سريعة جدًّا؛ لذلك يستخدم الكيميائيون المول لعدّ الجسيمات بطريقة غير مباشرة.', '["عدد الذرات في 1 mol هو 6.02 × 10²³","6.02 × 10¹⁴ ثانية","1.91 × 10⁷ سنة","العدّ المباشر غير عملي حتى بآلة سريعة","الحاجة إلى المول للعدّ غير المباشر"]'::jsonb, '["الزمن بالثواني = 6.02 × 10²³ ÷ 1.00 × 10⁹ = 6.02 × 10¹⁴ s","الزمن بالسنوات = 6.02 × 10¹⁴ ÷ 3.15 × 10⁷ = 1.91 × 10⁷ سنة"]'::jsonb, '[{"element":"حساب الزمن بالثواني 6.02 × 10¹⁴","marks":1},{"element":"تحويل الزمن إلى سنوات 1.91 × 10⁷","marks":1},{"element":"استنتاج أن العدّ المباشر غير عملي حتى بآلة سريعة جدًّا","marks":1},{"element":"ربط ذلك بسبب استخدام المول (عدّ غير مباشر)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح بالثواني ثم بالسنوات مع استنتاج صحيح وربط بسبب استخدام المول"},{"level":"2–3 درجات","description":"حساب صحيح مع استنتاج ناقص، أو استنتاج صحيح مع خطأ حسابي واحد"},{"level":"1 درجة","description":"حساب الزمن بالثواني فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب 6.02 × 10²³ في 1.00 × 10⁹ بدلًا من قسمته","نسيان تحويل الثواني إلى سنوات","الاكتفاء بالحساب دون الاستنتاج المطلوب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:27:04.869Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) الدرزن يمثل 12 شيئًا، والمول يمثل 6.02 × 10²³ جسيم. (2) العدد الذي تمثله كل وحدة ثابت أيًّا كان نوع الشيء؛ فالدرزن 12 سواء أكان وردًا أم أقلامًا، والمول 6.02 × 10²³ سواء أكان ذرات أم جزيئات أم وحدات صيغة. (3) الدرزن يناسب عدّ أشياء يومية قليلة العدد كالأقلام والبيض والورد، والمول يناسب عدّ الجسيمات المتناهية الصغر كالذرات والجزيئات. ولا يناسب المول كرات اللعب الزجاجية لأن عدد أفوجادرو منها هائل جدًّا يغطي سطح الأرض بعمق يتجاوز ستة كيلومترات.', '["الدرزن = 12، والمول = 6.02 × 10²³","العدد ثابت لا يتغير بنوع الشيء في الوحدتين","الدرزن للأشياء اليومية والمول للجسيمات الدقيقة","عدد أفوجادرو من الكرات يغطي الأرض بعمق يتجاوز 6 km","المول لا يناسب الأجسام الكبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"العدد الذي تمثله كل وحدة (12 و6.02 × 10²³)","marks":1},{"element":"ثبات العدد أيًّا كان نوع الشيء المعدود","marks":1},{"element":"نوع الأشياء التي يناسبها كل منهما","marks":1},{"element":"تفسير عدم صلاحية المول لعدّ الكرات الزجاجية بكبر عدد أفوجادرو","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في النقاط الثلاث مع تفسير صحيح لعدم ملاءمة المول للكرات الزجاجية"},{"level":"3–4 درجات","description":"مقارنة صحيحة في نقطتين أو ثلاث مع تفسير ناقص أو بدونه"},{"level":"1–2 درجة","description":"ذكر العددين فقط أو نقطة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المول يختلف عدده باختلاف المادة","القول إن عدد أفوجادرو صغير","الاكتفاء بذكر الفرق في العدد دون ذكر نوع الأشياء المعدودة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.869Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
