('mcq', 7, 'أيّ الأزواج الآتية يذكر وحدتي الكتلة الذرية والكتلة المولية بشكل صحيح؟', null, '["الكتلة الذرية: amu ، الكتلة المولية: g/mol","الكتلة الذرية: g/mol ، الكتلة المولية: amu","الكتلة الذرية: g ، الكتلة المولية: g","الكتلة الذرية: amu ، الكتلة المولية: amu"]'::jsonb, 'فهم', 'تمييز وحدات', 'متوسط', 'الكتاب ص 161، 162 — الكتلة المولية والكتلة الذرية'),
('essay', 1, 'عرّف الكتلة المولية، واذكر وحدتها، ثم بيّن علاقتها العددية بالكتلة الذرية للعنصر مستشهدًا بالحديد الذي كتلته الذرية 55.845 amu.', null, null, 'تذكر', 'تذكر تعريف مع مثال', 'متوسط', 'الكتاب ص 161 — الكتلة المولية'),
