from (values
('mcq', 1, 1, 'الكتلة المولية هي الكتلة بالجرامات لمول واحد من أي مادة نقية، أي كتلة عدد أفوجادرو من جسيمات المادة؛ وهذا هو الخيار «الكتلة بالجرامات لمول واحد من أي مادة نقية».', '["هذا تعريف الكتلة الذرية التي تخص ذرة واحدة وتُقاس بوحدة amu، لا الكتلة المولية.","","الكتلة المولية تُحسب لمول واحد من المادة وليس لحجم مقداره لتر واحد؛ فالحجم لا يحدد عدد الجسيمات.","هذا خلط بين الكتلة وعدد الجسيمات؛ فالكتلة المولية كتلة (وحدتها g/mol) وليست عددًا من الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.870Z"}'::jsonb),
('mcq', 2, 3, 'الكتلة المولية هي الكتلة بالجرامات لمول واحد، فوحدتها جرام لكل مول (g/mol)؛ وهذا هو الخيار الأخير.', '["وحدة الكتلة الذرية amu هي وحدة كتلة الذرة الواحدة، وليست وحدة الكتلة المولية.","هذه الوحدة مقلوبة؛ فالكتلة المولية جرامات في البسط ومولات في المقام.","الجرام وحده وحدة كتلة فقط، أما الكتلة المولية فهي كتلة لمول واحد فيجب أن تتضمن «لكل مول».",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.870Z"}'::jsonb),
('mcq', 3, 0, 'الكتلة المولية للعنصر تساوي عدديًّا كتلته الذرية؛ فالحديد كتلته الذرية 55.845 amu وكتلته المولية 55.845 g/mol. إذن الإجابة هي كتلته الذرية.', '["","العدد الذري يساوي عدد البروتونات (للحديد 26) ولا يساوي كتلته المولية 55.845 g/mol.","عدد أفوجادرو (6.02×10²³) هو عدد الجسيمات في المول وليس كتلة؛ والكتلة المولية للحديد مثلًا 55.845 g/mol.","عدد الإلكترونات في الذرة المتعادلة يساوي العدد الذري، وهو لا يساوي الكتلة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:27:04.870Z"}'::jsonb),
('mcq', 4, 2, 'المول يُعرَّف بأنه عدد ذرات الكربون-12 في 12 g منه، فكتلة 1 mol من ذرات الكربون-12 تساوي 12 g.', '["العدد 6 هو عدد بروتونات الكربون، وليس كتلة المول التي تساوي 12 g.","12 amu هي كتلة ذرة كربون-12 واحدة وليست كتلة مول كامل من الذرات.","","6.02×10²³ هو عدد الذرات في المول وليس كتلته بالجرامات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.870Z"}'::jsonb),
('mcq', 5, 1, '6.02×10²³ ذرة هي مول واحد من الحديد، وكتلة المول بالجرامات تساوي عدديًّا الكتلة الذرية؛ فكتلتها 55.845 g.', '["هذه كتلة ذرة حديد واحدة بوحدة amu، أما 6.02×10²³ ذرة فكتلتها بالجرامات.","","هذه القيمة ناتجة عن ضرب 55.845 في عدد أفوجادرو، وهو خطأ لأن المول يحمل عدد أفوجادرو من الذرات أصلًا وكتلته 55.845 g.","هذه القيمة ناتجة عن قسمة 55.845 على عدد أفوجادرو، أي كتلة ذرة واحدة بالجرامات، وليست كتلة المول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.870Z"}'::jsonb),
('mcq', 6, 3, 'الكتلة بالجرامات لمول واحد من أي مادة نقية تسمى الكتلة المولية؛ فالقيمة 18 g/mol هي الكتلة المولية للماء.', '["الكتلة الذرية تخص ذرة واحدة وتُقاس بوحدة amu، وليست كتلة مول من الماء.","عدد أفوجادرو هو 6.02×10²³ جسيمًا في المول، وليس كتلة.","عدد المولات يقيس كمية المادة ولا يُقاس بالجرامات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:27:04.871Z"}'::jsonb),
('mcq', 7, 0, 'تُقاس الكتلة الذرية بوحدة amu، وتُقاس الكتلة المولية بوحدة g/mol؛ وهذا ما يذكره الخيار الأول.', '["","الوحدتان معكوستان؛ فـ g/mol وحدة الكتلة المولية لا الكتلة الذرية.","الجرام وحده لا يعبّر عن أي منهما بالدقة؛ فالكتلة الذرية تقاس بـ amu والمولية بـ g/mol.","الكتلة المولية لا تُقاس بوحدة amu؛ فهي كتلة بالجرامات لمول واحد، ووحدتها g/mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.871Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكتلة المولية هي الكتلة بالجرامات لمول واحد من أي مادة نقية (أي كتلة عدد أفوجادرو من جسيماتها). ووحدتها g/mol. والكتلة المولية لأي عنصر تساوي عدديًّا كتلته الذرية؛ فالحديد كتلة ذرته 55.845 amu، لذا فكتلته المولية 55.845 g/mol، أي إن كتلة 1 mol من الحديد هي 55.845 g.', '["الكتلة المولية هي كتلة مول واحد من المادة النقية بالجرامات","وحدتها g/mol","تساوي عدديًّا الكتلة الذرية للعنصر","الحديد: 55.845 amu يقابله 55.845 g/mol"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف: كتلة مول واحد من مادة نقية بالجرامات","marks":1},{"element":"الوحدة g/mol","marks":1},{"element":"المساواة العددية مع الكتلة الذرية","marks":1},{"element":"المثال: 55.845 g/mol للحديد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ووحدة صحيحة وعلاقة عددية صحيحة مع المثال"},{"level":"2–3 درجات","description":"ذكر عنصرين أو ثلاثة من العناصر المطلوبة"},{"level":"1 درجة","description":"ذكر عنصر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوحدة amu للكتلة المولية بدل g/mol","تعريف الكتلة المولية بأنها كتلة ذرة واحدة","عدم ذكر أن الكتلة المولية تخص مولًا واحدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:27:04.871Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة 1 mol من ذرات الكربون-12 تساوي 12 g تمامًا. والكتلة المولية لأي مادة هي كتلة عدد أفوجادرو (6.02×10²³) من جسيماتها المكوّنة لها بالجرامات. وبما أن الكتلة المولية للعنصر تساوي عدديًّا كتلته الذرية، فالكتلة المولية للهيليوم 4.00 g/mol، وكتلة 6.02×10²³ ذرة منه (أي مول واحد) تساوي 4.00 g.', '["كتلة 1 mol من الكربون-12 تساوي 12 g","الكتلة المولية هي كتلة عدد أفوجادرو من الجسيمات","الكتلة المولية للهيليوم 4.00 g/mol","كتلة 6.02×10²³ ذرة هيليوم تساوي 4.00 g"]'::jsonb, '[]'::jsonb, '[{"element":"كتلة مول الكربون-12 تساوي 12 g","marks":1},{"element":"ربط الكتلة المولية بعدد أفوجادرو من الجسيمات","marks":1},{"element":"الكتلة المولية للهيليوم 4.00 g/mol","marks":1},{"element":"كتلة 6.02×10²³ ذرة هيليوم تساوي 4.00 g","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الإجابات الأربع صحيحة بالوحدات الصحيحة"},{"level":"2–3 درجات","description":"صحة إجابتين أو ثلاث"},{"level":"1 درجة","description":"صحة إجابة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كتلة مول الكربون-12 تساوي 12 amu","ضرب 4.00 في عدد أفوجادرو لحساب كتلة 6.02×10²³ ذرة","كتابة الكتلة المولية للهيليوم بوحدة amu"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:27:04.871Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القيمة 63.546 amu هي الكتلة الذرية للنحاس، وتصف كتلة ذرة نحاس واحدة. والقيمة 63.546 g/mol هي الكتلة المولية للنحاس، وتصف كتلة مول واحد من ذرات النحاس بالجرامات. والعدد 6.02×10²³ هو عدد أفوجادرو، وهو عدد الذرات في المول الواحد، وكتلة هذا العدد من ذرات النحاس تساوي 63.546 g.', '["63.546 amu هي الكتلة الذرية وتخص ذرة واحدة","63.546 g/mol هي الكتلة المولية وتخص مولًا واحدًا","6.02×10²³ هو عدد أفوجادرو: عدد الجسيمات في المول"]'::jsonb, '[]'::jsonb, '[{"element":"الكتلة الذرية لذرة واحدة","marks":1},{"element":"الكتلة المولية لمول واحد","marks":1},{"element":"عدد أفوجادرو عدد جسيمات المول","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تسمية الكميات الثلاث مع بيان ما تصفه كل منها"},{"level":"2 درجتان","description":"تسمية كميتين صحيحتين مع بيان ما تصفانه"},{"level":"1 درجة","description":"تسمية كمية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية 63.546 g/mol كتلة ذرية","عدّ عدد أفوجادرو كتلة وليس عددًا من الجسيمات","عدم الإشارة إلى أن الكتلة الذرية تخص ذرة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:27:04.871Z"}'::jsonb)
