('mcq', 3, 'ما عدد مولات الحديد Fe في 1.00 kg منه، علمًا أن كتلته المولية 55.845 g/mol؟', null, '["0.0179 mol","5.58×10⁴ mol","0.0558 mol","17.9 mol"]'::jsonb, 'تطبيق', 'تحويل الكتلة إلى مولات مع تحويل الوحدة', 'متوسط', 'الكتاب ص 164، 180 — تحويل الكتلة إلى مولات'),
('mcq', 4, 'ما كتلة 2.45×10⁻² mol من الخارصين Zn، علمًا أن كتلته المولية 65.38 g/mol؟', null, '["3.75×10⁻⁴ g","1.60 g","2.67×10³ g","160 g"]'::jsonb, 'تطبيق', 'تحويل المولات إلى كتلة بالصيغة العلمية', 'متوسط', 'الكتاب ص 163 — تحويل المولات إلى كتلة'),
('mcq', 5, 'حسب طالب كتلة 0.0200 mol من المغنيسيوم Mg (كتلته المولية 24.31 g/mol) فحصل على 1.22×10³ g. أيّ تقويم للإجابة صحيح؟', null, '["غير معقولة؛ لأن 0.0200 mol أقل من 0.1 mol فيجب أن تكون الكتلة أقل من 0.1 من الكتلة المولية","معقولة؛ لأن الكتلة بالجرامات تكون دائمًا أكبر من الكتلة المولية","معقولة؛ لأن عدد المولات صغير فتكون الكتلة كبيرة","غير معقولة؛ لأن الكتلة يجب أن تساوي الكتلة المولية 24.31 g"]'::jsonb, 'تحليل', 'تقويم معقولية الإجابة بالتقدير', 'صعب', 'الكتاب ص 163 — تقويم الإجابة (مثال 5-2)'),
('mcq', 6, 'ما عامل التحويل الصحيح لتحويل 25.5 g من الفضة Ag إلى مولات، علمًا أن كتلتها المولية 107.87 g/mol؟', null, '["107.87 g Ag ÷ 1 mol Ag","6.02×10²³ atom Ag ÷ 1 mol Ag","1 mol Ag ÷ 107.87 g Ag","1 mol Ag ÷ 25.5 g Ag"]'::jsonb, 'فهم', 'اختيار عامل التحويل', 'سهل', 'الكتاب ص 162، 167 — مقلوب الكتلة المولية عاملَ تحويل'),
('mcq', 7, 'ما عدد مولات الخارصين Zn في 1.25×10³ g منه، علمًا أن كتلته المولية 65.38 g/mol؟', null, '["8.17×10⁴ mol","0.0523 mol","1.91×10⁻² mol","19.1 mol"]'::jsonb, 'تطبيق', 'تحويل الكتلة إلى مولات بالصيغة العلمية', 'متوسط', 'الكتاب ص 164 — تحويل الكتلة إلى مولات'),
('essay', 1, '(أ) احسب كتلة 2.50 mol من النحاس Cu علمًا أن كتلته المولية 63.546 g/mol. (ب) احسب عدد مولات الفضة Ag في 25.5 g منها علمًا أن كتلتها المولية 107.87 g/mol.', null, null, 'تطبيق', 'تحويلان بين المولات والكتلة', 'متوسط', 'الكتاب ص 162، 164 — التحويل بين المولات والكتلة'),
('essay', 2, 'عيّنة من النيكل Ni كتلتها 0.250 kg. (أ) احسب عدد مولاتها. (ب) ثم احسب كتلة 4.25×10⁻² mol من النيكل نفسه. الكتلة المولية للنيكل 58.69 g/mol.', null, null, 'تطبيق', 'تحويلان مع تحويل وحدة وصيغة علمية', 'صعب', 'الكتاب ص 163، 164، 180 — التحويل بين المولات والكتلة'),
('essay', 3, 'حسبت طالبة عدد مولات المغنيسيوم Mg في 48.6 g منه (الكتلة المولية 24.31 g/mol) بضرب 48.6 في 24.31 فحصلت على 1.18×10³ mol. بيّن الخطأ، وصحّح الحل، وأوضح كيف كان يمكنها اكتشاف الخطأ بالتقدير قبل الحساب.', null, null, 'تقويم', 'تحليل خطأ وتصحيحه', 'صعب', 'الكتاب ص 163، 164 — تقويم الإجابة بالتقدير')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C5-L2-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الكتلة (g) = عدد المولات × الكتلة المولية = 0.250 mol × 55.845 g/mol = 13.96 g، وبثلاثة أرقام معنوية تساوي 14.0 g.', '["هذه القيمة ناتجة عن قسمة عدد المولات على الكتلة المولية (0.250 ÷ 55.845) بدل ضربهما.","هذه القيمة ناتجة عن قسمة الكتلة المولية على عدد المولات (55.845 ÷ 0.250)، أي استعمال عامل التحويل مقلوبًا.","","هذه هي كتلة مول واحد (الكتلة المولية)، وقد نُسي ضربها في عدد المولات 0.250."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.872Z"}'::jsonb),
('mcq', 2, 0, 'عدد المولات = الكتلة × (1 mol ÷ الكتلة المولية) = 75.0 g × (1 mol ÷ 40.08 g) = 1.87 mol.', '["","هذه القيمة ناتجة عن ضرب الكتلة في الكتلة المولية (75.0 × 40.08)، وهو استعمال خاطئ لعامل التحويل عند التحويل من الكتلة إلى المولات.","هذه القيمة ناتجة عن قسمة الكتلة المولية على الكتلة (40.08 ÷ 75.0)، أي مقلوب الناتج الصحيح.","هذه القيمة ناتجة عن قسمة الإجابة الصحيحة على 1000، أي تحويل خاطئ للجرامات إلى كيلوجرامات لا يتطلبه السؤال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:27:04.872Z"}'::jsonb),
('mcq', 3, 3, 'نحوّل أولًا 1.00 kg إلى 1000 g، ثم عدد المولات = 1000 g × (1 mol ÷ 55.845 g) = 17.9 mol.', '["هذه القيمة ناتجة عن استعمال 1.00 بدل 1000 g، أي نُسي تحويل الكيلوجرام إلى جرام.","هذه القيمة ناتجة عن ضرب 1000 g في الكتلة المولية (1000 × 55.845) بدل القسمة عليها.","هذه القيمة ناتجة عن قسمة الكتلة المولية على 1000 (55.845 ÷ 1000)، وهي لا تمثل عدد المولات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:27:04.872Z"}'::jsonb),
('mcq', 4, 1, 'الكتلة = 2.45×10⁻² mol × 65.38 g/mol = 1.60 g (بثلاثة أرقام معنوية).', '["هذه القيمة ناتجة عن قسمة عدد المولات على الكتلة المولية بدل ضربهما.","","هذه القيمة ناتجة عن قسمة الكتلة المولية على عدد المولات (65.38 ÷ 2.45×10⁻²).","هذه القيمة ناتجة عن إهمال الأس 10⁻² عند الضرب (2.45 × 65.38)، فجاءت أكبر مئة مرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.872Z"}'::jsonb),
('mcq', 5, 0, 'العينة أقل من 0.1 mol، فيجب أن تكون كتلتها أقل من 0.1 من الكتلة المولية أي أقل من نحو 2.4 g. والقيمة الصحيحة 0.0200 × 24.31 = 0.486 g، أما 1.22×10³ g فناتجة عن قسمة 24.31 على 0.0200؛ لذا الإجابة غير معقولة.', '["","الكتلة ليست أكبر من الكتلة المولية دائمًا؛ فهي تكون أصغر منها عندما يكون عدد المولات أقل من 1 mol.","قلة عدد المولات تعني كتلة صغيرة لا كبيرة؛ فالكتلة تتناسب طرديًّا مع عدد المولات.","الكتلة تساوي الكتلة المولية فقط عند وجود 1 mol، وهنا العدد 0.0200 mol فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.872Z"}'::jsonb),
('mcq', 6, 2, 'للتحويل من الكتلة إلى المولات نستعمل مقلوب الكتلة المولية (1 mol Ag ÷ 107.87 g Ag) لكي تختصر وحدة الجرام ويبقى المول.', '["هذا عامل تحويل المولات إلى كتلة؛ وعند استعماله مع الجرامات لا تختصر وحدة الجرام.","هذا عامل التحويل بين المولات وعدد الذرات وليس بين الكتلة والمولات.","","الكتلة 25.5 g معطى المسألة وليست عامل تحويل؛ فعامل التحويل يعتمد على الكتلة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-18T03:27:04.873Z"}'::jsonb),
('mcq', 7, 3, 'عدد المولات = 1.25×10³ g × (1 mol ÷ 65.38 g) = 19.1 mol.', '["هذه القيمة ناتجة عن ضرب الكتلة في الكتلة المولية (1.25×10³ × 65.38) بدل القسمة.","هذه القيمة ناتجة عن قسمة الكتلة المولية على الكتلة (65.38 ÷ 1.25×10³)، أي مقلوب الناتج الصحيح.","هذه القيمة ناتجة عن إهمال الأس 10³ عند القسمة (1.25 ÷ 65.38).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:27:04.873Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الكتلة = 2.50 mol × (63.546 g ÷ 1 mol) = 158.865 g، أي 159 g من النحاس. (ب) عدد المولات = 25.5 g × (1 mol ÷ 107.87 g) = 0.236 mol من الفضة.', '["استعمال الكتلة المولية عاملَ تحويل في (أ): 63.546 g ÷ 1 mol","كتلة النحاس 159 g","استعمال مقلوب الكتلة المولية في (ب): 1 mol ÷ 107.87 g","عدد مولات الفضة 0.236 mol"]'::jsonb, '["(أ) الكتلة (g) = عدد المولات × الكتلة المولية ÷ 1 mol","2.50 mol Cu × (63.546 g Cu ÷ 1 mol Cu) = 158.865 g ≈ 159 g Cu","(ب) عدد المولات = الكتلة × (1 mol ÷ الكتلة المولية)","25.5 g Ag × (1 mol Ag ÷ 107.87 g Ag) = 0.236 mol Ag"]'::jsonb, '[{"element":"كتابة عامل التحويل الصحيح في (أ) والتعويض","marks":1},{"element":"الناتج 159 g بثلاثة أرقام معنوية","marks":1},{"element":"استعمال مقلوب الكتلة المولية في (ب) والتعويض","marks":1},{"element":"الناتج 0.236 mol بثلاثة أرقام معنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حلّان صحيحان بعاملي تحويل صحيحين ووحدات وأرقام معنوية صحيحة"},{"level":"2–3 درجات","description":"أحد الحلّين صحيح كاملًا، أو الحلان صحيحان مع خطأ في الأرقام المعنوية أو الوحدة"},{"level":"1 درجة","description":"اختيار عامل تحويل صحيح دون الوصول إلى ناتج صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال الكتلة المولية بدل مقلوبها في (ب)","ضرب الكتلة في الكتلة المولية عند التحويل إلى مولات","إهمال الوحدات أو كتابة عدد خاطئ من الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-18T03:27:04.873Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نحوّل 0.250 kg إلى 250 g، ثم عدد المولات = 250 g × (1 mol ÷ 58.69 g) = 4.26 mol. (ب) الكتلة = 4.25×10⁻² mol × 58.69 g/mol = 2.49 g.', '["تحويل 0.250 kg إلى 250 g","عدد المولات 4.26 mol","ضرب عدد المولات في الكتلة المولية في (ب)","الكتلة 2.49 g"]'::jsonb, '["0.250 kg × 1000 g/kg = 250 g","250 g Ni × (1 mol Ni ÷ 58.69 g Ni) = 4.26 mol Ni","4.25×10⁻² mol Ni × (58.69 g Ni ÷ 1 mol Ni) = 2.49 g Ni"]'::jsonb, '[{"element":"تحويل الكيلوجرام إلى جرام","marks":1},{"element":"عدد المولات 4.26 mol بالتعويض الصحيح","marks":1},{"element":"استعمال الكتلة المولية عاملَ تحويل في (ب)","marks":1},{"element":"الكتلة 2.49 g بثلاثة أرقام معنوية","marks":1},{"element":"الوحدات صحيحة في جميع الخطوات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الخطوات والنواتج والوحدات صحيحة"},{"level":"3–4 درجات","description":"حل أحد الفرعين صحيح كاملًا مع خطأ بسيط في الفرع الآخر"},{"level":"1–2 درجة","description":"استعمال عامل تحويل صحيح في خطوة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل الكيلوجرام إلى جرام فيخرج الناتج أصغر بألف مرة","ضرب الكتلة في الكتلة المولية في (أ)","إهمال الأس 10⁻² في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:27:04.873Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ أن الطالبة ضربت الكتلة في الكتلة المولية، بينما يجب استعمال مقلوب الكتلة المولية عند التحويل من الكتلة إلى المولات حتى تختصر وحدة الجرام. الحل الصحيح: 48.6 g × (1 mol ÷ 24.31 g) = 2.00 mol. ويمكن اكتشاف الخطأ بالتقدير: 48.6 g تساوي نحو ضعف الكتلة المولية 24.31 g، فيجب أن تكون الإجابة قريبة من 2 mol، لا 1.18×10³ mol.', '["الخطأ ضرب الكتلة في الكتلة المولية بدل استعمال مقلوبها","الحل الصحيح 48.6 × (1 ÷ 24.31)","الناتج الصحيح 2.00 mol","التقدير: الكتلة نحو ضعف الكتلة المولية فالناتج نحو 2 mol"]'::jsonb, '["48.6 g Mg × (1 mol Mg ÷ 24.31 g Mg) = 2.00 mol Mg","التقدير: 48.6 g ≈ 2 × 24.31 g، إذن عدد المولات ≈ 2 mol"]'::jsonb, '[{"element":"تحديد الخطأ: استعمال عامل التحويل مقلوبًا","marks":1},{"element":"الحل الصحيح بالمقلوب","marks":1},{"element":"الناتج 2.00 mol","marks":1},{"element":"التقدير الذي يكشف الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ، والحل الصحيح، والناتج، وتقدير مقنع"},{"level":"2–3 درجات","description":"تحديد الخطأ مع حل صحيح دون تقدير، أو العكس"},{"level":"1 درجة","description":"ذكر أن الحل خاطئ دون تحديد السبب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخطأ في الكتلة المولية نفسها","إعادة الحساب دون تفسير سبب الخطأ","إغفال مقارنة الكتلة المعطاة بالكتلة المولية عند التقدير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:27:04.873Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C5-L2-O02') and x.type = v.type and x.number = v.number
